/// Owns every long-lived allocation/state created by `main` in exact
/// registration order. Zig lowers a `defer` body at every error return in its
/// scope; hundreds of independent top-level defers therefore made the former
/// monolithic driver explode before LLVM optimization. The cleanup callbacks
/// below are deliberately out-of-line and execute in the same reverse order
/// as the defers they replace.
const MainResources = struct {
    const capacity = 640;
    const Cleanup = *const fn (*anyopaque, ?*anyopaque, std.mem.Allocator, std.Io) void;
    const Entry = struct {
        first: *anyopaque,
        second: ?*anyopaque = null,
        cleanup: Cleanup,
    };

    allocator: std.mem.Allocator,
    io: std.Io,
    entries: [capacity]Entry = undefined,
    len: usize = 0,

    fn init(allocator: std.mem.Allocator, io: std.Io) MainResources {
        return .{ .allocator = allocator, .io = io };
    }

    noinline fn deinit(self: *MainResources) void {
        while (self.len != 0) {
            self.len -= 1;
            const entry = self.entries[self.len];
            entry.cleanup(entry.first, entry.second, self.allocator, self.io);
        }
    }

    noinline fn push(
        self: *MainResources,
        first: *anyopaque,
        second: ?*anyopaque,
        cleanup: Cleanup,
    ) void {
        if (self.len >= self.entries.len) @panic("MainResources cleanup capacity exceeded");
        self.entries[self.len] = .{ .first = first, .second = second, .cleanup = cleanup };
        self.len += 1;
    }

    fn ownFree(self: *MainResources, value_pointer: anytype) void {
        const Pointer = @TypeOf(value_pointer);
        const Callback = struct {
            noinline fn cleanup(raw: *anyopaque, _: ?*anyopaque, allocator: std.mem.Allocator, _: std.Io) void {
                const pointer: Pointer = @ptrCast(@alignCast(raw));
                allocator.free(pointer.*);
            }
        };
        self.push(@ptrCast(@constCast(value_pointer)), null, Callback.cleanup);
    }

    fn ownOptionalFree(self: *MainResources, value_pointer: anytype) void {
        const Pointer = @TypeOf(value_pointer);
        const Callback = struct {
            noinline fn cleanup(raw: *anyopaque, _: ?*anyopaque, allocator: std.mem.Allocator, _: std.Io) void {
                const pointer: Pointer = @ptrCast(@alignCast(raw));
                if (pointer.*) |value| allocator.free(value);
            }
        };
        self.push(@ptrCast(@constCast(value_pointer)), null, Callback.cleanup);
    }

    fn ownDeinit(self: *MainResources, value_pointer: anytype) void {
        const Pointer = @TypeOf(value_pointer);
        const Callback = struct {
            noinline fn cleanup(raw: *anyopaque, _: ?*anyopaque, _: std.mem.Allocator, _: std.Io) void {
                const pointer: Pointer = @ptrCast(@alignCast(raw));
                pointer.deinit();
            }
        };
        self.push(@ptrCast(@constCast(value_pointer)), null, Callback.cleanup);
    }

    fn ownDeinitTracked(self: *MainResources, value_pointer: anytype) usize {
        const index = self.len;
        self.ownDeinit(value_pointer);
        return index;
    }

    fn retarget(
        self: *MainResources,
        index: usize,
        old_pointer: anytype,
        new_pointer: anytype,
    ) void {
        if (@TypeOf(old_pointer) != @TypeOf(new_pointer))
            @compileError("cleanup retarget requires identical pointer types");
        if (index >= self.len) @panic("cleanup retarget index is not live");
        const old_raw: *anyopaque = @ptrCast(@constCast(old_pointer));
        if (self.entries[index].first != old_raw)
            @panic("cleanup retarget source does not match registered owner");
        self.entries[index].first = @ptrCast(@constCast(new_pointer));
    }

    fn ownOptionalDeinit(self: *MainResources, value_pointer: anytype) void {
        const Pointer = @TypeOf(value_pointer);
        const Callback = struct {
            noinline fn cleanup(raw: *anyopaque, _: ?*anyopaque, _: std.mem.Allocator, _: std.Io) void {
                const pointer: Pointer = @ptrCast(@alignCast(raw));
                if (pointer.*) |*value| value.deinit();
            }
        };
        self.push(@ptrCast(value_pointer), null, Callback.cleanup);
    }

    fn ownPrefixFree(self: *MainResources, values_pointer: anytype, count_pointer: *usize) void {
        const Pointer = @TypeOf(values_pointer);
        const Callback = struct {
            noinline fn cleanup(raw: *anyopaque, count_raw: ?*anyopaque, allocator: std.mem.Allocator, _: std.Io) void {
                const pointer: Pointer = @ptrCast(@alignCast(raw));
                const count: *usize = @ptrCast(@alignCast(count_raw.?));
                for (pointer.*[0..count.*]) |value| allocator.free(value);
            }
        };
        self.push(@ptrCast(@constCast(values_pointer)), @ptrCast(count_pointer), Callback.cleanup);
    }

    fn ownPrefixDeinit(self: *MainResources, values_pointer: anytype, count_pointer: *usize) void {
        const Pointer = @TypeOf(values_pointer);
        const Callback = struct {
            noinline fn cleanup(raw: *anyopaque, count_raw: ?*anyopaque, _: std.mem.Allocator, _: std.Io) void {
                const pointer: Pointer = @ptrCast(@alignCast(raw));
                const count: *usize = @ptrCast(@alignCast(count_raw.?));
                for (pointer.*[0..count.*]) |*value| value.deinit();
            }
        };
        self.push(@ptrCast(@constCast(values_pointer)), @ptrCast(count_pointer), Callback.cleanup);
    }

    fn ownOptionalDeinitSliceAndFree(self: *MainResources, values_pointer: anytype) void {
        const Pointer = @TypeOf(values_pointer);
        const Callback = struct {
            noinline fn cleanup(raw: *anyopaque, _: ?*anyopaque, allocator: std.mem.Allocator, _: std.Io) void {
                const pointer: Pointer = @ptrCast(@alignCast(raw));
                for (pointer.*) |*maybe_value| if (maybe_value.*) |*value| value.deinit();
                allocator.free(pointer.*);
            }
        };
        self.push(@ptrCast(@constCast(values_pointer)), null, Callback.cleanup);
    }

    fn ownOptionalDirClose(self: *MainResources, dir_pointer: anytype) void {
        const Pointer = @TypeOf(dir_pointer);
        const Callback = struct {
            noinline fn cleanup(raw: *anyopaque, _: ?*anyopaque, _: std.mem.Allocator, io: std.Io) void {
                const pointer: Pointer = @ptrCast(@alignCast(raw));
                if (pointer.*) |dir| dir.close(io);
            }
        };
        self.push(@ptrCast(@constCast(dir_pointer)), null, Callback.cleanup);
    }

    fn ownOptionalDirTree(self: *MainResources, dir_pointer: anytype, path_pointer: anytype) void {
        const DirPointer = @TypeOf(dir_pointer);
        const PathPointer = @TypeOf(path_pointer);
        const Callback = struct {
            noinline fn cleanup(raw: *anyopaque, path_raw: ?*anyopaque, _: std.mem.Allocator, io: std.Io) void {
                const pointer: DirPointer = @ptrCast(@alignCast(raw));
                const path: PathPointer = @ptrCast(@alignCast(path_raw.?));
                if (pointer.*) |dir| dir.deleteTree(io, path.*) catch {};
            }
        };
        self.push(
            @ptrCast(@constCast(dir_pointer)),
            @ptrCast(@constCast(path_pointer)),
            Callback.cleanup,
        );
    }
};

test "MainResources retargets tracked cleanup to the live moved owner" {
    const Owner = struct {
        deinit_count: usize = 0,

        fn deinit(self: *@This()) void {
            self.deinit_count += 1;
        }
    };

    var resources = MainResources.init(std.testing.allocator, std.testing.io);
    var original: Owner = .{};
    const cleanup_index = resources.ownDeinitTracked(&original);
    var moved = original;
    resources.retarget(cleanup_index, &original, &moved);
    resources.deinit();

    try std.testing.expectEqual(@as(usize, 0), original.deinit_count);
    try std.testing.expectEqual(@as(usize, 1), moved.deinit_count);
}

/// Seeds the initial soil profile from the site's mean annual soil temperature.
///
/// `starts.f` lines 397--400 and 1222 seed the profile isothermally at
/// `ATKS = ATCS + 273.15`, where `ATCS` comes from the site's mean annual air
/// temperature. `GridState` allocates `soil_temperature_k` at 273.15 K as a
/// placeholder, so without this every layer would begin exactly on the
/// pure-water freezing point, the worst possible start for a phase-enthalpy
/// solver.
///
/// Enabling this reduced the day-1 heat imbalance from `-3.913e8` MJ to
/// `-2.695e7` MJ, a 14.5x improvement, and cut the share carried by the first
/// three hours from 67.3% to 8.3%. `profile_relayering` also drops to exactly
/// zero for all 24 hours, confirming its earlier large deltas were an artifact
/// of the freezing-point start rather than a redistribution defect. See
/// EXEC-002.
const seed_soil_profile_from_mean_annual = true;

/// Runs checkpoint restoration and the pass/scene/hour execution pipeline.
///
/// The generic parameter is one explicit, pointer-only context object whose
/// concrete heterogeneous type is inferred at its single call site. Keeping
/// the owner declarations in `main` preserves cleanup order while `noinline`
/// bounds LLVM's per-function optimization work.
const TimelineState = struct {
    climate_state: ecosys.climate_change.State,
    executed_scene_passes: usize,
    resume_position: ?ecosys.checkpoint_manifest.SimulationInstant,
    initial_snow_chemistry_initialized: bool,
    execution_journal: ?*ecosys.execution_evidence.Journal = null,
};

fn shouldSeedStarteChemistryAtSceneStart(executed_scene_passes: usize) bool {
    return executed_scene_passes == 0;
}

test "STARTE chemistry transport synchronization is initial-scene only" {
    try std.testing.expect(shouldSeedStarteChemistryAtSceneStart(0));
    try std.testing.expect(!shouldSeedStarteChemistryAtSceneStart(1));
    try std.testing.expect(!shouldSeedStarteChemistryAtSceneStart(8));
}

/// Records the calendar and scene-structure stages, which are observable from
/// the orchestration state the hourly loop already holds.
///
/// Only stages listed in `Stage.instrumented` are recorded here, and that list
/// is deliberately short: every other variant reports as "not yet
/// instrumented" rather than as a measured absence, because a stage nobody
/// wired must not masquerade as evidence that the science never ran. The plant
/// and management stages need signals that live below this layer and are the
/// next increment.
/// Takes plain observed values rather than reaching into the duck-typed
/// `driver_context`: an `anytype` field access that names a field the context
/// does not have compiles only if the call is never instantiated, so a typo
/// here would silently disable the census instead of failing the build.
fn recordHourStageExecution(
    census: *ecosys.stage_execution_census.Census,
    scene_weather_hours: usize,
    previous_day_of_year: ?u16,
    current_day_of_year: ?u16,
) void {
    const hour: u64 = @intCast(scene_weather_hours);

    // Positive control, not science: fires every hour so the report can state
    // whether the census is live. Without it, "3 of 3 stages never executed"
    // is ambiguous between a real finding and a dead instrument.
    census.record(.census_positive_control, hour);

    // The day-of-year wrap. The deck is six forcing years repeated five times
    // with continuous state, so this fires at each 365->1 boundary. Legacy
    // handles that boundary with `reads.f:760-767` setting IDAYR=365 so
    // `soil.f:39,78,106` do not re-initialize; ng has no such gate, so whether
    // this ever fires is exactly what needs measuring.
    if (previous_day_of_year) |previous| {
        if (current_day_of_year) |current| {
            if (current < previous) census.record(.day_of_year_reset, hour);
        }
    }
}

/// Publishes which science stages actually ran. Emitted through `std.log` at
/// `info`, one line per stage, because the never-executed list is a headline
/// result about what the run's evidence covers rather than a debug detail: a
/// run that reports conservation closure over a horizon in which
/// photosynthesis never fired has not tested photosynthesis, and that has to
/// be visible in the same log a reader uses to believe the closure.
///
/// Formatting happens exactly once, at run end, so this costs nothing per hour.
/// Publishes the accumulated conservation breach list. Never returns an error,
/// so it can be used from a `defer` on the failure path.
noinline fn reportConservationSurvey(
    survey: *const ecosys.conservation_survey.Survey,
) void {
    var buffer: [16384]u8 = undefined;
    var writer = std.Io.Writer.fixed(&buffer);
    survey.summary(&writer) catch |err| {
        std.log.warn("conservation survey summary truncated: error={s}", .{@errorName(err)});
        std.log.warn(
            "conservation survey: {d} quantities breached in {d} of {d} simulated hour(s); NOT production evidence",
            .{ survey.breachedQuantityCount(), survey.breaching_hours, survey.observed_hours },
        );
        return;
    };
    var lines = std.mem.splitScalar(u8, writer.buffered(), '\n');
    while (lines.next()) |line| {
        if (line.len == 0) continue;
        // `warn`, not `info`: a surveyed run has continued past a conservation
        // breach and every line of this summary is a reason not to trust its
        // outputs.
        std.log.warn("{s}", .{line});
    }
}

/// Tallies one conservation report's failing quantities into the survey.
///
/// The verdict is taken verbatim from the report -- `failing_cell_count`,
/// `maximum_absolute` and `maximum_normalized_relative` were all computed by
/// the audit at its production limits. Nothing is recomputed or re-thresholded
/// here, so a survey can never disagree with the audit it records.
fn recordConservationSurveyReport(
    survey: *ecosys.conservation_survey.Survey,
    report: ecosys.hourly_cell_conservation.Report,
    simulated_hour: u64,
    scope_name: []const u8,
) bool {
    var breached = false;
    inline for (@typeInfo(ecosys.hourly_cell_conservation.Quantity).@"enum".fields) |field| {
        const index: usize = @intCast(field.value);
        // Report this quantity's activity whether or not it breached, so the
        // summary can tell a conserved-while-active pass from a vacuous one.
        //
        // `Closure.normalization_scale` IS that activity:
        // `scoped_conservation.zig:evaluate` sets it to
        // `@max(@abs(delta_storage), throughput)`, which is the same scale the
        // relative half of the acceptance limit is computed against. Taking it
        // verbatim means the survey cannot disagree with the verdict it records.
        //
        // The largest scale across cells is the right summary for a landscape
        // quantity: if ANY cell moved it, the quantity is not inert. A mean
        // would let one active cell be diluted into apparent inertness by
        // quiet neighbours.
        var largest_scale: f64 = 0;
        for (report.cells) |cell_report| {
            const scale = cell_report.closure[index].normalization_scale;
            if (std.math.isFinite(scale) and @abs(scale) > largest_scale) largest_scale = @abs(scale);
        }
        survey.observeActivity(index, largest_scale);
        if (report.failing_cell_count[index] != 0) {
            breached = true;
            survey.record(
                index,
                simulated_hour,
                report.maximum_absolute[index],
                report.maximum_normalized_relative[index],
            );
            // Streamed per breach, and NOT redundant with the end-of-run
            // summary -- it is the only trustworthy record. A failing hour is
            // rolled back by the outer-hour transaction and the aggregated
            // tally reverts with it. Measured with pointer identity confirmed
            // equal: right after recording the tally read
            // `observed=347 breached=1`, and the end-of-run summary on the
            // same pointer read `observed_hours=346, breached=0`.
            std.log.warn(
                "CONSERVATION_BREACH hour={d} scope={s} quantity={s} failing_cells={d} maximum_absolute={e} maximum_normalized_relative={e}",
                .{
                    simulated_hour,
                    scope_name,
                    field.name,
                    report.failing_cell_count[index],
                    report.maximum_absolute[index],
                    report.maximum_normalized_relative[index],
                },
            );
        }
    }
    return breached;
}

/// Records the cell-total and layer-local conservation verdicts for one hour
/// without halting. Both reports share `hourly_cell_conservation.Report`, so
/// one tallying routine serves both scopes.
fn recordConservationSurvey(
    survey: *ecosys.conservation_survey.Survey,
    cell_report: ecosys.hourly_cell_conservation.Report,
    layer_report: ecosys.hourly_cell_conservation.Report,
    simulated_hour: u64,
) void {
    survey.observeHour(simulated_hour);
    // Both sides must run: `or` would short-circuit and lose the layer tally
    // for every hour in which the cell total also breached.
    const cell_breached = recordConservationSurveyReport(survey, cell_report, simulated_hour, "cell");
    const layer_breached = recordConservationSurveyReport(survey, layer_report, simulated_hour, "layer");
    if (cell_breached or layer_breached) survey.noteBreachingHour();
}

/// True when any element is nonzero. Used only by the stage execution census,
/// to distinguish "this accumulation ran" from "something was actually
/// applied": several management ledgers accumulate every day regardless, so an
/// unconditional census record there would report a stage as exercised on a
/// deck that never performed the operation.
fn anyNonzero(values: []const f64) bool {
    for (values) |value| if (value != 0) return true;
    return false;
}

/// Never returns an error, so it can be published from a `defer` on the
/// failure path as well as the success path. That matters more than it sounds:
/// this deck currently dies mid-run, and `finishTimeline` is skipped when it
/// does, so publishing only on success would make the census unobtainable in
/// exactly the situation it was built to measure.
noinline fn reportStageExecutionCensus(
    census: *const ecosys.stage_execution_census.Census,
) void {
    var buffer: [8192]u8 = undefined;
    var writer = std.Io.Writer.fixed(&buffer);
    census.report(&writer) catch |err| {
        // A diagnostic must never be the reason a completed run fails. Report
        // the truncation and keep going; the counts are still in memory and
        // the next line states how many stages never ran.
        std.log.warn("stage execution census report truncated: error={s}", .{@errorName(err)});
        std.log.info(
            "stage execution census: {d} of {d} stages never executed across {d} simulated hour(s)",
            .{ census.neverExecutedCount(), ecosys.stage_execution_census.Stage.count(), census.observed_hours },
        );
        return;
    };
    var lines = std.mem.splitScalar(u8, writer.buffered(), '\n');
    while (lines.next()) |line| {
        if (line.len == 0) continue;
        std.log.info("{s}", .{line});
    }
}

/// Restores a requested checkpoint, reconciles output state, and returns the
/// small mutable orchestration state needed by the pass/scene/hour pipeline.
noinline fn initializeTimeline(driver_context: anytype) !TimelineState {
    var climate_state: ecosys.climate_change.State = .{};
    const executed_scene_passes: usize = 0;
    var resume_position: ?ecosys.checkpoint_manifest.SimulationInstant = null;
    var restored_output_checkpoint: ?ecosys.output_hour_transaction.AcceptedCheckpoint = null;
    var initial_snow_chemistry_initialized = false;
    var first_pass_preview = try ecosys.simulation_timeline.PassIterator.init(driver_context.runscript.*.scenarios, driver_context.runscript.*.execution_repeat_count);
    const first_requested_pass = first_pass_preview.next() orelse return error.EmptySimulationTimeline;
    driver_context.hourly_science_context.*.restoring_checkpoint =
        driver_context.scene_options.*[first_requested_pass.scene_index].resume_from_checkpoint;
    // Legacy multi-scene runs mark later scenes as continuation scenes. They
    // already inherit live state in this process; only a resume flag on the
    // first executed scene requests an external bundle restore.
    if (driver_context.scene_options.*[first_requested_pass.scene_index].resume_from_checkpoint) {
        if (driver_context.plant_root_state.* == null or driver_context.detailed_canopy_state.* == null or driver_context.canopy_precipitation_retention_state.* == null or driver_context.plant_phenology_state.* == null or driver_context.plant_growth_stage_state.* == null or driver_context.plant_dormancy_state.* == null or driver_context.branch_development_state.* == null) return error.CheckpointResumeRequiresCompletePlantState;
        var maximum_species_name_bytes: usize = 1;
        for (driver_context.checkpoint_species_names.*) |name| maximum_species_name_bytes = @max(maximum_species_name_bytes, name.len);
        const canopy = &driver_context.detailed_canopy_state.*.?;
        const maximum_branches = canopy.plant_branch_offsets[canopy.plant_branch_offsets.len - 1];
        const maximum_nodes = canopy.branch_node_offsets[canopy.branch_node_offsets.len - 1];
        const maximum_samples = canopy.node_sample_offsets[canopy.node_sample_offsets.len - 1];
        var restored = try ecosys.checkpoint_bundle_reader.read(
            driver_context.allocator.*,
            driver_context.init.*.io,
            std.Io.Dir.cwd(),
            driver_context.config.*,
            .{
                .manifest = .{ .maximum_columns = driver_context.config.*.lon_count, .maximum_rows = driver_context.config.*.lat_count, .maximum_soil_layers = driver_context.config.*.soil_layers, .maximum_snow_layers = driver_context.snow_transport_state.*.layer_capacity, .maximum_plant_species_per_cell = driver_context.config.*.plant_populations, .maximum_root_axes_per_plant = driver_context.runscript.*.root_axes_per_plant },
                .plant_metadata = .{ .maximum_cells = driver_context.state.*.cell_count, .maximum_species_per_cell = driver_context.config.*.plant_populations, .maximum_species_name_bytes = maximum_species_name_bytes },
                .plant_development = .{ .maximum_cells = driver_context.state.*.cell_count, .maximum_species = driver_context.config.*.plant_populations, .maximum_branches = driver_context.plant_growth_stage_state.*.?.branches.len },
                .plant_roots = .{ .maximum_plants = driver_context.plant_root_state.*.?.plant_count, .maximum_soil_layers = driver_context.config.*.soil_layers, .maximum_root_axes = driver_context.runscript.*.root_axes_per_plant },
                .plant_canopy = .{ .maximum_cells = driver_context.state.*.cell_count, .maximum_species = driver_context.config.*.plant_populations, .maximum_branches = maximum_branches, .maximum_nodes = maximum_nodes, .maximum_samples = maximum_samples, .maximum_layers = driver_context.runscript.*.canopy_layer_count, .maximum_inclinations = driver_context.canopy_geometry.*.leaf_inclination_sine.len, .maximum_azimuths = driver_context.canopy_geometry.*.leaf_azimuth_radians.len },
                .soil_biogeochemistry = .{ .maximum_cells = driver_context.state.*.cell_count, .maximum_layers = driver_context.config.*.soil_layers, .maximum_substrates = driver_context.runscript.*.microbial_substrate_count, .maximum_populations = driver_context.runscript.*.microbial_population_count },
                .soil_organic = .{ .maximum_profile_layers = driver_context.state.*.layer_count, .maximum_surface_cells = driver_context.state.*.cell_count },
                .transport = .{ .maximum_transport_cells = driver_context.state.*.layer_count, .maximum_solute_species = driver_context.micropore_solute_state.*.species_count, .maximum_snow_cells = driver_context.state.*.cell_count, .maximum_snow_layers = driver_context.snow_transport_state.*.layer_capacity },
                .soil_geometry = .{ .maximum_columns = driver_context.config.*.lon_count, .maximum_rows = driver_context.config.*.lat_count, .maximum_soil_layers = driver_context.config.*.soil_layers, .maximum_snow_layers = driver_context.snow_transport_state.*.layer_capacity, .maximum_plants = driver_context.runtime_plant_count.* },
            },
            .{ .manifest_buffer_bytes = 16 * 1024, .section_read_buffer_bytes = 64 * 1024, .section_verify_buffer_bytes = 64 * 1024 },
        );
        errdefer restored.deinit();
        try ecosys.checkpoint_resume.validateCompletedDayBoundary(
            restored.manifest.instant.completed_scene_hours,
        );
        const selected_output_manifest = driver_context.output_resume_manifest.* orelse
            return error.MissingCheckpointOutputIdentity;
        if (restored.manifest.generation != selected_output_manifest.generation or
            !std.meta.eql(restored.manifest.instant, selected_output_manifest.instant) or
            restored.manifest.output.run_identity != driver_context.output_run_identity.* or
            restored.manifest.output.fingerprint != selected_output_manifest.output.fingerprint or
            !std.mem.eql(u8, restored.manifest.output.canonical_root, driver_context.output_tree.*.root_path))
            return error.CheckpointChangedDuringOutputResume;
        const restored_generation = restored.manifest.generation;
        resume_position = restored.manifest.instant;
        restored_output_checkpoint = .{
            .checkpoint_generation = restored_generation,
            .output_generation = restored_generation,
            .instant = .{
                .year = restored.manifest.instant.year,
                .day_of_year = restored.manifest.instant.day_of_year,
                .hour = restored.manifest.instant.hour,
                .execution_iteration = restored.manifest.instant.execution_iteration,
                .scenario_index = restored.manifest.instant.scenario_index,
                .scenario_iteration = restored.manifest.instant.scenario_iteration,
                .scene_index = restored.manifest.instant.scene_index,
                .completed_scene_hours = restored.manifest.instant.completed_scene_hours,
            },
        };
        // A8a: resuming into a different crop than was checkpointed silently
        // reinterprets every per-species array, so refuse it here. The bundle
        // reader only checks counts (`bundle_reader.zig:175`); the name-level
        // comparison lives in `checkpoint_resume.validatePlantMetadata`, which
        // had no caller until this line. Skipped when the runscript declares no
        // plant assignments, because then no species topology exists to compare.
        if (driver_context.plant_assignments.* != null)
            try ecosys.checkpoint_resume.validatePlantMetadata(
                driver_context.checkpoint_metadata_cells.*,
                restored.plant_metadata,
                restored.manifest.instant,
            );
        try ecosys.checkpoint_bundle_reader.swapIntoLive(&restored, .{
            .grid = &driver_context.state.*,
            .plants = &driver_context.plant_state.*,
            .plant_development = .{ .phenology = &driver_context.plant_phenology_state.*.?, .growth = &driver_context.plant_growth_stage_state.*.?, .dormancy = &driver_context.plant_dormancy_state.*.?, .branch_development = &driver_context.branch_development_state.*.? },
            .plant_roots = &driver_context.plant_root_state.*.?,
            .plant_canopy = .{ .canopy = &driver_context.detailed_canopy_state.*.?, .retention = &driver_context.canopy_precipitation_retention_state.*.?, .layer_distribution = &driver_context.canopy_layer_distribution_state.*.? },
            .soil_biogeochemistry = .{ .microbial = &driver_context.soil_microbial_state.*, .microbial_thermal_adaptation = &driver_context.microbial_thermal_adaptation_state.*, .chemistry = &driver_context.initial_chemistry_state.*, .available_nutrients = &driver_context.plant_available_nutrient_state.*, .fertilizer = &driver_context.soil_fertilizer_inventory.*, .mineral_fertilizer = &driver_context.mineral_fertilizer_inventory.*, .fertilizer_band = &driver_context.fertilizer_band_state.*, .reactive_nitrogen = &driver_context.soil_reactive_nitrogen_state.*, .microbial_phosphorus = &driver_context.soil_microbial_phosphorus_state.*, .nutrient_competition = &driver_context.soil_nutrient_competition_history.* },
            .soil_organic_matter = .{ .profile = &driver_context.soil_organic_state.*, .surface = &driver_context.surface_organic_state.*, .litter_chemistry = &driver_context.surface_litter_chemistry_state.*, .litter_fertilizer = &driver_context.surface_litter_fertilizer_state.*, .surface_respiration = &driver_context.surface_microbial_respiration_state.*, .surface_autotrophic = &driver_context.surface_autotrophic_complex_state.*, .surface_denitrification = &driver_context.surface_denitrification_state.*, .surface_fire_exchange = &driver_context.surface_fire_exchange_state.*, .litter_salt_ingress = &driver_context.plant_litter_salt_ingress_state.* },
            .transport = .{ .micropore = &driver_context.micropore_solute_state.*, .macropore = &driver_context.macropore_solute_state.*, .mineral_nitrogen = &driver_context.mineral_nitrogen_transport_state.*, .organic = &driver_context.soil_organic_transport_state.*, .gas = &driver_context.gas_transport_state.*, .litter_gas = &driver_context.litter_gas_transport_state.*, .snow = &driver_context.snow_transport_state.*, .surface = &driver_context.surface_transport_state.* },
            .soil_geometry_and_hydrology = .{ .geometry = &driver_context.soil_geometry_state.*, .hydrology = &driver_context.transport_hydrology_state.*, .surface = &driver_context.surface_precipitation_state.*, .erosion = &driver_context.surface_erosion_state.*, .suspended = &driver_context.suspended_constituent_state.*, .climate = &climate_state, .eroded_minerals = &driver_context.eroded_mineral_state.*, .runtime = .{ .soil_properties = &driver_context.soil_solver_property_state.*, .soil_thermal = &driver_context.soil_thermal_state.*, .soil_chemistry_layer_parameters = driver_context.soil_chemistry_layer_parameters.* }, .surface_boundary = .{ .ground_air = &driver_context.ground_air_state.*, .surface_aerodynamics = &driver_context.surface_aerodynamic_state.*, .atmospheric_carrier = &driver_context.atmospheric_canopy_gas_state.* }, .water_table = .{ .topology = &driver_context.soil_boundary_topology_state.* }, .adaptive_hour_schedule = &driver_context.fixed_hour_recovery_workspace.*.adaptive_hour_schedule, .surface_litter_geometry = &driver_context.surface_litter_geometry_state.*, .surface_litter_ice_m3 = driver_context.surface_litter_ice_m3.*, .delayed_live_canopy_combustion_heat_megajoules = driver_context.delayed_live_canopy_combustion_heat_megajoules.*, .delayed_standing_dead_combustion_heat_megajoules = driver_context.delayed_standing_dead_combustion_heat_megajoules.*, .delayed_subsurface_combustion_heat_megajoules = driver_context.delayed_subsurface_combustion_heat_megajoules.*, .delayed_root_uptake_heat_megajoules = driver_context.delayed_root_uptake_heat_megajoules.*, .delayed_surface_combustion_heat_megajoules = driver_context.delayed_surface_combustion_heat_megajoules.* },
            .landscape_mass_balance = &driver_context.landscape_mass_balance_state.*,
            .plant_accounting = .{ .daily_flux = &driver_context.plant_daily_flux_ledger.*, .root_soil_exchange = &driver_context.plant_root_soil_exchange_state.*, .cumulative_harvest_salt_mol_by_plant = driver_context.cumulative_harvest_salt_mol_by_plant.*, .cumulative_water_source_m3_by_plant = driver_context.plant_water_state_update_state.*.cumulative_water_source_m3_by_plant },
        });
        // PLANT_ACCLIM_MODE2_RESUME_BINDING: the checkpoint owns the climate
        // modifiers and the four acclimated canopy fields, but HFUNC also
        // reads three derived parameter mirrors that are intentionally not
        // checkpoint payloads. Re-derive all mirrors from the restored
        // cumulative DTA before any resumed science. Do not call advanceDay:
        // the checkpoint has already accepted that calendar day's increment.
        const restored_scene_index = std.math.cast(usize, restored.manifest.instant.scene_index) orelse
            return error.CheckpointSceneIndexOutOfRange;
        if (restored_scene_index >= driver_context.scene_options.*.len)
            return error.CheckpointSceneIndexOutOfRange;
        const restored_scene_options = driver_context.scene_options.*[restored_scene_index];
        if (restored_scene_options.climate_change_mode == 2) {
            const restored_average_air_temperature_change_c = try climate_state.averageAirTemperatureChangeC(
                restored_scene_options,
                restored.manifest.instant.day_of_year,
            );
            const restored_canopy = &driver_context.detailed_canopy_state.*.?;
            try ecosys.biological_climate_acclimation.applyDaily(driver_context.allocator.*, .{
                .cell_count = driver_context.state.*.cell_count,
                .plants_per_cell = driver_context.config.*.plant_populations,
                .source_hour = 1,
                .incremental_climate_change = true,
                .daily_average_air_temperature_change_c = restored_average_air_temperature_change_c,
                .initial_mean_annual_air_temperature_c_by_cell = driver_context.mean_annual_temperature_c_by_cell.*,
                .plant_initial_thermal_adaptation_zone = driver_context.plant_initial_thermal_adaptation_zone.*,
                .plant_photosynthesis_pathway = driver_context.plant_initial_photosynthesis_pathway.*,
                .plant_initial_floral_initiation_group = driver_context.plant_initial_floral_initiation_group.*,
                .plant_seed_initial_node_number = driver_context.plant_seed_initial_node_number.*,
                .plant_biomass_turnover_type = driver_context.plant_topology_controls.*.aboveground_turnover_type,
                .default_lower_temperature_threshold_c = driver_context.runscript.*.thermal_acclimation_parameters.base_leafout_threshold_c,
                .default_upper_temperature_threshold_c = driver_context.runscript.*.thermal_acclimation_parameters.base_leafoff_threshold_c,
            }, .{
                .thermal_adaptation_offset_c = restored_canopy.plant_thermal_adaptation_offset_c,
                .leafout_threshold_c = restored_canopy.plant_leafout_threshold_c,
                .leafoff_threshold_c = restored_canopy.plant_leafoff_threshold_c,
                .seed_set_high_temperature_c = restored_canopy.plant_seed_set_high_temperature_c,
                .floral_initiation_node_number = driver_context.plant_topology_controls.*.initial_maturity_group,
                .dormancy_parameters_by_plant = driver_context.development_dormancy_parameters.*,
            });
            for (driver_context.development_species_parameters.*, driver_context.plant_topology_controls.*.initial_maturity_group) |*parameters, group|
                parameters.maturity_group_node_count = group;
        }
        // The versioned transport checkpoint owns both snow chemistry
        // carriers.  Reapplying first-header STARTE chemistry here would
        // duplicate storage and make restart diverge from uninterrupted runs.
        initial_snow_chemistry_initialized = true;
        // The owner swap replaces these slices. Rebind every consumer through
        // the same checked helper used by in-memory recovery before the
        // restored bundle releases the former live allocation.
        var restored_harvest_emerged: ?*?[]bool = null;
        if (driver_context.harvest_context.*) |*value|
            restored_harvest_emerged = &value.emerged_by_plant;
        try hourly_heat_water_solute.rebindPhenologyAliases(
            &driver_context.plant_phenology_state.*.?,
            &driver_context.hourly_science_context.*.development_emerged,
            restored_harvest_emerged,
            driver_context.checkpoint_metadata_cells.*,
            driver_context.config.*.plant_populations,
        );
        driver_context.hourly_science_context.*.restoring_checkpoint = true;
        restored.deinit();
        // The checkpointed thermal owner is authoritative. Its accepted
        // layer thickness and volume can intentionally differ from the soil
        // geometry carrier after freeze/thaw and remapping; rebuilding either
        // value here changes the next surface heat-storage equation.
        // The same rule applies to the checkpointed runtime soil-property
        // owner. Erosion texture, organic-carbon concentration, exchange
        // capacities, and rainfall conductivity damage are accepted mutable
        // state, not restart-time derivations.
        try driver_context.soil_transport_faces.*.refreshMapped(
            &driver_context.transport_hydrology_state.*,
            &driver_context.state.*,
            &driver_context.soil_geometry_state.*,
            driver_context.soil_numerical_scales_state.*.geometry_floor_m,
        );
        try driver_context.soil_face_geometry_state.*.refreshMapped(
            &driver_context.state.*,
            &driver_context.soil_transport_faces.*,
            driver_context.soil_solver_property_state.*.layer_thickness_m,
            driver_context.grid_environment.*.horizontal_cell_width_m,
            driver_context.grid_environment.*.vertical_cell_width_m,
        );
        driver_context.executed_weather_hours.* = std.math.cast(usize, restored_generation) orelse return error.CheckpointGenerationExceedsRuntimeCounter;
    }
    if (restored_output_checkpoint) |accepted_checkpoint|
        try driver_context.output_hour_coordinator.*.reconcile(.{ .checkpoint = accepted_checkpoint })
    else
        try driver_context.output_hour_coordinator.*.reconcile(.fresh);
    return .{
        .climate_state = climate_state,
        .executed_scene_passes = executed_scene_passes,
        .resume_position = resume_position,
        .initial_snow_chemistry_initialized = initial_snow_chemistry_initialized,
    };
}

/// Flushes all accepted output banks and validates the final model state.
noinline fn finishTimeline(driver_context: anytype, timeline_state: *const TimelineState) !void {
    try driver_context.hourly_soil_carbon_bank.*.finish();
    try driver_context.hourly_plant_carbon_bank.*.finish();
    try driver_context.hourly_soil_water_bank.*.finish();
    try driver_context.hourly_plant_water_bank.*.finish();
    try driver_context.hourly_soil_nitrogen_bank.*.finish();
    try driver_context.hourly_plant_nitrogen_bank.*.finish();
    try driver_context.hourly_soil_phosphorus_bank.*.finish();
    try driver_context.hourly_plant_phosphorus_bank.*.finish();
    try driver_context.hourly_soil_heat_bank.*.finish();
    try driver_context.daily_soil_carbon_bank.*.finish();
    try driver_context.daily_soil_water_bank.*.finish();
    try driver_context.daily_soil_phosphorus_bank.*.finish();
    try driver_context.daily_soil_nitrogen_bank.*.finish();
    try driver_context.daily_soil_heat_bank.*.finish();
    try driver_context.hourly_plant_heat_bank.*.finish();
    try driver_context.daily_plant_carbon_bank.*.finish();
    try driver_context.daily_plant_water_bank.*.finish();
    try driver_context.daily_plant_nitrogen_bank.*.finish();
    try driver_context.daily_plant_phosphorus_bank.*.finish();
    try driver_context.daily_plant_development_bank.*.finish();
    try driver_context.visualization_streams.*.finish();
    if (driver_context.executed_weather_hours.* == 0) return error.EmptyWeatherStream;
    try driver_context.atmospheric_state.*.validateFinite();
    if (driver_context.canopy_optics_state.*) |optics_state| try optics_state.validateFinite();
    if (driver_context.canopy_structure_state.*) |structure_state| try structure_state.validateFinite();
    if (driver_context.canopy_interception_state.*) |interception_state| try interception_state.validateFinite();
    try driver_context.ground_radiation_state.*.validateFinite();
    if (driver_context.canopy_exposure_state.*) |exposure_state| try exposure_state.validateFinite();
    try driver_context.surface_energy_state.*.validateFinite();
    try driver_context.surface_temperature_solver_state.*.validateFinite();
    const surface_solver_diagnostics = try driver_context.surface_temperature_solver_state.*.validateConvergence();
    std.log.info("surface Newton-Raphson/Picard diagnostics: cells={d}, iterations={d}, newton_raphson_steps={d}, picard_steps={d}, cells_using_picard={d}, maximum_absolute_residual_megajoules_per_m2={e}", .{ driver_context.state.*.cell_count, surface_solver_diagnostics.total_iterations, surface_solver_diagnostics.total_newton_raphson_steps, surface_solver_diagnostics.total_picard_steps, surface_solver_diagnostics.cells_using_picard, surface_solver_diagnostics.maximum_absolute_residual_megajoules_per_m2 });
    if (driver_context.canopy_energy_state.*) |energy_state| try energy_state.validateFinite();
    if (driver_context.detailed_canopy_state.*) |canopy_state| try canopy_state.validateFinite();
    if (driver_context.plant_root_state.*) |root_state| try root_state.validateFinite();
    if (driver_context.branch_development_state.*) |development_state| try development_state.validateFinite();
    try driver_context.terrain_radiation_state.*.validateFinite();
    std.log.info("ecosys-ng inputs validated: cells={d}, soil_layer_capacity={d}, soil_profiles={d}, plant_species_capacity={d}, plant_trait_profiles={d}, plant_management_schedules={d}, plant_assignment_units={d}, land_management_units={d}, disturbance_schedules={d}, fertilizer_schedules={d}, irrigation_schedules={d}, output_selections={d}, landscape_units={d}, scenarios={d}, scenes={d}, planned_days={d}, planned_hours={d}, total_weather_records={d}, executed_scene_passes={d}, executed_weather_hours={d}, latitude_deg_n={d:.3}, first_scene_water_heat_solute_max_iterations={d}, first_scene_gas_max_iterations={d}", .{
        driver_context.state.*.cell_count,
        driver_context.config.*.soil_layers,
        driver_context.soil_catalog.*.entries.items.len,
        driver_context.config.*.plant_populations,
        driver_context.plant_catalog.*.entries.items.len,
        driver_context.plant_management_catalog.*.entries.items.len,
        if (driver_context.plant_assignments.*) |assignments| assignments.units.len else 0,
        if (driver_context.land_management_assignments.*) |assignments| assignments.units.len else 0,
        driver_context.disturbance_catalog.*.entries.items.len,
        driver_context.fertilizer_catalog.*.entries.items.len,
        driver_context.irrigation_catalog.*.entries.items.len,
        driver_context.output_selection_catalog.*.entries.items.len,
        driver_context.topography.*.units.len,
        driver_context.runscript.*.scenarios.len,
        driver_context.runscript.*.scenes.len,
        driver_context.timeline.*.execution_weighted_days,
        driver_context.timeline.*.execution_weighted_hours,
        driver_context.total_weather_records.*,
        timeline_state.executed_scene_passes,
        driver_context.executed_weather_hours.*,
        driver_context.latitude_degrees_north_by_cell.*[0],
        driver_context.iteration_limits.*.water_heat_solute_max_iterations,
        driver_context.iteration_limits.*.gas_max_iterations,
    });
}

/// Writes the already-accepted hour, rolls daily output state, and publishes
/// a scheduled checkpoint. The caller's hourly transaction defers remain live
/// across this entire noinline call.
noinline fn writeAcceptedHourOutputs(driver_context: anytype, timeline_state: *TimelineState, accepted_context: anytype) !void {
    const accepted_output_instant: ecosys.output_hour_transaction.Instant = .{
        .year = accepted_context.current_year.*,
        .day_of_year = accepted_context.current_day_of_year.*,
        .hour = try accepted_context.timestamp.*.modelHourIndex(),
        .execution_iteration = @intCast(accepted_context.pass.*.execution_iteration),
        .scenario_index = @intCast(accepted_context.pass.*.scenario_index),
        .scenario_iteration = @intCast(accepted_context.pass.*.scenario_iteration),
        .scene_index = @intCast(accepted_context.pass.*.scene_index),
        .completed_scene_hours = @intCast(accepted_context.scene_weather_hours.*),
    };
    try driver_context.output_hour_coordinator.*.beginHour(
        @intCast(driver_context.executed_weather_hours.*),
        accepted_output_instant,
    );
    try writeAcceptedHourlyOutputs(driver_context, accepted_context);
    try writeAcceptedDailyOutputs(driver_context, accepted_context);
    try finishAcceptedHourOutputs(
        driver_context,
        timeline_state,
        accepted_context,
        accepted_output_instant,
    );
}

noinline fn writeAcceptedHourlyOutputs(driver_context: anytype, accepted_context: anytype) !void {
    const completed_hour_count = accepted_context.scene_weather_hours.*;
    if (@mod(completed_hour_count, accepted_context.active_options.*.hourly_output_interval_hours) == 0) {
        const editor_index: usize = 0;
        const editor_name = accepted_context.scene.*.output_editors[editor_index];
        if (!ecosys.delimited_input.isNo(editor_name)) {
            const resolved = driver_context.resolved_output_editors.*[accepted_context.pass.*.scene_index * 10 + editor_index] orelse return error.UnresolvedHourlySoilCarbonEditor;
            const selection_index = driver_context.output_selection_catalog.*.find(editor_name) orelse return error.MissingOutputSelection;
            const selection = driver_context.output_selection_catalog.*.entries.items[selection_index].selection;
            for (0..driver_context.state.*.cell_count) |cell| {
                const root_gas_withdrawal = if (driver_context.plant_root_state.*) |*roots|
                    try ecosys.plant_root_disturbance.rootGasWithdrawalForCell(roots, cell, driver_context.config.*.plant_populations)
                else
                    ecosys.plant_root_disturbance.CellRootGasWithdrawal{};
                const values = try driver_context.hourly_soil_carbon_bank.*.row(cell);
                const carbon_dioxide_concentration = values[4 .. 4 + driver_context.config.*.soil_layers];
                const methane_first = 5 + driver_context.config.*.soil_layers;
                const methane_concentration = values[methane_first .. methane_first + driver_context.config.*.soil_layers];
                const oxygen_first = methane_first + driver_context.config.*.soil_layers;
                const oxygen_concentration = values[oxygen_first .. oxygen_first + driver_context.config.*.soil_layers];
                for (0..driver_context.state.*.active_soil_layer_count[cell]) |local_layer| {
                    const layer = try driver_context.state.*.layerIndex(cell, local_layer);
                    const water_m3 = driver_context.state.*.liquid_water_m3[layer];
                    inline for (.{ ecosys.gas_transport.Species.carbon_dioxide, ecosys.gas_transport.Species.methane, ecosys.gas_transport.Species.oxygen }) |species| {
                        const component = layer * ecosys.gas_transport.species_count + @intFromEnum(species);
                        const concentration = try ecosys.soil_biogeochemistry_output.dissolvedGasConcentration(driver_context.gas_transport_state.*.dissolved_mass_g[component], water_m3);
                        switch (species) {
                            .carbon_dioxide => carbon_dioxide_concentration[local_layer] = concentration,
                            .methane => methane_concentration[local_layer] = concentration,
                            .oxygen => oxygen_concentration[local_layer] = concentration,
                            else => unreachable,
                        }
                    }
                }
                var ground_flux_g: [ecosys.gas_transport.species_count]f64 = @splat(0);
                inline for (.{ ecosys.gas_transport.Species.carbon_dioxide, ecosys.gas_transport.Species.methane, ecosys.gas_transport.Species.oxygen }) |species|
                    ground_flux_g[@intFromEnum(species)] = try ecosys.soil_hourly_output_binding.gasBoundaryExchangeG(
                        driver_context.soil_gas_transport_state.*.atmospheric_flux_g_per_h,
                        driver_context.surface_litter_gas_transport_state.*.atmospheric_flux_g_per_h,
                        try driver_context.state.*.layerIndex(cell, 0),
                        driver_context.config.*.soil_layers,
                        cell,
                        species,
                    );
                const litter_oxygen = try ecosys.soil_biogeochemistry_output.dissolvedGasConcentration(
                    driver_context.litter_gas_transport_state.*.dissolved_mass_g[cell * ecosys.gas_transport.species_count + @intFromEnum(ecosys.gas_transport.Species.oxygen)],
                    driver_context.surface_litter_gas_transport_state.*.water_volume_m3[cell],
                );
                const canopy_net_fixation_g_c_per_h = if (driver_context.canopy_carbon_exchange_state.*) |ledger|
                    try ledger.netFixationForCell(&driver_context.detailed_canopy_state.*.?, cell)
                else
                    0;
                const root_atmospheric_co2_g_c_per_h = try ecosys.root_uptake_ledger.atmosphereToRootForCellGPerH(&driver_context.root_uptake_ledger_state.*, &driver_context.state.*, cell, 0);
                const root_atmospheric_oxygen_g_o_per_h = try ecosys.root_uptake_ledger.atmosphereToRootForCellGPerH(&driver_context.root_uptake_ledger_state.*, &driver_context.state.*, cell, 1);
                const root_atmospheric_methane_g_c_per_h = try ecosys.root_uptake_ledger.atmosphereToRootForCellGPerH(&driver_context.root_uptake_ledger_state.*, &driver_context.state.*, cell, 2);
                try ecosys.soil_biogeochemistry_output.calculateCarbonInto(.{
                    .carbon_dioxide_emission_g_c_per_h = ground_flux_g[@intFromEnum(ecosys.gas_transport.Species.carbon_dioxide)] + root_gas_withdrawal.carbon_dioxide_g_c_per_h - root_atmospheric_co2_g_c_per_h,
                    .net_carbon_exchange_g_c_per_h = canopy_net_fixation_g_c_per_h + ground_flux_g[@intFromEnum(ecosys.gas_transport.Species.carbon_dioxide)] + root_gas_withdrawal.carbon_dioxide_g_c_per_h - root_atmospheric_co2_g_c_per_h,
