                    .surface_ice_volume_m3 = driver_context.surface_litter_ice_m3.*[cell],
                    .surface_liquid_water_m3 = driver_context.surface_precipitation_state.*.litter_water_m3[cell],
                    // Dall'Amico soil/surface ice is already
