                    .timestamp = .{ .year = accepted_context.current_year.*, .day_of_year = accepted_context.current_day_of_year.*, .month = accepted_context.management_date.*.month, .day = accepted_context.management_date.*.day, .hour = try accepted_context.timestamp.*.modelHourIndex() },
                    .longitude_degrees_east = driver_context.longitude_degrees_east_by_cell.*[cell],
                    .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
                    .values = values,
                });
            }
        }
    }
    if (@mod(completed_hour_count, accepted_context.active_options.*.hourly_output_interval_hours) == 0) {
        const editor_index: usize = 1;
        const editor_name = accepted_context.scene.*.output_editors[editor_index];
        if (!ecosys.delimited_input.isNo(editor_name)) {
