                const roots = if (driver_context.plant_root_state.*) |*value| value else return error.HourlyPlantWaterOutputRequiresRootState;
                const surface = if (driver_context.canopy_surface_exchange_state.*) |*value| value else return error.HourlyPlantWaterOutputRequiresSurfaceExchangeState;
                const surface_workspace = if (driver_context.canopy_surface_input_workspace.*) |*value| value else return error.HourlyPlantWaterOutputRequiresSurfaceWorkspace;
                for (0..driver_context.state.*.cell_count) |cell| for (0..driver_context.config.*.plant_populations) |species| {
