                    const file_name = try ecosys.output_record.buildOutputFileName(driver_context.allocator.*, driver_context.latitude_degrees_north_by_cell.*[cell], driver_context.longitude_degrees_east_by_cell.*[cell], .{ .species = .{ .name = species_label, .population_number = species + 1 } }, accepted_context.current_year.*, try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*), cell + 1, editor_name);
                    defer driver_context.allocator.*.free(file_name);
