                const nitrous_oxide_concentration = values[5 .. 5 + driver_context.config.*.soil_layers];
                const litter_nitrous_oxide_index = 5 + driver_context.config.*.soil_layers;
                const ammonia_concentration = values[litter_nitrous_oxide_index + 1 ..][0..driver_context.config.*.soil_layers];
                for (0..driver_context.config.*.soil_layers) |local_layer| {
