            const ecosystem_carbon = try ecosys.soil_daily_ecosystem_carbon.calculate(.{
                .net_primary_productivity_g_c = ecosystem_net_primary_productivity_g,
                .signed_heterotrophic_respiration_g_c = driver_context.daily_heterotrophic_respiration.*.daily_signed_g_c[cell],
                .dissolved_organic_carbon_runoff_g_c = driver_context.daily_carbon_export.*.dissolved_organic_carbon_runoff_g[cell],
                .dissolved_inorganic_carbon_runoff_g_c = driver_context.daily_carbon_export.*.dissolved_inorganic_carbon_runoff_g[cell],
                .dissolved_organic_carbon_drainage_g_c = driver_context.daily_carbon_export.*.dissolved_organic_carbon_drainage_g[cell],
                .dissolved_inorganic_carbon_drainage_g_c = driver_context.daily_carbon_export.*.dissolved_inorganic_carbon_drainage_g[cell],
                .dissolved_organic_carbon_input_g_c = driver_context.daily_carbon_export.*.dissolved_organic_carbon_input_g[cell],
                .dissolved_inorganic_carbon_input_g_c = driver_context.daily_carbon_export.*.dissolved_inorganic_carbon_input_g[cell],
                .harvested_carbon_g_c = harvested_carbon_g,
                .organic_fertilizer_carbon_input_g_c = driver_context.daily_biome_organic_carbon_input_g_c.*[cell],
            });
            const first_layer = try driver_context.state.*.layerIndex(cell, 0);
            const layer_end = first_layer + driver_context.config.*.soil_layers;
            _ = try driver_context.visualization_streams.*.calculateAndWriteHourly(
                cell,
                driver_context.longitude_degrees_east_by_cell.*[cell],
                driver_context.latitude_degrees_north_by_cell.*[cell],
                .{
                    .year = accepted_context.current_year.*,
                    .day_of_year = accepted_context.current_day_of_year.*,
                    .month = accepted_context.management_date.*.month,
                    .day = accepted_context.management_date.*.day,
                    .hour = try accepted_context.timestamp.*.modelHourIndex(),
                },
                try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*),
                .{
                    .cell_area_m2 = driver_context.canopy_cell_area_m2.*[cell],
                    .species_cumulative_gross_carbon_g = driver_context.plant_daily_flux_ledger.*.gross_primary_productivity_g[first_plant..plant_end],
                    .species_cumulative_respired_carbon_g = driver_context.visualization_species_respired_carbon_g.*,
                    .ecosystem_gross_primary_productivity_g = ecosystem_gross_primary_productivity_g,
                    .ecosystem_net_primary_productivity_g = ecosystem_net_primary_productivity_g,
                    .ecosystem_autotrophic_respiration_g = -ecosystem_signed_autotrophic_respiration_g,
                    .ecosystem_heterotrophic_respiration_g = -driver_context.daily_heterotrophic_respiration.*.daily_signed_g_c[cell],
                    .net_biome_productivity_g = ecosystem_carbon.net_biome_productivity_g_c,
                    .carbon_dioxide_flux_g = driver_context.atmospheric_canopy_gas_state.*.cumulative_co2_exchange_g_c[cell],
                    .methane_flux_g = driver_context.atmospheric_canopy_gas_state.*.cumulative_ch4_exchange_g_c[cell],
                    .net_radiation_megajoules_h = driver_context.ecosystem_energy_ledger_state.*.ecosystem_net_radiation_megajoules[cell],
                    .latent_heat_flux_megajoules_h = driver_context.ecosystem_energy_ledger_state.*.ecosystem_latent_heat_megajoules[cell],
                    .sensible_heat_flux_megajoules_h = driver_context.ecosystem_energy_ledger_state.*.ecosystem_sensible_heat_megajoules[cell],
                    .liquid_water_m3_by_layer = driver_context.state.*.matrix_liquid_water_m3[first_layer..layer_end],
                    .air_volume_m3_by_layer = driver_context.state.*.matrix_air_volume_m3[first_layer..layer_end],
                    .macropore_water_m3_by_layer = driver_context.state.*.macropore_liquid_water_m3[first_layer..layer_end],
                    .total_volume_m3_by_layer = driver_context.soil_solver_property_state.*.layer_volume_m3[first_layer..layer_end],
                    .soil_temperature_k_by_layer = driver_context.state.*.soil_temperature_k[first_layer..layer_end],
                },
            );
        }
    }
}

noinline fn writeAcceptedDailyOutputs(driver_context: anytype, accepted_context: anytype) !void {
    if (accepted_context.scene_weather_hours.* % 24 == 0) {
        // The midnight step belongs to the completed day. Use the
        // previous step's timestamp to label this output correctly
        // regardless of whether the weather file uses hour 0000 or
        // hour 2400 for the day transition.
        const completed_day_of_year = try dayOfYearFromTimestamp(accepted_context.completed_day_timestamp.*.?);
        const completed_management_date = try ecosys.plant_management_dispatch.dateFromTimestamp(accepted_context.completed_day_timestamp.*.?);
        try driver_context.daily_ecosystem_carbon.*.finalizeDay(
            &driver_context.state.*,
            driver_context.config.*.plant_populations,
            driver_context.plant_daily_flux_ledger.*.gross_primary_productivity_g,
            driver_context.plant_daily_flux_ledger.*.signed_total_respiration_carbon_g,
            driver_context.plant_daily_flux_ledger.*.harvested_carbon_g,
            driver_context.daily_heterotrophic_respiration.*.daily_signed_g_c,
            driver_context.daily_biome_organic_carbon_input_g_c.*,
            &driver_context.daily_carbon_export.*,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedWater(
            driver_context.daily_water_ledger.*.rainfall_m3,
            driver_context.daily_water_ledger.*.boundary_water_inflow_m3,
            driver_context.daily_water_ledger.*.runoff_m3,
            driver_context.daily_water_ledger.*.evaporation_m3,
            driver_context.daily_water_ledger.*.water_outflow_m3,
            driver_context.daily_water_ledger.*.lateral_water_outflow_m3,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedFertilizer(
            driver_context.soil_fertilizer_inventory.*.daily_nitrogen_input_g_n,
            driver_context.daily_organic_fertilizer_nitrogen_input_g_n.*,
            driver_context.mineral_fertilizer_inventory.*.daily_phosphorus_input_g_p,
            driver_context.daily_organic_fertilizer_phosphorus_input_g_p.*,
            driver_context.daily_organic_fertilizer_carbon_input_g_c.*,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedExports(
            .{
                driver_context.daily_carbon_export.*.dissolved_organic_carbon_runoff_g,
                driver_context.daily_carbon_export.*.dissolved_inorganic_carbon_runoff_g,
                driver_context.daily_carbon_export.*.dissolved_organic_carbon_drainage_g,
                driver_context.daily_carbon_export.*.dissolved_inorganic_carbon_drainage_g,
            },
            .{
                driver_context.daily_nitrogen_export.*.dissolved_organic_nitrogen_runoff_g_n,
                driver_context.daily_nitrogen_export.*.dissolved_inorganic_nitrogen_runoff_g_n,
                driver_context.daily_nitrogen_export.*.dissolved_organic_nitrogen_drainage_g_n,
                driver_context.daily_nitrogen_export.*.dissolved_inorganic_nitrogen_drainage_g_n,
            },
            .{
                driver_context.daily_phosphorus_export.*.dissolved_organic_phosphorus_runoff_g_p,
                driver_context.daily_phosphorus_export.*.dissolved_inorganic_phosphorus_runoff_g_p,
                driver_context.daily_phosphorus_export.*.dissolved_organic_phosphorus_drainage_g_p,
                driver_context.daily_phosphorus_export.*.dissolved_inorganic_phosphorus_drainage_g_p,
            },
            driver_context.daily_heat_ledger.*.ionic_outflow_mol,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedIonTransportInputs(
            driver_context.daily_heat_ledger.*.ionic_inflow_mol,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedCarbonTransportInputs(
            driver_context.daily_carbon_export.*.dissolved_organic_carbon_input_g,
            driver_context.daily_carbon_export.*.dissolved_inorganic_carbon_input_g,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedNitrogenTransportInputs(
            driver_context.daily_nitrogen_export.*.dissolved_organic_nitrogen_input_g_n,
            driver_context.daily_nitrogen_export.*.dissolved_inorganic_nitrogen_input_g_n,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedPhosphorusTransportInputs(
            driver_context.daily_phosphorus_export.*.dissolved_organic_phosphorus_input_g_p,
            driver_context.daily_phosphorus_export.*.dissolved_inorganic_phosphorus_input_g_p,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedPlantLitter(
            driver_context.plant_daily_flux_ledger.*.carbon_sink_g,
            driver_context.plant_daily_flux_ledger.*.nitrogen_sink_g,
            driver_context.plant_daily_flux_ledger.*.phosphorus_sink_g,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedPlantHarvest(
            driver_context.plant_daily_flux_ledger.*.harvested_carbon_g,
            driver_context.plant_daily_flux_ledger.*.harvested_nitrogen_g,
            driver_context.plant_daily_flux_ledger.*.harvested_phosphorus_g,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedRootSoilOrganicExchange(
            driver_context.plant_daily_flux_ledger.*.root_soil_carbon_exchange_g,
            driver_context.plant_daily_flux_ledger.*.root_soil_nitrogen_exchange_g,
            driver_context.plant_daily_flux_ledger.*.root_soil_phosphorus_exchange_g,
        );
        // FIRE-NOX-BOUNDARY-001: gaseous nitrogen and phosphorus
        // emitted by soil and root combustion are computed and
        // accumulated into these two-cell ledger pairs (see the
        // fire block earlier this hour) but, before this call,
        // never reached the boundary ledger, so they vanished
        // from the landscape balance instead of leaving through
        // it like the REDIST ZN2GIN/TPIN debit they translate.
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedFireNutrientEmission(
            driver_context.daily_soil_fire_nitrogen_flux_g_n.*,
            driver_context.daily_root_fire_nitrogen_flux_g_n.*,
            driver_context.daily_soil_fire_phosphorus_flux_g_p.*,
            driver_context.daily_root_fire_phosphorus_flux_g_p.*,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedAtmosphericGas(
            &driver_context.daily_soil_gas_flux.*,
            &driver_context.daily_canopy_gas_exchange.*,
            driver_context.plant_daily_flux_ledger.*.ammonia_exchange_g_n,
            driver_context.plant_daily_flux_ledger.*.symbiotic_nitrogen_fixation_g,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedRedistSurfaceGas(
            try driver_context.daily_soil_gas_flux.*.getRedistSurfaceGasTotals(),
        );
        const atmospheric_parameters = driver_context.runscript.*.chemistry_primary_initialization.molar_mass_g_per_mol;
        const atmospheric_ion_molar_masses: ecosys.snow_surface_discharge.IonMolarMassesGPerMol = .{
            .aluminum = atmospheric_parameters.aluminum,
            .iron = atmospheric_parameters.iron,
            .calcium = atmospheric_parameters.calcium,
            .magnesium = atmospheric_parameters.magnesium,
            .sodium = atmospheric_parameters.sodium,
            .potassium = atmospheric_parameters.potassium,
            .sulfur = atmospheric_parameters.sulfur,
            .chloride = atmospheric_parameters.chloride,
        };
        try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedAtmosphericSolutes(
            &driver_context.atmospheric_solute_input_ledger_state.*,
            atmospheric_ion_molar_masses,
        );
        const completed_scene_day = accepted_context.scene_weather_hours.* / 24;
        const completed_scene_final_day = accepted_context.scene_weather_hours.* == accepted_context.scene_expected_hours.*;
        if (ecosys.mass_balance_audit.shouldAudit(true, completed_scene_final_day)) {
            const totals = try reconstructLandscapeMassBalance(
                driver_context.hourly_science_context.*,
            );
            const monitor = driver_context.landscape_mass_balance_state.*.monitor orelse
                return error.MassBalanceMonitorNotInitialized;
            {
                const area = totals.landscape_area_m2;
                const b = try ecosys.mass_balance_audit.balance(totals);
                std.log.debug("phosphorus day-end: residue={e} organic={e} phosphate={e} input={e} output={e} fertilizer={e} sink={e} total_g_m2={e}", .{ totals.residue_phosphorus_g / area, totals.organic_phosphorus_g / area, totals.phosphate_phosphorus_g / area, totals.cumulative_phosphorus_input_g / area, totals.cumulative_phosphorus_output_g / area, totals.cumulative_organic_fertilizer_phosphorus_g / area, totals.cumulative_phosphorus_sink_g / area, b.phosphorus_g / area });
                std.log.debug("nitrogen day-end: residue={e} organic={e} n2={e} nh4={e} no3={e} n2in={e} nin={e} nout={e} fert={e} sink={e} root_uptake={e} root_exudate={e} total_g_m2={e}", .{ totals.residue_nitrogen_g / area, totals.organic_nitrogen_g / area, totals.dinitrogen_nitrogen_g / area, totals.ammonium_nitrogen_g / area, totals.nitrate_nitrogen_g / area, totals.cumulative_dinitrogen_input_g / area, totals.cumulative_nitrogen_input_g / area, totals.cumulative_nitrogen_output_g / area, totals.cumulative_organic_fertilizer_nitrogen_g / area, totals.cumulative_nitrogen_sink_g / area, totals.cumulative_plant_root_organic_nitrogen_uptake_g / area, totals.cumulative_plant_root_organic_nitrogen_exudate_g / area, b.nitrogen_g / area });
                var diagnostic_gas_n_g: f64 = 0;
                var diagnostic_boundary_gas_n_g: f64 = 0;
                var diagnostic_don_runoff_g_n: f64 = 0;
                var diagnostic_din_runoff_g_n: f64 = 0;
                var diagnostic_don_drainage_g_n: f64 = 0;
                var diagnostic_din_drainage_g_n: f64 = 0;
                for (0..driver_context.state.*.cell_count) |cell| {
                    inline for (.{ ecosys.gas_transport.Species.nitrogen, .nitrous_oxide, .ammonia }) |species| {
                        diagnostic_gas_n_g += try driver_context.daily_soil_gas_flux.*.get(cell, species);
                        diagnostic_boundary_gas_n_g += try driver_context.daily_soil_gas_flux.*.getSoilLitterBoundary(cell, species);
                    }
                    diagnostic_don_runoff_g_n += driver_context.daily_nitrogen_export.*.dissolved_organic_nitrogen_runoff_g_n[cell];
                    diagnostic_din_runoff_g_n += driver_context.daily_nitrogen_export.*.dissolved_inorganic_nitrogen_runoff_g_n[cell];
                    diagnostic_don_drainage_g_n += driver_context.daily_nitrogen_export.*.dissolved_organic_nitrogen_drainage_g_n[cell];
                    diagnostic_din_drainage_g_n += driver_context.daily_nitrogen_export.*.dissolved_inorganic_nitrogen_drainage_g_n[cell];
                }
                std.log.debug("nitrogen boundary probe: gas_combined={e} gas_soil_litter={e} don_runoff={e} din_runoff={e} don_drainage={e} din_drainage={e}", .{ diagnostic_gas_n_g / area, diagnostic_boundary_gas_n_g / area, diagnostic_don_runoff_g_n / area, diagnostic_din_runoff_g_n / area, diagnostic_don_drainage_g_n / area, diagnostic_din_drainage_g_n / area });
            }
            _ = try monitor.check(
                completed_scene_day,
                accepted_context.current_year.*,
                totals,
            );
        }
        if (@mod(completed_scene_day, accepted_context.active_options.*.daily_output_interval_days) == 0) {
            try writeAcceptedDailyCarbonOutput(driver_context, accepted_context, completed_day_of_year, completed_management_date);
            try writeAcceptedDailyWaterOutput(driver_context, accepted_context, completed_day_of_year, completed_management_date);
            try writeAcceptedDailySoilNitrogenOutput(driver_context, accepted_context, completed_day_of_year, completed_management_date);
            try writeAcceptedDailySoilPhosphorusOutput(driver_context, accepted_context, completed_day_of_year, completed_management_date);
            try writeAcceptedDailySoilHeatOutput(driver_context, accepted_context, completed_day_of_year, completed_management_date);
            try writeAcceptedDailyPlantOutputs(driver_context, accepted_context, completed_day_of_year, completed_management_date);
        }
        try writeAcceptedDailyVisualizationOutput(driver_context, accepted_context, completed_day_of_year, completed_management_date);
        try closeAndResetAcceptedDay(driver_context, accepted_context, completed_day_of_year);
    }
}

noinline fn writeAcceptedDailyCarbonOutput(
    driver_context: anytype,
    accepted_context: anytype,
    completed_day_of_year: anytype,
    completed_management_date: anytype,
) !void {
    const carbon_editor_index: usize = 5;
    const carbon_editor_name = accepted_context.scene.*.output_editors[carbon_editor_index];
    if (!ecosys.delimited_input.isNo(carbon_editor_name)) {
        const resolved = driver_context.resolved_output_editors.*[accepted_context.pass.*.scene_index * 10 + carbon_editor_index] orelse return error.UnresolvedDailyPlantCarbonEditor;
        if (std.mem.indexOfScalar(bool, resolved.soil_enabled, true) != null) {
            const selection_index = driver_context.output_selection_catalog.*.find(carbon_editor_name) orelse return error.MissingOutputSelection;
            const selection = driver_context.output_selection_catalog.*.entries.items[selection_index].selection;
            for (0..driver_context.state.*.cell_count) |cell| {
                const values = try driver_context.daily_soil_carbon_bank.*.row(cell);
                @memset(values, std.math.nan(f64));
                const first_layer = try driver_context.state.*.layerIndex(cell, 0);
                const active_layers = driver_context.state.*.active_soil_layer_count[cell];
                const layer_carbon = driver_context.daily_soil_organic_carbon_by_layer_g_c.*[first_layer .. first_layer + driver_context.config.*.soil_layers];
                @memset(layer_carbon, 0);
                const pools = try ecosys.soil_daily_carbon_pools.calculate(
                    &driver_context.soil_organic_state.*,
                    &driver_context.surface_organic_state.*,
                    first_layer,
                    active_layers,
                    cell,
                    layer_carbon[0..active_layers],
                );
                const plant_flux = try ecosys.soil_daily_plant_carbon_flux.calculate(&driver_context.plant_daily_flux_ledger.*, cell, driver_context.config.*.plant_populations);
                var gas_inventory_g: [ecosys.gas_transport.species_count]f64 = @splat(0);
                for (0..active_layers) |local_layer| {
                    const layer = first_layer + local_layer;
                    for (0..ecosys.gas_transport.species_count) |species| {
                        const component = layer * ecosys.gas_transport.species_count + species;
                        gas_inventory_g[species] +=
                            driver_context.gas_transport_state.*.gaseous_mass_g[component] +
                            driver_context.gas_transport_state.*.dissolved_mass_g[component] +
                            driver_context.gas_transport_state.*.macropore_dissolved_mass_g[component] +
                            driver_context.gas_transport_state.*.band_dissolved_mass_g[component];
                    }
                }
                for (0..ecosys.gas_transport.species_count) |species| {
                    const component = cell * ecosys.gas_transport.species_count + species;
                    gas_inventory_g[species] +=
                        driver_context.litter_gas_transport_state.*.gaseous_mass_g[component] +
                        driver_context.litter_gas_transport_state.*.dissolved_mass_g[component] +
                        driver_context.litter_gas_transport_state.*.macropore_dissolved_mass_g[component] +
                        driver_context.litter_gas_transport_state.*.band_dissolved_mass_g[component];
                }
                const area_inverse = 1.0 / driver_context.canopy_cell_area_m2.*[cell];
                values[0] = pools.residue_carbon_g_c * area_inverse;
                values[1] = pools.humus_carbon_g_c * area_inverse;
                values[2] = driver_context.daily_organic_fertilizer_carbon_input_g_c.*[cell] * area_inverse;
                values[3] = plant_flux.plant_litterfall_g_c * area_inverse;
                values[4] = (try driver_context.daily_soil_gas_flux.*.getSoilLitterBoundary(cell, .carbon_dioxide)) * area_inverse;
                values[5] = (try driver_context.daily_soil_gas_flux.*.getSoilLitterBoundary(cell, .oxygen)) * area_inverse;
                values[6] = driver_context.daily_heterotrophic_respiration.*.daily_carbon_dioxide_production_g_c[cell] * area_inverse;
                values[7] = pools.microbial_carbon_g_c * area_inverse;
                values[8] = pools.surface_noncharcoal_organic_carbon_g_c * area_inverse;
                values[9] = (try driver_context.daily_soil_gas_flux.*.getSoilLitterBoundary(cell, .methane)) * area_inverse;
                values[10] = driver_context.daily_carbon_export.*.dissolved_organic_carbon_runoff_g[cell] / driver_context.total_grid_area_m2.*;
                values[11] = driver_context.daily_carbon_export.*.dissolved_organic_carbon_drainage_g[cell] / driver_context.total_grid_area_m2.*;
                values[12] = driver_context.daily_carbon_export.*.dissolved_inorganic_carbon_runoff_g[cell] / driver_context.total_grid_area_m2.*;
                values[13] = driver_context.daily_carbon_export.*.dissolved_inorganic_carbon_drainage_g[cell] / driver_context.total_grid_area_m2.*;
                values[14] = driver_context.atmospheric_canopy_gas_state.*.canopy_co2_umol_mol[cell];
                values[15] = driver_context.daily_ecosystem_carbon.*.net_biome_productivity_g_c[cell] * area_inverse;
                values[16] = (driver_context.daily_soil_fire_carbon_dioxide_emission_g_c.*[cell] + driver_context.daily_root_fire_carbon_dioxide_emission_g_c.*[cell]) * area_inverse;
                for (0..driver_context.config.*.soil_layers) |layer| values[17 + layer] = layer_carbon[layer] * area_inverse;
                const after_layers = 17 + driver_context.config.*.soil_layers;
                values[after_layers] = driver_context.daily_soil_fire_charcoal_production_g_c.*[cell] * area_inverse;
                // OUTSD 33--35 are the exact REDIST/DAY
                // ZCNET/ZHNET/ZONET accumulators.
                values[after_layers + 1] = driver_context.atmospheric_canopy_gas_state.*.cumulative_co2_exchange_g_c[cell] * area_inverse;
                values[after_layers + 2] = driver_context.atmospheric_canopy_gas_state.*.cumulative_ch4_exchange_g_c[cell] * area_inverse;
                values[after_layers + 3] = driver_context.atmospheric_canopy_gas_state.*.cumulative_o2_exchange_g_o[cell] * area_inverse;
                // OUTSD choices 36..40 are source-reserved zeros.
                @memset(values[after_layers + 4 .. after_layers + 9], 0);
                const tail = after_layers + 9;
                // OUTSD choice 41 is UH2GG: accepted daily
                // ecosystem-atmosphere H2 exchange, not
                // the end-of-day H2 storage inventory.
                values[tail] = try ecosys.soil_daily_output.dailyHydrogenFluxGPerM2(
                    &driver_context.daily_soil_gas_flux.*,
                    cell,
                    driver_context.canopy_cell_area_m2.*[cell],
                );
                values[tail + 1] = plant_flux.harvested_carbon_g_c * area_inverse;
                // With no active plant branches, OUTSD ARLFC and WTSTGT
                // are both authoritative zero-valued ecosystem pools.
                values[tail + 2] = 0;
                values[tail + 9] = 0;
                if (driver_context.detailed_canopy_state.*) |canopy| {
                    var total_leaf_area_m2: f64 = 0;
                    for (0..driver_context.config.*.plant_populations) |species| {
                        const plant = cell * driver_context.config.*.plant_populations + species;
                        const branches = try canopy.branchRange(plant);
                        for (canopy.branch_leaf_area_m2[branches.first..branches.end]) |leaf_area_m2| total_leaf_area_m2 += leaf_area_m2;
                    }
                    values[tail + 2] = total_leaf_area_m2 * area_inverse;
                    values[tail + 9] =
                        driver_context.cell_litter_standing_dead_state_update_state.*
                            .standing_dead_carbon_g_c_by_cell[cell] *
                        area_inverse;
                }
                values[tail + 3] = plant_flux.gross_primary_productivity_g_c * area_inverse;
                values[tail + 4] = plant_flux.autotrophic_respiration_g_c * area_inverse;
                values[tail + 5] = plant_flux.net_primary_productivity_g_c * area_inverse;
                values[tail + 6] = driver_context.daily_heterotrophic_respiration.*.daily_signed_g_c[cell] * area_inverse;
                values[tail + 7] = (driver_context.daily_soil_fire_methane_emission_g_c.*[cell] + driver_context.daily_root_fire_methane_emission_g_c.*[cell]) * area_inverse;
                const active_carbonate = driver_context.daily_soil_carbonate_mol_per_m3.*[first_layer .. first_layer + active_layers];
                const active_bicarbonate = driver_context.daily_soil_bicarbonate_mol_per_m3.*[first_layer .. first_layer + active_layers];
                const active_carbonate_complexes = driver_context.daily_soil_carbonate_complexes_mol_per_m3.*[first_layer .. first_layer + active_layers];
                const active_calcite = driver_context.daily_soil_calcite_mol_per_m3.*[first_layer .. first_layer + active_layers];
                for (0..active_layers) |local_layer| {
                    const layer = first_layer + local_layer;
                    const aqueous = driver_context.initial_chemistry_state.*.aqueous[layer];
                    active_carbonate[local_layer] = aqueous.carbonate;
                    active_bicarbonate[local_layer] = aqueous.bicarbonate;
                    active_carbonate_complexes[local_layer] =
                        aqueous.calcium_carbonate + aqueous.calcium_bicarbonate +
                        aqueous.magnesium_carbonate + aqueous.magnesium_bicarbonate +
                        aqueous.sodium_carbonate;
                    active_calcite[local_layer] = driver_context.initial_chemistry_state.*.geochemistry_solids[layer].calcite_solid_mol_per_m3;
                }
                const litter_aqueous = driver_context.surface_litter_chemistry_state.*.cells[cell];
                const litter_aqueous_carrier_m3 = try ecosys.surface_litter_chemistry_carrier_rebase.effectiveAqueousCarrierM3(
                    driver_context.surface_precipitation_state.*.litter_water_m3[cell],
                    driver_context.surface_litter_chemistry_state.*.dry_reference_water_m3[cell],
                );
                values[tail + 8] = try ecosys.soil_inorganic_carbon_storage.calculate(.{
                    .carbon_dioxide_and_methane_g_c = gas_inventory_g[@intFromEnum(ecosys.gas_transport.Species.carbon_dioxide)] +
                        gas_inventory_g[@intFromEnum(ecosys.gas_transport.Species.methane)],
                    .soil_water_volume_m3 = driver_context.state.*.matrix_liquid_water_m3[first_layer .. first_layer + active_layers],
                    .soil_bulk_volume_m3 = driver_context.soil_solver_property_state.*.matrix_bulk_volume_m3[first_layer .. first_layer + active_layers],
                    .carbonate_mol_per_m3 = active_carbonate,
                    .bicarbonate_mol_per_m3 = active_bicarbonate,
                    .dissolved_carbonate_complexes_mol_per_m3 = active_carbonate_complexes,
                    .calcite_mol_per_m3 = active_calcite,
                    .litter_water_volume_m3 = litter_aqueous_carrier_m3,
                    .litter_carbonate_mol_per_m3 = litter_aqueous.carbonate_mol_per_m3,
                    .litter_bicarbonate_mol_per_m3 = litter_aqueous.bicarbonate_mol_per_m3,
                    .litter_dissolved_carbonate_complexes_mol_per_m3 = 0,
                    .litter_calcite_mol_per_m3 = litter_aqueous.salt_minerals.calcite_mol_per_m3,
                    .litter_mineral_reference_volume_m3 = driver_context.surface_litter_chemistry_state.*.mineral_reference_water_m3[cell],
                }) * area_inverse;
                for (resolved.soil_enabled, values, 0..) |enabled, value, choice| if (enabled and !std.math.isFinite(value)) {
                    const name = driver_context.daily_soil_carbon_catalog.*.variables[choice].name;
                    if (std.mem.startsWith(u8, name, "reserved_zero_")) {
                        values[choice] = 0;
                    } else {
                        std.log.err("daily soil carbon choice is not yet backed by an authoritative translated owner: choice={d} name={s}", .{ choice + 1, name });
                        return error.UntranslatedDailySoilCarbonChoice;
                    }
                };
                const file_name = try ecosys.output_record.buildOutputFileName(driver_context.allocator.*, driver_context.latitude_degrees_north_by_cell.*[cell], driver_context.longitude_degrees_east_by_cell.*[cell], .soil_or_eco, accepted_context.current_year.*, try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*), cell + 1, carbon_editor_name);
                defer driver_context.allocator.*.free(file_name);
                _ = try driver_context.daily_soil_carbon_bank.*.streams[cell].write(file_name, driver_context.daily_soil_carbon_catalog.*.variables, selection, resolved.soil_enabled, .{
                    .timestamp = .{ .year = accepted_context.current_year.*, .day_of_year = completed_day_of_year, .month = completed_management_date.month, .day = completed_management_date.day, .hour = 23 },
                    .longitude_degrees_east = driver_context.longitude_degrees_east_by_cell.*[cell],
                    .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
                    .values = values,
                });
            }
        }
        if (std.mem.indexOfScalar(bool, resolved.plant_enabled, true) != null) {
            const selection_index = driver_context.output_selection_catalog.*.find(carbon_editor_name) orelse return error.MissingOutputSelection;
            const selection = driver_context.output_selection_catalog.*.entries.items[selection_index].selection;
            const canopy = if (driver_context.detailed_canopy_state.*) |*value| value else return error.DailyPlantCarbonOutputRequiresCanopyState;
            const roots = if (driver_context.plant_root_state.*) |*value| value else return error.DailyPlantCarbonOutputRequiresRootState;
            for (0..driver_context.state.*.cell_count) |cell| for (0..driver_context.config.*.plant_populations) |species| {
                const plant = try canopy.plantIndex(cell, species);
                const branches = try canopy.branchRange(plant);
                const values = try driver_context.daily_plant_carbon_bank.*.row(plant);
                const root_profile = values[20 .. 20 + driver_context.config.*.soil_layers];
                @memset(root_profile, 0);
                var root_symbiont_carbon_g: f64 = 0;
                for (0..driver_context.config.*.soil_layers) |layer| {
                    for (0..driver_context.root_metabolism_plant_parameters.*[plant].biologicalDomainCount()) |domain| {
                        const root = try roots.layerIndex(plant, domain, layer);
                        root_profile[layer] += roots.mobile_carbon_g[root];
                        root_symbiont_carbon_g +=
                            roots.symbiont_structural_carbon_g_c[root] +
                            roots.symbiont_mobile_carbon_g_c[root];
                        for (0..roots.active_root_axis_count[plant]) |axis| {
                            const axis_layer = try roots.layerAxisIndex(plant, domain, layer, axis);
                            root_profile[layer] += roots.axis_primary_carbon_g[axis_layer] + roots.axis_secondary_carbon_g[axis_layer];
                        }
                    }
                }
                var leaf_intermediate_carbon_g: f64 = 0;
                var canopy_symbiont_carbon_g: f64 = 0;
                var projected_leaf_area_m2: f64 = 0;
                for (branches.first..branches.end) |branch| {
                    canopy_symbiont_carbon_g +=
                        canopy.branch_symbiont_structural_carbon_g[branch] +
                        canopy.branch_symbiont_mobile_carbon_g[branch];
                    projected_leaf_area_m2 += canopy.branch_leaf_area_m2[branch];
                    const nodes = try canopy.nodeRange(branch);
                    for (nodes.first..nodes.end) |node| {
                        leaf_intermediate_carbon_g +=
                            canopy.node_c3_nonstructural_carbon_g[node] +
                            canopy.node_c4_mesophyll_nonstructural_carbon_g[node] +
                            canopy.node_bundle_sheath_co2_carbon_g[node] +
                            canopy.node_bundle_sheath_bicarbonate_carbon_g[node];
                    }
                }
                const primary_root_first = try roots.layerIndex(plant, 0, 0);
                const pools = try ecosys.plant_daily_pool_aggregation.calculateCarbonInto(.{
                    .branch_leaf_carbon_g = canopy.branch_leaf_carbon_g[branches.first..branches.end],
                    .branch_sheath_carbon_g = canopy.branch_sheath_carbon_g[branches.first..branches.end],
                    .branch_stalk_carbon_g = canopy.branch_stalk_carbon_g[branches.first..branches.end],
                    .branch_reserve_carbon_g = canopy.branch_reserve_carbon_g[branches.first..branches.end],
                    .branch_husk_carbon_g = canopy.branch_husk_carbon_g[branches.first..branches.end],
                    .branch_ear_carbon_g = canopy.branch_ear_carbon_g[branches.first..branches.end],
                    .branch_grain_carbon_g = canopy.branch_grain_carbon_g[branches.first..branches.end],
                    .branch_mobile_carbon_g = canopy.branch_mobile_carbon_g[branches.first..branches.end],
                    .branch_seed_count = canopy.branch_seed_count[branches.first..branches.end],
                    .c4_intermediate_carbon_g = leaf_intermediate_carbon_g,
                    .canopy_symbiont_carbon_g = canopy_symbiont_carbon_g,
                    .root_carbon_g_by_layer = root_profile,
                    .primary_root_length_density_m_per_m3_by_layer = roots.root_length_density_m_per_m3[primary_root_first .. primary_root_first + driver_context.config.*.soil_layers],
                    .root_symbiont_carbon_g = root_symbiont_carbon_g,
                    .standing_dead_carbon_g = canopy.plant_standing_dead_carbon_g[plant],
                    .seed_storage_carbon_g = canopy.plant_seed_storage_carbon_g[plant],
                    .projected_leaf_area_m2 = projected_leaf_area_m2,
                    .plant_population_count = canopy.plant_population_count[plant],
                }, root_profile);
                const net_primary_productivity_g =
                    driver_context.plant_daily_flux_ledger.*.net_carbon_change_g[plant] +
                    driver_context.plant_daily_flux_ledger.*.signed_total_respiration_carbon_g[plant];
                const carbon_balance_inputs: ecosys.plant_daily_output.CarbonBalanceInputs = .{
                    .shoot_carbon_g = pools.shoot_carbon_g,
                    .root_carbon_g = pools.root_carbon_g,
                    .nodule_carbon_g = pools.nodule_carbon_g,
                    .storage_carbon_g = pools.storage_carbon_g,
                    .standing_dead_carbon_g = pools.vegetative_residue_carbon_g,
                    .cumulative_carbon_sink_g = driver_context.plant_daily_flux_ledger.*.carbon_sink_g[plant],
                    .cumulative_root_soil_carbon_exchange_g = driver_context.plant_daily_flux_ledger.*.root_soil_carbon_exchange_g[plant],
                    .cumulative_carbon_balance_g = driver_context.plant_daily_flux_ledger.*.cumulative_carbon_balance_g[plant],
                    .cumulative_harvested_carbon_g = driver_context.plant_daily_flux_ledger.*.cumulative_harvested_carbon_g[plant],
                    .harvested_carbon_g = driver_context.plant_daily_flux_ledger.*.harvested_carbon_g[plant],
                    .carbon_oxidation_g = driver_context.plant_daily_flux_ledger.*.carbon_oxidation_g[plant],
                    .cumulative_net_primary_productivity_g = net_primary_productivity_g,
                };
                driver_context.plant_balance_carbon_inputs_workspace.*[plant] = carbon_balance_inputs;
                const balance_carbon_g = try ecosys.plant_daily_output.carbonBalance(carbon_balance_inputs);
                try ecosys.plant_daily_output.calculateCarbonInto(.{
                    .cell_area_m2 = driver_context.canopy_cell_area_m2.*[cell],
                    .shoot_carbon_g = pools.shoot_carbon_g,
                    .leaf_carbon_g = pools.leaf_carbon_g,
                    .sheath_carbon_g = pools.sheath_carbon_g,
                    .stalk_carbon_g = pools.stalk_carbon_g,
                    .reserve_carbon_g = pools.reserve_carbon_g,
                    .husk_carbon_g = pools.husk_carbon_g,
                    .ear_carbon_g = pools.ear_carbon_g,
                    .grain_carbon_g = pools.grain_carbon_g,
                    .root_carbon_g = pools.root_carbon_g,
                    .nodule_carbon_g = pools.nodule_carbon_g,
                    .vegetative_residue_carbon_g = pools.vegetative_residue_carbon_g,
                    .grain_number = pools.grain_number,
                    .projected_leaf_area_m2 = pools.projected_leaf_area_m2,
                    .daily_net_carbon_change_g = driver_context.plant_daily_flux_ledger.*.net_carbon_change_g[plant],
                    .cumulative_carbon_uptake_g = driver_context.plant_daily_flux_ledger.*.root_soil_carbon_exchange_g[plant],
                    .cumulative_carbon_sink_g = driver_context.plant_daily_flux_ledger.*.carbon_sink_g[plant],
                    .initial_cumulative_carbon_sink_g = driver_context.plant_daily_flux_ledger.*.initial_carbon_sink_g[plant],
                    .signed_total_respiration_carbon_g = driver_context.plant_daily_flux_ledger.*.signed_total_respiration_carbon_g[plant],
                    .signed_aboveground_respiration_carbon_g = driver_context.plant_daily_flux_ledger.*.signed_aboveground_respiration_carbon_g[plant],
                    .carbon_pollination_factor = canopy.plant_mobile_carbon_concentration_g_per_g[plant],
                    .harvested_carbon_g = driver_context.plant_daily_flux_ledger.*.harvested_carbon_g[plant],
                    .root_length_density_m_per_m3_by_layer = root_profile,
                    .plant_population = canopy.plant_population_count[plant],
                    .balance_carbon_g = balance_carbon_g,
                    .storage_carbon_g = pools.storage_carbon_g,
                    .carbon_oxidation_flux_g = driver_context.plant_daily_flux_ledger.*.carbon_oxidation_g[plant],
                    .net_primary_productivity_g = net_primary_productivity_g,
                    .canopy_height_m = driver_context.development_canopy_height_m.*[plant],
                }, values);
                // Only assigned species produce output; an unassigned population
                // would emit all-zero rows, so no file is created for it.
                const species_label = outputSpeciesLabel(driver_context.plant_assignments.*, driver_context.plant_unit_by_cell.*, cell, species) orelse continue;
                const file_name = try ecosys.output_record.buildOutputFileName(driver_context.allocator.*, driver_context.latitude_degrees_north_by_cell.*[cell], driver_context.longitude_degrees_east_by_cell.*[cell], .{ .species = .{ .name = species_label, .population_number = species + 1 } }, accepted_context.current_year.*, try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*), cell + 1, carbon_editor_name);
                defer driver_context.allocator.*.free(file_name);
                _ = try driver_context.daily_plant_carbon_bank.*.streams[plant].write(file_name, driver_context.daily_plant_carbon_catalog.*.variables, selection, resolved.plant_enabled, .{
                    .timestamp = .{ .year = accepted_context.current_year.*, .day_of_year = completed_day_of_year, .month = completed_management_date.month, .day = completed_management_date.day, .hour = 23 },
                    .longitude_degrees_east = driver_context.longitude_degrees_east_by_cell.*[cell],
                    .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
                    .values = values,
                });
            };
        }
    }
}

noinline fn writeAcceptedDailyWaterOutput(
    driver_context: anytype,
    accepted_context: anytype,
    completed_day_of_year: anytype,
    completed_management_date: anytype,
) !void {
    const editor_index: usize = 6;
    const editor_name = accepted_context.scene.*.output_editors[editor_index];
    if (!ecosys.delimited_input.isNo(editor_name)) {
        const resolved = driver_context.resolved_output_editors.*[accepted_context.pass.*.scene_index * 10 + editor_index] orelse return error.UnresolvedDailySoilWaterEditor;
        if (std.mem.indexOfScalar(bool, resolved.soil_enabled, true) != null) {
            const selection_index = driver_context.output_selection_catalog.*.find(editor_name) orelse return error.MissingOutputSelection;
            const selection = driver_context.output_selection_catalog.*.entries.items[selection_index].selection;
            const liquid_fraction = driver_context.daily_water_profile_workspace.*[0..driver_context.config.*.soil_layers];
            const ice_fraction = driver_context.daily_water_profile_workspace.*[driver_context.config.*.soil_layers .. 2 * driver_context.config.*.soil_layers];
            const potential_count = dailySoilWaterPotentialLayerCount(driver_context.config.*.soil_layers);
            const matric_plus_osmotic_potential = driver_context.daily_water_profile_workspace.*[2 * driver_context.config.*.soil_layers ..][0..potential_count];
            for (0..driver_context.state.*.cell_count) |cell| {
                var soil_water_storage_m3: f64 = 0;
                for (0..driver_context.config.*.soil_layers) |local_layer| {
                    const layer = try driver_context.state.*.layerIndex(cell, local_layer);
                    const layer_volume_m3 = driver_context.soil_solver_property_state.*.layer_volume_m3[layer];
                    if (!std.math.isFinite(layer_volume_m3) or layer_volume_m3 <= 0) return error.InvalidOutputSoilLayerVolume;
                    liquid_fraction[local_layer] = driver_context.state.*.liquid_water_m3[layer] / layer_volume_m3;
                    ice_fraction[local_layer] = driver_context.state.*.ice_water_m3[layer] / driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.ice_density_megagrams_per_m3 / layer_volume_m3;
                    soil_water_storage_m3 += driver_context.state.*.liquid_water_m3[layer] +
                        driver_context.state.*.water_vapor_volume_m3[layer] +
                        driver_context.state.*.ice_water_m3[layer];
                    if (local_layer < potential_count) matric_plus_osmotic_potential[local_layer] = driver_context.soil_hourly_workspace.*.matric_plus_osmotic_potential_megapascal[layer];
                }
                const snow_base = cell * driver_context.snow_transport_state.*.layer_capacity;
                for (0..driver_context.snow_transport_state.*.layer_capacity) |snow_layer| {
                    const snow = snow_base + snow_layer;
                    soil_water_storage_m3 += driver_context.snow_transport_state.*.solid_snow_water_equivalent_m3[snow] +
                        driver_context.snow_transport_state.*.liquid_water_volume_m3[snow] +
                        driver_context.snow_transport_state.*.vapor_water_equivalent_m3[snow] +
                        driver_context.snow_transport_state.*.ice_volume_m3[snow] * driver_context.runscript.*.snow_ice_density_megagrams_per_m3;
                }
                soil_water_storage_m3 +=
                    driver_context.surface_precipitation_state.*.litter_water_m3[cell] +
                    driver_context.surface_litter_ice_m3.*[cell];
                for (0..driver_context.config.*.plant_populations) |species| {
                    const plant = cell * driver_context.config.*.plant_populations + species;
                    soil_water_storage_m3 += driver_context.plant_state.*.canopy_water_storage_m_per_m2[plant] * driver_context.canopy_cell_area_m2.*[cell];
                    if (driver_context.canopy_precipitation_retention_state.*) |retention| {
                        soil_water_storage_m3 += retention.living_surface_water_m3[plant] + retention.standing_dead_surface_water_m3[plant];
                    }
                }
                const litter_capacity_m3 = driver_context.surface_precipitation_state.*.litter_water_capacity_m3[cell];
                const surface_litter_thickness_m =
                    driver_context.surface_litter_geometry_state.*.expanded_total_volume_m3[cell] /
                    driver_context.canopy_cell_area_m2.*[cell];
                if (!std.math.isFinite(surface_litter_thickness_m) or
                    surface_litter_thickness_m < 0)
                    return error.InvalidOutputSurfaceLitterThickness;
                const active_boundary_base = cell * (driver_context.soil_geometry_state.*.layer_capacity + 1);
                const active_surface_depth_m = driver_context.soil_geometry_state.*.boundary_depth_m[active_boundary_base + driver_context.soil_geometry_state.*.first_active_layer[cell]];
                const values = try driver_context.daily_soil_water_bank.*.row(cell);
                try ecosys.soil_daily_output.calculateWaterInto(.{
                    .cell_area_m2 = driver_context.canopy_cell_area_m2.*[cell],
                    .grid_area_m2 = driver_context.total_grid_area_m2.*,
                    .rainfall_m3 = driver_context.daily_water_ledger.*.rainfall_m3[cell],
                    .evaporation_m3 = driver_context.daily_water_ledger.*.evaporation_m3[cell],
                    .runoff_m3 = driver_context.daily_water_ledger.*.runoff_m3[cell],
                    .soil_water_storage_m3 = soil_water_storage_m3,
                    .outflow_m3 = driver_context.daily_water_ledger.*.water_outflow_m3[cell],
                    .snow_depth_m = driver_context.snow_depth_m.*[cell],
                    .liquid_water_fraction_by_layer = liquid_fraction,
                    .surface_excess_liquid_water_depth_m = @max(
                        0,
                        (driver_context.surface_precipitation_state.*.litter_water_m3[cell] -
                            litter_capacity_m3) /
                            driver_context.canopy_cell_area_m2.*[cell],
                    ),
                    .ice_fraction_by_layer = ice_fraction,
                    .surface_excess_ice_water_depth_m = @max(
                        0,
                        (driver_context.surface_litter_ice_m3.*[cell] -
                            litter_capacity_m3) /
                            driver_context.canopy_cell_area_m2.*[cell],
                    ),
                    .matric_plus_osmotic_potential_mpa_by_layer = matric_plus_osmotic_potential,
                    .surface_matric_potential_megapascal = driver_context.surface_litter_water_environment_state.*.matric_water_potential_megapascal[cell],
                    .lateral_water_outflow_m3 = driver_context.daily_water_ledger.*.lateral_water_outflow_m3[cell],
                    .sediment_outflow_m3 = driver_context.daily_water_ledger.*.sediment_outflow_m3[cell],
                    .mineral_soil_surface_depth_m = active_surface_depth_m,
                    .surface_litter_thickness_m = surface_litter_thickness_m,
                    .active_layer_bottom_depth_m = driver_context.soil_boundary_topology_state.*.active_layer_depth_m[cell],
                    .water_table_depth_m = driver_context.soil_boundary_topology_state.*.internal_water_table_depth_m[cell],
                }, values);
                const file_name = try ecosys.output_record.buildOutputFileName(driver_context.allocator.*, driver_context.latitude_degrees_north_by_cell.*[cell], driver_context.longitude_degrees_east_by_cell.*[cell], .soil_or_eco, accepted_context.current_year.*, try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*), cell + 1, editor_name);
                defer driver_context.allocator.*.free(file_name);
                _ = try driver_context.daily_soil_water_bank.*.streams[cell].write(file_name, driver_context.daily_soil_water_catalog.*.variables, selection, resolved.soil_enabled, .{
                    .timestamp = .{ .year = accepted_context.current_year.*, .day_of_year = completed_day_of_year, .month = completed_management_date.month, .day = completed_management_date.day, .hour = 23 },
                    .longitude_degrees_east = driver_context.longitude_degrees_east_by_cell.*[cell],
                    .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
                    .values = values,
                });
            }
        }
    }
    if (!ecosys.delimited_input.isNo(editor_name)) {
        const resolved = driver_context.resolved_output_editors.*[accepted_context.pass.*.scene_index * 10 + editor_index] orelse return error.UnresolvedDailyPlantWaterEditor;
        if (std.mem.indexOfScalar(bool, resolved.plant_enabled, true) != null) {
            const selection_index = driver_context.output_selection_catalog.*.find(editor_name) orelse return error.MissingOutputSelection;
            const selection = driver_context.output_selection_catalog.*.entries.items[selection_index].selection;
            const growth = if (driver_context.plant_growth_stage_state.*) |*value| value else return error.DailyPlantWaterOutputRequiresGrowthStageState;
            const dormancy = if (driver_context.plant_dormancy_state.*) |*value| value else return error.DailyPlantWaterOutputRequiresDormancyState;
            for (0..driver_context.state.*.cell_count) |cell| for (0..driver_context.config.*.plant_populations) |species| {
                const plant = cell * driver_context.config.*.plant_populations + species;
                const output = try ecosys.plant_daily_output.water(
                    driver_context.plant_water_state_update_state.*.cumulative_water_source_m3_by_plant[plant],
                    try ecosys.plant_development.coldOrWaterStressHours(growth, dormancy, plant),
                    driver_context.phenology_root_oxygen_fraction.*[plant],
                    driver_context.plant_state.*.canopy_water_storage_m_per_m2[plant] * driver_context.canopy_cell_area_m2.*[cell],
                    driver_context.canopy_cell_area_m2.*[cell],
                );
                const values = try driver_context.daily_plant_water_bank.*.row(plant);
                values[0] = output.transpiration_mm;
                values[1] = output.cold_or_water_stress_h;
                values[2] = output.oxygen_stress_factor;
                values[3] = output.plant_water_storage_mm;
                // Only assigned species produce output; an unassigned population
                // would emit all-zero rows, so no file is created for it.
                const species_label = outputSpeciesLabel(driver_context.plant_assignments.*, driver_context.plant_unit_by_cell.*, cell, species) orelse continue;
                const file_name = try ecosys.output_record.buildOutputFileName(driver_context.allocator.*, driver_context.latitude_degrees_north_by_cell.*[cell], driver_context.longitude_degrees_east_by_cell.*[cell], .{ .species = .{ .name = species_label, .population_number = species + 1 } }, accepted_context.current_year.*, try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*), cell + 1, editor_name);
                defer driver_context.allocator.*.free(file_name);
                _ = try driver_context.daily_plant_water_bank.*.streams[plant].write(file_name, driver_context.daily_plant_water_catalog.*.variables, selection, resolved.plant_enabled, .{
                    .timestamp = .{ .year = accepted_context.current_year.*, .day_of_year = completed_day_of_year, .month = completed_management_date.month, .day = completed_management_date.day, .hour = 23 },
                    .longitude_degrees_east = driver_context.longitude_degrees_east_by_cell.*[cell],
                    .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
                    .values = values,
                });
            };
        }
    }
}

noinline fn writeAcceptedDailySoilNitrogenOutput(
    driver_context: anytype,
    accepted_context: anytype,
    completed_day_of_year: anytype,
    completed_management_date: anytype,
) !void {
    const soil_nitrogen_editor_index: usize = 7;
    const soil_nitrogen_editor_name = accepted_context.scene.*.output_editors[soil_nitrogen_editor_index];
    if (!ecosys.delimited_input.isNo(soil_nitrogen_editor_name)) {
        const resolved = driver_context.resolved_output_editors.*[accepted_context.pass.*.scene_index * 10 + soil_nitrogen_editor_index] orelse return error.UnresolvedDailySoilNitrogenEditor;
        if (std.mem.indexOfScalar(bool, resolved.soil_enabled, true) != null) {
            const selection_index = driver_context.output_selection_catalog.*.find(soil_nitrogen_editor_name) orelse return error.MissingOutputSelection;
            const selection = driver_context.output_selection_catalog.*.entries.items[selection_index].selection;
            for (0..driver_context.state.*.cell_count) |cell| {
                const values = try driver_context.daily_soil_nitrogen_bank.*.row(cell);
                @memset(values, std.math.nan(f64));
                const first_layer = try driver_context.state.*.layerIndex(cell, 0);
                const active_layers = driver_context.state.*.active_soil_layer_count[cell];
                const pools = try ecosys.soil_daily_nitrogen_pools.calculate(
                    &driver_context.soil_organic_state.*,
                    &driver_context.surface_organic_state.*,
                    first_layer,
                    active_layers,
                    cell,
                );
                const area_inverse = 1.0 / driver_context.canopy_cell_area_m2.*[cell];
                values[0] = pools.residue_nitrogen_g_n * area_inverse;
                values[1] = pools.humus_nitrogen_g_n * area_inverse;
                values[2] = (driver_context.soil_fertilizer_inventory.*.daily_nitrogen_input_g_n[cell] + driver_context.daily_organic_fertilizer_nitrogen_input_g_n.*[cell]) * area_inverse;
                var plant_nitrogen_sink_g_n: f64 = 0;
                var harvested_nitrogen_g_n: f64 = 0;
                for (0..driver_context.config.*.plant_populations) |species| {
                    const plant = cell * driver_context.config.*.plant_populations + species;
                    plant_nitrogen_sink_g_n += driver_context.plant_daily_flux_ledger.*.nitrogen_sink_g[plant];
                    harvested_nitrogen_g_n += driver_context.plant_daily_flux_ledger.*.harvested_nitrogen_g[plant];
                }
                values[3] = plant_nitrogen_sink_g_n * area_inverse;
                values[6] = driver_context.daily_nitrogen_export.*.dissolved_organic_nitrogen_runoff_g_n[cell] / driver_context.total_grid_area_m2.*;
                values[7] = driver_context.daily_nitrogen_export.*.dissolved_organic_nitrogen_drainage_g_n[cell] / driver_context.total_grid_area_m2.*;
                values[8] = driver_context.daily_nitrogen_export.*.dissolved_inorganic_nitrogen_runoff_g_n[cell] / driver_context.total_grid_area_m2.*;
                values[9] = driver_context.daily_nitrogen_export.*.dissolved_inorganic_nitrogen_drainage_g_n[cell] / driver_context.total_grid_area_m2.*;
                var dissolved_dinitrogen_g_n: f64 = 0;
                for (0..active_layers) |local_layer| {
                    const layer = first_layer + local_layer;
                    for (0..ecosys.gas_transport.species_count) |species| {
                        const component = layer * ecosys.gas_transport.species_count + species;
                        if (species == @intFromEnum(ecosys.gas_transport.Species.nitrogen)) {
                            dissolved_dinitrogen_g_n +=
                                driver_context.gas_transport_state.*.dissolved_mass_g[component] +
                                driver_context.gas_transport_state.*.macropore_dissolved_mass_g[component] +
                                driver_context.gas_transport_state.*.band_dissolved_mass_g[component];
                        }
                    }
                }
                for (0..ecosys.gas_transport.species_count) |species| {
                    const component = cell * ecosys.gas_transport.species_count + species;
                    if (species == @intFromEnum(ecosys.gas_transport.Species.nitrogen)) {
                        dissolved_dinitrogen_g_n +=
                            driver_context.litter_gas_transport_state.*.dissolved_mass_g[component] +
                            driver_context.litter_gas_transport_state.*.macropore_dissolved_mass_g[component] +
                            driver_context.litter_gas_transport_state.*.band_dissolved_mass_g[component];
                    }
                }
                values[10] = (try driver_context.daily_soil_gas_flux.*.getSoilLitterBoundary(cell, .nitrous_oxide)) * area_inverse;
                values[11] = (try driver_context.daily_soil_gas_flux.*.getSoilLitterBoundary(cell, .ammonia)) * area_inverse;
                values[12] = dissolved_dinitrogen_g_n * area_inverse;
                values[13] = (pools.residue_nitrogen_g_n + pools.humus_nitrogen_g_n) * area_inverse;
                const ammonium_profile = values[14 .. 14 + driver_context.config.*.soil_layers];
                const oxidized_profile = values[14 + driver_context.config.*.soil_layers .. 14 + 2 * driver_context.config.*.soil_layers];
                const mineral = try ecosys.soil_daily_mineral_nitrogen.calculateInto(
                    &driver_context.initial_chemistry_state.*,
                    &driver_context.soil_reactive_nitrogen_state.*,
                    first_layer,
                    active_layers,
                    driver_context.state.*.matrix_liquid_water_m3,
                    driver_context.soil_solver_property_state.*.matrix_bulk_volume_m3,
                    driver_context.soil_solver_property_state.*.bulk_density_megagrams_per_m3,
                    &driver_context.fertilizer_band_state.*,
                    driver_context.runscript.*.fertilizer_nitrogen_molar_mass_g_per_mol,
                    .{
                        .bulk_absolute_m3 = driver_context.config.*.physical_tolerance.volume_m3,
                        .water_absolute_m3 = driver_context.config.*.physical_tolerance.water_volume_m3,
                        .relative = driver_context.config.*.physical_tolerance.relative,
                    },
                    ammonium_profile,
                    oxidized_profile,
                );
                values[4] = mineral.ammonium_nitrogen_g_n * area_inverse;
                values[5] = mineral.nitrate_plus_nitrite_nitrogen_g_n * area_inverse;
                const tail = 14 + 2 * driver_context.config.*.soil_layers;
                const litter = driver_context.surface_litter_chemistry_state.*.cells[cell];
                const litter_bulk_volume_m3 = driver_context.surface_litter_geometry_state.*.expanded_total_volume_m3[cell];
                const litter_aqueous_carrier_m3 = try ecosys.surface_litter_chemistry_carrier_rebase.effectiveAqueousCarrierM3(
                    driver_context.surface_precipitation_state.*.litter_water_m3[cell],
                    driver_context.surface_litter_chemistry_state.*.dry_reference_water_m3[cell],
                );
                const litter_ammonium_g_n = driver_context.runscript.*.fertilizer_nitrogen_molar_mass_g_per_mol *
                    (litter.ammonium_mol_per_m3 * litter_aqueous_carrier_m3 +
                        litter.exchange.ammonium_mol_per_megagram * driver_context.surface_litter_geometry_state.*.dry_mass_megagrams[cell]);
                values[tail] = if (litter_bulk_volume_m3 > driver_context.config.*.physical_tolerance.volume(litter_bulk_volume_m3)) litter_ammonium_g_n / litter_bulk_volume_m3 else 0;
                values[tail + 1] = driver_context.daily_soil_combusted_nitrogen_g_n.*[cell] * area_inverse;
                values[tail + 2] = harvested_nitrogen_g_n * area_inverse;
                values[tail + 3] = driver_context.daily_microbial_nitrogen_mineralization_g_n.*[cell] * area_inverse;
                values[tail + 4] = (driver_context.daily_soil_fire_nitrogen_flux_g_n.*[cell] + driver_context.daily_root_fire_nitrogen_flux_g_n.*[cell]) * area_inverse;
                values[tail + 5] = (try driver_context.daily_soil_gas_flux.*.getSoilLitterBoundary(cell, .nitrogen)) * area_inverse;
                for (resolved.soil_enabled, values, 0..) |enabled, value, choice| if (enabled and !std.math.isFinite(value)) {
                    std.log.err("daily soil nitrogen choice has non-finite authoritative state: choice={d} name={s}", .{ choice + 1, driver_context.daily_soil_nitrogen_catalog.*.variables[choice].name });
                    return error.NonFiniteDailySoilNitrogenChoice;
                };
                const file_name = try ecosys.output_record.buildOutputFileName(driver_context.allocator.*, driver_context.latitude_degrees_north_by_cell.*[cell], driver_context.longitude_degrees_east_by_cell.*[cell], .soil_or_eco, accepted_context.current_year.*, try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*), cell + 1, soil_nitrogen_editor_name);
                defer driver_context.allocator.*.free(file_name);
                _ = try driver_context.daily_soil_nitrogen_bank.*.streams[cell].write(file_name, driver_context.daily_soil_nitrogen_catalog.*.variables, selection, resolved.soil_enabled, .{
                    .timestamp = .{ .year = accepted_context.current_year.*, .day_of_year = completed_day_of_year, .month = completed_management_date.month, .day = completed_management_date.day, .hour = 23 },
                    .longitude_degrees_east = driver_context.longitude_degrees_east_by_cell.*[cell],
                    .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
                    .values = values,
                });
            }
        }
    }
}

noinline fn writeAcceptedDailySoilPhosphorusOutput(
    driver_context: anytype,
    accepted_context: anytype,
    completed_day_of_year: anytype,
    completed_management_date: anytype,
) !void {
    const soil_phosphorus_editor_index: usize = 8;
    const soil_phosphorus_editor_name = accepted_context.scene.*.output_editors[soil_phosphorus_editor_index];
    if (!ecosys.delimited_input.isNo(soil_phosphorus_editor_name)) {
        const resolved = driver_context.resolved_output_editors.*[accepted_context.pass.*.scene_index * 10 + soil_phosphorus_editor_index] orelse return error.UnresolvedDailySoilPhosphorusEditor;
        if (std.mem.indexOfScalar(bool, resolved.soil_enabled, true) != null) {
            const selection_index = driver_context.output_selection_catalog.*.find(soil_phosphorus_editor_name) orelse return error.MissingOutputSelection;
            const selection = driver_context.output_selection_catalog.*.entries.items[selection_index].selection;
            for (0..driver_context.state.*.cell_count) |cell| {
                const values = try driver_context.daily_soil_phosphorus_bank.*.row(cell);
                @memset(values, std.math.nan(f64));
                const area_inverse = 1.0 / driver_context.canopy_cell_area_m2.*[cell];
                values[2] = (driver_context.mineral_fertilizer_inventory.*.daily_phosphorus_input_g_p[cell] + driver_context.daily_organic_fertilizer_phosphorus_input_g_p.*[cell]) * area_inverse;
                var plant_litterfall_phosphorus_g_p: f64 = 0;
                for (0..driver_context.config.*.plant_populations) |species| plant_litterfall_phosphorus_g_p += driver_context.plant_daily_flux_ledger.*.phosphorus_sink_g[cell * driver_context.config.*.plant_populations + species];
                values[3] = plant_litterfall_phosphorus_g_p * area_inverse;
                const first_layer = try driver_context.state.*.layerIndex(cell, 0);
                const active_layers = driver_context.state.*.active_soil_layer_count[cell];
                const organic_pools = try ecosys.soil_daily_phosphorus_pools.calculate(
                    &driver_context.soil_organic_state.*,
                    &driver_context.surface_organic_state.*,
                    first_layer,
                    active_layers,
                    cell,
                );
                values[0] = organic_pools.residue_phosphorus_g_p * area_inverse;
                values[1] = organic_pools.humus_phosphorus_g_p * area_inverse;
                values[5] = driver_context.daily_phosphorus_export.*.dissolved_organic_phosphorus_runoff_g_p[cell] / driver_context.total_grid_area_m2.*;
                values[6] = driver_context.daily_phosphorus_export.*.dissolved_organic_phosphorus_drainage_g_p[cell] / driver_context.total_grid_area_m2.*;
                values[7] = driver_context.daily_phosphorus_export.*.dissolved_inorganic_phosphorus_runoff_g_p[cell] / driver_context.total_grid_area_m2.*;
                values[8] = driver_context.daily_phosphorus_export.*.dissolved_inorganic_phosphorus_drainage_g_p[cell] / driver_context.total_grid_area_m2.*;
                values[4] = try ecosys.soil_phosphate_inventory.exchangeablePhosphorus_g_p(
                    &driver_context.state.*,
                    &driver_context.initial_chemistry_state.*,
                    &driver_context.surface_litter_chemistry_state.*,
                    driver_context.soil_solver_property_state.*.matrix_bulk_volume_m3,
                    driver_context.soil_solver_property_state.*.bulk_density_megagrams_per_m3,
                    driver_context.surface_litter_geometry_state.*.dry_mass_megagrams,
                    cell,
                    &driver_context.fertilizer_band_state.*,
                    driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol,
                ) * area_inverse;
                values[9] = try ecosys.soil_phosphate_inventory.precipitatedPhosphorus_g_p(
                    &driver_context.state.*,
                    &driver_context.initial_chemistry_state.*,
                    &driver_context.surface_litter_chemistry_state.*,
                    driver_context.state.*.matrix_liquid_water_m3,
                    driver_context.surface_precipitation_state.*.litter_water_m3,
                    cell,
                    &driver_context.fertilizer_band_state.*,
                    driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol,
                ) * area_inverse;
                values[10] = organic_pools.microbial_phosphorus_g_p * area_inverse;
                values[11] = (try ecosys.soil_daily_fire_phosphorus.sourceSignedFlux_g_p(
                    cell,
                    driver_context.daily_soil_fire_phosphorus_flux_g_p.*,
                    driver_context.plant_daily_flux_ledger.*.phosphorus_oxidation_g,
                    driver_context.config.*.plant_populations,
                ) + driver_context.daily_root_fire_phosphorus_flux_g_p.*[cell]) * area_inverse;
                for (0..driver_context.config.*.soil_layers) |local_layer| {
                    const aqueous_index = 12 + local_layer;
                    const sorbed_index = 12 + driver_context.config.*.soil_layers + local_layer;
                    if (local_layer >= active_layers) {
                        values[aqueous_index] = 0;
                        values[sorbed_index] = 0;
                        continue;
                    }
                    const layer = first_layer + local_layer;
                    const fractions = try driver_context.fertilizer_band_state.*.scienceZoneFractions(cell, local_layer);
                    const non_band = driver_context.initial_chemistry_state.*.non_band_phosphate[layer];
                    const band = driver_context.initial_chemistry_state.*.band_phosphate[layer];
                    values[aqueous_index] = 31.0 * (fractions.phosphate_non_band * (non_band.dissolved_hpo4_mol_p_per_m3 + non_band.dissolved_h2po4_mol_p_per_m3) + fractions.phosphate_band * (band.dissolved_hpo4_mol_p_per_m3 + band.dissolved_h2po4_mol_p_per_m3));
                    values[sorbed_index] = try ecosys.soil_daily_output.sorbedPhosphorusConcentrationGPerM3(
                        fractions.phosphate_non_band *
                            (non_band.adsorbed_hpo4_mol_p_per_megagram +
                                non_band.adsorbed_h2po4_mol_p_per_megagram) +
                            fractions.phosphate_band *
                                (band.adsorbed_hpo4_mol_p_per_megagram +
                                    band.adsorbed_h2po4_mol_p_per_megagram),
                        driver_context.soil_solver_property_state.*.bulk_density_megagrams_per_m3[layer],
                        driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol,
                    );
                }
                const after_layers = 12 + 2 * driver_context.config.*.soil_layers;
                const litter = driver_context.surface_litter_chemistry_state.*.cells[cell];
                values[after_layers] = if (driver_context.surface_precipitation_state.*.litter_water_m3[cell] > 0.0)
                    driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol *
                        (litter.hpo4_mol_p_per_m3 + litter.h2po4_mol_p_per_m3)
                else
                    0.0;
                values[after_layers + 1] = if (driver_context.surface_litter_geometry_state.*.expanded_total_volume_m3[cell] >
                    driver_context.config.*.physical_tolerance.volume(driver_context.surface_litter_geometry_state.*.expanded_total_volume_m3[cell]))
                    try ecosys.soil_daily_output.sorbedPhosphorusConcentrationGPerM3(
                        litter.phosphate_surface.adsorbed_hpo4_mol_p_per_megagram +
                            litter.phosphate_surface.adsorbed_h2po4_mol_p_per_megagram,
                        driver_context.surface_litter_geometry_state.*.dry_mass_megagrams[cell] /
                            driver_context.surface_litter_geometry_state.*.expanded_total_volume_m3[cell],
                        driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol,
                    )
                else
                    0;
                const final_fixed = after_layers + 2;
                values[final_fixed] = driver_context.daily_soil_combusted_phosphorus_g_p.*[cell] * area_inverse;
                values[final_fixed + 1] = try ecosys.soil_phosphate_inventory.solublePhosphorus_g_p(
                    &driver_context.state.*,
                    &driver_context.initial_chemistry_state.*,
                    &driver_context.surface_litter_chemistry_state.*,
                    driver_context.state.*.matrix_liquid_water_m3,
                    driver_context.surface_precipitation_state.*.litter_water_m3,
                    cell,
                    &driver_context.fertilizer_band_state.*,
                    driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol,
                ) * area_inverse;
                var harvested_phosphorus_g_p: f64 = 0;
                for (0..driver_context.config.*.plant_populations) |species| harvested_phosphorus_g_p += driver_context.plant_daily_flux_ledger.*.harvested_phosphorus_g[cell * driver_context.config.*.plant_populations + species];
                values[final_fixed + 2] = harvested_phosphorus_g_p * area_inverse;
                values[final_fixed + 3] = driver_context.daily_microbial_phosphate_mineralization_g_p.*[cell] * area_inverse;
                // OUTSD phosphorus choices 49 and 50 are source-reserved.
                values[values.len - 2] = 0;
                values[values.len - 1] = 0;
                for (resolved.soil_enabled, values, 0..) |enabled, value, choice| if (enabled and !std.math.isFinite(value)) {
                    const name = driver_context.daily_soil_phosphorus_catalog.*.variables[choice].name;
                    if (std.mem.startsWith(u8, name, "reserved_zero_")) {
                        values[choice] = 0;
                    } else {
                        std.log.err("daily soil phosphorus choice is not yet backed by an authoritative translated owner: choice={d} name={s}", .{ choice + 1, name });
                        return error.UntranslatedDailySoilPhosphorusChoice;
                    }
                };
                const file_name = try ecosys.output_record.buildOutputFileName(driver_context.allocator.*, driver_context.latitude_degrees_north_by_cell.*[cell], driver_context.longitude_degrees_east_by_cell.*[cell], .soil_or_eco, accepted_context.current_year.*, try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*), cell + 1, soil_phosphorus_editor_name);
                defer driver_context.allocator.*.free(file_name);
                _ = try driver_context.daily_soil_phosphorus_bank.*.streams[cell].write(file_name, driver_context.daily_soil_phosphorus_catalog.*.variables, selection, resolved.soil_enabled, .{
                    .timestamp = .{ .year = accepted_context.current_year.*, .day_of_year = completed_day_of_year, .month = completed_management_date.month, .day = completed_management_date.day, .hour = 23 },
                    .longitude_degrees_east = driver_context.longitude_degrees_east_by_cell.*[cell],
                    .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
                    .values = values,
                });
            }
        }
    }
}

noinline fn writeAcceptedDailySoilHeatOutput(
    driver_context: anytype,
    accepted_context: anytype,
    completed_day_of_year: anytype,
    completed_management_date: anytype,
) !void {
    const soil_heat_editor_index: usize = 9;
    const soil_heat_editor_name = accepted_context.scene.*.output_editors[soil_heat_editor_index];
    if (!ecosys.delimited_input.isNo(soil_heat_editor_name)) {
        const resolved = driver_context.resolved_output_editors.*[accepted_context.pass.*.scene_index * 10 + soil_heat_editor_index] orelse return error.UnresolvedDailySoilHeatEditor;
        if (std.mem.indexOfScalar(bool, resolved.soil_enabled, true) != null) {
            const selection_index = driver_context.output_selection_catalog.*.find(soil_heat_editor_name) orelse return error.MissingOutputSelection;
            const selection = driver_context.output_selection_catalog.*.entries.items[selection_index].selection;
            const maximum_temperature_c = driver_context.daily_soil_heat_workspace.*[0..driver_context.config.*.soil_layers];
            const minimum_temperature_c = driver_context.daily_soil_heat_workspace.*[driver_context.config.*.soil_layers .. 2 * driver_context.config.*.soil_layers];
            const electrical_conductivity_dS_per_m = driver_context.daily_soil_heat_workspace.*[2 * driver_context.config.*.soil_layers .. 3 * driver_context.config.*.soil_layers];
            for (0..driver_context.state.*.cell_count) |cell| {
                try driver_context.daily_heat_ledger.*.validateCell(cell);
                const first_layer = try driver_context.state.*.layerIndex(cell, 0);
                const active_layers = driver_context.state.*.active_soil_layer_count[cell];
                const ledger_first = cell * driver_context.config.*.soil_layers;
                @memset(maximum_temperature_c, 0);
                @memset(minimum_temperature_c, 0);
                @memset(electrical_conductivity_dS_per_m, 0);
                @memcpy(maximum_temperature_c[0..active_layers], driver_context.daily_heat_ledger.*.maximum_soil_temperature_c[ledger_first .. ledger_first + active_layers]);
                @memcpy(minimum_temperature_c[0..active_layers], driver_context.daily_heat_ledger.*.minimum_soil_temperature_c[ledger_first .. ledger_first + active_layers]);
                for (0..active_layers) |local_layer| {
                    const charge_fractions = try driver_context.fertilizer_band_state.*.scienceZoneFractions(cell, local_layer);
                    const coefficients = try driver_context.initial_chemistry_state.*.activityCoefficients(first_layer + local_layer, charge_fractions);
                    electrical_conductivity_dS_per_m[local_layer] = coefficients.electrical_conductivity_dS_per_m;
                }
                const values = try driver_context.daily_soil_heat_bank.*.row(cell);
                try ecosys.soil_daily_output.calculateHeatInto(.{
                    .total_radiation_megajoules_m2 = driver_context.daily_heat_ledger.*.total_radiation_megajoules_per_m2[cell],
                    .maximum_air_temperature_c = driver_context.daily_heat_ledger.*.maximum_air_temperature_c[cell],
                    .minimum_air_temperature_c = driver_context.daily_heat_ledger.*.minimum_air_temperature_c[cell],
                    .maximum_atmospheric_vapor_pressure_kpa = driver_context.daily_heat_ledger.*.maximum_vapor_pressure_kpa[cell],
                    .minimum_atmospheric_vapor_pressure_kpa = driver_context.daily_heat_ledger.*.minimum_vapor_pressure_kpa[cell],
                    .cumulative_wind_m = driver_context.daily_heat_ledger.*.cumulative_wind_distance_m[cell],
                    .total_precipitation_mm = driver_context.daily_heat_ledger.*.total_precipitation_mm[cell],
                    .maximum_soil_temperature_c_by_layer = maximum_temperature_c,
                    .minimum_soil_temperature_c_by_layer = minimum_temperature_c,
                    .surface_maximum_soil_temperature_c = driver_context.daily_heat_ledger.*.surface_maximum_temperature_c[cell],
                    .surface_minimum_soil_temperature_c = driver_context.daily_heat_ledger.*.surface_minimum_temperature_c[cell],
                    .electrical_conductivity_by_layer = electrical_conductivity_dS_per_m,
                    .ionic_outflow_mol = driver_context.daily_heat_ledger.*.ionic_outflow_mol[cell],
                    .grid_area_m2 = driver_context.total_grid_area_m2.*,
                }, values);
                const file_name = try ecosys.output_record.buildOutputFileName(driver_context.allocator.*, driver_context.latitude_degrees_north_by_cell.*[cell], driver_context.longitude_degrees_east_by_cell.*[cell], .soil_or_eco, accepted_context.current_year.*, try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*), cell + 1, soil_heat_editor_name);
                defer driver_context.allocator.*.free(file_name);
                _ = try driver_context.daily_soil_heat_bank.*.streams[cell].write(file_name, driver_context.daily_soil_heat_catalog.*.variables, selection, resolved.soil_enabled, .{
                    .timestamp = .{ .year = accepted_context.current_year.*, .day_of_year = completed_day_of_year, .month = completed_management_date.month, .day = completed_management_date.day, .hour = 23 },
                    .longitude_degrees_east = driver_context.longitude_degrees_east_by_cell.*[cell],
                    .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
                    .values = values,
                });
            }
        }
    }
}

noinline fn writeAcceptedDailyPlantOutputs(
    driver_context: anytype,
    accepted_context: anytype,
    completed_day_of_year: anytype,
    completed_management_date: anytype,
) !void {
    inline for (.{ DailyPlantElement.nitrogen, DailyPlantElement.phosphorus }) |element| {
        const nutrient_editor_index: usize = switch (element) {
            .nitrogen => 7,
            .phosphorus => 8,
        };
        const nutrient_editor_name = accepted_context.scene.*.output_editors[nutrient_editor_index];
        if (!ecosys.delimited_input.isNo(nutrient_editor_name)) {
            const resolved = driver_context.resolved_output_editors.*[accepted_context.pass.*.scene_index * 10 + nutrient_editor_index] orelse return error.UnresolvedDailyPlantNutrientEditor;
            if (std.mem.indexOfScalar(bool, resolved.plant_enabled, true) != null) {
                const selection_index = driver_context.output_selection_catalog.*.find(nutrient_editor_name) orelse return error.MissingOutputSelection;
                const selection = driver_context.output_selection_catalog.*.entries.items[selection_index].selection;
                const canopy = if (driver_context.detailed_canopy_state.*) |*value| value else return error.DailyPlantNutrientOutputRequiresCanopyState;
                const roots = if (driver_context.plant_root_state.*) |*value| value else return error.DailyPlantNutrientOutputRequiresRootState;
                for (0..driver_context.state.*.cell_count) |cell| for (0..driver_context.config.*.plant_populations) |species| {
                    const plant = try canopy.plantIndex(cell, species);
                    const branches = try canopy.branchRange(plant);
                    const root_workspace = driver_context.daily_element_root_workspace.*[plant * driver_context.config.*.soil_layers .. (plant + 1) * driver_context.config.*.soil_layers];
                    const pools = try calculateDailyPlantElementPools(
                        canopy,
                        roots,
                        plant,
                        branches,
                        element,
                        driver_context.root_metabolism_plant_parameters.*[plant].biologicalDomainCount(),
                        root_workspace,
                    );
                    var leaf_carbon_g: f64 = 0;
                    var leaf_nitrogen_g: f64 = 0;
                    var leaf_phosphorus_g: f64 = 0;
                    for (branches.first..branches.end) |branch| {
                        leaf_carbon_g += canopy.branch_leaf_carbon_g[branch];
                        leaf_nitrogen_g += canopy.branch_leaf_nitrogen_g[branch];
                        leaf_phosphorus_g += canopy.branch_leaf_phosphorus_g[branch];
                    }
                    const balance_inputs: ecosys.plant_daily_output.NutrientBalanceInputs = switch (element) {
                        .nitrogen => .{
                            .shoot_g = pools.shoot_g,
                            .root_g = pools.root_g,
                            .nodule_g = pools.nodule_g,
                            .storage_g = pools.storage_g,
                            .standing_dead_g = pools.vegetative_residue_g,
                            .cumulative_sink_g = driver_context.plant_daily_flux_ledger.*.nitrogen_sink_g[plant],
                            .cumulative_root_soil_exchange_g = driver_context.plant_daily_flux_ledger.*.root_soil_nitrogen_exchange_g[plant],
                            .cumulative_balance_g = driver_context.plant_daily_flux_ledger.*.cumulative_nitrogen_balance_g[plant],
                            .cumulative_harvested_g = driver_context.plant_daily_flux_ledger.*.cumulative_harvested_nitrogen_g[plant],
                            .harvested_g = driver_context.plant_daily_flux_ledger.*.harvested_nitrogen_g[plant],
                            .oxidation_g = driver_context.plant_daily_flux_ledger.*.nitrogen_oxidation_g[plant],
                            .atmospheric_exchange_g = driver_context.plant_daily_flux_ledger.*.ammonia_exchange_g_n[plant],
                            .biological_fixation_g = driver_context.plant_daily_flux_ledger.*.symbiotic_nitrogen_fixation_g[plant],
                        },
                        .phosphorus => .{
                            .shoot_g = pools.shoot_g,
                            .root_g = pools.root_g,
                            .nodule_g = pools.nodule_g,
                            .storage_g = pools.storage_g,
                            .standing_dead_g = pools.vegetative_residue_g,
                            .cumulative_sink_g = driver_context.plant_daily_flux_ledger.*.phosphorus_sink_g[plant],
                            .cumulative_root_soil_exchange_g = driver_context.plant_daily_flux_ledger.*.root_soil_phosphorus_exchange_g[plant],
                            .cumulative_balance_g = driver_context.plant_daily_flux_ledger.*.cumulative_phosphorus_balance_g[plant],
                            .cumulative_harvested_g = driver_context.plant_daily_flux_ledger.*.cumulative_harvested_phosphorus_g[plant],
                            .harvested_g = driver_context.plant_daily_flux_ledger.*.harvested_phosphorus_g[plant],
                            .oxidation_g = driver_context.plant_daily_flux_ledger.*.phosphorus_oxidation_g[plant],
                        },
                    };
                    switch (element) {
                        .nitrogen => driver_context.plant_balance_nitrogen_inputs_workspace.*[plant] = balance_inputs,
                        .phosphorus => driver_context.plant_balance_phosphorus_inputs_workspace.*[plant] = balance_inputs,
                    }
                    const nutrient_inputs: ecosys.plant_daily_output.NutrientInputs = .{
                        .cell_area_m2 = driver_context.canopy_cell_area_m2.*[cell],
                        .shoot_g = pools.shoot_g,
                        .leaf_g = pools.leaf_g,
                        .sheath_g = pools.sheath_g,
                        .stalk_g = pools.stalk_g,
                        .reserve_g = pools.reserve_g,
                        .husk_g = pools.husk_g,
                        .ear_g = pools.ear_g,
                        .grain_g = pools.grain_g,
                        .root_g = pools.root_g,
                        .nodule_g = pools.nodule_g,
                        .vegetative_residue_g = pools.vegetative_residue_g,
                        .cumulative_uptake_g = switch (element) {
                            .nitrogen => driver_context.plant_daily_flux_ledger.*.root_soil_nitrogen_exchange_g[plant],
                            .phosphorus => driver_context.plant_daily_flux_ledger.*.root_soil_phosphorus_exchange_g[plant],
                        },
                        .cumulative_sink_g = switch (element) {
                            .nitrogen => driver_context.plant_daily_flux_ledger.*.nitrogen_sink_g[plant],
                            .phosphorus => driver_context.plant_daily_flux_ledger.*.phosphorus_sink_g[plant],
                        },
                        .nitrogen_fixation_g = driver_context.plant_daily_flux_ledger.*.symbiotic_nitrogen_fixation_g[plant],
                        .aboveground_litter_sink_g = switch (element) {
                            .nitrogen => driver_context.plant_daily_flux_ledger.*.initial_nitrogen_sink_g[plant],
                            .phosphorus => driver_context.plant_daily_flux_ledger.*.initial_phosphorus_sink_g[plant],
                        },
                        .pollination_factor = switch (element) {
                            .nitrogen => canopy.plant_mobile_nitrogen_concentration_g_per_g[plant],
                            .phosphorus => canopy.plant_mobile_phosphorus_concentration_g_per_g[plant],
                        },
                        .leaf_carbon_g = leaf_carbon_g,
                        .leaf_nitrogen_g = leaf_nitrogen_g,
                        .leaf_phosphorus_g = leaf_phosphorus_g,
                        .nonstructural_carbon_g = canopy.plant_mobile_carbon_g[plant],
                        .nonstructural_nitrogen_g = canopy.plant_mobile_nitrogen_g[plant],
                        .nonstructural_phosphorus_g = canopy.plant_mobile_phosphorus_g[plant],
                        .minimum_leaf_carbon_g = driver_context.runscript.*.plant_pool_parameters.branch_structural_presence_g_per_plant * canopy.plant_population_count[plant],
                        .other_pollination_factor = canopy.plant_mobile_phosphorus_concentration_g_per_g[plant],
                        .gaseous_loss_g = driver_context.plant_daily_flux_ledger.*.ammonia_exchange_g_n[plant],
                        .harvested_g = switch (element) {
                            .nitrogen => driver_context.plant_daily_flux_ledger.*.harvested_nitrogen_g[plant],
                            .phosphorus => driver_context.plant_daily_flux_ledger.*.harvested_phosphorus_g[plant],
                        },
                        .balance_g = switch (element) {
                            .nitrogen => try ecosys.plant_daily_output.nitrogenBalance(balance_inputs),
                            .phosphorus => try ecosys.plant_daily_output.phosphorusBalance(balance_inputs),
                        },
                        .storage_g = pools.storage_g,
                        .oxidation_flux_g = switch (element) {
                            .nitrogen => driver_context.plant_daily_flux_ledger.*.nitrogen_oxidation_g[plant],
                            .phosphorus => driver_context.plant_daily_flux_ledger.*.phosphorus_oxidation_g[plant],
                        },
                    };
                    const values = switch (element) {
                        .nitrogen => try driver_context.daily_plant_nitrogen_bank.*.row(plant),
                        .phosphorus => try driver_context.daily_plant_phosphorus_bank.*.row(plant),
                    };
                    switch (element) {
                        .nitrogen => @memcpy(values, &(try ecosys.plant_daily_output.nitrogen(nutrient_inputs)).values),
                        .phosphorus => @memcpy(values, &(try ecosys.plant_daily_output.phosphorus(nutrient_inputs)).values),
                    }
                    // Only assigned species produce output; an unassigned population
                    // would emit all-zero rows, so no file is created for it.
                    const species_label = outputSpeciesLabel(driver_context.plant_assignments.*, driver_context.plant_unit_by_cell.*, cell, species) orelse continue;
                    const file_name = try ecosys.output_record.buildOutputFileName(driver_context.allocator.*, driver_context.latitude_degrees_north_by_cell.*[cell], driver_context.longitude_degrees_east_by_cell.*[cell], .{ .species = .{ .name = species_label, .population_number = species + 1 } }, accepted_context.current_year.*, try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*), cell + 1, nutrient_editor_name);
                    defer driver_context.allocator.*.free(file_name);
                    _ = switch (element) {
                        .nitrogen => try driver_context.daily_plant_nitrogen_bank.*.streams[plant].write(file_name, driver_context.daily_plant_nitrogen_catalog.*.variables, selection, resolved.plant_enabled, .{
                            .timestamp = .{ .year = accepted_context.current_year.*, .day_of_year = completed_day_of_year, .month = completed_management_date.month, .day = completed_management_date.day, .hour = 23 },
                            .longitude_degrees_east = driver_context.longitude_degrees_east_by_cell.*[cell],
                            .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
                            .values = values,
                        }),
                        .phosphorus => try driver_context.daily_plant_phosphorus_bank.*.streams[plant].write(file_name, driver_context.daily_plant_phosphorus_catalog.*.variables, selection, resolved.plant_enabled, .{
                            .timestamp = .{ .year = accepted_context.current_year.*, .day_of_year = completed_day_of_year, .month = completed_management_date.month, .day = completed_management_date.day, .hour = 23 },
                            .longitude_degrees_east = driver_context.longitude_degrees_east_by_cell.*[cell],
                            .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
                            .values = values,
                        }),
                    };
                };
            }
        }
    }
    // GROSUB 13071–13165 / EXTRACT 949–951: per-plant C/N/P balance tuple
    // and cell totals.
    if (driver_context.detailed_canopy_state.* != null and
        driver_context.plant_root_state.* != null and
        driver_context.plant_phenology_state.* != null)
    {
        const canopy = &driver_context.detailed_canopy_state.*.?;
        const roots = &driver_context.plant_root_state.*.?;
        try assemblePlantBalanceInputs(
            canopy,
            roots,
            driver_context.root_metabolism_plant_parameters.*,
            &driver_context.plant_daily_flux_ledger.*,
            driver_context.plant_phenology_state.*.?.active,
            driver_context.plant_balance_carbon_inputs_workspace.*,
            driver_context.plant_balance_nitrogen_inputs_workspace.*,
            driver_context.plant_balance_phosphorus_inputs_workspace.*,
            driver_context.plant_balance_carbon_root_by_layer.*,
            driver_context.plant_balance_carbon_root_length_density_by_layer.*,
            driver_context.plant_balance_nutrient_root_by_layer.*,
        );
        try ecosys.plant_balance_state_update.refresh(
            &driver_context.plant_balance_state_update_state.*,
            .{
                .active_by_plant = driver_context.plant_phenology_state.*.?.active,
                .carbon_by_plant = driver_context.plant_balance_carbon_inputs_workspace.*,
                .nitrogen_by_plant = driver_context.plant_balance_nitrogen_inputs_workspace.*,
                .phosphorus_by_plant = driver_context.plant_balance_phosphorus_inputs_workspace.*,
            },
        );
    }
    const development_editor_index: usize = 9;
    const development_editor_name = accepted_context.scene.*.output_editors[development_editor_index];
    if (!ecosys.delimited_input.isNo(development_editor_name)) {
        const resolved = driver_context.resolved_output_editors.*[accepted_context.pass.*.scene_index * 10 + development_editor_index] orelse return error.UnresolvedDailyPlantDevelopmentEditor;
        if (std.mem.indexOfScalar(bool, resolved.plant_enabled, true) != null) {
            const selection_index = driver_context.output_selection_catalog.*.find(development_editor_name) orelse return error.MissingOutputSelection;
            const selection = driver_context.output_selection_catalog.*.entries.items[selection_index].selection;
            const canopy = if (driver_context.detailed_canopy_state.*) |*value| value else return error.DailyPlantDevelopmentOutputRequiresCanopyState;
            const growth = if (driver_context.plant_growth_stage_state.*) |*value| value else return error.DailyPlantDevelopmentOutputRequiresGrowthStageState;
            const development_state = if (driver_context.branch_development_state.*) |*value| value else return error.DailyPlantDevelopmentOutputRequiresBranchDevelopmentState;
            const phenology = if (driver_context.plant_phenology_state.*) |*value| value else return error.DailyPlantDevelopmentOutputRequiresPhenologyState;
            for (0..driver_context.state.*.cell_count) |cell| for (0..driver_context.config.*.plant_populations) |species| {
                const plant = cell * driver_context.config.*.plant_populations + species;
                const branches = try growth.branchRange(plant);
                const has_branch = branches.first < branches.end;
                const main_branch = (try growth.mainLivingBranch(plant)) orelse branches.first;
                if (has_branch and (main_branch >= canopy.branch_leaf_carbon_g.len or main_branch >= development_state.branch_count)) return error.DailyPlantDevelopmentBranchDimensionMismatch;
                const stage: ecosys.plant_growth_stages.BranchState = if (has_branch) growth.branches[main_branch] else .{};
                const milestones = [_]u32{
                    stage.emergence_day,
                    stage.floral_initiation_day,
                    stage.stem_elongation_start_day,
                    stage.stem_elongation_midpoint_day,
                    stage.stem_elongation_end_day,
                    stage.anthesis_day,
                    stage.grain_fill_start_day,
                    stage.seed_number_set_end_day,
                    stage.seed_size_set_end_day,
                    if (has_branch) development_state.stage_day[main_branch * 10 + 9] else 0,
                };
                var leaf_carbon_g: f64 = 0;
                var leaf_nitrogen_g: f64 = 0;
                var leaf_phosphorus_g: f64 = 0;
                for (branches.first..branches.end) |branch| {
                    if (growth.branches[branch].dead) continue;
                    leaf_carbon_g += canopy.branch_leaf_carbon_g[branch];
                    leaf_nitrogen_g += canopy.branch_leaf_nitrogen_g[branch];
                    leaf_phosphorus_g += canopy.branch_leaf_phosphorus_g[branch];
                }
                const output = try ecosys.plant_daily_output.development(.{
                    .alive = has_branch and phenology.active[plant],
                    .milestone_day_by_stage = &milestones,
                    .branch_count = branches.end - branches.first,
                    .main_branch_stage = stage.accumulated_vegetative_stage,
                    .development_feedback = canopy.plant_nitrogen_phosphorus_fixation_constraint_fraction[plant],
                    .leaf_structural_carbon_g = leaf_carbon_g,
                    .leaf_structural_nitrogen_g = leaf_nitrogen_g,
                    .leaf_structural_phosphorus_g = leaf_phosphorus_g,
                    .plant_nonstructural_carbon_g = canopy.plant_mobile_carbon_g[plant],
                    .plant_nonstructural_nitrogen_g = canopy.plant_mobile_nitrogen_g[plant],
                    .plant_nonstructural_phosphorus_g = canopy.plant_mobile_phosphorus_g[plant],
                    .minimum_leaf_carbon_g = driver_context.runscript.*.plant_pool_parameters.branch_structural_presence_g_per_plant * canopy.plant_population_count[plant],
                    .minimum_daily_canopy_water_potential_megapascal = canopy.plant_minimum_daily_canopy_water_potential_megapascal[plant],
                    .oxygen_stress_factor = driver_context.phenology_root_oxygen_fraction.*[plant],
                    .temperature_function = canopy.plant_uptake_growth_temperature_response[plant],
                });
                const values = try driver_context.daily_plant_development_bank.*.row(plant);
                values[0] = @floatFromInt(@intFromEnum(output.phase));
                values[1] = @floatFromInt(output.branch_count);
                values[2] = output.main_branch_stage;
                values[3] = output.development_feedback;
                values[4] = output.leaf_nitrogen_to_carbon_ratio;
                values[5] = output.leaf_phosphorus_to_carbon_ratio;
                values[6] = output.minimum_daily_canopy_water_potential_megapascal;
                values[7] = output.oxygen_stress_factor;
                values[8] = output.temperature_function;
                // Only assigned species produce output; an unassigned population
                // would emit all-zero rows, so no file is created for it.
                const species_label = outputSpeciesLabel(driver_context.plant_assignments.*, driver_context.plant_unit_by_cell.*, cell, species) orelse continue;
                const file_name = try ecosys.output_record.buildOutputFileName(driver_context.allocator.*, driver_context.latitude_degrees_north_by_cell.*[cell], driver_context.longitude_degrees_east_by_cell.*[cell], .{ .species = .{ .name = species_label, .population_number = species + 1 } }, accepted_context.current_year.*, try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*), cell + 1, development_editor_name);
                defer driver_context.allocator.*.free(file_name);
                _ = try driver_context.daily_plant_development_bank.*.streams[plant].write(file_name, driver_context.daily_plant_development_catalog.*.variables, selection, resolved.plant_enabled, .{
                    .timestamp = .{ .year = accepted_context.current_year.*, .day_of_year = completed_day_of_year, .month = completed_management_date.month, .day = completed_management_date.day, .hour = 23 },
                    .longitude_degrees_east = driver_context.longitude_degrees_east_by_cell.*[cell],
                    .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
                    .values = values,
                });
            };
        }
    }
}

noinline fn writeAcceptedDailyVisualizationOutput(
    driver_context: anytype,
    accepted_context: anytype,
    completed_day_of_year: anytype,
    completed_management_date: anytype,
) !void {
    if (accepted_context.active_options.*.visualizationIncludesYear(accepted_context.current_year.*)) {
        const canopy = if (driver_context.detailed_canopy_state.*) |*value|
            value
        else
            return error.VisualizationDailyOutputRequiresCanopyState;
        const roots = if (driver_context.plant_root_state.*) |*value|
            value
        else
            return error.VisualizationDailyOutputRequiresRootState;
        for (0..driver_context.state.*.cell_count) |cell| {
            var total_leaf_area_m2: f64 = 0;
            for (0..driver_context.config.*.plant_populations) |species| {
                const plant =
                    cell * driver_context.config.*.plant_populations + species;
                const branches = try canopy.branchRange(plant);
                var leaf_carbon_g: f64 = 0;
                var stalk_carbon_g: f64 = 0;
                for (branches.first..branches.end) |branch| {
                    leaf_carbon_g +=
                        canopy.branch_leaf_carbon_g[branch];
                    stalk_carbon_g +=
                        canopy.branch_stalk_carbon_g[branch];
                    total_leaf_area_m2 +=
                        canopy.branch_leaf_area_m2[branch];
                }
                @memset(
                    driver_context.visualization_root_profile_carbon_g.*,
                    0,
                );
                var root_carbon_g: f64 = 0;
                for (0..driver_context.config.*.soil_layers) |local_layer| {
                    for (0..driver_context.root_metabolism_plant_parameters.*[plant].biologicalDomainCount()) |domain| {
                        const root = try roots.layerIndex(
                            plant,
                            domain,
                            local_layer,
                        );
                        driver_context.visualization_root_profile_carbon_g.*[local_layer] +=
                            roots.mobile_carbon_g[root];
                        for (0..roots.active_root_axis_count[plant]) |axis| {
                            const axis_layer =
                                try roots.layerAxisIndex(
                                    plant,
                                    domain,
                                    local_layer,
                                    axis,
                                );
                            driver_context.visualization_root_profile_carbon_g.*[local_layer] +=
                                roots.axis_primary_carbon_g[axis_layer] +
                                roots.axis_secondary_carbon_g[axis_layer];
                        }
                    }
                    root_carbon_g +=
                        driver_context.visualization_root_profile_carbon_g.*[local_layer];
                }
                driver_context.visualization_leaf_carbon_g.*[species] =
                    leaf_carbon_g;
                driver_context.visualization_stalk_carbon_g.*[species] =
                    stalk_carbon_g;
                driver_context.visualization_root_carbon_g.*[species] =
                    root_carbon_g;
            }

            const first_layer = try driver_context.state.*.layerIndex(cell, 0);
            const active_layers =
                driver_context.state.*.active_soil_layer_count[cell];
            const carbon_pools =
                try ecosys.soil_daily_carbon_pools.calculate(
                    &driver_context.soil_organic_state.*,
                    &driver_context.surface_organic_state.*,
                    first_layer,
                    active_layers,
                    cell,
                    driver_context.visualization_organic_carbon_g.*[1 .. active_layers + 1],
                );
            driver_context.visualization_organic_carbon_g.*[0] =
                carbon_pools.surface_noncharcoal_organic_carbon_g_c;
            @memset(
                driver_context.visualization_organic_carbon_g.*[active_layers + 1 ..],
                0,
            );
            const active_boundary_base =
                cell * (driver_context.soil_geometry_state.*.layer_capacity + 1);
            const active_surface_depth_m =
                driver_context.soil_geometry_state.*.boundary_depth_m[
                    active_boundary_base +
                        driver_context.soil_geometry_state.*.first_active_layer[cell]
                ];
            const first_plant =
                cell * driver_context.config.*.plant_populations;
            const plant_end =
                first_plant + driver_context.config.*.plant_populations;
            _ = try driver_context.visualization_streams.*.calculateAndWriteDaily(
                cell,
                driver_context.longitude_degrees_east_by_cell.*[cell],
                driver_context.latitude_degrees_north_by_cell.*[cell],
                .{
                    .year = accepted_context.current_year.*,
                    .day_of_year = completed_day_of_year,
                    .month = completed_management_date.month,
                    .day = completed_management_date.day,
                    .hour = 23,
                },
                try ecosys.output_record.PassOrdinals.fromScenePass(accepted_context.pass.*),
                .{
                    .cell_area_m2 = driver_context.canopy_cell_area_m2.*[cell],
                    .cumulative_transpiration_source_m3_by_species = driver_context.plant_water_state_update_state.*.cumulative_water_source_m3_by_plant[first_plant..plant_end],
                    .cumulative_evapotranspiration_m3 = driver_context.daily_water_ledger.*.evaporation_m3[cell],
                    .cumulative_runoff_m3 = driver_context.daily_water_ledger.*.runoff_m3[cell],
                    // water_outflow_m3 is the accepted Richards external
                    // boundary residual and already contains the
                    // artificial-drainage subset separately tracked in
                    // lateral_water_outflow_m3 (see
                    // daily_water_budget.zig's field doc and
                    // landscape_boundary_balance.zig's
                    // accumulateAcceptedWater, which discards the latter
                    // for the same reason). Do not sum them here or tile
                    // drainage is double-booked into this column.
                    .cumulative_outflow_m3 = driver_context.daily_water_ledger.*.water_outflow_m3[cell],
                    .water_table_bottom_depth_m = driver_context.soil_boundary_topology_state.*.internal_water_table_depth_m[cell],
                    .active_surface_depth_m = active_surface_depth_m,
                    .snow_depth_m = driver_context.snow_depth_m.*[cell],
                    .total_leaf_area_m2 = total_leaf_area_m2,
                    .leaf_carbon_g_by_species = driver_context.visualization_leaf_carbon_g.*,
                    .stalk_carbon_g_by_species = driver_context.visualization_stalk_carbon_g.*,
                    .root_carbon_g_by_species = driver_context.visualization_root_carbon_g.*,
                    .organic_carbon_g_by_layer_including_surface = driver_context.visualization_organic_carbon_g.*,
                },
            );
        }
    }
}

noinline fn closeAndResetAcceptedDay(
    driver_context: anytype,
    accepted_context: anytype,
    completed_day_of_year: anytype,
) !void {
    // Legacy SOIL writes OUTPD after hour 24, then calls DAY
    // before the next day's hour 1. DAY's per-plant carry and
    // reset (day.f:152-193) is itself gated on I.EQ.1
    // (day.f:84-85,197): it fires only when the day about to
    // start is day 1 of a new year, not on every day
    // boundary. Reproduce that cadence here: the day that
    // just completed is the last day of its year exactly
    // when the next day is day 1 (PLANT-CADENCE-001, fixed).
    if (completed_day_of_year == ecosys.climate_change.daysInYear(accepted_context.current_year.*)) {
        try driver_context.plant_daily_flux_ledger.*.closeYearAfterOutput();
        try driver_context.plant_water_state_update_state.*.closeYearAfterOutput();
        try ecosys.plant_daily_flux_ledger.closeYearHarvestSaltAfterOutput(
            driver_context.cumulative_harvest_salt_mol_by_plant.*,
            std.mem.indexOfScalar(bool, driver_context.salinity_enabled_by_cell.*, true) != null,
        );
    }
    driver_context.daily_soil_gas_flux.*.reset();
    driver_context.daily_canopy_gas_exchange.*.reset();
    driver_context.atmospheric_canopy_gas_state.*.resetDailyExchange();
    driver_context.daily_heterotrophic_respiration.*.resetDaily();
    driver_context.daily_carbon_export.*.resetDaily();
    driver_context.daily_phosphorus_export.*.resetDaily();
    driver_context.daily_nitrogen_export.*.resetDaily();
    driver_context.daily_water_ledger.*.resetDaily();
    driver_context.daily_heat_ledger.*.reset();
    driver_context.atmospheric_solute_input_ledger_state.*.resetDaily();
    @memset(driver_context.daily_soil_fire_charcoal_production_g_c.*, 0);
    @memset(driver_context.daily_soil_fire_carbon_dioxide_emission_g_c.*, 0);
    @memset(driver_context.daily_soil_fire_methane_emission_g_c.*, 0);
    @memset(driver_context.daily_soil_fire_phosphorus_flux_g_p.*, 0);
    @memset(driver_context.daily_soil_fire_nitrogen_flux_g_n.*, 0);
    @memset(driver_context.daily_root_fire_carbon_dioxide_emission_g_c.*, 0);
    @memset(driver_context.daily_root_fire_methane_emission_g_c.*, 0);
    @memset(driver_context.daily_root_fire_nitrogen_flux_g_n.*, 0);
    @memset(driver_context.daily_root_fire_phosphorus_flux_g_p.*, 0);
    @memset(driver_context.daily_root_fire_nitrogen_loss_g_n.*, 0);
    @memset(driver_context.daily_root_fire_phosphorus_loss_g_p.*, 0);
    @memset(driver_context.daily_soil_combusted_nitrogen_g_n.*, 0);
    @memset(driver_context.daily_soil_combusted_phosphorus_g_p.*, 0);
    @memset(driver_context.daily_microbial_phosphate_mineralization_g_p.*, 0);
    @memset(driver_context.daily_microbial_nitrogen_mineralization_g_n.*, 0);
    @memset(driver_context.daily_organic_fertilizer_carbon_input_g_c.*, 0);
    @memset(driver_context.daily_organic_fertilizer_phosphorus_input_g_p.*, 0);
    @memset(driver_context.daily_organic_fertilizer_nitrogen_input_g_n.*, 0);
    driver_context.soil_fertilizer_inventory.*.resetDaily();
    driver_context.mineral_fertilizer_inventory.*.resetDaily();
    @memset(driver_context.daily_biome_organic_carbon_input_g_c.*, 0);
}

noinline fn finishAcceptedHourOutputs(
    driver_context: anytype,
    timeline_state: *TimelineState,
    accepted_context: anytype,
    accepted_output_instant: ecosys.output_hour_transaction.Instant,
) !void {
    if (accepted_context.scene_weather_hours.* < 24) {
        const diagnostic_totals = try reconstructLandscapeMassBalance(driver_context.hourly_science_context.*);
        std.log.debug("phosphorus end hourly loop: hour={d} stored_g={e}", .{ accepted_context.scene_weather_hours.*, diagnostic_totals.residue_phosphorus_g + diagnostic_totals.organic_phosphorus_g + diagnostic_totals.phosphate_phosphorus_g });
    }
    try driver_context.output_hour_coordinator.*.commitHour();
    const scene_final_hour = accepted_context.scene_weather_hours.* == accepted_context.scene_expected_hours.*;
    if (try ecosys.checkpoint_schedule.shouldPublish(
        accepted_context.active_options.*.checkpoint_output_enabled,
        accepted_context.active_options.*.checkpoint_interval_days,
        accepted_context.current_day_of_year.*,
        @intCast(accepted_context.scene_weather_hours.*),
        scene_final_hour,
    )) {
        if (driver_context.plant_root_state.* == null or driver_context.detailed_canopy_state.* == null or driver_context.canopy_precipitation_retention_state.* == null or driver_context.plant_phenology_state.* == null or driver_context.plant_growth_stage_state.* == null or driver_context.plant_dormancy_state.* == null or driver_context.branch_development_state.* == null) return error.CheckpointRequestedWithoutCompletePlantState;
        try driver_context.output_hour_coordinator.*.checkpointWillPublish();
        try ecosys.checkpoint_bundle_writer.publish(
            driver_context.allocator.*,
            driver_context.init.*.io,
            std.Io.Dir.cwd(),
            @intCast(driver_context.executed_weather_hours.*),
            .{
                .year = accepted_context.current_year.*,
                .day_of_year = accepted_context.current_day_of_year.*,
                .hour = try accepted_context.timestamp.*.modelHourIndex(),
                .execution_iteration = @intCast(accepted_context.pass.*.execution_iteration),
                .scenario_index = @intCast(accepted_context.pass.*.scenario_index),
                .scenario_iteration = @intCast(accepted_context.pass.*.scenario_iteration),
                .scene_index = @intCast(accepted_context.pass.*.scene_index),
                .completed_scene_hours = @intCast(accepted_context.scene_weather_hours.*),
            },
            .{
                .canonical_root = driver_context.output_tree.*.root_path,
                .run_identity = driver_context.output_run_identity.*,
            },
            .{ .columns = driver_context.config.*.lon_count, .rows = driver_context.config.*.lat_count, .soil_layers = driver_context.config.*.soil_layers, .snow_layers = driver_context.snow_transport_state.*.layer_capacity, .plant_species_per_cell = driver_context.config.*.plant_populations, .root_axes_per_plant = driver_context.runscript.*.root_axes_per_plant },
            .{
                .grid = &driver_context.state.*,
                .plants = &driver_context.plant_state.*,
                .plant_metadata_cells = driver_context.checkpoint_metadata_cells.*,
                .plant_development = .{ .phenology = &driver_context.plant_phenology_state.*.?, .growth = &driver_context.plant_growth_stage_state.*.?, .dormancy = &driver_context.plant_dormancy_state.*.?, .branch_development = &driver_context.branch_development_state.*.? },
                .plant_roots = &driver_context.plant_root_state.*.?,
                .plant_canopy = .{ .canopy = &driver_context.detailed_canopy_state.*.?, .retention = &driver_context.canopy_precipitation_retention_state.*.?, .layer_distribution = &driver_context.canopy_layer_distribution_state.*.? },
                .soil_biogeochemistry = .{ .microbial = &driver_context.soil_microbial_state.*, .microbial_thermal_adaptation = &driver_context.microbial_thermal_adaptation_state.*, .chemistry = &driver_context.initial_chemistry_state.*, .available_nutrients = &driver_context.plant_available_nutrient_state.*, .fertilizer = &driver_context.soil_fertilizer_inventory.*, .mineral_fertilizer = &driver_context.mineral_fertilizer_inventory.*, .fertilizer_band = &driver_context.fertilizer_band_state.*, .reactive_nitrogen = &driver_context.soil_reactive_nitrogen_state.*, .microbial_phosphorus = &driver_context.soil_microbial_phosphorus_state.*, .nutrient_competition = &driver_context.soil_nutrient_competition_history.* },
                .soil_organic_matter = .{ .profile = &driver_context.soil_organic_state.*, .surface = &driver_context.surface_organic_state.*, .litter_chemistry = &driver_context.surface_litter_chemistry_state.*, .litter_fertilizer = &driver_context.surface_litter_fertilizer_state.*, .surface_respiration = &driver_context.surface_microbial_respiration_state.*, .surface_autotrophic = &driver_context.surface_autotrophic_complex_state.*, .surface_denitrification = &driver_context.surface_denitrification_state.*, .surface_fire_exchange = &driver_context.surface_fire_exchange_state.*, .litter_salt_ingress = &driver_context.plant_litter_salt_ingress_state.* },
                .transport = .{ .micropore = &driver_context.micropore_solute_state.*, .macropore = &driver_context.macropore_solute_state.*, .mineral_nitrogen = &driver_context.mineral_nitrogen_transport_state.*, .organic = &driver_context.soil_organic_transport_state.*, .gas = &driver_context.gas_transport_state.*, .litter_gas = &driver_context.litter_gas_transport_state.*, .snow = &driver_context.snow_transport_state.*, .surface = &driver_context.surface_transport_state.* },
                .soil_geometry_and_hydrology = .{ .geometry = &driver_context.soil_geometry_state.*, .hydrology = &driver_context.transport_hydrology_state.*, .surface = &driver_context.surface_precipitation_state.*, .erosion = &driver_context.surface_erosion_state.*, .suspended = &driver_context.suspended_constituent_state.*, .climate = &timeline_state.climate_state, .eroded_minerals = &driver_context.eroded_mineral_state.*, .runtime = .{ .soil_properties = &driver_context.soil_solver_property_state.*, .soil_thermal = &driver_context.soil_thermal_state.*, .soil_chemistry_layer_parameters = driver_context.soil_chemistry_layer_parameters.* }, .surface_boundary = .{ .ground_air = &driver_context.ground_air_state.*, .surface_aerodynamics = &driver_context.surface_aerodynamic_state.*, .atmospheric_carrier = &driver_context.atmospheric_canopy_gas_state.* }, .water_table = .{ .topology = &driver_context.soil_boundary_topology_state.* }, .adaptive_hour_schedule = &driver_context.fixed_hour_recovery_workspace.*.adaptive_hour_schedule, .surface_litter_geometry = &driver_context.surface_litter_geometry_state.*, .surface_litter_ice_m3 = driver_context.surface_litter_ice_m3.*, .delayed_live_canopy_combustion_heat_megajoules = driver_context.delayed_live_canopy_combustion_heat_megajoules.*, .delayed_standing_dead_combustion_heat_megajoules = driver_context.delayed_standing_dead_combustion_heat_megajoules.*, .delayed_subsurface_combustion_heat_megajoules = driver_context.delayed_subsurface_combustion_heat_megajoules.*, .delayed_root_uptake_heat_megajoules = driver_context.delayed_root_uptake_heat_megajoules.*, .delayed_surface_combustion_heat_megajoules = driver_context.delayed_surface_combustion_heat_megajoules.* },
                .landscape_mass_balance = driver_context.landscape_mass_balance_state.*,
                .plant_accounting = .{ .daily_flux = &driver_context.plant_daily_flux_ledger.*, .root_soil_exchange = &driver_context.plant_root_soil_exchange_state.*, .cumulative_harvest_salt_mol_by_plant = driver_context.cumulative_harvest_salt_mol_by_plant.*, .cumulative_water_source_m3_by_plant = driver_context.plant_water_state_update_state.*.cumulative_water_source_m3_by_plant },
            },
            .{ .section_write_buffer_bytes = 64 * 1024, .section_verify_buffer_bytes = 64 * 1024, .manifest_write_buffer_bytes = 16 * 1024 },
        );
        try driver_context.output_hour_coordinator.*.checkpointDidPublish(.{
            .checkpoint_generation = @intCast(driver_context.executed_weather_hours.*),
            .output_generation = @intCast(driver_context.executed_weather_hours.*),
            .instant = accepted_output_instant,
        });
    }
}

/// Advances one fixed external hour. Weather is materialized before rollback
/// capture, and every rollback defer remains live through accepted output and
/// checkpoint publication at the end of this call.
/// Applies post-science management, coupling, and accepted-process
/// accounting while the caller's outer-hour rollback defers remain live.
noinline fn postScienceAccounting(driver_context: anytype, advance_context: anytype, post_context: anytype) !void {
    try postScienceManagementAndGasAccounting(driver_context, advance_context, post_context);
    try postScienceCanopyFireAndCloseout(driver_context, advance_context);
}

noinline fn postScienceManagementAndGasAccounting(driver_context: anytype, advance_context: anytype, post_context: anytype) !void {
    if (driver_context.harvest_context.*) |*context|
        context.current_day_of_year = @intCast(post_context.current_day_of_year.*);
    // GROSUB 406-464 recomputes FWOOD/FWODR before its harvest
    // blocks from current-hour stalk and sapwood. Keep a durable
    // per-plant runtime owner so all later automatic, scheduled,
    // mortality, and thinning paths see the same current state.
    if (driver_context.harvest_context.* != null) {
        const canopy_state = driver_context.harvest_context.*.?.canopy_state;
        for (driver_context.belowground_harvest_composition_by_plant.*.?, driver_context.shoot_growth_plant_parameters.*, 0..) |*composition, parameters, plant| {
            const branches = try canopy_state.branchRange(plant);
            var stalk_carbon_g_c: f64 = 0;
            var sapwood_carbon_g_c: f64 = 0;
            for (branches.first..branches.end) |branch| {
                stalk_carbon_g_c += canopy_state.branch_stalk_carbon_g[branch];
                sapwood_carbon_g_c += canopy_state.branch_sapwood_carbon_g[branch];
            }
            composition.* = try ecosys.plant_harvest_runtime.sourceOrderBelowgroundHarvestComposition(
                parameters.turnover_type != 0,
                parameters.root_profile_type > 1,
                parameters.growth_habit,
                stalk_carbon_g_c,
                sapwood_carbon_g_c,
                parameters.nitrogen_to_carbon_g_n_per_g_c[2],
                parameters.root_nitrogen_to_carbon_g_n_per_g_c,
                parameters.phosphorus_to_carbon_g_p_per_g_c[2],
                parameters.root_phosphorus_to_carbon_g_p_per_g_c,
                driver_context.runscript.*.plant_pool_parameters.plant_root_structural_presence_g_per_plant,
                driver_context.runscript.*.root_metabolism_parameters.nonwoody_root_fraction_exponent,
            );
        }
    }
    try ecosys.outer_hour_transaction.Transaction.injectFailureForTest(.after_soil_solve);
    if (driver_context.harvest_context.* != null and driver_context.plant_phenology_state.* != null) {
        var transitioned = false;
        for (driver_context.plant_phenology_state.*.?.leafout_transition_this_step, 0..) |leafout, plant| {
            if (!leafout or !driver_context.plant_phenology_state.*.?.active[plant] or driver_context.plant_topology_controls.*.growth_habit_code[plant] == 0) continue;
            transitioned = true;
        }
        if (transitioned) for (0..driver_context.runtime_plant_count.*) |plant| {
            const exported = try ecosys.plant_harvest_runtime.publishPlantProducts(&driver_context.harvest_context.*.?, plant);
            const harvest_activity: ecosys.hourly_cell_conservation.BoundaryActivity = .{
                .carbon_output_g = exported.carbon_g,
                .nitrogen_output_g = exported.nitrogen_g,
                .phosphorus_output_g = exported.phosphorus_g,
            };
            const cell = plant / driver_context.config.*.plant_populations;
            try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, harvest_activity);
            try ecosys.layer_local_conservation.accumulateCanopyHarvest(
                &driver_context.hourly_layer_boundary_ledger.*,
                cell,
                exported.carbon_g,
                exported.nitrogen_g,
                exported.phosphorus_g,
            );
            try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, harvest_activity);
            try driver_context.plant_daily_flux_ledger.*.accumulateHarvest(plant, exported.carbon_g, exported.nitrogen_g, exported.phosphorus_g);
        };
    }
    // GROSUB creates an immediate grain/JHVST=2 event when the
    // main branch of a self-seeding deciduous annual enters
    // end-of-season reproductive turnover.
    if (driver_context.harvest_context.* != null) {
        const automatic_harvest_date = try ecosys.execution_calendar_date.fromDayOfYear(
            post_context.current_day_of_year.*,
            @intCast(post_context.current_year.*),
        );
        const automatic_self_seed_count = try ecosys.plant_harvest_runtime.applyAutomaticSelfSeedingHarvests(
            &driver_context.harvest_context.*.?,
            driver_context.seasonal_turnover_event_by_plant.*,
            driver_context.plant_topology_controls.*.growth_habit_code,
            driver_context.plant_topology_controls.*.leaf_phenology_code,
            .{ .day = automatic_harvest_date.day, .month = automatic_harvest_date.month, .year = automatic_harvest_date.year },
        );
        if (automatic_self_seed_count > 0) for (0..driver_context.runtime_plant_count.*) |plant| {
            const exported = try ecosys.plant_harvest_runtime.publishPlantProducts(&driver_context.harvest_context.*.?, plant);
            const harvest_activity: ecosys.hourly_cell_conservation.BoundaryActivity = .{
                .carbon_output_g = exported.carbon_g,
                .nitrogen_output_g = exported.nitrogen_g,
                .phosphorus_output_g = exported.phosphorus_g,
            };
            const cell = plant / driver_context.config.*.plant_populations;
            try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, harvest_activity);
            try ecosys.layer_local_conservation.accumulateCanopyHarvest(
                &driver_context.hourly_layer_boundary_ledger.*,
                cell,
                exported.carbon_g,
                exported.nitrogen_g,
                exported.phosphorus_g,
            );
            try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, harvest_activity);
            try driver_context.plant_daily_flux_ledger.*.accumulateHarvest(plant, exported.carbon_g, exported.nitrogen_g, exported.phosphorus_g);
        };
    }
    // GROSUB 12549--12572 consumes IFLGI after every producer in
    // the current GROSUB, including automatic self-seeding at
    // 4572--4599. Read the HFUNC counters advanced earlier this
    // hour, then stage production reconstruction for the next
    // IFLGC gate. Keep reseed_pending set: it is the production
    // token that preserves retained seed and standing-dead
    // inventories during reconstruction, not legacy IFLGI.
    if (driver_context.plant_phenology_state.* != null and driver_context.plant_growth_stage_state.* != null and driver_context.plant_dormancy_state.* != null) {
        for (0..driver_context.runtime_plant_count.*) |plant| {
            if (!driver_context.plant_phenology_state.*.?.reseed_pending[plant]) continue;
            advance_context.dormant_seed_branches.*.items.len = 0;
            const branch_range = try driver_context.plant_growth_stage_state.*.?.branchRange(plant);
            const cell = plant / driver_context.config.*.plant_populations;
            const boundary_base = cell * (driver_context.soil_geometry_state.*.layer_capacity + 1);
            const soil_surface_boundary_depth_m = driver_context.soil_geometry_state.*.boundary_depth_m[boundary_base + driver_context.soil_geometry_state.*.first_active_layer[cell]];
            for (branch_range.first..branch_range.end) |branch| {
                const branch_dormancy = driver_context.plant_dormancy_state.*.?.branches[branch];
                try advance_context.dormant_seed_branches.*.append(driver_context.allocator.*, .{
                    .leafout_disabled = branch_dormancy.leafout_disabled,
                    .accumulated_leafout_h = branch_dormancy.accumulated_leafout_h,
                    .required_leafout_h = driver_context.development_dormancy_parameters.*[plant].required_leafout_h,
                });
            }
            const activation = try ecosys.plant_harvest_runtime.sourceOrderDormantSeedActivation(
                true,
                driver_context.plant_phenology_state.*.?.reseed_pending[plant],
                advance_context.dormant_seed_branches.*.items,
                post_context.current_day_of_year.*,
                post_context.current_year.*,
                soil_surface_boundary_depth_m,
            ) orelse continue;
            driver_context.plant_phenology_state.*.?.active[plant] = false;
            driver_context.plant_phenology_state.*.?.lifecycle_initialized[plant] = false;
            driver_context.development_planting_day_of_year.*[plant] = activation.planting_day_of_year;
            driver_context.development_planting_year.*[plant] = activation.planting_year;
            if (driver_context.plant_water_workspace.* != null) driver_context.plant_water_workspace.*.?.seeding_depth_m[plant] = activation.seeding_depth_m;
        }
    }
    // Tillage is a late-GROSUB transaction. Applying it here keeps
    // current-hour growth and FWODR composition, and prevents the
    // removed roots from regrowing before the next hour.
    var deferred_tillage_runtime: ?ecosys.redist_tillage_runtime_adapter.Context = null;
    if (driver_context.disturbance_schedule_maps.*[advance_context.pass.*.scene_index] != null) {
        const disturbance_source_hour =
            try ecosys.disturbance_management_dispatch.sourceHourOneThroughTwentyFour(
                try post_context.timestamp.*.modelClockHour(),
            );
        var surface_litter_removal_context: ecosys.disturbance_management_dispatch.SurfaceLitterRemovalContext = .{
            .runtime = .{
                .surface_organic = &driver_context.surface_organic_state.*,
                .surface_chemistry = &driver_context.surface_litter_chemistry_state.*,
                .surface_fertilizer = &driver_context.surface_litter_fertilizer_state.*,
                .surface_denitrification = &driver_context.surface_denitrification_state.*,
                .surface_geometry = &driver_context.surface_litter_geometry_state.*,
                .litter_water_m3 = driver_context.surface_precipitation_state.*.litter_water_m3,
                .litter_ice_m3 = driver_context.surface_litter_ice_m3.*,
                .surface_temperature_k = driver_context.state.*.surface_temperature_k,
                .geometry_parameters = driver_context.surface_gas_parameters.*.litter_geometry,
                .ice_density_megagrams_per_m3 = driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.ice_density_megagrams_per_m3,
                .nitrogen_g_per_mol = driver_context.runscript.*.fertilizer_nitrogen_molar_mass_g_per_mol,
                .phosphorus_g_per_mol = driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol,
            },
            .carbon_export_g_c_per_h_by_cell = driver_context.surface_organic_carbon_export_g_c_per_h.*,
            .nitrogen_export_g_n_per_h_by_cell = driver_context.surface_organic_nitrogen_export_g_n_per_h.*,
            .phosphorus_export_g_p_per_h_by_cell = driver_context.surface_organic_phosphorus_export_g_p_per_h.*,
            .cumulative_heat_output_megajoules = &driver_context.landscape_mass_balance_state.*.boundary_ledger.cumulative.heat_output_megajoules,
        };
        var disturbance_context: ecosys.disturbance_management_dispatch.ApplyContext = .{
            .roots = &driver_context.plant_root_state.*.?,
            .litter_partition = &driver_context.plant_litter_partition_state.*.?,
            .soil_organic = &driver_context.soil_organic_state.*,
            .grid = &driver_context.state.*,
            .species_count = driver_context.config.*.plant_populations,
            .plant_assignments = &driver_context.plant_assignments.*.?,
            .plant_unit_by_cell = driver_context.plant_unit_by_cell.*.?,
            .biological_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
            .root_nonwoody_fraction_by_plant = driver_context.plant_water_workspace.*.?.woody_root_fraction,
            .biomass_turnover_type_by_plant = driver_context.canopy_layer_controls.*.biomass_turnover_type,
            .root_profile_type_by_plant = driver_context.canopy_layer_controls.*.root_profile_type,
            .growth_habit_by_plant = driver_context.plant_topology_controls.*.growth_habit_code,
            .leaf_phenology_type_by_plant = driver_context.plant_topology_controls.*.leaf_phenology_code,
            .planting_day_of_year_by_plant = driver_context.development_planting_day_of_year.*,
            .planting_year_by_plant = driver_context.development_planting_year.*,
            .current_day_of_year = post_context.current_day_of_year.*,
            .current_year = @intCast(post_context.current_year.*),
            .source_hour_one_through_twenty_four = disturbance_source_hour,
            .solar_noon_hour_by_cell = advance_context.solar_noon_hour_by_cell.*,
            .soil_boundary_topology = &driver_context.soil_boundary_topology_state.*,
            .terrain_hydrology = &driver_context.terrain_hydrology_state.*,
            .soil_geometry = &driver_context.soil_geometry_state.*,
            .plant_harvest = if (driver_context.harvest_context.*) |*value| value else null,
            .root_litter_carbon_ledger = &driver_context.root_litter_carbon_ledger.*,
            .surface_energy = &driver_context.surface_energy_state.*,
            .fire_active_this_hour = driver_context.fire_active_this_hour.*,
            .surface_litter_removal = &surface_litter_removal_context,
            .tillage_runtime = .{
                .allocator = driver_context.allocator.*,
                .local_activity = &driver_context.tillage_local_activity.*,
                .grid = &driver_context.state.*,
                .geometry = &driver_context.soil_geometry_state.*,
                .properties = &driver_context.soil_solver_property_state.*,
                .thermal = &driver_context.soil_thermal_state.*,
                .soil_organic = &driver_context.soil_organic_state.*,
                .soil_organic_transport = &driver_context.soil_organic_transport_state.*,
                .surface_organic = &driver_context.surface_organic_state.*,
                .soil_gas = &driver_context.gas_transport_state.*,
                .surface_gas = &driver_context.litter_gas_transport_state.*,
                .soil_chemistry = &driver_context.initial_chemistry_state.*,
                .surface_chemistry = &driver_context.surface_litter_chemistry_state.*,
                .surface_geometry = &driver_context.surface_litter_geometry_state.*,
                .fertilizer_band = &driver_context.fertilizer_band_state.*,
                .fertilizer_nitrogen = &driver_context.soil_fertilizer_inventory.*,
                .surface_fertilizer = &driver_context.surface_litter_fertilizer_state.*,
                .mineral_fertilizer = &driver_context.mineral_fertilizer_inventory.*,
                .reactive_nitrogen = &driver_context.soil_reactive_nitrogen_state.*,
                .micropore_solutes = &driver_context.micropore_solute_state.*,
                .macropore_solutes = &driver_context.macropore_solute_state.*,
                .mineral_nitrogen_transport = &driver_context.mineral_nitrogen_transport_state.*,
                .chemistry_layer_parameters = driver_context.soil_chemistry_layer_parameters.*,
                .surface_denitrification = &driver_context.surface_denitrification_state.*,
                .surface_solute_transport = &driver_context.surface_transport_state.*,
                .plant_litter_salt_ingress = &driver_context.plant_litter_salt_ingress_state.*,
                .surface_water_m3 = driver_context.surface_precipitation_state.*.litter_water_m3,
                .surface_ice_m3 = driver_context.surface_litter_ice_m3.*,
                .surface_heat_capacity_megajoules_per_k = driver_context.surface_heat_capacity_megajoules_per_k.*,
                .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
                .salinity_enabled_by_cell = driver_context.salinity_enabled_by_cell.*,
                .minimum_layer_thickness_m = driver_context.runscript.*.soil_geometry_parameters.minimum_layer_thickness_m,
                .dry_organic_heat_capacity_megajoules_per_g_c_k = driver_context.runscript.*.surface_pond_dry_organic_heat_capacity_megajoules_per_g_c_k,
                .liquid_water_heat_capacity_megajoules_per_m3_k = driver_context.runscript.*.soil_phase_heat_parameters.liquid_water_heat_capacity_megajoules_per_m3_k,
                .physical_ice_heat_capacity_megajoules_per_m3_k = driver_context.runscript.*.soil_phase_heat_parameters.ice_heat_capacity_megajoules_per_m3_k,
                .ice_density_megagrams_per_m3 = driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.ice_density_megagrams_per_m3,
                .latent_heat_of_fusion_megajoules_per_m3 = driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.latent_heat_of_fusion_megajoules_per_m3,
                .pure_water_melting_temperature_k = driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.pure_water_freezing_temperature_k,
                .carbon_g_per_mol = 12.0,
                .nitrogen_g_per_mol = driver_context.runscript.*.fertilizer_nitrogen_molar_mass_g_per_mol,
                .phosphorus_g_per_mol = driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol,
            },
        };
        disturbance_context.deferred_tillage_soil_by_cell = driver_context.deferred_tillage_soil_by_cell.*;
        deferred_tillage_runtime = disturbance_context.tillage_runtime;
        _ = try ecosys.disturbance_management_dispatch.dispatchDatePhase(
            driver_context.disturbance_schedule_maps.*[advance_context.pass.*.scene_index].?,
            driver_context.disturbance_catalog.*,
            try ecosys.plant_management_dispatch.dateFromTimestamp(post_context.timestamp.*),
            &disturbance_context,
            .post_science,
        );
        // Census the aboveground tillage branch on the count the dispatch
        // accumulated, not on the fact that a dispatch happened. This runs
        // every hour, and `dispatchDatePhase`'s own return value counts every
        // operation kind, so either would report tillage as exercised on a deck
        // that tilled nothing -- the false positive already caught once on the
        // soil half (`:3988`). `disturbance_context` is a fresh local per hour,
        // so the counter starts at zero without an explicit reset.
        //
        // Only the `.post_science` phase can reach it: `:809-812` routes `.fire`
        // to pre-science and everything else, including `.tillage`, here. A
        // record at the pre-science site would be dead.
        if (disturbance_context.aboveground_tillage_plant_count != 0)
            driver_context.stage_census.*.recordCurrent(.tillage_aboveground_application);
        if (driver_context.harvest_context.* != null) for (0..driver_context.runtime_plant_count.*) |plant| {
            const exported = try ecosys.plant_harvest_runtime.publishPlantProducts(&driver_context.harvest_context.*.?, plant);
            const harvest_activity: ecosys.hourly_cell_conservation.BoundaryActivity = .{
                .carbon_output_g = exported.carbon_g,
                .nitrogen_output_g = exported.nitrogen_g,
                .phosphorus_output_g = exported.phosphorus_g,
            };
            const cell = plant / driver_context.config.*.plant_populations;
            try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, harvest_activity);
            try ecosys.layer_local_conservation.accumulateCanopyHarvest(
                &driver_context.hourly_layer_boundary_ledger.*,
                cell,
                exported.carbon_g,
                exported.nitrogen_g,
                exported.phosphorus_g,
            );
            try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, harvest_activity);
            try driver_context.plant_daily_flux_ledger.*.accumulateHarvest(plant, exported.carbon_g, exported.nitrogen_g, exported.phosphorus_g);
        };
    }
    // REDIST 11090--11100 is outside the event-code arms but
    // inside the once-daily, per-cell solar-noon gate. Apply it
    // even when a cell has no disturbance schedule.
    for (0..driver_context.state.*.cell_count) |cell| {
        if (post_context.timestamp.*.hour != advance_context.solar_noon_hour_by_cell.*[cell]) continue;
        const first = driver_context.soil_geometry_state.*.first_active_layer[cell];
        if (driver_context.soil_geometry_state.*.active_layer_count[cell] == 0 or first >= driver_context.soil_geometry_state.*.layer_capacity)
            return error.InvalidActiveSoilLayerRange;
        const surface_boundary_depth_m = driver_context.soil_geometry_state.*.boundary_depth_m[
            try driver_context.soil_geometry_state.*.boundaryIndex(cell, first)
        ];
        _ = try driver_context.soil_boundary_topology_state.*.advanceMobileTablesAtSolarNoon(
            cell,
            surface_boundary_depth_m,
            driver_context.transport_hydrology_state.*.boundary_water_exchange_m3_per_step[cell],
            driver_context.canopy_cell_area_m2.*[cell],
        );
    }
    if (driver_context.harvest_context.* != null and driver_context.management_schedule_map.* != null and driver_context.plant_phenology_state.* != null) {
        @memset(driver_context.grazing_average_shoot_carbon_g_c.*, 0);
        @memset(driver_context.grazing_active_cell_count.*, 0);
        const canopy = &driver_context.detailed_canopy_state.*.?;
        for (0..driver_context.runtime_plant_count.*) |plant| {
            if (!driver_context.plant_phenology_state.*.?.active[plant]) continue;
            const species = plant % driver_context.config.*.plant_populations;
            driver_context.grazing_average_shoot_carbon_g_c.*[species] += canopy.plant_total_shoot_carbon_g[plant];
            driver_context.grazing_active_cell_count.*[species] += 1;
        }
        for (driver_context.grazing_average_shoot_carbon_g_c.*, driver_context.grazing_active_cell_count.*) |*average, count| {
            if (count > 0) average.* /= @floatFromInt(count);
        }
        try ecosys.plant_management_dispatch.accumulateGrazingRebalanceTotals(
            driver_context.management_schedule_map.*.?,
            driver_context.plant_management_catalog.*,
            post_context.management_date.*,
            canopy.plant_total_shoot_carbon_g,
            driver_context.plant_phenology_state.*.?.active,
            driver_context.grazing_total_shoot_carbon_g_c_by_cell.*,
            driver_context.grazing_total_grazer_biomass_by_cell.*,
        );
        const GrazingDispatch = struct {
            harvest: *ecosys.plant_harvest_runtime.Context,
            average_shoot_carbon_g_c: []const f64,
            cell_area_m2: []const f64,
            active: []const bool,
            turnover_type: []const u8,
            root_profile_type: []const u8,
            total_shoot_carbon_g_c_by_cell: []const f64,
            total_grazer_biomass_by_cell: []const f64,
            species_count: usize,
            is_monthly_self_thinning_day: bool,
            solar_noon_hour_by_cell: []const u8,
            current_hour_of_day: u8,

            fn apply(self: *@This(), plant: usize, event: ecosys.plant_management.HarvestEvent) !void {
                if (!self.active[plant]) return;
                const species = plant % self.species_count;
                const cell = plant / self.species_count;
                if (self.is_monthly_self_thinning_day and
                    self.current_hour_of_day == self.solar_noon_hour_by_cell[cell] and
                    self.turnover_type[plant] != 0 and self.root_profile_type[plant] > 1) return;
                var effective_event = event;
                if (event.kind == .animal_grazing and self.total_shoot_carbon_g_c_by_cell[cell] > 0) {
                    effective_event.cutting_height_m_or_lai_fraction =
                        self.total_grazer_biomass_by_cell[cell] *
                        self.harvest.canopy_state.plant_total_shoot_carbon_g[plant] /
                        self.total_shoot_carbon_g_c_by_cell[cell];
                }
                _ = try ecosys.plant_harvest_runtime.applyGrazingEvent(
                    self.harvest,
                    plant,
                    effective_event,
                    self.average_shoot_carbon_g_c[species],
                    self.cell_area_m2[cell],
                );
            }
        };
        var grazing_dispatch: GrazingDispatch = .{
            .harvest = &driver_context.harvest_context.*.?,
            .average_shoot_carbon_g_c = driver_context.grazing_average_shoot_carbon_g_c.*,
            .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
            .active = driver_context.plant_phenology_state.*.?.active,
            .turnover_type = driver_context.canopy_layer_controls.*.biomass_turnover_type,
            .root_profile_type = driver_context.canopy_layer_controls.*.root_profile_type,
            .total_shoot_carbon_g_c_by_cell = driver_context.grazing_total_shoot_carbon_g_c_by_cell.*,
            .total_grazer_biomass_by_cell = driver_context.grazing_total_grazer_biomass_by_cell.*,
            .species_count = driver_context.config.*.plant_populations,
            .is_monthly_self_thinning_day = post_context.current_day_of_year.* % 30 == 0,
            .solar_noon_hour_by_cell = advance_context.solar_noon_hour_by_cell.*,
            .current_hour_of_day = post_context.timestamp.*.hour,
        };
        _ = try ecosys.plant_management_dispatch.dispatchDateGrazing(
            driver_context.management_schedule_map.*.?,
            driver_context.plant_management_catalog.*,
            post_context.management_date.*,
            &grazing_dispatch,
            GrazingDispatch.apply,
        );
        for (0..driver_context.runtime_plant_count.*) |plant| {
            const exported = try ecosys.plant_harvest_runtime.publishPlantProducts(&driver_context.harvest_context.*.?, plant);
            const harvest_activity: ecosys.hourly_cell_conservation.BoundaryActivity = .{
                .carbon_output_g = exported.carbon_g,
                .nitrogen_output_g = exported.nitrogen_g,
                .phosphorus_output_g = exported.phosphorus_g,
            };
            const cell = plant / driver_context.config.*.plant_populations;
            try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, harvest_activity);
            try ecosys.layer_local_conservation.accumulateCanopyHarvest(
                &driver_context.hourly_layer_boundary_ledger.*,
                cell,
                exported.carbon_g,
                exported.nitrogen_g,
                exported.phosphorus_g,
            );
            try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, harvest_activity);
            try driver_context.plant_daily_flux_ledger.*.accumulateHarvest(plant, exported.carbon_g, exported.nitrogen_g, exported.phosphorus_g);
        }
    }
    // GROSUB monthly forest self-thinning is evaluated at each
    // cell's own local solar noon after the current-hour stem
    // diameter refresh (cells may be assigned distinct weather
    // streams with distinct solar-noon hours).
    if (driver_context.harvest_context.* != null and post_context.current_day_of_year.* % 30 == 0) {
        for (0..driver_context.runtime_plant_count.*) |plant| {
            const cell = plant / driver_context.config.*.plant_populations;
            if (post_context.timestamp.*.hour != advance_context.solar_noon_hour_by_cell.*[cell]) continue;
            if (driver_context.canopy_layer_controls.*.biomass_turnover_type[plant] == 0 or
                driver_context.canopy_layer_controls.*.root_profile_type[plant] <= 1 or
                driver_context.plant_phenology_state.* == null or !driver_context.plant_phenology_state.*.?.active[plant]) continue;
            if (driver_context.management_schedule_map.* != null and
                !try ecosys.plant_management_dispatch.allowsForestSelfThinning(
                    driver_context.management_schedule_map.*.?,
                    driver_context.plant_management_catalog.*,
                    try ecosys.plant_management_dispatch.dateFromTimestamp(post_context.timestamp.*),
                    plant,
                )) continue;
            const thinned_fraction = try ecosys.plant_harvest_runtime.applyForestSelfThinning(&driver_context.harvest_context.*.?, plant);
            if (thinned_fraction > 0) {
                const exported = try ecosys.plant_harvest_runtime.publishPlantProducts(&driver_context.harvest_context.*.?, plant);
                const harvest_activity: ecosys.hourly_cell_conservation.BoundaryActivity = .{
                    .carbon_output_g = exported.carbon_g,
                    .nitrogen_output_g = exported.nitrogen_g,
                    .phosphorus_output_g = exported.phosphorus_g,
                };
                try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, harvest_activity);
                try ecosys.layer_local_conservation.accumulateCanopyHarvest(
                    &driver_context.hourly_layer_boundary_ledger.*,
                    cell,
                    exported.carbon_g,
                    exported.nitrogen_g,
                    exported.phosphorus_g,
                );
                try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, harvest_activity);
                try driver_context.plant_daily_flux_ledger.*.accumulateHarvest(plant, exported.carbon_g, exported.nitrogen_g, exported.phosphorus_g);
            }
        }
    }
    if (driver_context.harvest_context.* != null and driver_context.management_schedule_map.* != null) {
        // Solar-noon deterministic harvest is gated per cell,
        // not on the global stream-0 solar noon, since cells may
        // be assigned distinct weather streams with distinct
        // solar-noon hours (mirrors the fertilizer dispatch fix).
        const NonGrazingHarvestDispatch = struct {
            inner: *ecosys.plant_harvest_runtime.Context,
            solar_noon_hour_by_cell: []const u8,
            current_hour_of_day: u8,
            species_count: usize,

            fn apply(self: *@This(), plant: usize, event: ecosys.plant_management.HarvestEvent) !void {
                const cell = plant / self.species_count;
                if (self.current_hour_of_day != self.solar_noon_hour_by_cell[cell]) return;
                try ecosys.plant_harvest_runtime.applyEvent(self.inner, plant, event);
            }
        };
        const harvest_date = try ecosys.plant_management_dispatch.dateFromTimestamp(post_context.timestamp.*);
        var non_grazing_harvest_dispatch: NonGrazingHarvestDispatch = .{
            .inner = &driver_context.harvest_context.*.?,
            .solar_noon_hour_by_cell = advance_context.solar_noon_hour_by_cell.*,
            .current_hour_of_day = post_context.timestamp.*.hour,
            .species_count = driver_context.config.*.plant_populations,
        };
        _ = try ecosys.plant_management_dispatch.dispatchDateNonGrazing(
            driver_context.management_schedule_map.*.?,
            driver_context.plant_management_catalog.*,
            harvest_date,
            &non_grazing_harvest_dispatch,
            NonGrazingHarvestDispatch.apply,
        );
        for (driver_context.harvest_products_by_plant.*.?, 0..) |ledger, plant| {
            const cell = plant / driver_context.config.*.plant_populations;
            if (post_context.timestamp.*.hour != advance_context.solar_noon_hour_by_cell.*[cell]) continue;
            // Census the two harvest stages from the ACCEPTED product ledger,
            // which is the pattern `canopy_photosynthesis_occurred` and
            // `symbiotic_nitrogen_fixation` already use: read the outcome, not
            // the dispatch. `applyEvent` returns `!void`, so a record at its
            // call site above could only say "a harvest event was dispatched
            // this hour", which is the false positive already caught once on
            // tillage (`ecosys_ng.zig:3988`). Read here, before
            // `publishPlantProducts` consumes the ledger.
            //
            // `harvested_grain` is written only by
            // `photosynthesis_harvest.harvestReproductiveOrgans`, so it is
            // exactly this stage's question.
            if (ledger.harvested_grain.carbon_g != 0)
                driver_context.stage_census.*.recordCurrent(.harvest_reproductive_organs);
            // The non-grain, non-foliar groups: `woody` is the branch/stalk
            // structural fraction and `nonstructural` the mobile reserve, with
            // `nonfoliar` covering the remaining non-leaf organs. Any of them
            // moving means this stage ran; naming all three is deliberate
            // because an annual maize/soybean carries almost no woody mass, so
            // gating on `woody` alone would under-report.
            const branch_stalk_and_reserve_carbon_g =
                ledger.woody.ecosystem_export.carbon_g + ledger.woody.litter.carbon_g +
                ledger.nonstructural.ecosystem_export.carbon_g + ledger.nonstructural.litter.carbon_g +
                ledger.nonfoliar.ecosystem_export.carbon_g + ledger.nonfoliar.litter.carbon_g;
            if (branch_stalk_and_reserve_carbon_g != 0)
                driver_context.stage_census.*.recordCurrent(.harvest_branch_stalk_and_reserve);
            const exported = try ecosys.plant_harvest_runtime.publishPlantProducts(&driver_context.harvest_context.*.?, plant);
            const harvest_activity: ecosys.hourly_cell_conservation.BoundaryActivity = .{
                .carbon_output_g = exported.carbon_g,
                .nitrogen_output_g = exported.nitrogen_g,
                .phosphorus_output_g = exported.phosphorus_g,
            };
            try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, harvest_activity);
            try ecosys.layer_local_conservation.accumulateCanopyHarvest(
                &driver_context.hourly_layer_boundary_ledger.*,
                cell,
                exported.carbon_g,
                exported.nitrogen_g,
                exported.phosphorus_g,
            );
            try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, harvest_activity);
            try driver_context.plant_daily_flux_ledger.*.accumulateHarvest(plant, exported.carbon_g, exported.nitrogen_g, exported.phosphorus_g);
        }
    }
    try driver_context.daily_soil_gas_flux.*.accumulateHour(
        if (driver_context.plant_root_state.*) |*roots| roots else null,
        driver_context.config.*.plant_populations,
        driver_context.config.*.soil_layers,
        driver_context.soil_gas_transport_state.*.atmospheric_flux_g_per_h,
        driver_context.surface_litter_gas_transport_state.*.atmospheric_flux_g_per_h,
    );
    // PR-O2-01B / O2-BIND: publish accepted external subsurface O2
    // through the same physical-boundary DAY storage that already
    // carries the nitrogen species. `subsurface_flux_g_per_h` is a
    // different array from `atmospheric_flux_g_per_h` consumed by
    // `accumulateHour` above, so no term is booked twice, and the
    // REDIST diagnostic fields stay out of the audit partition.
    try driver_context.daily_soil_gas_flux.*.accumulateSubsurfacePhysicalBoundaryHour(
        driver_context.config.*.soil_layers,
        driver_context.state.*.active_soil_layer_count,
        driver_context.soil_gas_transport_state.*.subsurface_flux_g_per_h,
    );
    // Publish the same accepted dry-gas boundary producers to
    // their independent layer/surface owners. This deliberately
    // excludes root exchange, which has its own layer sidecar.
    try ecosys.layer_local_conservation.accumulateSoilSurfaceGasAtmosphere(
        &driver_context.hourly_layer_boundary_ledger.*,
        driver_context.state.*.active_soil_layer_count,
        driver_context.soil_gas_transport_state.*.atmospheric_flux_g_per_h,
        driver_context.soil_gas_transport_state.*.subsurface_flux_g_per_h,
        driver_context.surface_litter_gas_transport_state.*.atmospheric_flux_g_per_h,
    );
    // The hourly cell gate consumes the same accepted producer
    // values as DAY gas accounting, never a difference of its
    // cumulative arrays. Preflight the whole grid before booking
    // any cell so a late invalid gas leaves this ledger unchanged.
    for (0..driver_context.state.*.cell_count) |cell| {
        const atmospheric = try driver_context.daily_soil_gas_flux.*.currentHourElementActivityForCell(
            if (driver_context.plant_root_state.*) |*roots| roots else null,
            driver_context.config.*.plant_populations,
            driver_context.config.*.soil_layers,
            driver_context.soil_gas_transport_state.*.atmospheric_flux_g_per_h,
            driver_context.surface_litter_gas_transport_state.*.atmospheric_flux_g_per_h,
            cell,
        );
        const subsurface = try driver_context.daily_soil_gas_flux.*.currentHourSubsurfacePhysicalActivityForCell(
            driver_context.config.*.soil_layers,
            driver_context.state.*.active_soil_layer_count,
            driver_context.soil_gas_transport_state.*.subsurface_flux_g_per_h,
            cell,
        );
        const gas_activity = try atmospheric.add(subsurface);
        try driver_context.hourly_cell_boundary_ledger.*.preflight(
            cell,
            try ecosys.hourly_cell_conservation.signedElementActivity(.{
                .carbon_g = gas_activity.carbon_net_input_g_c,
                .oxygen_g = gas_activity.oxygen_net_input_g_o,
                .nitrogen_g = gas_activity.nitrogen_net_input_g_n,
                .hydrogen_g = gas_activity.hydrogen_net_input_g_h,
            }),
        );
    }
    for (0..driver_context.state.*.cell_count) |cell| {
        const atmospheric = driver_context.daily_soil_gas_flux.*.currentHourElementActivityForCell(
            if (driver_context.plant_root_state.*) |*roots| roots else null,
            driver_context.config.*.plant_populations,
            driver_context.config.*.soil_layers,
            driver_context.soil_gas_transport_state.*.atmospheric_flux_g_per_h,
            driver_context.surface_litter_gas_transport_state.*.atmospheric_flux_g_per_h,
            cell,
        ) catch unreachable;
        const subsurface = driver_context.daily_soil_gas_flux.*.currentHourSubsurfacePhysicalActivityForCell(
            driver_context.config.*.soil_layers,
            driver_context.state.*.active_soil_layer_count,
            driver_context.soil_gas_transport_state.*.subsurface_flux_g_per_h,
            cell,
        ) catch unreachable;
        const gas_activity = atmospheric.add(subsurface) catch unreachable;
        try driver_context.hourly_cell_boundary_ledger.*.accumulate(
            cell,
            ecosys.hourly_cell_conservation.signedElementActivity(.{
                .carbon_g = gas_activity.carbon_net_input_g_c,
                .oxygen_g = gas_activity.oxygen_net_input_g_o,
                .nitrogen_g = gas_activity.nitrogen_net_input_g_n,
                .hydrogen_g = gas_activity.hydrogen_net_input_g_h,
            }) catch unreachable,
        );
    }
    // REDIST lines 4465--4507: accumulate soil/litter gas boundary
    // fluxes and precipitation/irrigation dissolved gases into the
    // source-signed hourly element ledgers.
    for (0..driver_context.state.*.cell_count) |cell| {
        const first_layer = cell * driver_context.config.*.soil_layers;
        const layer_count = driver_context.state.*.active_soil_layer_count[cell];
        const co2_species = @intFromEnum(ecosys.gas_transport.Species.carbon_dioxide);
        const ch4_species = @intFromEnum(ecosys.gas_transport.Species.methane);
        const o2_species = @intFromEnum(ecosys.gas_transport.Species.oxygen);
        var co2_soil_surface_flux: f64 = 0;
        var ch4_soil_surface_flux: f64 = 0;
        var o2_soil_surface_flux: f64 = 0;
        const co2_litter_flux = driver_context.surface_litter_gas_transport_state.*.atmospheric_flux_g_per_h[cell * ecosys.gas_transport.species_count + co2_species];
        const ch4_litter_flux = driver_context.surface_litter_gas_transport_state.*.atmospheric_flux_g_per_h[cell * ecosys.gas_transport.species_count + ch4_species];
        const o2_litter_flux = driver_context.surface_litter_gas_transport_state.*.atmospheric_flux_g_per_h[cell * ecosys.gas_transport.species_count + o2_species];
        var subsurface_irrigation_m3_per_h: f64 = 0;
        for (first_layer..first_layer + layer_count) |layer| {
            subsurface_irrigation_m3_per_h += driver_context.irrigation_loads.*.subsurface_water_m3[layer];
        }
        for (first_layer..first_layer + layer_count) |layer| {
            co2_soil_surface_flux += driver_context.soil_gas_transport_state.*.atmospheric_flux_g_per_h[layer * ecosys.gas_transport.species_count + co2_species];
            ch4_soil_surface_flux += driver_context.soil_gas_transport_state.*.atmospheric_flux_g_per_h[layer * ecosys.gas_transport.species_count + ch4_species];
            o2_soil_surface_flux += driver_context.soil_gas_transport_state.*.atmospheric_flux_g_per_h[layer * ecosys.gas_transport.species_count + o2_species];
        }
        const carbon_fluxes = ecosys.redist_surface_gas_flux_accounting.SurfaceGasFluxes{
            .soil_surface_exchange_g = co2_soil_surface_flux,
            .mineral_layer_convective_g = 0,
            .bulk_mass_transfer_g = 0,
            .litter_layer_convective_g = co2_litter_flux,
            .litter_volatilization_g = 0,
        };
        const methane_fluxes = ecosys.redist_surface_gas_flux_accounting.SurfaceGasFluxes{
            .soil_surface_exchange_g = ch4_soil_surface_flux,
            .mineral_layer_convective_g = 0,
            .bulk_mass_transfer_g = 0,
            .litter_layer_convective_g = ch4_litter_flux,
            .litter_volatilization_g = 0,
        };
        const oxygen_fluxes = ecosys.redist_surface_gas_flux_accounting.SurfaceGasFluxes{
            .soil_surface_exchange_g = o2_soil_surface_flux,
            .mineral_layer_convective_g = 0,
            .bulk_mass_transfer_g = 0,
            .litter_layer_convective_g = o2_litter_flux,
            .litter_volatilization_g = 0,
        };
        const aqueous = ecosys.redist_surface_gas_flux_accounting.AqueousFluxes{
            .rain_to_surface_m3 = driver_context.surface_precipitation_state.*.water_to_matrix_m3_per_h[cell] + driver_context.surface_precipitation_state.*.water_to_macropore_m3_per_h[cell],
            .rain_to_litter_m3 = driver_context.surface_precipitation_state.*.water_to_litter_m3_per_h[cell],
            .irrigation_to_surface_m3 = driver_context.irrigation_loads.*.surface_water_m3[cell],
            .irrigation_to_litter_m3 = 0,
        };
        var precipitation_gas = std.mem.zeroes(
            ecosys.precipitation_irrigation_dissolved_gases.DissolvedGasConcentrations,
        );
        var irrigation_gas = std.mem.zeroes(
            ecosys.precipitation_irrigation_dissolved_gases.DissolvedGasConcentrations,
        );
        {
            const parameters = driver_context.surface_gas_parameters.*;
            const dissolved = try ecosys.precipitation_irrigation_dissolved_gases.calculate(
                .{
                    .carbon_dioxide_g_m3 = driver_context.atmospheric_canopy_gas_state.*.mass_concentration_g_per_m3[cell * ecosys.gas_transport.species_count + co2_species],
                    .methane_g_m3 = driver_context.atmospheric_canopy_gas_state.*.mass_concentration_g_per_m3[cell * ecosys.gas_transport.species_count + ch4_species],
                    .oxygen_g_m3 = driver_context.atmospheric_canopy_gas_state.*.mass_concentration_g_per_m3[cell * ecosys.gas_transport.species_count + o2_species],
                    .nitrogen_g_m3 = driver_context.atmospheric_canopy_gas_state.*.mass_concentration_g_per_m3[cell * ecosys.gas_transport.species_count + @intFromEnum(ecosys.gas_transport.Species.nitrogen)],
                    .nitrous_oxide_g_m3 = driver_context.atmospheric_canopy_gas_state.*.mass_concentration_g_per_m3[cell * ecosys.gas_transport.species_count + @intFromEnum(ecosys.gas_transport.Species.nitrous_oxide)],
                },
                .{
                    .carbon_dioxide_ratio = parameters.solubility.reference_water_to_air[co2_species],
                    .methane_ratio = parameters.solubility.reference_water_to_air[ch4_species],
                    .oxygen_ratio = parameters.solubility.reference_water_to_air[o2_species],
                    .nitrogen_ratio = parameters.solubility.reference_water_to_air[@intFromEnum(ecosys.gas_transport.Species.nitrogen)],
                    .nitrous_oxide_ratio = parameters.solubility.reference_water_to_air[@intFromEnum(ecosys.gas_transport.Species.nitrous_oxide)],
                },
                .{
                    .carbon_dioxide = parameters.precipitation_activity_log[co2_species],
                    .methane = parameters.precipitation_activity_log[ch4_species],
                    .oxygen = parameters.precipitation_activity_log[o2_species],
                    .nitrogen = parameters.precipitation_activity_log[@intFromEnum(ecosys.gas_transport.Species.nitrogen)],
                    .nitrous_oxide = parameters.precipitation_activity_log[@intFromEnum(ecosys.gas_transport.Species.nitrous_oxide)],
                },
                driver_context.atmospheric_state.*.air_temperature_k[cell] - 273.15,
            );
            precipitation_gas = dissolved.precipitation;
            irrigation_gas = dissolved.irrigation;
        }
        const carbon_flux = try ecosys.redist_surface_gas_flux_accounting.computeCarbonGas(.{
            .co2_fluxes = carbon_fluxes,
            .ch4_fluxes = methane_fluxes,
            .aqueous = aqueous,
            .co2_rain_concentration_g_per_m3 = precipitation_gas.carbon_dioxide_g_m3,
            .co2_irrigation_concentration_g_per_m3 = irrigation_gas.carbon_dioxide_g_m3,
            .ch4_rain_concentration_g_per_m3 = precipitation_gas.methane_g_m3,
            .ch4_irrigation_concentration_g_per_m3 = irrigation_gas.methane_g_m3,
            .subsurface_irrigation_m3_per_h = subsurface_irrigation_m3_per_h,
            .litter_subsurface_co2_transfer_g = 0,
            .timestep_h = 1,
        });
        // REDIST-ROGOX-ORDER-001: ROGOX(0)/RC4OX(0) (litter fire
        // O2-limited uptake and CH4 combustion, REDIST lines
        // 4498--4499) are not known until
        // `surface_fire_exchange_state.finalizeSurfaceCell` runs
        // later this hour (mirrors TRNSFR, soil.f:201, running
        // before REDIST, soil.f:221, in the Fortran source).
        // Cache everything else needed for the O2/H2 boundary
        // ledger here and finish the computation, plus the
        // accumulator/ledger updates that depend on it, in the
        // deferred pass right after that finalize loop below.
        driver_context.pending_surface_gas_ledger.*[cell] = .{
            .co2_surface_input_g = carbon_flux.co2_surface_input_g,
            .ch4_surface_input_g = carbon_flux.ch4_surface_input_g,
            .total_subsurface_carbon_flux_g = carbon_flux.total_subsurface_carbon_flux_g,
            .oxygen_hydrogen_inputs = .{
                .o2_fluxes = oxygen_fluxes,
                .h2_fluxes = std.mem.zeroes(ecosys.redist_surface_gas_flux_accounting.SurfaceGasFluxes),
                .aqueous = aqueous,
                .o2_rain_concentration_g_per_m3 = precipitation_gas.oxygen_g_m3,
                .o2_irrigation_concentration_g_per_m3 = irrigation_gas.oxygen_g_m3,
                .subsurface_irrigation_m3_per_h = subsurface_irrigation_m3_per_h,
                // RUPOXO is driven by surface microbial O2 uptake in this port.
                .litter_microbial_o2_uptake_g = blk: {
                    var microbial_o2_uptake_g: f64 = 0;
                    const first = cell * ecosys.surface_microbial_oxygen_driver.unit_count_per_cell;
                    for (0..ecosys.surface_microbial_oxygen_driver.unit_count_per_cell) |unit| {
                        microbial_o2_uptake_g +=
                            driver_context.surface_microbial_oxygen_state.*.allocation.oxygen_uptake_g_o[first + unit];
                    }
                    break :blk microbial_o2_uptake_g;
                },
                // Placeholders; overwritten from
                // `surface_fire_exchange_state` in the deferred
                // pass once this hour's litter combustion exists.
                .litter_o2_limited_uptake_g = 0,
                .litter_ch4_combustion_g_c = 0,
                .litter_h2_output_g = -driver_context.surface_microbial_oxygen_state.*.respiration_hydrogen_g_h_per_step[cell],
                .timestep_h = 1,
            },
        };
    }
    for (0..driver_context.state.*.cell_count) |cell| {
        var evaporation_m3: f64 = driver_context.ground_surface_evaporation_m3_per_h.*[cell];
        var canopy_atmospheric_input_m3: f64 = 0;
        for (0..driver_context.config.*.plant_populations) |species| {
            const plant = cell * driver_context.config.*.plant_populations + species;
            const atmospheric_exchange = try ecosys.plant_water_state_update.atmosphericBoundaryExchange(
                if (driver_context.canopy_surface_exchange_state.*) |exchange| exchange.transpiration_m3_per_h[plant] else 0,
                if (driver_context.canopy_surface_exchange_state.*) |exchange| exchange.intercepted_water_change_m3_per_h[plant] else 0,
                driver_context.standing_dead_evaporation_m3_per_h.*[plant],
            );
            // Preserve signed TEVAPP physics while retaining both
            // gross sides: positive living/dead condensation is an
            // atmospheric input, and negative source terms are an
            // atmospheric output. Splitting before cell reduction
            // prevents different plants from hiding one another.
            canopy_atmospheric_input_m3 += atmospheric_exchange.input_m3_per_h;
            evaporation_m3 += atmospheric_exchange.output_m3_per_h;
        }
        var external_water_outflow_m3: f64 = 0;
        var external_water_inflow_m3: f64 = 0;
        for (0..driver_context.state.*.active_soil_layer_count[cell]) |local_layer| {
            const layer = try driver_context.state.*.layerIndex(cell, local_layer);
            external_water_outflow_m3 += @max(0, driver_context.transport_hydrology_state.*.micropore_external_water_flux_m3_per_step[layer]);
            external_water_outflow_m3 += @max(0, driver_context.transport_hydrology_state.*.macropore_external_water_flux_m3_per_step[layer]);
            external_water_inflow_m3 += @max(0, -driver_context.transport_hydrology_state.*.micropore_external_water_flux_m3_per_step[layer]);
            external_water_inflow_m3 += @max(0, -driver_context.transport_hydrology_state.*.macropore_external_water_flux_m3_per_step[layer]);
        }
        const top_layer = try driver_context.state.*.layerIndex(cell, 0);
        const bulk_density_megagrams_per_m3 = driver_context.soil_solver_property_state.*.bulk_density_megagrams_per_m3[top_layer];
        if (!std.math.isFinite(bulk_density_megagrams_per_m3) or bulk_density_megagrams_per_m3 <= 0) return error.InvalidOutputSoilBulkDensity;
        // The daily water producer already has every accepted
        // external term in native per-cell units. Publish the
        // same terms before its cumulative reduction. Surface
        // runoff is excluded here because its routing producer
        // books external and intercell water at acceptance;
        // artificial drainage is already part of the Richards
        // external outflow above.
        try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, .{
            .water_input_m3 = driver_context.atmospheric_state.*.precipitation_m[cell] * driver_context.canopy_cell_area_m2.*[cell] +
                driver_context.ground_surface_condensation_m3_per_h.*[cell] + canopy_atmospheric_input_m3 + external_water_inflow_m3,
            .water_output_m3 = evaporation_m3 + external_water_outflow_m3,
        });
        try driver_context.daily_water_ledger.*.accumulateCell(cell, .{
            // This legacy precipitation/condensation carrier already
            // includes ground condensation; include canopy and
            // standing-dead condensation on the same boundary side.
            .rainfall_m3 = driver_context.atmospheric_state.*.precipitation_m[cell] * driver_context.canopy_cell_area_m2.*[cell] +
                driver_context.ground_surface_condensation_m3_per_h.*[cell] + canopy_atmospheric_input_m3,
            .boundary_water_inflow_m3 = external_water_inflow_m3,
            .evaporation_m3 = evaporation_m3,
            // Routing and the daily ledger both store positive export amounts.
            // Only the legacy hourly output adapter uses signed runoff flux.
            .runoff_m3 = driver_context.surface_runoff_state.*.exported_water_m3[cell],
            .water_outflow_m3 = external_water_outflow_m3,
            .lateral_water_outflow_m3 = driver_context.transport_hydrology_state.*.artificial_drainage_outflow_m3_per_step[cell],
            .sediment_outflow_m3 = driver_context.surface_erosion_state.*.routing.sediment_export_megagrams[cell] / bulk_density_megagrams_per_m3,
            .boundary_water_exchange_gain_m3 = @max(0, driver_context.transport_hydrology_state.*.boundary_water_exchange_m3_per_step[cell]),
            .boundary_water_exchange_loss_m3 = @max(0, -driver_context.transport_hydrology_state.*.boundary_water_exchange_m3_per_step[cell]),
        });
        const active_layers = driver_context.state.*.active_soil_layer_count[cell];
        const first_layer = try driver_context.state.*.layerIndex(cell, 0);
        const first_solute = first_layer * driver_context.aqueous_species_count.*;
        const cell_solute_boundary = driver_context.soil_solute_boundary_net_flux_mol.*[first_solute..][0 .. active_layers * driver_context.aqueous_species_count.*];
        const ionic_inflow_mol = try ecosys.solute_transport_species.legacyBoundaryIonInput(cell_solute_boundary);
        const ionic_outflow_mol = try ecosys.solute_transport_species.legacyBoundaryIonOutflow(cell_solute_boundary);
        try driver_context.daily_heat_ledger.*.accumulateHour(
            cell,
            active_layers,
            driver_context.atmospheric_state.*.shortwave_radiation_megajoules_per_m2[cell],
            driver_context.atmospheric_state.*.air_temperature_k[cell],
            driver_context.atmospheric_state.*.vapor_pressure_kpa[cell],
            driver_context.atmospheric_state.*.wind_speed_m_per_h[cell],
            driver_context.atmospheric_state.*.precipitation_m[cell],
            driver_context.state.*.soil_temperature_k[first_layer .. first_layer + active_layers],
            driver_context.state.*.surface_temperature_k[cell],
            ionic_inflow_mol,
            ionic_outflow_mol,
        );
    }
    try driver_context.daily_heterotrophic_respiration.*.accumulateHour(&driver_context.state.*);
    try driver_context.daily_carbon_export.*.accumulateOrganicDrainageHour(&driver_context.state.*, &driver_context.soil_organic_transport_state.*);
    try driver_context.daily_carbon_export.*.accumulateOrganicRunoffHour(driver_context.surface_organic_carbon_export_g_c_per_h.*);
    try driver_context.daily_carbon_export.*.accumulateInorganicRunoffHour(driver_context.surface_inorganic_carbon_export_g_c_per_h.*);
    try driver_context.daily_carbon_export.*.accumulateDissolvedInorganicDrainageHour(&driver_context.state.*, &driver_context.soil_dissolved_gas_transport_state.*);
    try driver_context.daily_carbon_export.*.accumulateGaseousInorganicDrainageHour(&driver_context.state.*, &driver_context.soil_gas_transport_state.*);
    try driver_context.daily_carbon_export.*.accumulateSoluteCarbonateDrainageHour(
        &driver_context.state.*,
        driver_context.soil_solute_boundary_net_flux_mol.*,
        driver_context.aqueous_species_count.*,
        12,
    );
    try driver_context.daily_phosphorus_export.*.accumulateOrganicDrainageHour(&driver_context.state.*, &driver_context.soil_organic_transport_state.*);
    try driver_context.daily_phosphorus_export.*.accumulateInorganicDrainageHour(
        &driver_context.state.*,
        driver_context.soil_solute_boundary_net_flux_mol.*,
        driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol,
    );
    try driver_context.daily_phosphorus_export.*.accumulateRunoffHour(
        driver_context.surface_organic_phosphorus_export_g_p_per_h.*,
        driver_context.surface_inorganic_phosphorus_export_g_p_per_h.*,
    );
    try driver_context.daily_nitrogen_export.*.accumulateOrganicDrainageHour(&driver_context.state.*, &driver_context.soil_organic_transport_state.*);
    try driver_context.daily_nitrogen_export.*.accumulateInorganicDrainageHour(&driver_context.state.*, &driver_context.mineral_nitrogen_transport_state.*);
    try driver_context.daily_nitrogen_export.*.accumulateDissolvedGasDrainageHour(
        &driver_context.state.*,
        &driver_context.soil_dissolved_gas_transport_state.*,
    );
    try driver_context.daily_nitrogen_export.*.accumulateRunoffHour(
        driver_context.surface_organic_nitrogen_export_g_n_per_h.*,
        driver_context.surface_inorganic_nitrogen_export_g_n_per_h.*,
    );
    // PR-O2-01C / EXEC-O2-BALANCE-005: legacy REDIST books
    // subsurface microbial O2 consumption into `OXYGOU`
    // (`redist.f:627`, `OXYGOU=OXYGOU-OXR`). The Zig oxygen solver
    // already removes this mass from the gaseous/aqueous soil gas
    // pools that the landscape inventory counts as storage, but no
    // ledger consumer existed, so the whole of it showed up as an
    // unbooked day-1 storage loss. The surface/litter counterpart
    // is already booked through `litter_microbial_o2_uptake_g` in
    // the REDIST surface gas path, so only the subsurface term is
    // added here and nothing is counted twice.
    try driver_context.landscape_mass_balance_state.*.boundary_ledger
        .accumulateAcceptedSoilMicrobialOxygenUptake(
        driver_context.soil_microbial_oxygen_state.*.oxygen_uptake_g_o,
    );
    try ecosys.hourly_cell_conservation.accumulateSoilMicrobialOxygenUptake(
        &driver_context.hourly_cell_boundary_ledger.*,
        driver_context.state.*.active_soil_layer_count,
        driver_context.state.*.soil_layer_capacity,
        driver_context.soil_microbial_oxygen_state.*.population_count,
        driver_context.soil_microbial_oxygen_state.*.oxygen_uptake_g_o,
    );
    // PR-O2-01D / EXEC-O2-BALANCE-006: dissolved O2 leaving on
    // surface runoff (`redist.f:1095`, `OXS`). Distinct from the
    // microbial sink above and from the REDIST subsurface gas
    // outflow already tracked in
    // `redist_oxygen_subsurface_output_g_o`.
    try driver_context.landscape_mass_balance_state.*.boundary_ledger
        .accumulateAcceptedSurfaceDissolvedOxygenRunoff(
        driver_context.surface_dissolved_oxygen_export_g_o_per_h.*,
    );
    if (advance_context.scene_weather_hours.* < 24) {
        var diagnostic_rain_m3: f64 = 0;
        var diagnostic_water_output_m3: f64 = 0;
        var diagnostic_ground_evaporation_m3: f64 = 0;
        var diagnostic_ground_condensation_m3: f64 = 0;
        var diagnostic_transpiration_m3: f64 = 0;
        var diagnostic_living_interception_evaporation_m3: f64 = 0;
        var diagnostic_dead_evaporation_m3: f64 = 0;
        var diagnostic_runoff_m3: f64 = 0;
        var diagnostic_external_outflow_m3: f64 = 0;
        var diagnostic_lateral_outflow_m3: f64 = 0;
        for (0..driver_context.state.*.cell_count) |cell| {
            diagnostic_rain_m3 += driver_context.daily_water_ledger.*.rainfall_m3[cell] + driver_context.daily_water_ledger.*.boundary_water_inflow_m3[cell];
            diagnostic_ground_evaporation_m3 += driver_context.ground_surface_evaporation_m3_per_h.*[cell];
            diagnostic_ground_condensation_m3 += driver_context.ground_surface_condensation_m3_per_h.*[cell];
            for (0..driver_context.config.*.plant_populations) |species| {
                const plant = cell * driver_context.config.*.plant_populations + species;
                if (driver_context.canopy_surface_exchange_state.*) |exchange| {
                    diagnostic_transpiration_m3 += @max(0, -exchange.transpiration_m3_per_h[plant]);
                    diagnostic_living_interception_evaporation_m3 += @max(0, -exchange.intercepted_water_change_m3_per_h[plant]);
                }
                diagnostic_dead_evaporation_m3 += @max(0, -driver_context.standing_dead_evaporation_m3_per_h.*[plant]);
            }
            diagnostic_water_output_m3 += driver_context.daily_water_ledger.*.runoff_m3[cell] +
                driver_context.daily_water_ledger.*.evaporation_m3[cell] +
                driver_context.daily_water_ledger.*.water_outflow_m3[cell];
            diagnostic_runoff_m3 += driver_context.daily_water_ledger.*.runoff_m3[cell];
            diagnostic_external_outflow_m3 += driver_context.daily_water_ledger.*.water_outflow_m3[cell];
            diagnostic_lateral_outflow_m3 += driver_context.daily_water_ledger.*.lateral_water_outflow_m3[cell];
        }
        const diagnostic_totals = try reconstructLandscapeMassBalance(driver_context.hourly_science_context.*);
        std.log.debug("hourly water closure: hour={d} residual_m3={e} storage_change_m3={e} rain_m3={e} output_m3={e} current_ground_evaporation_m3={e} current_ground_condensation_m3={e}", .{ advance_context.scene_weather_hours.* + 1, diagnostic_totals.water_storage_m3 - driver_context.landscape_mass_balance_state.*.monitor.?.baseline.water_m3 - diagnostic_rain_m3 + diagnostic_water_output_m3, diagnostic_totals.water_storage_m3 - driver_context.landscape_mass_balance_state.*.monitor.?.baseline.water_m3, diagnostic_rain_m3, diagnostic_water_output_m3, diagnostic_ground_evaporation_m3, diagnostic_ground_condensation_m3 });
        const diagnostic_boundary = driver_context.landscape_mass_balance_state.*.boundary_ledger.cumulative;
        // NOTE: this read precedes the surface/canopy heat booking
        // (`accumulateAcceptedSurfaceAndCanopyHeat`, ~700 lines below),
        // so `heat_output_megajoules` here lags the storage term by one
        // hour and this residual is NOT the audited quantity. Correcting
        // the phase by hand makes the cumulative residual converge on the
        // day-1 audit total (ratio 0.969 -> 0.992 -> 1.0, hours 20--23).
        std.log.debug("hourly heat closure: hour={d} residual_megajoules={e} storage_change_megajoules={e} heat_input_megajoules={e} heat_output_megajoules={e} internal_production_megajoules={e} internal_consumption_megajoules={e}", .{ advance_context.scene_weather_hours.* + 1, diagnostic_totals.heat_storage_megajoules - driver_context.landscape_mass_balance_state.*.monitor.?.baseline.heat_megajoules - diagnostic_boundary.heat_input_megajoules + diagnostic_boundary.heat_output_megajoules - driver_context.landscape_mass_balance_state.*.boundary_ledger.cumulative_internal.heat_production_megajoules + driver_context.landscape_mass_balance_state.*.boundary_ledger.cumulative_internal.heat_consumption_megajoules, diagnostic_totals.heat_storage_megajoules - driver_context.landscape_mass_balance_state.*.monitor.?.baseline.heat_megajoules, diagnostic_boundary.heat_input_megajoules, diagnostic_boundary.heat_output_megajoules, driver_context.landscape_mass_balance_state.*.boundary_ledger.cumulative_internal.heat_production_megajoules, driver_context.landscape_mass_balance_state.*.boundary_ledger.cumulative_internal.heat_consumption_megajoules });
        // EXEC-002 follow-on: the oxygen audit fails on day 1 and
        // blocks any multi-day heat measurement, so report its hourly
        // closure on the same footing as heat.
        std.log.debug("hourly oxygen closure: hour={d} residual_g={e} storage_change_g={e} oxygen_input_g={e} oxygen_output_g={e}", .{ advance_context.scene_weather_hours.* + 1, diagnostic_totals.oxygen_storage_g - driver_context.landscape_mass_balance_state.*.monitor.?.baseline.oxygen_g - diagnostic_boundary.oxygen_input_g + diagnostic_boundary.oxygen_output_g, diagnostic_totals.oxygen_storage_g - driver_context.landscape_mass_balance_state.*.monitor.?.baseline.oxygen_g, diagnostic_boundary.oxygen_input_g, diagnostic_boundary.oxygen_output_g });
        {
            // EXEC-004: break the surface organic carbon down by pool
            // family so the family losing the unaccounted carbon can be
            // named rather than guessed at.
            var surface_structural_g_c: f64 = 0;
            var surface_residue_g_c: f64 = 0;
            var surface_dissolved_g_c: f64 = 0;
            var surface_adsorbed_g_c: f64 = 0;
            var surface_microbial_g_c: f64 = 0;
            var surface_acetate_g_c: f64 = 0;
            for (driver_context.surface_organic_state.*.structural) |pool| surface_structural_g_c += pool.carbon_g_c;
            for (driver_context.surface_organic_state.*.residue) |pool| surface_residue_g_c += pool.carbon_g_c;
            for (driver_context.surface_organic_state.*.dissolved) |pool| surface_dissolved_g_c += pool.carbon_g_c;
            for (driver_context.surface_organic_state.*.adsorbed) |pool| surface_adsorbed_g_c += pool.carbon_g_c;
            for (driver_context.surface_organic_state.*.microbial) |pool| surface_microbial_g_c += pool.carbon_g_c;
            for (driver_context.surface_organic_state.*.dissolved_acetate_carbon_g_c) |value| surface_acetate_g_c += value;
            for (driver_context.surface_organic_state.*.adsorbed_acetate_carbon_g_c) |value| surface_acetate_g_c += value;
            std.log.debug("surface organic carbon families: hour={d} structural_g_c={e} residue_g_c={e} dissolved_g_c={e} adsorbed_g_c={e} microbial_g_c={e} acetate_g_c={e}", .{ advance_context.scene_weather_hours.* + 1, surface_structural_g_c, surface_residue_g_c, surface_dissolved_g_c, surface_adsorbed_g_c, surface_microbial_g_c, surface_acetate_g_c });
            // EXEC-004: `aggregateSurfaceOrganic` skips microbial
            // substrate 4 (humus) with `if (substrate == 4) continue`,
            // so carbon growing there is counted by neither the residue
            // nor the organic term. Split the microbial total by whether
            // the census counts it, to test that directly.
            var counted_microbial_g_c: f64 = 0;
            var skipped_microbial_g_c: f64 = 0;
            for (0..driver_context.state.*.cell_count) |cell| {
                for (0..ecosys.soil_organic_initialization.microbial_substrate_count) |substrate| {
                    const first = (cell * ecosys.soil_organic_initialization.microbial_substrate_count + substrate) *
                        ecosys.soil_organic_initialization.microbial_population_count *
                        ecosys.soil_organic_initialization.kinetic_fraction_count;
                    const count = ecosys.soil_organic_initialization.microbial_population_count *
                        ecosys.soil_organic_initialization.kinetic_fraction_count;
                    for (driver_context.surface_organic_state.*.microbial[first .. first + count]) |pool| {
                        if (substrate == 4) skipped_microbial_g_c += pool.carbon_g_c else counted_microbial_g_c += pool.carbon_g_c;
                    }
                }
            }
            std.log.debug("surface microbial census split: hour={d} counted_g_c={e} skipped_humus_g_c={e}", .{ advance_context.scene_weather_hours.* + 1, counted_microbial_g_c, skipped_microbial_g_c });
            // Report the independent aqueous and solid-mineral
            // litter-carbon owners on their authoritative carriers.
            var litter_inorganic_carbon_g_c: f64 = 0;
            var litter_aqueous_carbon_concentration_sum: f64 = 0;
            var litter_calcite_concentration_sum: f64 = 0;
            var litter_aqueous_carrier_m3: f64 = 0;
            var litter_mineral_reference_m3: f64 = 0;
            for (driver_context.surface_litter_chemistry_state.*.cells, 0..) |litter_cell, litter_index| {
                const aqueous_carrier = try ecosys.surface_litter_chemistry_carrier_rebase.effectiveAqueousCarrierM3(
                    driver_context.surface_precipitation_state.*.litter_water_m3[litter_index],
                    driver_context.surface_litter_chemistry_state.*.dry_reference_water_m3[litter_index],
                );
                const mineral_reference = driver_context.surface_litter_chemistry_state.*.mineral_reference_water_m3[litter_index];
                const aqueous_concentration = litter_cell.carbonate_mol_per_m3 + litter_cell.bicarbonate_mol_per_m3;
                litter_aqueous_carrier_m3 += aqueous_carrier;
                litter_mineral_reference_m3 += mineral_reference;
                litter_aqueous_carbon_concentration_sum += aqueous_concentration;
                litter_calcite_concentration_sum += litter_cell.salt_minerals.calcite_mol_per_m3;
                litter_inorganic_carbon_g_c += 12.0 *
                    (aqueous_carrier * aqueous_concentration +
                        mineral_reference * litter_cell.salt_minerals.calcite_mol_per_m3);
            }
            std.log.debug("litter inorganic carbon: hour={d} carbon_g_c={e} aqueous_carrier_m3={e} mineral_reference_m3={e} aqueous_concentration_sum_mol_per_m3={e} calcite_concentration_sum_mol_per_m3={e}", .{ advance_context.scene_weather_hours.* + 1, litter_inorganic_carbon_g_c, litter_aqueous_carrier_m3, litter_mineral_reference_m3, litter_aqueous_carbon_concentration_sum, litter_calcite_concentration_sum });
        }
        std.log.debug("current evap components: transpiration_m3={e} living_interception_m3={e} standing_dead_m3={e}", .{ diagnostic_transpiration_m3, diagnostic_living_interception_evaporation_m3, diagnostic_dead_evaporation_m3 });
        std.log.debug("cumulative water output components: runoff_m3={e} evaporation_m3={e} external_outflow_m3={e} lateral_outflow_m3={e}", .{ diagnostic_runoff_m3, diagnostic_water_output_m3 - diagnostic_runoff_m3 - diagnostic_external_outflow_m3 - diagnostic_lateral_outflow_m3, diagnostic_external_outflow_m3, diagnostic_lateral_outflow_m3 });
    }
    const soil_process_units = driver_context.soil_nitrogen_flux_workspace.*.process_unit_count_per_layer;
    const surface_process_units = driver_context.surface_microbial_mineral_exchange_state.*.h2po4_exchange_g_p.len / driver_context.state.*.cell_count;
    for (0..driver_context.state.*.cell_count) |cell| {
        var immobilization_g_p: f64 = 0;
        var immobilization_g_n: f64 = 0;
        for (0..driver_context.state.*.active_soil_layer_count[cell]) |local_layer| {
            const layer = try driver_context.state.*.layerIndex(cell, local_layer);
            const first_unit = layer * soil_process_units;
            for (first_unit..first_unit + soil_process_units) |unit| immobilization_g_p +=
                driver_context.soil_nitrogen_flux_workspace.*.non_band_microbial_h2po4_exchange_g_p[unit] +
                driver_context.soil_nitrogen_flux_workspace.*.band_microbial_h2po4_exchange_g_p[unit] +
                driver_context.soil_nitrogen_flux_workspace.*.non_band_microbial_hpo4_exchange_g_p[unit] +
                driver_context.soil_nitrogen_flux_workspace.*.band_microbial_hpo4_exchange_g_p[unit];
            for (first_unit..first_unit + soil_process_units) |unit| immobilization_g_n +=
                driver_context.soil_nitrogen_flux_workspace.*.non_band_microbial_ammonium_exchange_g_n[unit] +
                driver_context.soil_nitrogen_flux_workspace.*.band_microbial_ammonium_exchange_g_n[unit] +
                driver_context.soil_nitrogen_flux_workspace.*.non_band_microbial_nitrate_exchange_g_n[unit] +
                driver_context.soil_nitrogen_flux_workspace.*.band_microbial_nitrate_exchange_g_n[unit];
        }
        const surface_first = cell * surface_process_units;
        for (surface_first..surface_first + surface_process_units) |unit| immobilization_g_p +=
            driver_context.surface_microbial_mineral_exchange_state.*.h2po4_exchange_g_p[unit] +
            driver_context.surface_microbial_mineral_exchange_state.*.hpo4_exchange_g_p[unit] +
            driver_context.surface_topsoil_mineral_exchange_state.*.h2po4_exchange_g_p[unit] +
            driver_context.surface_topsoil_mineral_exchange_state.*.hpo4_exchange_g_p[unit];
        for (surface_first..surface_first + surface_process_units) |unit| immobilization_g_n +=
            driver_context.surface_microbial_mineral_exchange_state.*.ammonium_exchange_g_n[unit] +
            driver_context.surface_microbial_mineral_exchange_state.*.nitrate_exchange_g_n[unit] +
            driver_context.surface_topsoil_mineral_exchange_state.*.ammonium_exchange_g_n[unit] +
            driver_context.surface_topsoil_mineral_exchange_state.*.nitrate_exchange_g_n[unit];
        const autotrophic_exchange = try ecosys.surface_autotrophic_complex_step.mineralExchangeTotalsForCell(&driver_context.surface_autotrophic_complex_state.*, cell);
        immobilization_g_n += autotrophic_exchange.immobilization_g_n;
        immobilization_g_p += autotrophic_exchange.immobilization_g_p;
        const next = driver_context.daily_microbial_phosphate_mineralization_g_p.*[cell] - immobilization_g_p;
        if (!std.math.isFinite(next)) return error.NonFiniteDailyMicrobialPhosphateMineralization;
        driver_context.daily_microbial_phosphate_mineralization_g_p.*[cell] = next;
        const nitrogen_next = driver_context.daily_microbial_nitrogen_mineralization_g_n.*[cell] - immobilization_g_n;
        if (!std.math.isFinite(nitrogen_next)) return error.NonFiniteDailyMicrobialNitrogenMineralization;
        driver_context.daily_microbial_nitrogen_mineralization_g_n.*[cell] = nitrogen_next;
    }
    // Late GROSUB salt removal follows all natural turnover,
    // management harvest, grazing, and tillage state_updates.
    // This is the single serial pre-EXTRACT ownership boundary.
    if (std.mem.indexOfScalar(bool, driver_context.salinity_enabled_by_cell.*, true) != null) {
        const canopy = if (driver_context.detailed_canopy_state.*) |*value| value else return error.MissingCanopyForPlantSaltHarvest;
        const roots = if (driver_context.plant_root_state.*) |*value| value else return error.MissingPlantRootsForPlantSaltHarvest;
        for (0..driver_context.runtime_plant_count.*) |plant| {
            const cell = plant / driver_context.config.*.plant_populations;
            if (!driver_context.salinity_enabled_by_cell.*[cell]) continue;
            // `plant_populations` is domain-wide capacity. The legacy GROSUB
            // salt block iterates each cell's configured NP0, represented here
            // by non-empty per-plant branch ranges; never-assigned padding is
            // outside that cell-local population set.
            if (!try ecosys.plant_salt_harvest_adapter.hasAssignedBranches(canopy, plant)) continue;
            const active_domain_count = driver_context.root_metabolism_plant_parameters.*[plant].biologicalDomainCount();
            try driver_context.root_litter_carbon_ledger.*.carbonByPlantLayer(
                plant,
                active_domain_count,
                driver_context.root_litter_carbon_g_c_by_layer.*,
            );
            var natural_shoot_litter_carbon_g_c: f64 = 0;
            const natural_litter = driver_context.shoot_senescence_products_by_plant.*[plant];
            for (natural_litter.woody_carbon_g, natural_litter.nonwoody_carbon_g) |woody, nonwoody| {
                natural_shoot_litter_carbon_g_c += woody + nonwoody;
                if (!std.math.isFinite(natural_shoot_litter_carbon_g_c))
                    return error.NonFinitePlantSaltLitterCarbon;
            }
            try ecosys.plant_salt_harvest_adapter.applyPlant(
                &driver_context.plant_salt_harvest_workspace.*,
                canopy,
                roots,
                .{
                    .cumulative_harvest_salt_mol_by_plant = driver_context.cumulative_harvest_salt_mol_by_plant.*,
                    .litter_salt_mol_by_plant_exchange_layer = driver_context.litter_salt_mol_by_plant_exchange_layer.*,
                },
                plant,
                .{
                    .shoot_carbon_g_c = canopy.plant_total_shoot_carbon_g[plant],
                    .current_harvest_carbon_g_c = driver_context.plant_daily_flux_ledger.*.harvested_carbon_g[plant],
                    .previous_harvest_carbon_g_c = driver_context.harvest_carbon_at_hour_start_g_c_by_plant.*[plant],
                    .shoot_litterfall_carbon_g_c = natural_shoot_litter_carbon_g_c +
                        driver_context.shoot_harvest_litter_carbon_g_c_by_plant.*[plant],
                    .root_litterfall_carbon_g_c_by_layer = driver_context.root_litter_carbon_g_c_by_layer.*,
                    .active_root_domain_count = active_domain_count,
                    .carbon_absolute_tolerance_g_c = driver_context.config.*.physical_tolerance.carbon_g,
                    .salt_absolute_tolerance_mol = driver_context.config.*.physical_tolerance.amount_mol,
                    .physical_relative_tolerance = driver_context.config.*.physical_tolerance.relative,
                },
            );
        }
        // Unlike legacy TION, the hourly element inventory owns
        // living plant salts. Only the current-hour increment of
        // the cumulative harvest owner crosses that inventory's
        // boundary; uptake, litterfall and fire return remain
        // internal plant/soil transfers.
        for (0..driver_context.state.*.cell_count) |cell| {
            var harvested_salt_mol: [ecosys.plant_root_system.salt_species_count]f64 = @splat(0);
            const first_plant = cell * driver_context.config.*.plant_populations;
            for (first_plant..first_plant + driver_context.config.*.plant_populations) |plant| {
                const first_salt = plant * ecosys.plant_root_system.salt_species_count;
                for (0..ecosys.plant_root_system.salt_species_count) |salt| {
                    const index = first_salt + salt;
                    const increment = driver_context.cumulative_harvest_salt_mol_by_plant.*[index] -
                        driver_context.harvest_salt_at_hour_start_mol_by_plant_species.*[index];
                    if (!std.math.isFinite(increment) or increment < 0)
                        return error.InvalidPlantHarvestSaltIncrement;
                    harvested_salt_mol[salt] += increment;
                    if (!std.math.isFinite(harvested_salt_mol[salt]))
                        return error.NonFinitePlantHarvestSaltIncrement;
                }
            }
            const activity = try ecosys.hourly_cell_conservation
                .plantSaltElementActivity(&harvested_salt_mol, .output);
            try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, activity);
            try ecosys.layer_local_conservation.accumulateCanopyHarvestSalt(
                &driver_context.hourly_layer_boundary_ledger.*,
                cell,
                &harvested_salt_mol,
            );
            try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, activity);
        }
        try ecosys.litter_salt_state_update.refresh(
            &driver_context.litter_salt_state_update_state.*,
            .{
                .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                .mol_by_plant_exchange_layer_salt = driver_context.litter_salt_mol_by_plant_exchange_layer.*,
            },
        );
        try ecosys.plant_litter_salt_ingress.apply(
            &driver_context.plant_litter_salt_ingress_state.*,
            .{
                .species_count = driver_context.config.*.plant_populations,
                .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                .litter_salt_mol_by_plant_exchange_layer = driver_context.litter_salt_mol_by_plant_exchange_layer.*,
                .surface_water_m3 = driver_context.surface_precipitation_state.*.litter_water_m3,
                .soil_water_m3 = driver_context.state.*.matrix_liquid_water_m3,
                .water_absolute_tolerance_m3 = driver_context.config.*.physical_tolerance.water_volume_m3,
                .physical_relative_tolerance = driver_context.config.*.physical_tolerance.relative,
            },
            &driver_context.surface_litter_chemistry_state.*,
            &driver_context.initial_chemistry_state.*,
            &driver_context.micropore_solute_state.*,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger
            .accumulateAcceptedLegacyPlantSaltInput(
            driver_context.litter_salt_state_update_state.*
                .mol_by_cell_exchange_layer_salt,
        );
    }
    // REDIST must see the salts returned by the roots and shoots
    // it just killed. Complete the staged soil transaction only
    // after litter ingress has atomically updated chemistry and
    // its authoritative micropore mirror.
    if (deferred_tillage_runtime) |*runtime| {
        // The return value is the count of cells actually tilled; it skips
        // every cell whose request is not pending. Census on that, not on the
        // call: this dispatch runs every hour, and an unconditional record
        // here reported tillage as exercised 346 times on a deck that had
        // tilled nothing -- caught by the first run that measured it.
        const tilled_cell_count = try ecosys.disturbance_management_dispatch.applyDeferredTillageSoil(
            runtime,
            driver_context.deferred_tillage_soil_by_cell.*,
        );
        if (tilled_cell_count != 0)
            driver_context.stage_census.*.recordCurrent(.tillage_soil_application);
        try ecosys.layer_local_conservation.accumulateTillageActivity(
            &driver_context.hourly_layer_boundary_ledger.*,
            &driver_context.tillage_local_activity.*,
        );
    }
    if (std.log.logEnabled(.debug, .default)) {
        const checkpoint = try reconstructLandscapeMassBalance(driver_context.hourly_science_context.*);
        std.log.debug("phosphorus after plant salt ingress: hour={d} stored_g={e}", .{ advance_context.scene_weather_hours.* + 1, checkpoint.residue_phosphorus_g + checkpoint.organic_phosphorus_g + checkpoint.phosphate_phosphorus_g });
    }
}

noinline fn postScienceCanopyFireAndCloseout(driver_context: anytype, advance_context: anytype) !void {
    try postScienceCanopyAndEnergy(driver_context, advance_context);
    try postScienceFireAndCloseout(driver_context, advance_context);
}

noinline fn postScienceCanopyAndEnergy(driver_context: anytype, advance_context: anytype) !void {
    try postScienceManureAndPlantExchange(driver_context, advance_context);
    try postScienceCanopyEnergyAndWater(driver_context);
    try postScienceCanopyStructureAndHeat(driver_context, advance_context);
    try postScienceRootLedgers(driver_context);
}

noinline fn postScienceManureAndPlantExchange(driver_context: anytype, advance_context: anytype) !void {
    try ecosys.manure_deposition_state_update.refresh(
        &driver_context.manure_deposition_state_update_state.*,
        driver_context.hourly_manure_products_by_plant.*,
    );
    try ecosys.layer_local_conservation.accumulateCanopySurfaceManure(
        &driver_context.hourly_layer_boundary_ledger.*,
        driver_context.config.*.plant_populations,
        driver_context.hourly_manure_products_by_plant.*,
    );
    if (std.log.logEnabled(.debug, .default)) {
        const checkpoint = try reconstructLandscapeMassBalance(driver_context.hourly_science_context.*);
        std.log.debug("phosphorus after manure state_update: hour={d} stored_g={e}", .{ advance_context.scene_weather_hours.* + 1, checkpoint.residue_phosphorus_g + checkpoint.organic_phosphorus_g + checkpoint.phosphate_phosphorus_g });
    }
    // EXTRACT accumulates these source-signed hourly exchanges
    // for OUTPD before DAY carries balances and clears them.
    @memset(driver_context.root_soil_element_exchange_workspace.*, 0);
    if (driver_context.detailed_canopy_state.*) |*canopy| {
        const carbon_exchange = if (driver_context.canopy_carbon_exchange_state.*) |*value| value else return error.PlantDailyLedgerRequiresCarbonExchangeState;
        try ecosys.canopy_ammonia_state_update.refresh(
            &driver_context.canopy_ammonia_state_update_state.*,
            .{
                .plant_branch_offsets = canopy.plant_branch_offsets,
                .branch_exchange_g_n_per_h = canopy.branch_canopy_ammonia_exchange_g_n_per_h,
                .preceding_cumulative_exchange_g_n_by_plant = driver_context.plant_daily_flux_ledger.*.ammonia_exchange_g_n,
            },
        );
        for (0..driver_context.runtime_plant_count.*) |plant| {
            try driver_context.plant_daily_flux_ledger.*.publishCanopyAmmoniaCumulative(
                plant,
                driver_context.canopy_ammonia_state_update_state.*.cumulative_exchange_g_n_by_plant[plant],
            );
            const branches = try canopy.branchRange(plant);
            const canopy_fixed_nitrogen_g_n_per_h =
                try ecosys.canopy_symbiotic_respiration_fixation.sumFixedNitrogenPerHour(
                    canopy.branch_symbiotic_fixed_nitrogen_g_n_per_h[branches.first..branches.end],
                );
            driver_context.rse_canopy_fixation_g_n_per_h_by_plant.*[plant] = canopy_fixed_nitrogen_g_n_per_h;
            const carbon_flux = try carbon_exchange.fluxForPlant(canopy, plant);
            var signed_total_respiration_carbon_g = carbon_flux.signed_aboveground_respiration_g_c_per_h;
            if (driver_context.plant_root_state.*) |roots| {
                for (0..driver_context.root_metabolism_plant_parameters.*[plant].biologicalDomainCount()) |domain| for (0..driver_context.config.*.soil_layers) |layer| {
                    const root = try roots.layerIndex(plant, domain, layer);
                    signed_total_respiration_carbon_g -= roots.actual_respiration_g_c_per_h[root] +
                        roots.symbiotic_respiration_actual_g_c_per_h[root];
                };
            }
            try driver_context.plant_daily_flux_ledger.*.accumulateHourlyExchange(plant, .{
                // GROSUB 1843 / DAY 153--155: CARBN owns gross
                // CO2F; signed TCO2T is accumulated separately.
                // HCNET already contains shoot respiration and
                // disturbance, so binding it here double counts
                // both in BALC and in the hourly plant gate.
                .net_canopy_carbon_g = canopy.plant_gross_primary_productivity_g_c_per_h[plant],
                .gross_primary_productivity_g = canopy.plant_gross_primary_productivity_g_c_per_h[plant],
                .signed_total_respiration_carbon_g = signed_total_respiration_carbon_g,
                .signed_aboveground_respiration_carbon_g = carbon_flux.signed_aboveground_respiration_g_c_per_h,
            });
            if (driver_context.plant_root_state.*) |*roots| {
                var root_soil_carbon_exchange_g: f64 = 0;
                var root_soil_nitrogen_exchange_g: f64 = 0;
                var root_soil_phosphorus_exchange_g: f64 = 0;
                for (0..driver_context.root_metabolism_plant_parameters.*[plant].biologicalDomainCount()) |domain| for (0..driver_context.config.*.soil_layers) |layer| {
                    const root = try roots.layerIndex(plant, domain, layer);
                    for (0..ecosys.plant_root_system.organic_substrate_count) |fraction| {
                        const substrate =
                            root * ecosys.plant_root_system.organic_substrate_count +
                            fraction;
                        root_soil_carbon_exchange_g +=
                            roots.exudate_carbon_exchange_g_c_per_h[substrate];
                        root_soil_nitrogen_exchange_g +=
                            roots.exudate_nitrogen_exchange_g_n_per_h[substrate];
                        root_soil_phosphorus_exchange_g +=
                            roots.exudate_phosphorus_exchange_g_p_per_h[substrate];
                    }
                    driver_context.rse_phosphate_h2_by_plant.*[plant] +=
                        roots.phosphate_h2_uptake_nonband_g_p_per_h[root] +
                        roots.phosphate_h2_uptake_band_g_p_per_h[root];
                    driver_context.rse_phosphate_h_by_plant.*[plant] +=
                        roots.phosphate_h_uptake_nonband_g_p_per_h[root] +
                        roots.phosphate_h_uptake_band_g_p_per_h[root];
                };
                driver_context.rse_organic_carbon_by_plant.*[plant] = root_soil_carbon_exchange_g;
                driver_context.rse_organic_nitrogen_by_plant.*[plant] = root_soil_nitrogen_exchange_g;
                driver_context.rse_organic_phosphorus_by_plant.*[plant] = root_soil_phosphorus_exchange_g;
                root_soil_nitrogen_exchange_g +=
                    roots.ammonium_uptake_g_n_per_h[plant] +
                    roots.nitrate_uptake_g_n_per_h[plant];
                root_soil_phosphorus_exchange_g += roots.phosphate_uptake_g_p_per_h[plant];
                driver_context.root_soil_carbon_exchange_g_c_per_h_by_plant.*[plant] =
                    root_soil_carbon_exchange_g;
                driver_context.root_soil_nitrogen_exchange_g_n_per_h_by_plant.*[plant] =
                    root_soil_nitrogen_exchange_g;
                driver_context.root_soil_phosphorus_exchange_g_p_per_h_by_plant.*[plant] =
                    root_soil_phosphorus_exchange_g;
                try driver_context.plant_daily_flux_ledger.*.accumulateHourlyRootSoilExchange(
                    plant,
                    root_soil_carbon_exchange_g,
                    root_soil_nitrogen_exchange_g,
                    root_soil_phosphorus_exchange_g,
                    roots.fixation_uptake_g_n_per_h[plant] + canopy_fixed_nitrogen_g_n_per_h,
                );
            } else {
                try driver_context.plant_daily_flux_ledger.*.accumulateHourlyRootSoilExchange(
                    plant,
                    0,
                    0,
                    0,
                    canopy_fixed_nitrogen_g_n_per_h,
                );
            }
            const litterfall = try ecosys.plant_litterfall_state_update.totals(
                driver_context.shoot_senescence_products_by_plant.*[plant],
                driver_context.root_litter_products_by_plant.*[plant],
                .{
                    .carbon_g_c = driver_context.shoot_harvest_litter_carbon_g_c_by_plant.*[plant],
                    .nitrogen_g_n = driver_context.shoot_harvest_litter_nitrogen_g_n_by_plant.*[plant],
                    .phosphorus_g_p = driver_context.shoot_harvest_litter_phosphorus_g_p_by_plant.*[plant],
                },
            );
            driver_context.aboveground_litter_carbon_g_c_per_h_by_plant.*[plant] =
                litterfall.aboveground.carbon_g_c;
            driver_context.aboveground_litter_nitrogen_g_n_per_h_by_plant.*[plant] =
                litterfall.aboveground.nitrogen_g_n;
            driver_context.aboveground_litter_phosphorus_g_p_per_h_by_plant.*[plant] =
                litterfall.aboveground.phosphorus_g_p;
            try driver_context.plant_daily_flux_ledger.*.accumulateLitterStateUpdate(
                plant,
                litterfall.aboveground.carbon_g_c,
                litterfall.aboveground.nitrogen_g_n,
                litterfall.aboveground.phosphorus_g_p,
                litterfall.belowground.carbon_g_c,
                litterfall.belowground.nitrogen_g_n,
                litterfall.belowground.phosphorus_g_p,
            );
        }
        // GROSUB 12636--12653 publishes natural shoot,
        // standing-dead and management litter through one common
        // CSNC/ZSNC/PSNC owner. Root litter remains within its
        // resolved soil-layer scope; only above-ground litter is
        // the paired canopy-to-surface local transfer.
        try ecosys.layer_local_conservation.accumulatePlantLitterfall(
            &driver_context.hourly_layer_boundary_ledger.*,
            driver_context.config.*.plant_populations,
            driver_context.aboveground_litter_carbon_g_c_per_h_by_plant.*,
            driver_context.aboveground_litter_nitrogen_g_n_per_h_by_plant.*,
            driver_context.aboveground_litter_phosphorus_g_p_per_h_by_plant.*,
        );
        if (driver_context.plant_root_state.*) |*roots| {
            try ecosys.plant_root_soil_exchange_accumulation.accumulate(
                &driver_context.plant_root_soil_exchange_state.*,
                .{
                    .organic_carbon_exchange_g_c = driver_context.rse_organic_carbon_by_plant.*,
                    .organic_nitrogen_exchange_g_n = driver_context.rse_organic_nitrogen_by_plant.*,
                    .organic_phosphorus_exchange_g_p = driver_context.rse_organic_phosphorus_by_plant.*,
                    .ammonium_uptake_g_n = roots.ammonium_uptake_g_n_per_h,
                    .nitrate_uptake_g_n = roots.nitrate_uptake_g_n_per_h,
                    .phosphate_h2_uptake_g_p = driver_context.rse_phosphate_h2_by_plant.*,
                    .phosphate_h_uptake_g_p = driver_context.rse_phosphate_h_by_plant.*,
                    .symbiotic_fixation_g_n = roots.fixation_uptake_g_n_per_h,
                    .additional_fixation_g_n = driver_context.rse_canopy_fixation_g_n_per_h_by_plant.*,
                    .carbon_balance_g_c = driver_context.plant_daily_flux_ledger.*.net_carbon_change_g,
                    .cumulative_respiration_g_c = driver_context.plant_daily_flux_ledger.*.signed_total_respiration_carbon_g,
                },
            );
        }
        try ecosys.grid_cell_litter_standing_dead_state_update.refresh(
            &driver_context.cell_litter_standing_dead_state_update_state.*,
            .{
                .aboveground_litter_carbon_g_c_per_h_by_plant = driver_context.aboveground_litter_carbon_g_c_per_h_by_plant.*,
                .aboveground_litter_nitrogen_g_n_per_h_by_plant = driver_context.aboveground_litter_nitrogen_g_n_per_h_by_plant.*,
                .aboveground_litter_phosphorus_g_p_per_h_by_plant = driver_context.aboveground_litter_phosphorus_g_p_per_h_by_plant.*,
                .standing_dead_carbon_g_c_by_plant = canopy.plant_standing_dead_carbon_g,
            },
        );
        const phenology = if (driver_context.plant_phenology_state.*) |*value|
            value
        else
            return error.RootSoilElementStateUpdateRequiresPhenologyState;
        try ecosys.root_soil_element_exchange_state_update.refresh(
            &driver_context.root_soil_element_exchange_state_update_state.*,
            .{
                .active_by_plant = phenology.active,
                .exchange_g_element_per_h_by_element_and_plant = .{
                    driver_context.root_soil_carbon_exchange_g_c_per_h_by_plant.*,
                    driver_context.root_soil_nitrogen_exchange_g_n_per_h_by_plant.*,
                    driver_context.root_soil_phosphorus_exchange_g_p_per_h_by_plant.*,
                },
            },
        );
    } else {
        inline for (
            driver_context.root_soil_element_exchange_state_update_state.*
                .change_g_element_per_h_by_element_and_cell,
        ) |values| @memset(values, 0);
        @memset(
            driver_context.canopy_ammonia_state_update_state.*
                .current_exchange_g_n_per_h_by_plant,
            0,
        );
        @memcpy(
            driver_context.canopy_ammonia_state_update_state.*
                .cumulative_exchange_g_n_by_plant,
            driver_context.plant_daily_flux_ledger.*.ammonia_exchange_g_n,
        );
        inline for (@typeInfo(
            ecosys.grid_cell_litter_standing_dead_state_update.State,
        ).@"struct".fields) |field|
            if (field.type == []f64)
                @memset(
                    @field(
                        driver_context.cell_litter_standing_dead_state_update_state.*,
                        field.name,
                    ),
                    0,
                );
    }
}

noinline fn postScienceCanopyEnergyAndWater(driver_context: anytype) !void {
    @memset(driver_context.canopy_net_radiation_megajoules.*, 0);
    @memset(driver_context.canopy_storage_heat_megajoules.*, 0);
    if (driver_context.canopy_energy_state.*) |energy| if (driver_context.canopy_surface_exchange_state.*) |exchange| {
        for (0..driver_context.runtime_plant_count.*) |plant| {
            const cell = plant / driver_context.config.*.plant_populations;
            driver_context.canopy_net_radiation_megajoules.*[plant] = energy.net_radiation_megajoules_per_m2[plant] * driver_context.canopy_cell_area_m2.*[cell];
            // HFLXC is the converged canopy energy residual sum;
            // EXTRACT later subtracts its convective VFLXC term.
            driver_context.canopy_storage_heat_megajoules.*[plant] = driver_context.canopy_net_radiation_megajoules.*[plant] +
                exchange.latent_heat_flux_megajoules_per_h[plant] +
                exchange.sensible_heat_flux_megajoules_per_h[plant] +
                exchange.vapor_sensible_heat_flux_megajoules_per_h[plant];
        }
    };
    const living_exchange = if (driver_context.canopy_surface_exchange_state.*) |*exchange| exchange else null;
    const dead_exchange = if (driver_context.standing_dead_surface_exchange_state.*) |*exchange| exchange else null;
    try ecosys.plant_energy_state_update.refresh(
        &driver_context.plant_energy_state_update_state.*,
        .{
            .living_net_radiation_megajoules = driver_context.canopy_net_radiation_megajoules.*,
            .living_latent_heat_megajoules = if (living_exchange) |exchange| exchange.latent_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
            .living_sensible_heat_megajoules = if (living_exchange) |exchange| exchange.sensible_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
            .living_storage_heat_megajoules = driver_context.canopy_storage_heat_megajoules.*,
            .living_convective_water_heat_megajoules = if (living_exchange) |exchange| exchange.vapor_sensible_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
            .standing_dead_net_radiation_megajoules = if (dead_exchange) |exchange| exchange.net_radiation_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
            .standing_dead_latent_heat_megajoules = if (dead_exchange) |exchange| exchange.latent_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
            .standing_dead_sensible_heat_megajoules = if (dead_exchange) |exchange| exchange.sensible_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
            .standing_dead_storage_heat_megajoules = if (dead_exchange) |exchange| exchange.storage_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
            .standing_dead_convective_water_heat_megajoules = if (dead_exchange) |exchange| exchange.vapor_sensible_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
        },
    );
    if (driver_context.canopy_precipitation_retention_state.*) |*retention| {
        try ecosys.plant_water_state_update.refresh(
            &driver_context.plant_water_state_update_state.*,
            .{
                .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
                .internal_water_depth_m_per_m2_by_plant = driver_context.plant_state.*.canopy_water_storage_m_per_m2,
                .living_surface_water_m3_by_plant = retention.living_surface_water_m3,
                .standing_dead_surface_water_m3_by_plant = retention.standing_dead_surface_water_m3,
                .transpiration_m3_per_h_by_plant = if (living_exchange) |exchange|
                    exchange.transpiration_m3_per_h
                else
                    driver_context.zero_plant_energy_megajoules.*,
                .living_evaporation_m3_per_h_by_plant = if (living_exchange) |exchange|
                    exchange.intercepted_water_change_m3_per_h
                else
                    driver_context.zero_plant_energy_megajoules.*,
                .standing_dead_evaporation_m3_per_h_by_plant = if (dead_exchange) |exchange|
                    exchange.intercepted_water_change_m3_per_h
                else
                    driver_context.zero_plant_energy_megajoules.*,
            },
        );
    }
    try ecosys.ecosystem_energy_ledger.refresh(&driver_context.ecosystem_energy_ledger_state.*, .{
        .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
        .ground_net_radiation_megajoules_per_m2 = driver_context.surface_energy_state.*.net_radiation_megajoules_per_m2,
        .ground_latent_heat_megajoules_per_m2 = driver_context.surface_temperature_solver_state.*.latent_heat_flux_megajoules_per_m2,
        // Completes legacy TLES (`watsub.f:4185` -> `redist.f:10629`) in the
        // reported column only. The conservation ledgers below deliberately
        // keep consuming `latent_heat_flux_megajoules_per_m2` alone.
        .ground_latent_heat_outside_surface_residual_megajoules_per_m2 = driver_context.surface_temperature_solver_state.*.latent_heat_outside_surface_residual_megajoules_per_m2,
        .ground_sensible_heat_megajoules_per_m2 = driver_context.surface_temperature_solver_state.*.sensible_heat_flux_megajoules_per_m2,
        .ground_storage_heat_megajoules_per_m2 = driver_context.surface_temperature_solver_state.*.storage_heat_flux_megajoules_per_m2,
        .species_count = driver_context.config.*.plant_populations,
        .canopy_net_radiation_megajoules = driver_context.canopy_net_radiation_megajoules.*,
        .canopy_latent_heat_megajoules = if (living_exchange) |exchange| exchange.latent_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
        .canopy_sensible_heat_megajoules = if (living_exchange) |exchange| exchange.sensible_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
        .canopy_storage_heat_megajoules = driver_context.canopy_storage_heat_megajoules.*,
        .canopy_convective_water_heat_megajoules = if (living_exchange) |exchange| exchange.vapor_sensible_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
        .standing_dead_net_radiation_megajoules = if (dead_exchange) |exchange| exchange.net_radiation_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
        .standing_dead_latent_heat_megajoules = if (dead_exchange) |exchange| exchange.latent_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
        .standing_dead_sensible_heat_megajoules = if (dead_exchange) |exchange| exchange.sensible_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
        .standing_dead_storage_heat_megajoules = if (dead_exchange) |exchange| exchange.storage_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
        .standing_dead_convective_water_heat_megajoules = if (dead_exchange) |exchange| exchange.vapor_sensible_heat_flux_megajoules_per_h else driver_context.zero_plant_energy_megajoules.*,
    });
    if (driver_context.canopy_precipitation_retention_state.*) |*retention| {
        // `uptake.f` closes canopy energy/water, root water uptake,
        // root gas content, root gas withdrawal, and root nutrient
        // uptake within one hourly pass. Publishing them from five
        // separate call sites let a half-advanced hour be observed
        // by REDIST, NITRO, and the output writers, and the EXTRACT
        // `ENGYX` carry made a repeated publish non-idempotent. One
        // transaction snapshots every destination, runs the same
        // five already validated owners with the same inputs,
        // checks the cross-owner invariants no single owner can
        // see, and rolls every array back on any failure.
        //
        // Placement is the earliest of the five former sites. The
        // root gas withdrawal ledger now published ~540 lines early
        // is unchanged over that span: its writers are
        // `plant_root_system.resetHourlyFluxes` (line 9618),
        // `plant_root_disturbance.releaseRootGasFraction` (reached
        // through harvest and tillage dispatch, all earlier), and
        // `plant_root_disturbance.withdrawRootAxisLayer` (reached
        // through `applyRootMetabolism`, line 5565). The root phase
        // inventories the gas content owner reads are next mutated
        // by `applyRootFireCombustion`, which is later still.
        // `plant_root_system.refreshLayerMorphology` is in fact
        // bound in production, not unbound as this comment
        // previously claimed: it runs every simulated hour from
        // `plant_water_balance.refreshRootWorkspace`
        // (`stages/hourly_vegetation.zig`, gated only by
        // `plant_water_balance` being active, the normal
        // production configuration whenever plants are
        // simulated), and its empty-root-layer branch does write
        // the same root gas content and withdrawal-loss ledger
        // arrays this transaction snapshots (see
        // `docs/discrepancy_register.md`'s `ROOT-001` entry).
        // Whether that write falls inside or outside the window
        // this transaction's placement assumes has not been
        // re-derived here; treat this as an open follow-up, not
        // as confirmed-safe.
        //
        // Guard equivalence: a non-null retention state implies a
        // non-null root, phenology, and water workspace state,
        // because those are constructed together, and the former
        // root block already returned an error in the mixed case.
        const uptake_roots = if (driver_context.plant_root_state.*) |*value|
            value
        else
            return error.UptakeCoupledTransactionRequiresRootState;
        const uptake_phenology = if (driver_context.plant_phenology_state.*) |*value|
            value
        else
            return error.UptakeCoupledTransactionRequiresPhenologyState;
        const uptake_water_workspace = if (driver_context.plant_water_workspace.*) |*value|
            value
        else
            return error.UptakeCoupledTransactionRequiresPlantWaterWorkspace;
        // RSMN is intentionally not supplied through `.stomate`:
        // hourly_snow_energy already ran the source's initial and
        // final STOMATE passes inside the accepted canopy/root
        // solve, committed RSMN, and hourly_vegetation consumed it
        // in same-hour GROSUB. Recomputing it here, after GROSUB,
        // would disconnect the published value from both users.
        try ecosys.uptake_coupled_transaction.apply(
            &driver_context.uptake_coupled_transaction_workspace.*,
            .{
                .canopy_energy = &driver_context.canopy_water_energy_state_update_state.*,
                .root_water = &driver_context.root_water_uptake_state_update_state.*,
                .root_gas_content = &driver_context.root_gas_content_state_update_state.*,
                .root_gas_withdrawal = &driver_context.root_gas_withdrawal_state_update_state.*,
                .root_nutrient = &driver_context.root_nutrient_uptake_state_update_state.*,
            },
            .{
                .shape = .{
                    .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                    .active_by_plant = uptake_phenology.active,
                    .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                },
                .canopy_energy = .{
                    .air_temperature_k_by_cell = driver_context.atmospheric_state.*.air_temperature_k,
                    .canopy_temperature_k_by_plant = driver_context.plant_state.*.canopy_temperature_k,
                    .living_surface_water_m3_by_plant = retention.living_surface_water_m3,
                    .standing_dead_surface_water_m3_by_plant = retention.standing_dead_surface_water_m3,
                    .living_retention_m3_per_h_by_plant = retention.living_retention_m3_per_h,
                    .standing_dead_retention_m3_per_h_by_plant = retention.standing_dead_retention_m3_per_h,
                },
                .previous_canopy_water_energy_megajoules_by_plant = retention.previous_water_energy_megajoules,
                .root_water = .{
                    .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                    .active_by_plant = uptake_phenology.active,
                    .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                    .plant_population_count = uptake_water_workspace.plant_population_count,
                    .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
                    .soil_temperature_k_by_layer = driver_context.state.*.soil_temperature_k,
                    .root_length_density_m_per_m3 = uptake_roots.root_length_density_m_per_m3,
                    .water_uptake_m3_per_h = uptake_roots.water_uptake_m3_per_h,
                },
                .root_gas_content = .{
                    .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                    .active_by_plant = uptake_phenology.active,
                    .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                    .gaseous_g_by_gas = .{
                        uptake_roots.gaseous_carbon_dioxide_g_c,
                        uptake_roots.gaseous_oxygen_g_o,
                        uptake_roots.gaseous_methane_g_c,
                        uptake_roots.gaseous_nitrous_oxide_g_n,
                        uptake_roots.gaseous_ammonia_g_n,
                        uptake_roots.gaseous_hydrogen_g_h,
                    },
                    .aqueous_g_by_gas = .{
                        uptake_roots.aqueous_carbon_dioxide_g_c,
                        uptake_roots.aqueous_oxygen_g_o,
                        uptake_roots.aqueous_methane_g_c,
                        uptake_roots.aqueous_nitrous_oxide_g_n,
                        uptake_roots.aqueous_ammonia_g_n,
                        uptake_roots.aqueous_hydrogen_g_h,
                    },
                },
                .root_gas_withdrawal = .{
                    .loss_g_element_per_h_by_gas_and_plant = .{
                        uptake_roots.withdrawal_carbon_dioxide_loss_g_c_per_h,
                        uptake_roots.withdrawal_oxygen_loss_g_o_per_h,
                        uptake_roots.withdrawal_methane_loss_g_c_per_h,
                        uptake_roots.withdrawal_nitrous_oxide_loss_g_n_per_h,
                        uptake_roots.withdrawal_ammonia_loss_g_n_per_h,
                        uptake_roots.withdrawal_hydrogen_loss_g_h_per_h,
                    },
                    .loss_g_element_per_h_by_gas_and_root = .{
                        uptake_roots.withdrawal_carbon_dioxide_loss_g_c_per_h_by_root,
                        uptake_roots.withdrawal_oxygen_loss_g_o_per_h_by_root,
                        uptake_roots.withdrawal_methane_loss_g_c_per_h_by_root,
                        uptake_roots.withdrawal_nitrous_oxide_loss_g_n_per_h_by_root,
                        uptake_roots.withdrawal_ammonia_loss_g_n_per_h_by_root,
                        uptake_roots.withdrawal_hydrogen_loss_g_h_per_h_by_root,
                    },
                },
                .root_nutrient = .{
                    .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                    .active_by_plant = uptake_phenology.active,
                    .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                    .uptake_g_element_per_h_by_nutrient_and_root = .{
                        uptake_roots.ammonium_uptake_nonband_g_n_per_h,
                        uptake_roots.nitrate_uptake_nonband_g_n_per_h,
                        uptake_roots.phosphate_h2_uptake_nonband_g_p_per_h,
                        uptake_roots.phosphate_h_uptake_nonband_g_p_per_h,
                        uptake_roots.ammonium_uptake_band_g_n_per_h,
                        uptake_roots.nitrate_uptake_band_g_n_per_h,
                        uptake_roots.phosphate_h2_uptake_band_g_p_per_h,
                        uptake_roots.phosphate_h_uptake_band_g_p_per_h,
                    },
                },
            },
        );
        @memcpy(
            driver_context.ecosystem_energy_ledger_state.*.canopy_water_energy_megajoules,
            driver_context.canopy_water_energy_state_update_state.*
                .water_energy_megajoules_by_cell,
        );
        @memcpy(
            driver_context.ecosystem_energy_ledger_state.*.canopy_water_energy_change_megajoules_per_h,
            driver_context.canopy_water_energy_state_update_state.*
                .water_energy_change_megajoules_per_h_by_cell,
        );
        try ecosys.canopy_conservation_sidecar.refresh(
            &driver_context.canopy_conservation_sidecar_state.*,
            .{
                .air_temperature_k_by_cell = driver_context.atmospheric_state.*.air_temperature_k,
                .living_retention_m3_per_h_by_plant = retention.living_retention_m3_per_h,
                .standing_dead_retention_m3_per_h_by_plant = retention.standing_dead_retention_m3_per_h,
                .transpiration_m3_per_h_by_plant = if (living_exchange) |exchange|
                    exchange.transpiration_m3_per_h
                else
                    driver_context.zero_plant_energy_megajoules.*,
                .living_evaporation_m3_per_h_by_plant = if (living_exchange) |exchange|
                    exchange.intercepted_water_change_m3_per_h
                else
                    driver_context.zero_plant_energy_megajoules.*,
                .standing_dead_evaporation_m3_per_h_by_plant = if (dead_exchange) |exchange|
                    exchange.intercepted_water_change_m3_per_h
                else
                    driver_context.zero_plant_energy_megajoules.*,
                .thflxc_megajoules_per_h_by_plant = driver_context.canopy_water_energy_state_update_state.*
                    .water_energy_change_megajoules_per_h_by_plant,
                .thflxc_megajoules_per_h_by_cell = driver_context.canopy_water_energy_state_update_state.*
                    .water_energy_change_megajoules_per_h_by_cell,
            },
        );
        // Publish producer-proven canopy/atmosphere directions.
        // Drainage remains absent until the coupled lower router
        // resolves its snow/litter/topsoil recipient. THFLXC is
        // the exact signed canopy boundary term paired with HEATH
        // by REDIST and closes ENGYC after retained-rain enthalpy.
        try ecosys.layer_local_conservation
            .accumulateCanopyAtmosphericActivity(
            &driver_context.hourly_layer_boundary_ledger.*,
            &driver_context.canopy_conservation_sidecar_state.*,
            1,
        );
    } else {
        @memset(
            driver_context.canopy_water_energy_state_update_state.*
                .water_energy_megajoules_by_plant,
            0,
        );
        @memset(
            driver_context.canopy_water_energy_state_update_state.*
                .water_energy_change_megajoules_per_h_by_plant,
            0,
        );
        @memset(
            driver_context.canopy_water_energy_state_update_state.*
                .water_energy_megajoules_by_cell,
            0,
        );
        @memset(
            driver_context.canopy_water_energy_state_update_state.*
                .water_energy_change_megajoules_per_h_by_cell,
            0,
        );
        @memset(driver_context.ecosystem_energy_ledger_state.*.canopy_water_energy_megajoules, 0);
        @memset(driver_context.ecosystem_energy_ledger_state.*.canopy_water_energy_change_megajoules_per_h, 0);
        driver_context.canopy_conservation_sidecar_state.*.reset();
    }
}

noinline fn postScienceCanopyStructureAndHeat(driver_context: anytype, advance_context: anytype) !void {
    if (driver_context.canopy_layer_distribution_state.*) |*layers| {
        const canopy = if (driver_context.detailed_canopy_state.*) |*value|
            value
        else
            return error.LivingCanopyStateUpdateRequiresCanopyState;
        const phenology = if (driver_context.plant_phenology_state.*) |*value|
            value
        else
            return error.LivingCanopyStateUpdateRequiresPhenologyState;
        try ecosys.living_canopy_layer_state_update.refresh(
            &driver_context.living_canopy_layer_state_update_state.*,
            .{
                .active_by_plant = phenology.active,
                .plant_branch_offsets = canopy.plant_branch_offsets,
                .branch_node_offsets = canopy.branch_node_offsets,
                .node_leaf_area_m2_by_layer = layers.node_leaf_area_m2,
                .node_leaf_carbon_g_c_by_layer = layers.node_leaf_carbon_g,
                .branch_stalk_area_m2_by_layer = layers.branch_stalk_area_m2,
            },
        );
        try ecosys.standing_dead_area_state_update.refresh(
            &driver_context.standing_dead_area_state_update_state.*,
            layers.plant_standing_dead_area_m2,
        );
    } else {
        @memset(
            driver_context.living_canopy_layer_state_update_state.*
                .leaf_area_m2_by_cell_layer,
            0,
        );
        @memset(
            driver_context.living_canopy_layer_state_update_state.*
                .leaf_carbon_g_c_by_cell_layer,
            0,
        );
        @memset(
            driver_context.living_canopy_layer_state_update_state.*
                .stalk_area_m2_by_cell_layer,
            0,
        );
        @memset(
            driver_context.living_canopy_layer_state_update_state.*
                .leaf_area_m2_by_cell,
            0,
        );
        @memset(
            driver_context.living_canopy_layer_state_update_state.*
                .stalk_area_m2_by_cell,
            0,
        );
        @memset(
            driver_context.standing_dead_area_state_update_state.*
                .area_m2_by_cell_layer,
            0,
        );
        @memset(
            driver_context.standing_dead_area_state_update_state.*.area_m2_by_cell,
            0,
        );
    }
    const heat_before = driver_context.landscape_mass_balance_state.*.boundary_ledger.cumulative;
    const ice_heat_capacity_per_water_equivalent_m3_k = try ecosys.ice_units.heatCapacityPerWaterEquivalentM3K(
        driver_context.runscript.*.soil_phase_heat_parameters.ice_heat_capacity_megajoules_per_m3_k,
        driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.ice_density_megagrams_per_m3,
    );
    try driver_context.hourly_cell_boundary_ledger.*.accumulateSurfaceAndCanopyHeat(
        driver_context.surface_energy_state.*.net_radiation_megajoules_per_m2,
        driver_context.surface_temperature_solver_state.*.sensible_heat_flux_megajoules_per_m2,
        driver_context.surface_temperature_solver_state.*.latent_heat_flux_megajoules_per_m2,
        driver_context.surface_temperature_solver_state.*.vapor_sensible_heat_flux_megajoules_per_m2,
        driver_context.canopy_cell_area_m2.*,
        driver_context.ecosystem_energy_ledger_state.*.canopy_water_energy_change_megajoules_per_h,
    );
    try driver_context.hourly_cell_boundary_ledger.*.accumulateSurfaceEndpointReferenceHeat(
        driver_context.surface_temperature_solver_state.*.ice_water_equivalent_change_m3,
        driver_context.surface_temperature_solver_state.*.internal_vapor_water_change_m3,
        driver_context.runscript.*.soil_phase_heat_parameters.liquid_water_heat_capacity_megajoules_per_m3_k,
        ice_heat_capacity_per_water_equivalent_m3_k,
        driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.pure_water_freezing_temperature_k,
        driver_context.runscript.*.ground_air_parameters.liquid_water_latent_heat_megajoules_per_m3,
    );
    try ecosys.layer_local_conservation.accumulateSurfaceEndpointReferenceHeat(
        &driver_context.hourly_layer_boundary_ledger.*,
        driver_context.surface_temperature_solver_state.*.ice_water_equivalent_change_m3,
        driver_context.surface_temperature_solver_state.*.internal_vapor_water_change_m3,
        driver_context.runscript.*.soil_phase_heat_parameters.liquid_water_heat_capacity_megajoules_per_m3_k,
        ice_heat_capacity_per_water_equivalent_m3_k,
        driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.pure_water_freezing_temperature_k,
        driver_context.runscript.*.ground_air_parameters.liquid_water_latent_heat_megajoules_per_m3,
    );
    try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedSurfaceAndCanopyHeat(
        driver_context.surface_energy_state.*.net_radiation_megajoules_per_m2,
        driver_context.surface_temperature_solver_state.*.sensible_heat_flux_megajoules_per_m2,
        driver_context.surface_temperature_solver_state.*.latent_heat_flux_megajoules_per_m2,
        driver_context.surface_temperature_solver_state.*.vapor_sensible_heat_flux_megajoules_per_m2,
        driver_context.canopy_cell_area_m2.*,
        driver_context.ecosystem_energy_ledger_state.*.canopy_water_energy_change_megajoules_per_h,
    );
    try driver_context.landscape_mass_balance_state.*.boundary_ledger.accumulateAcceptedSurfaceEndpointReferenceHeat(
        driver_context.surface_temperature_solver_state.*.ice_water_equivalent_change_m3,
        driver_context.surface_temperature_solver_state.*.internal_vapor_water_change_m3,
        driver_context.runscript.*.soil_phase_heat_parameters.liquid_water_heat_capacity_megajoules_per_m3_k,
        ice_heat_capacity_per_water_equivalent_m3_k,
        driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.pure_water_freezing_temperature_k,
        driver_context.runscript.*.ground_air_parameters.liquid_water_latent_heat_megajoules_per_m3,
    );
    // The soil's external (lateral/drainage) advective heat is
    // booked inside `solveSoilHeatWaterAndSoluteTransport` from
    // the transaction's own `external_water_advective_enthalpy_outward_megajoules`
    // diagnostic. It must NOT be recomputed here: by this point
    // the phase and spatial heat solves have already moved
    // `state.soil_temperature_k`, so this location values water
    // that has already left at the wrong temperature.
    if (advance_context.scene_weather_hours.* < 24) {
        var radiation_megajoules: f64 = 0;
        var sensible_megajoules: f64 = 0;
        var latent_megajoules: f64 = 0;
        var vapor_sensible_megajoules: f64 = 0;
        var phase_megajoules: f64 = 0;
        var ground_storage_megajoules: f64 = 0;
        var ground_conduction_megajoules: f64 = 0;
        var canopy_water_change_megajoules: f64 = 0;
        var direct_litter_precipitation_heat_megajoules: f64 = 0;
        var external_soil_water_heat_outward_megajoules: f64 = 0;
        for (0..driver_context.state.*.cell_count) |cell| {
            const area_m2 = driver_context.canopy_cell_area_m2.*[cell];
            radiation_megajoules += driver_context.surface_energy_state.*.net_radiation_megajoules_per_m2[cell] * area_m2;
            sensible_megajoules += driver_context.surface_temperature_solver_state.*.sensible_heat_flux_megajoules_per_m2[cell] * area_m2;
            latent_megajoules += driver_context.surface_temperature_solver_state.*.latent_heat_flux_megajoules_per_m2[cell] * area_m2;
            vapor_sensible_megajoules += driver_context.surface_temperature_solver_state.*.vapor_sensible_heat_flux_megajoules_per_m2[cell] * area_m2;
            phase_megajoules += driver_context.surface_temperature_solver_state.*.phase_heat_flux_megajoules_per_m2[cell] * area_m2;
            ground_storage_megajoules += driver_context.surface_temperature_solver_state.*.storage_heat_flux_megajoules_per_m2[cell] * area_m2;
            ground_conduction_megajoules += driver_context.surface_temperature_solver_state.*.conductive_heat_flux_megajoules_per_m2[cell] * area_m2;
            canopy_water_change_megajoules += driver_context.ecosystem_energy_ledger_state.*.canopy_water_energy_change_megajoules_per_h[cell];
            const direct_litter_water_m3 = @max(0, driver_context.surface_precipitation_state.*.water_to_litter_m3_per_h[cell] - driver_context.transport_hydrology_state.*.snow_to_litter_water_flux_m3_per_step[cell]);
            direct_litter_precipitation_heat_megajoules += direct_litter_water_m3 * driver_context.runscript.*.soil_phase_heat_parameters.liquid_water_heat_capacity_megajoules_per_m3_k * driver_context.atmospheric_state.*.air_temperature_k[cell];
            const first_layer = cell * driver_context.state.*.soil_layer_capacity;
            for (0..driver_context.state.*.active_soil_layer_count[cell]) |local_layer| {
                const layer = first_layer + local_layer;
                external_soil_water_heat_outward_megajoules += (driver_context.transport_hydrology_state.*.micropore_external_water_flux_m3_per_step[layer] + driver_context.transport_hydrology_state.*.macropore_external_water_flux_m3_per_step[layer]) * driver_context.runscript.*.soil_phase_heat_parameters.liquid_water_heat_capacity_megajoules_per_m3_k * driver_context.state.*.soil_temperature_k[layer];
            }
        }
        std.log.debug("current surface/canopy heat boundary: input_megajoules={e} output_megajoules={e} radiation_megajoules={e} sensible_megajoules={e} latent_megajoules={e} vapor_sensible_megajoules={e} phase_megajoules={e} storage_term_megajoules={e} conduction_megajoules={e} canopy_water_change_megajoules={e} direct_litter_precipitation_heat_megajoules={e} external_soil_water_heat_outward_megajoules={e}", .{ driver_context.landscape_mass_balance_state.*.boundary_ledger.cumulative.heat_input_megajoules - heat_before.heat_input_megajoules, driver_context.landscape_mass_balance_state.*.boundary_ledger.cumulative.heat_output_megajoules - heat_before.heat_output_megajoules, radiation_megajoules, sensible_megajoules, latent_megajoules, vapor_sensible_megajoules, phase_megajoules, ground_storage_megajoules, ground_conduction_megajoules, canopy_water_change_megajoules, direct_litter_precipitation_heat_megajoules, external_soil_water_heat_outward_megajoules });
    }
}

noinline fn postScienceRootLedgers(driver_context: anytype) !void {
    if (driver_context.plant_root_state.*) |*roots| {
        const water_workspace = if (driver_context.plant_water_workspace.*) |*workspace| workspace else return error.RootUptakeLedgerRequiresPlantWaterWorkspace;
        try ecosys.root_uptake_ledger.refresh(
            &driver_context.root_uptake_ledger_state.*,
            &driver_context.state.*,
            roots,
            driver_context.config.*.plant_populations,
            driver_context.root_biological_domain_count_by_plant.*,
            water_workspace.plant_population_count,
            driver_context.canopy_cell_area_m2.*,
            driver_context.salinity_enabled_by_cell.*,
        );
        const phenology = if (driver_context.plant_phenology_state.*) |*value|
            value
        else
            return error.RootWaterStateUpdateRequiresPhenologyState;
        // When a canopy precipitation retention state exists, root
        // water uptake, root gas content, and root nutrient uptake
        // were already published above by
        // `uptake_coupled_transaction.apply`, atomically with
        // canopy energy and root gas withdrawal; publishing them
        // again here would be a double mutation. These three remain
        // the owners for the configuration that has roots but no
        // retention state, which is reachable when no cell carries
        // a branch, and where the transaction does not run.
        if (driver_context.canopy_precipitation_retention_state.* == null) {
            try ecosys.root_water_uptake_state_update.refresh(
                &driver_context.root_water_uptake_state_update_state.*,
                .{
                    .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                    .active_by_plant = phenology.active,
                    .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                    .plant_population_count = water_workspace.plant_population_count,
                    .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
                    .soil_temperature_k_by_layer = driver_context.state.*.soil_temperature_k,
                    .root_length_density_m_per_m3 = roots.root_length_density_m_per_m3,
                    .water_uptake_m3_per_h = roots.water_uptake_m3_per_h,
                },
            );
            try ecosys.root_gas_content_state_update.refresh(
                &driver_context.root_gas_content_state_update_state.*,
                .{
                    .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                    .active_by_plant = phenology.active,
                    .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                    .gaseous_g_by_gas = .{
                        roots.gaseous_carbon_dioxide_g_c,
                        roots.gaseous_oxygen_g_o,
                        roots.gaseous_methane_g_c,
                        roots.gaseous_nitrous_oxide_g_n,
                        roots.gaseous_ammonia_g_n,
                        roots.gaseous_hydrogen_g_h,
                    },
                    .aqueous_g_by_gas = .{
                        roots.aqueous_carbon_dioxide_g_c,
                        roots.aqueous_oxygen_g_o,
                        roots.aqueous_methane_g_c,
                        roots.aqueous_nitrous_oxide_g_n,
                        roots.aqueous_ammonia_g_n,
                        roots.aqueous_hydrogen_g_h,
                    },
                },
            );
            try ecosys.root_nutrient_uptake_state_update.refresh(
                &driver_context.root_nutrient_uptake_state_update_state.*,
                .{
                    .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                    .active_by_plant = phenology.active,
                    .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                    .uptake_g_element_per_h_by_nutrient_and_root = .{
                        roots.ammonium_uptake_nonband_g_n_per_h,
                        roots.nitrate_uptake_nonband_g_n_per_h,
                        roots.phosphate_h2_uptake_nonband_g_p_per_h,
                        roots.phosphate_h_uptake_nonband_g_p_per_h,
                        roots.ammonium_uptake_band_g_n_per_h,
                        roots.nitrate_uptake_band_g_n_per_h,
                        roots.phosphate_h2_uptake_band_g_p_per_h,
                        roots.phosphate_h_uptake_band_g_p_per_h,
                    },
                },
            );
        }
        @memcpy(
            driver_context.root_uptake_ledger_state.*
                .total_root_length_density_m_per_m3,
            driver_context.root_water_uptake_state_update_state.*
                .root_length_density_m_per_m3,
        );
        @memcpy(
            driver_context.root_uptake_ledger_state.*.total_water_uptake_m3_per_h,
            driver_context.root_water_uptake_state_update_state.*
                .water_uptake_m3_per_h,
        );
        @memcpy(
            driver_context.root_uptake_ledger_state.*.convective_water_heat_megajoules_per_h,
            driver_context.root_water_uptake_state_update_state.*
                .convective_water_heat_megajoules_per_h,
        );
        // REDIST TUPWTR/TUPHT was already applied and booked at
        // REDIST entry by the same-hour root-water transaction. This
        // post-stage owner is diagnostic only; carrying it into the
        // next heat solve would duplicate and time-shift energy.
        for (
            driver_context.root_uptake_ledger_state.*.total_root_gas_content_g,
            driver_context.root_gas_content_state_update_state.*
                .total_g_by_gas_and_layer,
        ) |destination, source_values| @memcpy(destination, source_values);
        try ecosys.root_atmosphere_gas_state_update.refresh(
            &driver_context.root_atmosphere_gas_state_update_state.*,
            .{
                .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                .active_by_plant = phenology.active,
                .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                .exchange_g_per_h_by_root_and_transport_gas = roots.atmosphere_to_root_gas_exchange_g_per_h,
            },
        );
        for (
            driver_context.root_uptake_ledger_state.*
                .total_atmosphere_to_root_gas_exchange_g_per_h,
            driver_context.root_atmosphere_gas_state_update_state.*
                .exchange_g_per_h_by_gas_and_layer,
        ) |destination, source_values| @memcpy(destination, source_values);
        try ecosys.root_internal_gas_state_update.refresh(
            &driver_context.root_internal_gas_state_update_state.*,
            .{
                .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                .active_by_plant = phenology.active,
                .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                .aqueous_carbon_dioxide_reaction_g_c_per_h_by_root = roots.aqueous_carbon_dioxide_reaction_g_c_per_h,
                .oxygen_uptake_from_root_pool_g_o_per_h_by_root = roots.oxygen_uptake_from_root_pool_g_o_per_h,
            },
        );
        @memcpy(
            driver_context.root_uptake_ledger_state.*
                .root_pool_oxygen_uptake_g_o_per_h,
            driver_context.root_internal_gas_state_update_state.*
                .oxygen_uptake_g_o_per_h_by_layer,
        );
        try ecosys.root_soil_gas_state_update.refresh(
            &driver_context.root_soil_gas_state_update_state.*,
            .{
                .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                .active_by_plant = phenology.active,
                .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                .soil_to_root_exchange_g_per_h_by_root_and_transport_gas = roots.soil_to_root_gas_exchange_g_per_h,
                .oxygen_uptake_from_soil_g_o_per_h_by_root = roots.oxygen_uptake_from_soil_g_o_per_h,
            },
        );
        for (
            driver_context.root_uptake_ledger_state.*
                .total_soil_to_root_gas_exchange_g_per_h[0..4],
            driver_context.root_soil_gas_state_update_state.*
                .exchange_g_per_h_by_gas_and_layer[0..4],
        ) |destination, source_values| @memcpy(destination, source_values);
        @memcpy(
            driver_context.root_uptake_ledger_state.*
                .total_soil_to_root_gas_exchange_g_per_h[5],
            driver_context.root_soil_gas_state_update_state.*
                .exchange_g_per_h_by_gas_and_layer[4],
        );
        @memcpy(
            driver_context.root_uptake_ledger_state.*.soil_oxygen_uptake_g_o_per_h,
            driver_context.root_soil_gas_state_update_state.*
                .exchange_g_per_h_by_gas_and_layer[1],
        );
        // EXEC-O2-BALANCE-008: UPTAKE has already consumed these
        // accepted masses from authoritative soil dissolved and
        // root aqueous O2 storage. Legacy REDIST adds both
        // `TUPOXS` and `TUPOXP` to `OXYGOU` (redist.f:6580--6582).
        // Publish once here, after both cell-layer aggregates are
        // finalized and before the hourly conservation gate. Both
        // ledgers are captured by the outer-hour transaction, so
        // any later failure rolls this booking back with science.
        try driver_context.landscape_mass_balance_state.*.boundary_ledger
            .accumulateAcceptedRootOxygenUptake(
            driver_context.root_uptake_ledger_state.*.soil_oxygen_uptake_g_o_per_h,
            driver_context.root_uptake_ledger_state.*.root_pool_oxygen_uptake_g_o_per_h,
        );
        try ecosys.hourly_cell_conservation.accumulateRootOxygenUptake(
            &driver_context.hourly_cell_boundary_ledger.*,
            driver_context.state.*.active_soil_layer_count,
            driver_context.state.*.soil_layer_capacity,
            driver_context.root_uptake_ledger_state.*.soil_oxygen_uptake_g_o_per_h,
            driver_context.root_uptake_ledger_state.*.root_pool_oxygen_uptake_g_o_per_h,
        );
        for (
            driver_context.root_uptake_ledger_state.*.total_nutrient_uptake_by_layer,
            driver_context.root_nutrient_uptake_state_update_state.*
                .uptake_g_element_per_h_by_nutrient_and_layer,
        ) |destination, source_values| @memcpy(
            destination,
            source_values,
        );
        try ecosys.root_salt_uptake_state_update.refresh(
            &driver_context.root_salt_uptake_state_update_state.*,
            .{
                .salinity_enabled_by_cell = driver_context.salinity_enabled_by_cell.*,
                .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                .active_by_plant = phenology.active,
                .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                .uptake_mol_per_h_by_root_and_salt = roots.salt_uptake_mol_per_h,
            },
        );
        @memcpy(
            driver_context.root_uptake_ledger_state.*.total_salt_uptake_mol_per_h,
            driver_context.root_salt_uptake_state_update_state.*
                .uptake_mol_per_h_by_layer_and_salt,
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger
            .accumulateAcceptedLegacyRootSaltUptake(
            driver_context.root_salt_uptake_state_update_state.*
                .uptake_mol_per_h_by_layer_and_salt,
        );
        try ecosys.root_soil_ammonia_exchange_state_update.refresh(
            &driver_context.root_soil_ammonia_exchange_state_update_state.*,
            .{
                .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                .active_by_plant = phenology.active,
                .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                .non_band_exchange_g_n_per_h_by_root = roots.ammonia_nonband_soil_exchange_g_n_per_h,
                .band_exchange_g_n_per_h_by_root = roots.ammonia_band_soil_exchange_g_n_per_h,
            },
        );
        for (
            driver_context.root_uptake_ledger_state.*
                .total_soil_to_root_gas_exchange_g_per_h[4],
            driver_context.root_soil_ammonia_exchange_state_update_state.*
                .non_band_exchange_g_n_per_h_by_layer,
            driver_context.root_soil_ammonia_exchange_state_update_state.*
                .band_exchange_g_n_per_h_by_layer,
        ) |*dest, nonband, band| dest.* = nonband + band;
        try ecosys.root_exudate_state_update.refresh(
            &driver_context.root_exudate_state_update_state.*,
            .{
                .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                .active_by_plant = phenology.active,
                .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                .exchange_g_element_per_h_by_element_root_and_fraction = .{
                    roots.exudate_carbon_exchange_g_c_per_h,
                    roots.exudate_nitrogen_exchange_g_n_per_h,
                    roots.exudate_phosphorus_exchange_g_p_per_h,
                },
            },
        );
        @memcpy(
            driver_context.root_uptake_ledger_state.*
                .total_exudate_carbon_change_g_c_per_h,
            driver_context.root_exudate_state_update_state.*
                .change_g_element_per_h_by_element_layer_and_fraction[0],
        );
        @memcpy(
            driver_context.root_uptake_ledger_state.*
                .total_exudate_nitrogen_change_g_n_per_h,
            driver_context.root_exudate_state_update_state.*
                .change_g_element_per_h_by_element_layer_and_fraction[1],
        );
        @memcpy(
            driver_context.root_uptake_ledger_state.*
                .total_exudate_phosphorus_change_g_p_per_h,
            driver_context.root_exudate_state_update_state.*
                .change_g_element_per_h_by_element_layer_and_fraction[2],
        );
        try ecosys.root_competition_demand_state_update.refresh(
            &driver_context.root_competition_demand_state_update_state.*,
            .{
                .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                .active_by_plant = phenology.active,
                .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                .demand_g_element_per_h_by_kind_and_root = .{
                    roots.oxygen_demand_g_o_per_h,
                    roots.ammonium_demand_nonband_g_n_per_h,
                    roots.nitrate_demand_nonband_g_n_per_h,
                    roots.phosphate_h2_demand_nonband_g_p_per_h,
                    roots.phosphate_h_demand_nonband_g_p_per_h,
                    roots.ammonium_demand_band_g_n_per_h,
                    roots.nitrate_demand_band_g_n_per_h,
                    roots.phosphate_h2_demand_band_g_p_per_h,
                    roots.phosphate_h_demand_band_g_p_per_h,
                },
            },
        );
        for (
            driver_context.root_uptake_ledger_state.*
                .total_competition_demand_by_layer,
            driver_context.root_competition_demand_state_update_state.*
                .demand_g_element_per_h_by_kind_and_layer,
        ) |destination, source_values| @memcpy(
            destination,
            source_values,
        );
        try ecosys.root_nitrogen_fixation_state_update.refresh(
            &driver_context.root_nitrogen_fixation_state_update_state.*,
            .{
                .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                .active_by_plant = phenology.active,
                .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                .fixation_g_n_per_h_by_root = roots.fixation_uptake_g_n_per_h_by_layer,
            },
        );
        @memcpy(
            driver_context.root_uptake_ledger_state.*
                .total_nitrogen_fixation_g_n_per_h,
            driver_context.root_nitrogen_fixation_state_update_state.*
                .fixation_g_n_per_h_by_layer,
        );
    } else {
        @memset(
            driver_context.root_water_uptake_state_update_state.*
                .root_length_density_m_per_m3,
            0,
        );
        @memset(
            driver_context.root_water_uptake_state_update_state.*
                .water_uptake_m3_per_h,
            0,
        );
        @memset(
            driver_context.root_water_uptake_state_update_state.*
                .convective_water_heat_megajoules_per_h,
            0,
        );
        for (
            driver_context.root_gas_content_state_update_state.*
                .total_g_by_gas_and_layer,
        ) |values| @memset(values, 0);
        for (
            driver_context.root_atmosphere_gas_state_update_state.*
                .exchange_g_per_h_by_gas_and_layer,
        ) |values| @memset(values, 0);
        @memset(
            driver_context.root_internal_gas_state_update_state.*
                .carbon_dioxide_source_g_c_per_h_by_layer,
            0,
        );
        for (
            driver_context.root_soil_gas_state_update_state.*
                .exchange_g_per_h_by_gas_and_layer,
        ) |values| @memset(values, 0);
        for (
            driver_context.root_nutrient_uptake_state_update_state.*
                .uptake_g_element_per_h_by_nutrient_and_layer,
        ) |values| @memset(values, 0);
        @memset(
            driver_context.root_salt_uptake_state_update_state.*
                .uptake_mol_per_h_by_layer_and_salt,
            0,
        );
        @memset(
            driver_context.root_soil_ammonia_exchange_state_update_state.*
                .non_band_exchange_g_n_per_h_by_layer,
            0,
        );
        @memset(
            driver_context.root_soil_ammonia_exchange_state_update_state.*
                .band_exchange_g_n_per_h_by_layer,
            0,
        );
        for (
            driver_context.root_exudate_state_update_state.*
                .change_g_element_per_h_by_element_layer_and_fraction,
        ) |values| @memset(values, 0);
        for (
            driver_context.root_competition_demand_state_update_state.*
                .demand_g_element_per_h_by_kind_and_layer,
        ) |values| @memset(values, 0);
        @memset(
            driver_context.root_nitrogen_fixation_state_update_state.*
                .fixation_g_n_per_h_by_layer,
            0,
        );
        @memset(
            driver_context.root_internal_gas_state_update_state.*
                .oxygen_uptake_g_o_per_h_by_layer,
            0,
        );
        @memset(driver_context.root_uptake_ledger_state.*.total_root_length_density_m_per_m3, 0);
        @memset(driver_context.root_uptake_ledger_state.*.total_water_uptake_m3_per_h, 0);
        @memset(driver_context.root_uptake_ledger_state.*.convective_water_heat_megajoules_per_h, 0);
        for (driver_context.root_uptake_ledger_state.*.total_root_gas_content_g) |values| @memset(values, 0);
        for (driver_context.root_uptake_ledger_state.*.total_soil_to_root_gas_exchange_g_per_h) |values| @memset(values, 0);
        for (driver_context.root_uptake_ledger_state.*.total_aqueous_to_gaseous_root_exchange_g_per_h) |values| @memset(values, 0);
        for (driver_context.root_uptake_ledger_state.*.total_atmosphere_to_root_gas_exchange_g_per_h) |values| @memset(values, 0);
        @memset(driver_context.root_uptake_ledger_state.*.total_salt_uptake_mol_per_h, 0);
        @memset(driver_context.root_uptake_ledger_state.*.total_exudate_carbon_change_g_c_per_h, 0);
        @memset(driver_context.root_uptake_ledger_state.*.total_exudate_nitrogen_change_g_n_per_h, 0);
        @memset(driver_context.root_uptake_ledger_state.*.total_exudate_phosphorus_change_g_p_per_h, 0);
        for (driver_context.root_uptake_ledger_state.*.total_competition_demand_by_layer) |values| @memset(values, 0);
        for (driver_context.root_uptake_ledger_state.*.total_nutrient_uptake_by_layer) |values| @memset(values, 0);
        @memset(driver_context.root_uptake_ledger_state.*.soil_oxygen_uptake_g_o_per_h, 0);
        @memset(driver_context.root_uptake_ledger_state.*.root_pool_oxygen_uptake_g_o_per_h, 0);
        @memset(driver_context.root_uptake_ledger_state.*.total_nitrogen_fixation_g_n_per_h, 0);
    }
}

noinline fn postScienceFireAndCloseout(driver_context: anytype, advance_context: anytype) !void {
    var soil_fire = driver_context.runscript.*.soil_fire_combustion_parameters;
    if (std.log.logEnabled(.debug, .default)) {
        const checkpoint = try reconstructLandscapeMassBalance(driver_context.hourly_science_context.*);
        std.log.debug("phosphorus before soil fire: hour={d} stored_g={e}", .{ advance_context.scene_weather_hours.* + 1, checkpoint.residue_phosphorus_g + checkpoint.organic_phosphorus_g + checkpoint.phosphate_phosphorus_g });
    }
    soil_fire.negligible_carbon_g_c = driver_context.config.*.physical_tolerance.carbon_g;
    soil_fire.physical_relative_tolerance = driver_context.config.*.physical_tolerance.relative;
    const fire_product_parameters: ecosys.plant_soil_exchange.SubsurfaceFireParameters = .{
        .oxygen_g_per_g_carbon = soil_fire.oxygen_g_per_g_combusted_carbon,
        .maximum_aerobic_charcoal_fraction = soil_fire.maximum_aerobic_charcoal_fraction,
        .maximum_anaerobic_charcoal_fraction = soil_fire.maximum_anaerobic_charcoal_fraction,
        .oxygen_half_saturation_g_o_per_m3 = soil_fire.oxygen_half_saturation_g_o_per_m3,
        .methane_half_saturation_g_c_per_m3 = soil_fire.methane_half_saturation_g_c_per_m3,
        .aerobic_combustion_energy_megajoules_per_g_carbon = soil_fire.aerobic_combustion_energy_megajoules_per_g_c,
        .anaerobic_combustion_energy_megajoules_per_g_carbon = soil_fire.anaerobic_combustion_energy_megajoules_per_g_c,
        .methane_combustion_energy_megajoules_per_g_carbon = soil_fire.methane_combustion_energy_megajoules_per_g_c,
    };
    for (0..driver_context.state.*.cell_count) |cell| {
        _ = ecosys.soil_combustion.burnSurfaceOrganicStateCell(
            &driver_context.surface_organic_state.*,
            &driver_context.surface_fire_exchange_state.*,
            cell,
            driver_context.fire_active_this_hour.*[cell],
            driver_context.state.*.surface_temperature_k[cell],
            driver_context.canopy_cell_area_m2.*[cell],
            1,
            soil_fire,
        ) catch |err| {
            std.log.err("surface organic matter combustion failed: scene={d} scene_hour={d} cell={d} error={s}", .{ advance_context.pass.*.scene_index + 1, advance_context.scene_weather_hours.* + 1, cell, @errorName(err) });
            return err;
        };
        driver_context.surface_fire_exchange_state.*.finalizeSurfaceCell(
            cell,
            &driver_context.litter_gas_transport_state.*,
            &driver_context.surface_litter_chemistry_state.*,
            &driver_context.surface_organic_state.*,
            driver_context.surface_precipitation_state.*.litter_water_m3,
            driver_context.salinity_enabled_by_cell.*[cell],
            driver_context.delayed_surface_combustion_heat_megajoules.*,
            .{
                .carbon_g_c = driver_context.config.*.physical_tolerance.carbon(driver_context.surface_fire_exchange_state.*.unlimited_combustion_carbon_g_c[cell]),
                .water_volume_m3 = driver_context.config.*.physical_tolerance.waterVolume(driver_context.surface_precipitation_state.*.litter_water_m3[cell]),
            },
            driver_context.runscript.*.fertilizer_nitrogen_molar_mass_g_per_mol,
            driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol,
            fire_product_parameters,
        ) catch |err| {
            std.log.err("surface combustion products failed: scene={d} scene_hour={d} cell={d} error={s}", .{ advance_context.pass.*.scene_index + 1, advance_context.scene_weather_hours.* + 1, cell, @errorName(err) });
            return err;
        };
    }
    try ecosys.hourly_cell_conservation.accumulateSurfaceMicrobialAndFireOxygenUptake(
        &driver_context.hourly_cell_boundary_ledger.*,
        ecosys.surface_microbial_oxygen_driver.unit_count_per_cell,
        driver_context.surface_microbial_oxygen_state.*.allocation.oxygen_uptake_g_o,
        driver_context.surface_fire_exchange_state.*.oxygen_consumption_g_o,
    );
    // REDIST-ROGOX-ORDER-001: complete the O2/H2 surface boundary
    // ledger (REDIST lines 4492--4507) now that this hour's
    // litter fire products (ROGOX(0)/RC4OX(0), from
    // `surface_fire_exchange_state.finalizeSurfaceCell` above)
    // exist, using the non-fire inputs cached earlier this hour.
    for (0..driver_context.state.*.cell_count) |cell| {
        var oxygen_hydrogen_inputs = driver_context.pending_surface_gas_ledger.*[cell].oxygen_hydrogen_inputs;
        oxygen_hydrogen_inputs.litter_o2_limited_uptake_g =
            driver_context.surface_fire_exchange_state.*.oxygen_limited_uptake_g_o[cell];
        oxygen_hydrogen_inputs.litter_ch4_combustion_g_c =
            driver_context.surface_fire_exchange_state.*.methane_combustion_g_c[cell];
        const oxygen_flux = try ecosys.redist_surface_gas_flux_accounting.computeOxygenHydrogen(
            oxygen_hydrogen_inputs,
        );
        const co2_surface_input_g = driver_context.pending_surface_gas_ledger.*[cell].co2_surface_input_g;
        const ch4_surface_input_g = driver_context.pending_surface_gas_ledger.*[cell].ch4_surface_input_g;
        const total_subsurface_carbon_flux_g = driver_context.pending_surface_gas_ledger.*[cell].total_subsurface_carbon_flux_g;
        driver_context.hourly_accumulators.*[cell].canopy_co2_exchange_g_c_timestep += co2_surface_input_g;
        driver_context.hourly_accumulators.*[cell].canopy_ch4_exchange_g_c_timestep += ch4_surface_input_g;
        driver_context.hourly_accumulators.*[cell].canopy_o2_exchange_g_o_timestep += oxygen_flux.o2_surface_input_g;
        driver_context.hourly_accumulators.*[cell].redist_carbon_surface_input_g_c_timestep +=
            co2_surface_input_g + ch4_surface_input_g;
        driver_context.hourly_accumulators.*[cell].redist_carbon_subsurface_output_g_c_timestep +=
            total_subsurface_carbon_flux_g;
        driver_context.hourly_accumulators.*[cell].redist_oxygen_surface_input_g_o_timestep +=
            oxygen_flux.o2_surface_input_g;
        driver_context.hourly_accumulators.*[cell].redist_oxygen_subsurface_output_g_o_timestep +=
            oxygen_flux.o2_subsurface_out_g;
        driver_context.hourly_accumulators.*[cell].redist_hydrogen_surface_input_g_h_timestep +=
            oxygen_flux.h2_surface_input_g;
        driver_context.hourly_accumulators.*[cell].redist_hydrogen_subsurface_output_g_h_timestep +=
            oxygen_flux.h2_subsurface_out_g;
        try driver_context.daily_soil_gas_flux.*.accumulateRedistSurfaceGasHour(
            cell,
            co2_surface_input_g + ch4_surface_input_g,
            total_subsurface_carbon_flux_g,
            oxygen_flux.o2_surface_input_g,
            oxygen_flux.o2_subsurface_out_g,
            oxygen_flux.h2_surface_input_g,
            oxygen_flux.h2_subsurface_out_g,
        );
    }
    // Surface-organic fire is a REDIST product and therefore remains after
    // SOLUTE. Canopy/standing-dead EXTRACT products were already published by
    // the hourly vegetation stage before SOLUTE; do not run a second litter
    // convergence here.
    if (std.log.logEnabled(.debug, .default)) {
        const checkpoint = try reconstructLandscapeMassBalance(driver_context.hourly_science_context.*);
        std.log.debug("phosphorus after soil fire chemistry: hour={d} stored_g={e}", .{ advance_context.scene_weather_hours.* + 1, checkpoint.residue_phosphorus_g + checkpoint.organic_phosphorus_g + checkpoint.phosphate_phosphorus_g });
    }
    for (0..driver_context.state.*.cell_count) |cell| {
        if (!driver_context.fire_active_this_hour.*[cell]) continue;
        for (0..driver_context.state.*.active_soil_layer_count[cell]) |local_layer| {
            const layer = try driver_context.state.*.layerIndex(cell, local_layer);
            _ = ecosys.soil_combustion.burnOrganicStateLayer(
                &driver_context.soil_organic_state.*,
                &driver_context.organic_matter_fire_exchange_state.*,
                layer,
                true,
                driver_context.state.*.soil_temperature_k[layer],
                driver_context.canopy_cell_area_m2.*[cell],
                1,
                soil_fire,
            ) catch |err| {
                std.log.err("soil organic matter combustion failed: scene={d} scene_hour={d} cell={d} layer={d} error={s}", .{ advance_context.pass.*.scene_index + 1, advance_context.scene_weather_hours.* + 1, cell, local_layer, @errorName(err) });
                return err;
            };
        }
    }
    if (driver_context.plant_root_state.*) |*roots| {
        ecosys.disturbance_management_dispatch.applyRootFireCombustion(
            roots,
            if (driver_context.detailed_canopy_state.*) |*canopy| canopy else null,
            &driver_context.state.*,
            driver_context.config.*.plant_populations,
            driver_context.root_biological_domain_count_by_plant.*,
            driver_context.canopy_cell_area_m2.*,
            driver_context.fire_active_this_hour.*,
            1,
            driver_context.salinity_enabled_by_cell.*,
            driver_context.runscript.*.plant_fire_combustion_parameters,
            &driver_context.organic_matter_fire_exchange_state.*,
        ) catch |err| {
            std.log.err("root nodule combustion failed: scene={d} scene_hour={d} error={s}", .{ advance_context.pass.*.scene_index + 1, advance_context.scene_weather_hours.* + 1, @errorName(err) });
            return err;
        };
        try ecosys.root_combustion_salt_state_update.refresh(
            &driver_context.root_combustion_salt_state_update_state.*,
            .{
                .salinity_enabled_by_cell = driver_context.salinity_enabled_by_cell.*,
                .fire_active_by_cell = driver_context.fire_active_this_hour.*,
                .active_soil_layer_count_by_cell = driver_context.state.*.active_soil_layer_count,
                .root_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
                .released_mol_per_h_by_root_and_salt = roots.combustion_salt_loss_mol_per_h,
            },
        );
        try driver_context.landscape_mass_balance_state.*.boundary_ledger
            .accumulateAcceptedLegacyPlantSaltInput(
            driver_context.root_combustion_salt_state_update_state.*
                .total_released_mol_per_h_by_cell,
        );
    } else {
        @memset(
            driver_context.root_combustion_salt_state_update_state.*
                .released_mol_per_h_by_layer_and_salt,
            0,
        );
        @memset(
            driver_context.root_combustion_salt_state_update_state.*
                .total_released_mol_per_h_by_cell,
            0,
        );
    }
    // Soil organic fire products exist independently of whether
    // the run has plant roots; roots merely add to this ledger.
    for (0..driver_context.state.*.cell_count) |cell| {
        if (!driver_context.fire_active_this_hour.*[cell]) continue;
        for (0..driver_context.state.*.active_soil_layer_count[cell]) |local_layer| {
            const layer = try driver_context.state.*.layerIndex(cell, local_layer);
            driver_context.organic_matter_fire_exchange_state.*.finalizeLayer(
                layer,
                &driver_context.gas_transport_state.*,
                &driver_context.plant_available_nutrient_state.*,
                &driver_context.soil_organic_state.*,
                &driver_context.micropore_solute_state.*,
                driver_context.salinity_enabled_by_cell.*[cell],
                driver_context.delayed_subsurface_combustion_heat_megajoules.*,
                .{
                    .carbon_g_c = driver_context.config.*.physical_tolerance.carbon(driver_context.organic_matter_fire_exchange_state.*.unlimited_combustion_carbon_g_c[layer]),
                    .water_volume_m3 = driver_context.config.*.physical_tolerance.water_volume_m3,
                },
                fire_product_parameters,
            ) catch |err| {
                std.log.err("subsurface combustion products failed: scene={d} scene_hour={d} cell={d} layer={d} error={s}", .{ advance_context.pass.*.scene_index + 1, advance_context.scene_weather_hours.* + 1, cell, local_layer, @errorName(err) });
                return err;
            };
        }
        var emitted_carbon_dioxide_g_c =
            driver_context.surface_fire_exchange_state.*.carbon_dioxide_emission_g_c[cell];
        var emitted_methane_g_c =
            driver_context.surface_fire_exchange_state.*.methane_emission_g_c[cell];
        var produced_charcoal_g_c =
            driver_context.surface_fire_exchange_state.*.charcoal_production_g_c[cell];
        var emitted_phosphorus_g_p = driver_context.surface_fire_exchange_state.*.gaseous_phosphorus_emission_g_p[cell];
        var combusted_phosphorus_g_p = driver_context.surface_fire_exchange_state.*.combusted_phosphorus_g_p[cell];
        var emitted_nitrogen_g_n = driver_context.surface_fire_exchange_state.*.gaseous_nitrogen_emission_g_n[cell];
        var combusted_nitrogen_g_n = driver_context.surface_fire_exchange_state.*.combusted_nitrogen_g_n[cell];
        for (0..driver_context.state.*.active_soil_layer_count[cell]) |local_layer| {
            const layer = try driver_context.state.*.layerIndex(cell, local_layer);
            emitted_carbon_dioxide_g_c +=
                driver_context.organic_matter_fire_exchange_state.*.carbon_dioxide_emission_g_c[layer];
            emitted_methane_g_c +=
                driver_context.organic_matter_fire_exchange_state.*.methane_emission_g_c[layer];
            produced_charcoal_g_c +=
                driver_context.organic_matter_fire_exchange_state.*.charcoal_production_g_c[layer];
            emitted_phosphorus_g_p += driver_context.organic_matter_fire_exchange_state.*.gaseous_phosphorus_emission_g_p[layer];
            combusted_phosphorus_g_p += driver_context.organic_matter_fire_exchange_state.*.combusted_phosphorus_g_p[layer];
            emitted_nitrogen_g_n += driver_context.organic_matter_fire_exchange_state.*.gaseous_nitrogen_emission_g_n[layer];
            combusted_nitrogen_g_n += driver_context.organic_matter_fire_exchange_state.*.combusted_nitrogen_g_n[layer];
        }
        var root_ratio: f64 = 0;
        var root_combustion_carbon_abs: f64 = 0;
        if (driver_context.plant_root_state.*) |*roots| {
            const first_plant = cell * driver_context.config.*.plant_populations;
            const last_plant = try std.math.add(
                usize,
                first_plant,
                driver_context.config.*.plant_populations,
            );
            for (first_plant..last_plant) |plant| {
                const carbon_loss = roots.combustion_carbon_loss_g_c_per_h[plant];
                if (carbon_loss > 0) return error.InvalidSoilFireCarbonEmission;
                root_combustion_carbon_abs += -carbon_loss;
            }
            const total_carbon_g_c = emitted_carbon_dioxide_g_c +
                emitted_methane_g_c +
                produced_charcoal_g_c;
            if (total_carbon_g_c > 0 and root_combustion_carbon_abs > 0 and std.math.isFinite(total_carbon_g_c)) {
                root_ratio = @min(
                    1.0,
                    root_combustion_carbon_abs / total_carbon_g_c,
                );
            }
        }
        if (!std.math.isFinite(emitted_carbon_dioxide_g_c) or emitted_carbon_dioxide_g_c < 0 or
            !std.math.isFinite(emitted_methane_g_c) or emitted_methane_g_c < 0)
            return error.InvalidSoilFireCarbonEmission;
        if (!std.math.isFinite(produced_charcoal_g_c) or produced_charcoal_g_c < 0) return error.InvalidSoilFireCharcoalProduction;
        if (!std.math.isFinite(emitted_phosphorus_g_p) or emitted_phosphorus_g_p < 0) return error.InvalidSoilFirePhosphorusEmission;
        if (!std.math.isFinite(combusted_phosphorus_g_p) or combusted_phosphorus_g_p < 0) return error.InvalidSoilFirePhosphorusCombustion;
        if (!std.math.isFinite(emitted_nitrogen_g_n) or emitted_nitrogen_g_n < 0) return error.InvalidSoilFireNitrogenEmission;
        if (!std.math.isFinite(combusted_nitrogen_g_n) or combusted_nitrogen_g_n < 0) return error.InvalidSoilFireNitrogenCombustion;
        const subsurface_fire_oxygen_consumption_g_o =
            try ecosys.hourly_cell_conservation.soilFireOxygenConsumptionForCell(
                driver_context.organic_matter_fire_exchange_state.*.oxygen_consumption_g_o,
                cell,
                driver_context.state.*.active_soil_layer_count[cell],
                driver_context.state.*.soil_layer_capacity,
            );
        // Fire O2 is consumed by an ecosystem reaction rather
        // than crossing the modeled boundary. Keep that provenance
        // separate from the genuinely gaseous N/P outputs.
        const soil_fire_gaseous_activity = try ecosys.hourly_cell_conservation.addActivities(
            try ecosys.hourly_cell_conservation.signedElementActivity(.{
                .nitrogen_g = -emitted_nitrogen_g_n,
                .phosphorus_g = -emitted_phosphorus_g_p,
            }),
            .{ .oxygen_internal_consumption_g = subsurface_fire_oxygen_consumption_g_o },
        );
        try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, soil_fire_gaseous_activity);
        try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, soil_fire_gaseous_activity);
        // REDIST fire ledgers retain their source signs:
        // VCO2G/VCH4G are negative emissions, while VCOXFS is
        // positive charcoal transferred back to soil organic C.
        const root_carbon_dioxide_emission_g_c =
            emitted_carbon_dioxide_g_c * root_ratio;
        const root_methane_emission_g_c =
            emitted_methane_g_c * root_ratio;
        const root_charcoal_production_g_c =
            produced_charcoal_g_c * root_ratio;
        const root_nitrogen_emission_g_n =
            emitted_nitrogen_g_n * root_ratio;
        const root_phosphorus_emission_g_p =
            emitted_phosphorus_g_p * root_ratio;
        const root_combusted_nitrogen_g_n =
            combusted_nitrogen_g_n * root_ratio;
        const root_combusted_phosphorus_g_p =
            combusted_phosphorus_g_p * root_ratio;
        driver_context.daily_soil_fire_carbon_dioxide_emission_g_c.*[cell] -= emitted_carbon_dioxide_g_c - root_carbon_dioxide_emission_g_c;
        driver_context.daily_soil_fire_methane_emission_g_c.*[cell] -= emitted_methane_g_c - root_methane_emission_g_c;
        driver_context.daily_soil_fire_charcoal_production_g_c.*[cell] += produced_charcoal_g_c - root_charcoal_production_g_c;
        driver_context.daily_soil_fire_phosphorus_flux_g_p.*[cell] -= emitted_phosphorus_g_p - root_phosphorus_emission_g_p;
        driver_context.daily_soil_combusted_phosphorus_g_p.*[cell] -= combusted_phosphorus_g_p - root_combusted_phosphorus_g_p;
        driver_context.daily_soil_fire_nitrogen_flux_g_n.*[cell] -= emitted_nitrogen_g_n - root_nitrogen_emission_g_n;
        driver_context.daily_soil_combusted_nitrogen_g_n.*[cell] -= combusted_nitrogen_g_n - root_combusted_nitrogen_g_n;
        driver_context.daily_root_fire_carbon_dioxide_emission_g_c.*[cell] -= root_carbon_dioxide_emission_g_c;
        driver_context.daily_root_fire_methane_emission_g_c.*[cell] -= root_methane_emission_g_c;
        driver_context.daily_root_fire_nitrogen_flux_g_n.*[cell] -= root_nitrogen_emission_g_n;
        driver_context.daily_root_fire_phosphorus_flux_g_p.*[cell] -= root_phosphorus_emission_g_p;
        driver_context.daily_root_fire_nitrogen_loss_g_n.*[cell] -= root_combusted_nitrogen_g_n;
        driver_context.daily_root_fire_phosphorus_loss_g_p.*[cell] -= root_combusted_phosphorus_g_p;
    }
    try ecosys.layer_local_conservation.accumulateSoilSurfaceFireActivity(
        &driver_context.hourly_layer_boundary_ledger.*,
        driver_context.state.*.active_soil_layer_count,
        &driver_context.surface_fire_exchange_state.*,
        &driver_context.organic_matter_fire_exchange_state.*,
    );
    // EXEC-O2-BALANCE-009: finalizeLayer/finalizeSurfaceCell have
    // already debited these reaction sinks from inventoried soil
    // and litter O2. Legacy REDIST publishes the surface RUPOXO(0)
    // + ROGOX(0) + RC4OX(0)*2.667 and active-layer ROGOX(L) +
    // RC4OX(L)*2.667 terms to OXYGOU. Book the exact accepted
    // producer arrays once, excluding inactive layer capacity;
    // the outer-hour transaction owns this ledger publication.
    try driver_context.landscape_mass_balance_state.*.boundary_ledger
        .accumulateAcceptedSurfaceMicrobialAndFireOxygenUptake(
        driver_context.state.*.active_soil_layer_count,
        driver_context.state.*.soil_layer_capacity,
        ecosys.surface_microbial_oxygen_driver.unit_count_per_cell,
        driver_context.surface_microbial_oxygen_state.*.allocation.oxygen_uptake_g_o,
        driver_context.surface_fire_exchange_state.*.oxygen_consumption_g_o,
        driver_context.organic_matter_fire_exchange_state.*.oxygen_consumption_g_o,
    );
    if (driver_context.plant_root_state.* != null) {
        // Combustion was produced once, before SOLUTE. These are REDIST and
        // accounting consumers of the accepted canopy fire arrays only.
        if (driver_context.detailed_canopy_state.*) |*canopy| {
            try ecosys.plant_combustion_state_update.refresh(
                &driver_context.plant_combustion_state_update_state.*,
                .{
                    .plant_species_per_cell = driver_context.config.*.plant_populations,
                    .fire_active_by_cell = driver_context.fire_active_this_hour.*,
                    .signed_carbon_loss_g_c_per_h_by_plant = canopy.plant_combustion_carbon_loss_g_c_per_h,
                    .charcoal_return_g_c_per_h_by_plant = canopy.plant_fire_charcoal_production_g_c_per_h,
                    .signed_nitrogen_loss_g_n_per_h_by_plant = canopy.plant_combustion_nitrogen_loss_g_n_per_h,
                    .signed_phosphorus_loss_g_p_per_h_by_plant = canopy.plant_combustion_phosphorus_loss_g_p_per_h,
                },
            );
            for (0..driver_context.runtime_plant_count.*) |plant| {
                const cell = plant / driver_context.config.*.plant_populations;
                if (!driver_context.fire_active_this_hour.*[cell]) continue;
                try driver_context.plant_daily_flux_ledger.*.accumulateOxidation(
                    plant,
                    driver_context.plant_combustion_state_update_state.*.signed_carbon_balance_g_c_per_h_by_plant[plant],
                    driver_context.plant_combustion_state_update_state.*.signed_nitrogen_loss_g_n_per_h_by_plant[plant],
                    driver_context.plant_combustion_state_update_state.*.signed_phosphorus_loss_g_p_per_h_by_plant[plant],
                );
            }
        }
    }
    try ecosys.layer_local_conservation.accumulateCanopySurfaceFireReturns(
        &driver_context.hourly_layer_boundary_ledger.*,
        &driver_context.surface_fire_exchange_state.*,
        driver_context.runscript.*.fertilizer_nitrogen_molar_mass_g_per_mol,
        driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol,
    );
    if (driver_context.detailed_canopy_state.*) |*canopy| {
        try ecosys.canopy_fire_state_update.refresh(
            &driver_context.canopy_fire_state_update_state.*,
            .{
                .fire_active_by_cell = driver_context.fire_active_this_hour.*,
                .carbon_dioxide_emission_g_c_per_h_by_plant = canopy.plant_fire_carbon_dioxide_emission_g_c_per_h,
                .methane_emission_g_c_per_h_by_plant = canopy.plant_fire_methane_emission_g_c_per_h,
                .oxygen_consumption_g_o_per_h_by_plant = canopy.plant_fire_oxygen_consumption_g_o_per_h,
                .charcoal_production_g_c_per_h_by_plant = canopy.plant_fire_charcoal_production_g_c_per_h,
                .heat_release_megajoules_per_h_by_plant = canopy.plant_fire_heat_release_megajoules_per_h,
            },
        );
    } else {
        inline for (@typeInfo(
            ecosys.canopy_fire_state_update.State,
        ).@"struct".fields) |field|
            if (field.type == []f64)
                @memset(
                    @field(driver_context.canopy_fire_state_update_state.*, field.name),
                    0,
                );
    }
    // The coupled UPTAKE transaction above already published this
    // owner, atomically with the other four, whenever a canopy
    // precipitation retention state exists. This remains the owner
    // for the configuration that has roots but no retention state,
    // where the transaction does not run at all; publishing here in
    // the retention case as well would advance the ledger twice.
    if (driver_context.plant_root_state.*) |*roots| {
        if (driver_context.canopy_precipitation_retention_state.* == null)
            try ecosys.root_gas_withdrawal_state_update.refresh(
                &driver_context.root_gas_withdrawal_state_update_state.*,
                .{
                    .loss_g_element_per_h_by_gas_and_plant = .{
                        roots.withdrawal_carbon_dioxide_loss_g_c_per_h,
                        roots.withdrawal_oxygen_loss_g_o_per_h,
                        roots.withdrawal_methane_loss_g_c_per_h,
                        roots.withdrawal_nitrous_oxide_loss_g_n_per_h,
                        roots.withdrawal_ammonia_loss_g_n_per_h,
                        roots.withdrawal_hydrogen_loss_g_h_per_h,
                    },
                    .loss_g_element_per_h_by_gas_and_root = .{
                        roots.withdrawal_carbon_dioxide_loss_g_c_per_h_by_root,
                        roots.withdrawal_oxygen_loss_g_o_per_h_by_root,
                        roots.withdrawal_methane_loss_g_c_per_h_by_root,
                        roots.withdrawal_nitrous_oxide_loss_g_n_per_h_by_root,
                        roots.withdrawal_ammonia_loss_g_n_per_h_by_root,
                        roots.withdrawal_hydrogen_loss_g_h_per_h_by_root,
                    },
                },
            );
    } else {
        inline for (
            driver_context.root_gas_withdrawal_state_update_state.*
                .loss_g_element_per_h_by_gas_and_cell,
        ) |values| @memset(values, 0);
        inline for (
            driver_context.root_gas_withdrawal_state_update_state.*
                .loss_g_element_per_h_by_gas_and_layer,
        ) |values| @memset(values, 0);
    }
    // EXTRACT 784--798 and REDIST 6530--6582 retain root gas
    // atmosphere exchange, disturbance release, and O2
    // consumption by their emitting/consuming soil layer. Soil-
    // root and root phase exchange are internal to that exact
    // local scope and therefore do not cross this ledger.
    try ecosys.layer_local_conservation.accumulateRootGasActivity(
        &driver_context.hourly_layer_boundary_ledger.*,
        .{
            .active_soil_layer_count = driver_context.state.*.active_soil_layer_count,
            .atmosphere_exchange_g_per_h_by_gas_and_layer = driver_context.root_atmosphere_gas_state_update_state.*.exchange_g_per_h_by_gas_and_layer,
            .withdrawal_loss_g_per_h_by_gas_and_layer = driver_context.root_gas_withdrawal_state_update_state.*.loss_g_element_per_h_by_gas_and_layer,
            .soil_oxygen_uptake_g_o_per_h = driver_context.root_soil_gas_state_update_state.*.exchange_g_per_h_by_gas_and_layer[1],
            .root_pool_oxygen_uptake_g_o_per_h = driver_context.root_internal_gas_state_update_state.*.oxygen_uptake_g_o_per_h_by_layer,
        },
    );
    if (driver_context.detailed_canopy_state.*) |*canopy| {
        const exchange = if (driver_context.canopy_carbon_exchange_state.*) |*value|
            value
        else
            return error.CanopyCarbonStateUpdateRequiresExchangeState;
        const phenology = if (driver_context.plant_phenology_state.*) |*value|
            value
        else
            return error.CanopyCarbonStateUpdateRequiresPhenologyState;
        for (0..driver_context.runtime_plant_count.*) |plant|
            driver_context.canopy_net_fixation_g_c_per_h_by_plant.*[plant] =
                (try exchange.fluxForPlant(canopy, plant))
                    .net_co2_g_c_per_h;
        try ecosys.canopy_carbon_state_update.refresh(
            &driver_context.canopy_carbon_state_update_state.*,
            .{
                .active_by_plant = phenology.active,
                .net_fixation_g_c_per_h_by_plant = driver_context.canopy_net_fixation_g_c_per_h_by_plant.*,
                .oxygen_g_o_per_g_c = driver_context.runscript.*.root_gas_parameters
                    .oxygen_to_carbon_respiration_ratio_g_o_per_g_c,
            },
        );
    } else {
        @memset(
            driver_context.canopy_carbon_state_update_state.*
                .hourly_net_fixation_g_c_per_h_by_cell,
            0,
        );
        @memset(
            driver_context.canopy_carbon_state_update_state.*
                .canopy_carbon_exchange_g_c_per_h_by_cell,
            0,
        );
        @memset(
            driver_context.canopy_carbon_state_update_state.*
                .canopy_oxygen_exchange_g_o_per_h_by_cell,
            0,
        );
    }
    const canopy_for_hourly_cell_boundary: ?*const ecosys.canopy_photosynthesis.State =
        if (driver_context.detailed_canopy_state.*) |*canopy| canopy else null;
    var plant_internal_oxygen_production_g_o: f64 = 0;
    var plant_internal_oxygen_consumption_g_o: f64 = 0;
    var plant_fire_nitrogen_output_g_n: f64 = 0;
    var plant_fire_phosphorus_output_g_p: f64 = 0;
    for (0..driver_context.state.*.cell_count) |cell| {
        const accepted_plant = try ecosys.hourly_cell_conservation.plantAtmosphereCellActivityForCell(
            canopy_for_hourly_cell_boundary,
            if (driver_context.plant_root_state.*) |*value| value else null,
            &driver_context.canopy_carbon_state_update_state.*,
            &driver_context.canopy_fire_state_update_state.*,
            &driver_context.plant_combustion_state_update_state.*,
            cell,
            driver_context.runscript.*.root_gas_parameters.oxygen_to_carbon_respiration_ratio_g_o_per_g_c,
        );
        const activity = accepted_plant.boundary;
        try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, activity);
        driver_context.plant_atmosphere_local_activity.*[cell] =
            (try ecosys.hourly_cell_conservation.plantAtmosphereCellActivityForCell(
                canopy_for_hourly_cell_boundary,
                null,
                &driver_context.canopy_carbon_state_update_state.*,
                &driver_context.canopy_fire_state_update_state.*,
                &driver_context.plant_combustion_state_update_state.*,
                cell,
                driver_context.runscript.*.root_gas_parameters.oxygen_to_carbon_respiration_ratio_g_o_per_g_c,
            )).boundary;
        plant_internal_oxygen_production_g_o += activity.oxygen_internal_production_g;
        plant_internal_oxygen_consumption_g_o += activity.oxygen_internal_consumption_g;
        plant_fire_nitrogen_output_g_n += accepted_plant.fire_nutrient_output.nitrogen_g_n;
        plant_fire_phosphorus_output_g_p += accepted_plant.fire_nutrient_output.phosphorus_g_p;
        if (!std.math.isFinite(plant_internal_oxygen_production_g_o) or
            !std.math.isFinite(plant_internal_oxygen_consumption_g_o) or
            !std.math.isFinite(plant_fire_nitrogen_output_g_n) or
            !std.math.isFinite(plant_fire_phosphorus_output_g_p))
            return error.HourlyCellBoundaryOverflow;
    }
    try ecosys.layer_local_conservation.accumulatePlantAtmosphereActivity(
        &driver_context.hourly_layer_boundary_ledger.*,
        driver_context.plant_atmosphere_local_activity.*,
        driver_context.state.*.active_soil_layer_count,
        driver_context.root_nitrogen_fixation_state_update_state.*.fixation_g_n_per_h_by_layer,
    );
    var plant_atmosphere_domain_candidate = driver_context.landscape_mass_balance_state.*.boundary_ledger;
    try plant_atmosphere_domain_candidate.accumulateAcceptedOxygenTransformationTotals(
        plant_internal_oxygen_production_g_o,
        plant_internal_oxygen_consumption_g_o,
    );
    try plant_atmosphere_domain_candidate.accumulateAcceptedPlantFireNutrientEmissionTotals(
        plant_fire_nitrogen_output_g_n,
        plant_fire_phosphorus_output_g_p,
    );
    for (0..driver_context.state.*.cell_count) |cell| {
        const plant_atmosphere_activity = (try ecosys.hourly_cell_conservation.plantAtmosphereCellActivityForCell(
            canopy_for_hourly_cell_boundary,
            if (driver_context.plant_root_state.*) |*value| value else null,
            &driver_context.canopy_carbon_state_update_state.*,
            &driver_context.canopy_fire_state_update_state.*,
            &driver_context.plant_combustion_state_update_state.*,
            cell,
            driver_context.runscript.*.root_gas_parameters.oxygen_to_carbon_respiration_ratio_g_o_per_g_c,
        )).boundary;
        try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, plant_atmosphere_activity);
        // The daily reducer must consume the same accepted endpoint owner as
        // the hourly cell ledger above.  Re-aggregating the branch exchange
        // here bypassed carbon_state_update's phenology mask and could book
        // stale inactive-plant fixation as a daily atmospheric O2 flux.
        const canopy_net_fixation_g_c = driver_context.canopy_carbon_state_update_state.*
            .hourly_net_fixation_g_c_per_h_by_cell[cell];
        try driver_context.daily_canopy_gas_exchange.*.accumulateHour(
            cell,
            canopy_net_fixation_g_c,
            driver_context.canopy_fire_state_update_state.*
                .carbon_dioxide_emission_g_c_per_h_by_cell[cell],
            driver_context.canopy_fire_state_update_state.*
                .methane_emission_g_c_per_h_by_cell[cell],
            driver_context.canopy_fire_state_update_state.*
                .oxygen_consumption_g_o_per_h_by_cell[cell],
            driver_context.runscript.*.root_gas_parameters.oxygen_to_carbon_respiration_ratio_g_o_per_g_c,
        );
        // EXTRACT 192--194: shoot-fire CO2/CH4 emissions are
        // negative canopy inputs; oxygen combustion is positive
        // uptake from canopy air.
        driver_context.hourly_accumulators.*[cell].canopy_co2_exchange_g_c_timestep -=
            driver_context.canopy_fire_state_update_state.*.carbon_dioxide_emission_g_c_per_h_by_cell[cell];
        driver_context.hourly_accumulators.*[cell].canopy_ch4_exchange_g_c_timestep -=
            driver_context.canopy_fire_state_update_state.*.methane_emission_g_c_per_h_by_cell[cell];
        driver_context.hourly_accumulators.*[cell].canopy_o2_exchange_g_o_timestep +=
            driver_context.canopy_fire_state_update_state.*.oxygen_consumption_g_o_per_h_by_cell[cell];
        // EXTRACT 784--789 and REDIST 6530--6578: direct
        // root-atmosphere exchange and source-signed gas released
        // by root withdrawal are canopy-air boundary fluxes. They
        // must reach XCNET/XHNET/XONET; soil-root and root phase
        // exchanges remain internal and are intentionally absent.
        const root_boundary = try ecosys.root_uptake_ledger.canopyGasBoundaryForCell(
            &driver_context.root_uptake_ledger_state.*,
            &driver_context.state.*,
            .{
                driver_context.root_gas_withdrawal_state_update_state.*.loss_g_element_per_h_by_gas_and_cell[0],
                driver_context.root_gas_withdrawal_state_update_state.*.loss_g_element_per_h_by_gas_and_cell[1],
                driver_context.root_gas_withdrawal_state_update_state.*.loss_g_element_per_h_by_gas_and_cell[2],
                driver_context.root_gas_withdrawal_state_update_state.*.loss_g_element_per_h_by_gas_and_cell[3],
                driver_context.root_gas_withdrawal_state_update_state.*.loss_g_element_per_h_by_gas_and_cell[4],
                driver_context.root_gas_withdrawal_state_update_state.*.loss_g_element_per_h_by_gas_and_cell[5],
            },
            cell,
        );
        driver_context.hourly_accumulators.*[cell].canopy_co2_exchange_g_c_timestep +=
            root_boundary.carbon_dioxide_net_input_g_c_per_h;
        driver_context.hourly_accumulators.*[cell].canopy_ch4_exchange_g_c_timestep +=
            root_boundary.methane_net_input_g_c_per_h;
        driver_context.hourly_accumulators.*[cell].canopy_o2_exchange_g_o_timestep +=
            root_boundary.oxygen_net_input_g_o_per_h;
        // EXTRACT lines 939-943, REDIST line 10991: add plant photosynthesis
        // contribution to hourly XCNET/XONET (CNET per cell from canopy carbon).
        driver_context.hourly_accumulators.*[cell].canopy_co2_exchange_g_c_timestep +=
            driver_context.canopy_carbon_state_update_state.*.canopy_carbon_exchange_g_c_per_h_by_cell[cell];
        driver_context.hourly_accumulators.*[cell].canopy_o2_exchange_g_o_timestep +=
            driver_context.canopy_carbon_state_update_state.*.canopy_oxygen_exchange_g_o_per_h_by_cell[cell];
    }
    driver_context.landscape_mass_balance_state.*.boundary_ledger = plant_atmosphere_domain_candidate;
    // HOUR1 4791-4796 and REDIST 4373-4377,10991-11002: after
    // every soil, litter, root, plant and fire gas contribution is
    // complete, stage the per-cell TKQ/VPQ and CO2Q/CH4Q/OXYQ
    // carried into the following hour. The active mass carrier is
    // intentionally not refreshed here: HOUR1 consumes this result
    // only at the beginning of the next accepted hour.
    for (0..driver_context.state.*.cell_count) |cell| {
        driver_context.atmospheric_co2_net_input_g_c.*[cell] = driver_context.hourly_accumulators.*[cell].canopy_co2_exchange_g_c_timestep;
        driver_context.atmospheric_ch4_net_input_g_c.*[cell] = driver_context.hourly_accumulators.*[cell].canopy_ch4_exchange_g_c_timestep;
        driver_context.atmospheric_o2_net_input_g_o.*[cell] = driver_context.hourly_accumulators.*[cell].canopy_o2_exchange_g_o_timestep;
        driver_context.atmospheric_boundary_resistance_h_per_m.*[cell] = try ecosys.ground_air_exchange.atmosphericBoundaryResistance(
            driver_context.atmospheric_state.*.air_temperature_k[cell],
            driver_context.ground_air_state.*.temperature_k[cell],
            driver_context.surface_aerodynamic_state.*.bulk_richardson_coefficient_k[cell],
            driver_context.surface_aerodynamic_state.*.isothermal_aerodynamic_resistance_h_per_m[cell],
            driver_context.runscript.*.ground_air_parameters,
        );
    }
    const carrier_has_canopy = driver_context.detailed_canopy_state.* != null and
        driver_context.canopy_precipitation_retention_state.* != null and
        driver_context.canopy_exposure_state.* != null;
    const carrier_plant_count = if (carrier_has_canopy) driver_context.config.*.plant_populations else 0;
    const carrier_live_fraction: []const f64 = if (carrier_has_canopy) driver_context.canopy_precipitation_retention_state.*.?.living_radiation_fraction else &.{};
    const carrier_dead_fraction: []const f64 = if (carrier_has_canopy) driver_context.canopy_precipitation_retention_state.*.?.standing_dead_radiation_fraction else &.{};
    const carrier_live_temperature: []const f64 = if (carrier_has_canopy) driver_context.detailed_canopy_state.*.?.plant_canopy_aerodynamic_temperature_k else &.{};
    const carrier_dead_temperature: []const f64 = if (carrier_has_canopy) driver_context.detailed_canopy_state.*.?.plant_standing_dead_aerodynamic_temperature_k else &.{};
    const carrier_live_vapor: []const f64 = if (carrier_has_canopy) driver_context.detailed_canopy_state.*.?.plant_canopy_aerodynamic_vapor_pressure_kpa else &.{};
    const carrier_dead_vapor: []const f64 = if (carrier_has_canopy) driver_context.detailed_canopy_state.*.?.plant_standing_dead_aerodynamic_vapor_pressure_kpa else &.{};
    const carrier_ground_fraction: []const f64 = if (carrier_has_canopy) driver_context.canopy_exposure_state.*.?.ground_exposure_fraction else driver_context.atmospheric_ground_radiation_fraction.*;
    try driver_context.atmospheric_canopy_gas_state.*.closeAcceptedHour(.{
        .plants_per_cell = carrier_plant_count,
        .living_radiation_fraction = carrier_live_fraction,
        .standing_dead_radiation_fraction = carrier_dead_fraction,
        .living_air_temperature_k = carrier_live_temperature,
        .standing_dead_air_temperature_k = carrier_dead_temperature,
        .living_air_vapor_pressure_kpa = carrier_live_vapor,
        .standing_dead_air_vapor_pressure_kpa = carrier_dead_vapor,
        .vapor_fraction_conversion_k_per_kpa = driver_context.runscript.*.canopy_surface_exchange_parameters.saturation_vapor_prefactor_k,
        .ground_temperature_k = driver_context.ground_air_state.*.temperature_k,
        .ground_vapor_m3_per_m3 = driver_context.ground_air_state.*.vapor_volume_fraction,
        .ground_radiation_fraction = carrier_ground_fraction,
        .atmospheric_background = driver_context.atmospheric_background_mixing_ratios.*,
        .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
        .aerodynamic_resistance_h_m = driver_context.atmospheric_boundary_resistance_h_per_m.*,
        .canopy_height_m = driver_context.surface_canopy_height_m.*,
        .co2_net_input_g_c_step = driver_context.atmospheric_co2_net_input_g_c.*,
        .ch4_net_input_g_c_step = driver_context.atmospheric_ch4_net_input_g_c.*,
        .o2_net_input_g_o_step = driver_context.atmospheric_o2_net_input_g_o.*,
        .timestep_h = 1,
    });
    // Independently close every cell×species plant inventory
    // before cell/domain reduction can cancel local defects.
    // This gate is diagnostic-only and remains inside the outer
    // transaction, so failure publishes no scientific state.
    if (driver_context.detailed_canopy_state.* != null or driver_context.plant_root_state.* != null) {
        const canopy = if (driver_context.detailed_canopy_state.*) |*value| value else return error.PlantConservationRequiresCompleteState;
        const roots = if (driver_context.plant_root_state.*) |*value| value else return error.PlantConservationRequiresCompleteState;
        try assemblePlantBalanceInputs(
            canopy,
            roots,
            driver_context.root_metabolism_plant_parameters.*,
            &driver_context.plant_daily_flux_ledger.*,
            driver_context.plant_conservation_scope_enabled.*,
            driver_context.plant_balance_carbon_inputs_workspace.*,
            driver_context.plant_balance_nitrogen_inputs_workspace.*,
            driver_context.plant_balance_phosphorus_inputs_workspace.*,
            driver_context.plant_balance_carbon_root_by_layer.*,
            driver_context.plant_balance_carbon_root_length_density_by_layer.*,
            driver_context.plant_balance_nutrient_root_by_layer.*,
        );
        for (0..driver_context.runtime_plant_count.*) |plant| {
            const inventory_after = try ecosys.plant_daily_flux_ledger
                .ElementalInventory.fromBalanceInputs(
                driver_context.plant_balance_carbon_inputs_workspace.*[plant],
                driver_context.plant_balance_nitrogen_inputs_workspace.*[plant],
                driver_context.plant_balance_phosphorus_inputs_workspace.*[plant],
                .{
                    .carbon_g = canopy.plant_charcoal_carbon_g[plant],
                    .nitrogen_g = canopy.plant_charcoal_nitrogen_g[plant],
                    .phosphorus_g = canopy.plant_charcoal_phosphorus_g[plant],
                },
            );
            const ledger_after = try ecosys.plant_daily_flux_ledger
                .ConservationLedgerSnapshot.capture(
                &driver_context.plant_daily_flux_ledger.*,
                plant,
            );
            var manure_output: ecosys.plant_daily_flux_ledger.ElementalInventory = .{
                .nitrogen_g = driver_context.hourly_manure_products_by_plant.*[plant]
                    .inorganic_nitrogen_g_n,
                .phosphorus_g = driver_context.hourly_manure_products_by_plant.*[plant]
                    .inorganic_phosphorus_g_p,
            };
            for (driver_context.hourly_manure_products_by_plant.*[plant]
                .organic_by_biochemical_fraction) |mass|
            {
                manure_output.carbon_g += mass.carbon_g;
                manure_output.nitrogen_g += mass.nitrogen_g;
                manure_output.phosphorus_g += mass.phosphorus_g;
            }
            const cell = plant / driver_context.config.*.plant_populations;
            driver_context.plant_conservation_reports.*[plant] =
                try ecosys.plant_daily_flux_ledger.evaluateAcceptedHour(
                    driver_context.plant_conservation_hour_start.*[plant],
                    inventory_after,
                    ledger_after,
                    manure_output,
                    driver_context.canopy_cell_area_m2.*[cell],
                    .{
                        .absolute_per_area = driver_context.config.*.mass_balance_absolute_tolerance,
                        .relative = driver_context.config.*.mass_balance_relative_tolerance,
                    },
                );
        }
        try ecosys.plant_daily_flux_ledger.requireAccepted(
            driver_context.plant_conservation_reports.*,
        );
    }
}

/// Applies local conservation acceptance, commits the scientific hour, and
/// publishes accepted output while the caller's rollback defers remain live.
noinline fn acceptHourAndPublish(driver_context: anytype, timeline_state: *TimelineState, advance_context: anytype, accept_context: anytype) !void {
    // Per-cell closure is a scientific acceptance condition, not
    // a nonlinear convergence condition. It remains inside the
    // outer-hour transaction, after every current-hour producer
    // has booked activity and before counters, commit or output.
    try ecosys.hourly_cell_conservation.requireProductionCoverage();
    try ecosys.layer_local_conservation.requireProductionCoverage();
    try diagnostics.reconstructLayerMassBalanceScopes(
        driver_context.hourly_science_context.*,
        driver_context.layer_conservation_layout.*,
        driver_context.hourly_layer_storage_after.*,
        driver_context.hourly_cell_storage_after.*,
    );
    try ecosys.layer_local_conservation.accumulateAcceptedWaterStorageUpdateRoundoff(
        driver_context.hourly_cell_boundary_ledger,
        driver_context.hourly_layer_boundary_ledger,
        driver_context.hourly_layer_storage_before.*,
        driver_context.hourly_layer_storage_after.*,
    );
    try ecosys.layer_local_conservation.accumulateAcceptedHeatStorageUpdateRoundoff(
        driver_context.hourly_cell_boundary_ledger,
        driver_context.hourly_layer_boundary_ledger,
    );
    var hourly_cell_conservation_report = try ecosys.hourly_cell_conservation.evaluate(
        driver_context.allocator.*,
        driver_context.hourly_cell_storage_before.*,
        driver_context.hourly_cell_storage_after.*,
        driver_context.hourly_cell_boundary_ledger.*.cells,
        driver_context.canopy_cell_area_m2.*,
        .{
            .absolute_per_area = driver_context.config.*.mass_balance_absolute_tolerance,
            .relative = driver_context.config.*.mass_balance_relative_tolerance,
        },
    );
    defer hourly_cell_conservation_report.deinit(driver_context.allocator.*);
    if (!hourly_cell_conservation_report.accepted()) {
        var surface_carbon_dioxide_production_g_c: f64 = 0;
        var soil_carbon_dioxide_production_g_c: f64 = 0;
        var surface_signed_heterotrophic_respiration_g_c: f64 = 0;
        var soil_signed_heterotrophic_respiration_g_c: f64 = 0;
        for (driver_context.daily_heterotrophic_respiration.*.surface_hourly_carbon_dioxide_production_g_c) |value|
            surface_carbon_dioxide_production_g_c += value;
        for (driver_context.daily_heterotrophic_respiration.*.soil_hourly_carbon_dioxide_production_g_c) |value|
            soil_carbon_dioxide_production_g_c += value;
        for (driver_context.daily_heterotrophic_respiration.*.surface_hourly_signed_g_c) |value|
            surface_signed_heterotrophic_respiration_g_c += value;
        for (driver_context.daily_heterotrophic_respiration.*.soil_hourly_signed_g_c) |value|
            soil_signed_heterotrophic_respiration_g_c += value;
        std.log.err(
            "hourly carbon respiration diagnostics: surface_co2_production_g_c={e} soil_co2_production_g_c={e} surface_signed_co2_plus_methane_delta_g_c={e} soil_signed_co2_plus_methane_delta_g_c={e}",
            .{ surface_carbon_dioxide_production_g_c, soil_carbon_dioxide_production_g_c, surface_signed_heterotrophic_respiration_g_c, soil_signed_heterotrophic_respiration_g_c },
        );
        std.log.err(
            "hourly post-NITRO conservation trace: points=after_nitro,after_post_watsub,after_uptake,after_chemistry,after_transport,after_interface_heat,after_surface_gas residue_carbon_g_c={any} organic_carbon_g_c={any} inorganic_and_gas_carbon_g_c={any} plant_carbon_g_c={any} soil_gas_carbon_g_c={any} heat_storage_megajoules={any} heat_closed_megajoules={any} heat_internal_production_megajoules={any} heat_internal_consumption_megajoules={any} litter_soil_organic_heat_rebase_megajoules={e}",
            .{
                driver_context.hourly_science_context.*.diagnostic_residue_carbon_trace_g_c.*,
                driver_context.hourly_science_context.*.diagnostic_organic_carbon_trace_g_c.*,
                driver_context.hourly_science_context.*.diagnostic_inorganic_carbon_trace_g_c.*,
                driver_context.hourly_science_context.*.diagnostic_plant_carbon_trace_g_c.*,
                driver_context.hourly_science_context.*.diagnostic_soil_gas_carbon_trace_g_c.*,
                driver_context.hourly_science_context.*.diagnostic_heat_storage_trace_megajoules.*,
                driver_context.hourly_science_context.*.diagnostic_heat_closed_trace_megajoules.*,
                driver_context.hourly_science_context.*.diagnostic_heat_production_trace_megajoules.*,
                driver_context.hourly_science_context.*.diagnostic_heat_consumption_trace_megajoules.*,
                driver_context.hourly_science_context.*.diagnostic_litter_soil_organic_heat_rebase_megajoules.*,
            },
        );
        // N1's decisive pair. Compare `signed` against the `kind=surface`
        // scope's `storage_step - booked_step` printed above: equal means the
        // ledger gap IS the accepted process residual, ~0 means a term reaches
        // surface storage without passing through the residual. `absolute`
        // bounds how much same-signed accumulation is hiding inside `signed`.
        // The five census inputs at both ends of the hour. Evaluate
        // `landscape_mass_inventory_surface.zig:513-540` by hand from the two
        // sets and compare the difference against the `kind=surface` scope's
        // `storage_step` printed above: whichever input moved without a
        // matching booking is the answer, with no fitted constant anywhere.
        if (driver_context.state.*.cell_count > 0) {
            const science = driver_context.hourly_science_context.*;
            std.log.err(
                "hourly surface census inputs: organic_carbon_g_c={e}->{e} litter_water_m3={e}->{e} water_vapor_mol={e}->{e} ice_water_equivalent_m3={e}->{e} surface_temperature_k={e}->{e}",
                .{
                    science.diagnostic_surface_census_inputs_at_hour_start.*[0],
                    try science.surface_organic.totalCarbon_g_c(0),
                    science.diagnostic_surface_census_inputs_at_hour_start.*[1],
                    science.surface_precipitation.litter_water_m3[0],
                    science.diagnostic_surface_census_inputs_at_hour_start.*[2],
                    science.litter_gas_transport.water_vapor_mol[0],
                    science.diagnostic_surface_census_inputs_at_hour_start.*[3],
                    science.surface_litter_ice_m3[0],
                    science.diagnostic_surface_census_inputs_at_hour_start.*[4],
                    science.grid.surface_temperature_k[0],
                },
            );
        }
        // N1's remaining 3.47%, and it needs no fitted parameter. Respiration
        // accounts for 96.53% of the day-89 surface residual
        // (`c_org * surface_co2_production_g_c * T` = `6.893880176060551e-9` MJ
        // against `7.13310266409195e-9`), leaving `2.392e-10` MJ. This rebase
        // books the WHOLE nitro window's carbon change, not the CO2 alone, so:
        //   * if `c_org * (after - before) * temperature_used` equals
        //     `booked_rebase`, the rebase is self-consistent and the remainder
        //     lives outside it;
        //   * if `booked_rebase` differs from `c_org * co2 * T` by about
        //     `2.392e-10`, the window-versus-CO2 difference IS the remainder.
        // Either outcome is decisive. Do NOT solve for a temperature here: the
        // retracted fit needed `284.5854432719039 K`, which is `9.54 K` above
        // this hour's maximum census temperature and `394x` the hour's entire
        // temperature change, and that is why it was an artifact.
        // HEAT-001's predicted cause. `cross_term_megajoules` is
        // `c_org * sum_i dC_i*dT_i` over the interface rebase's substeps. If it
        // equals the `kind=surface` residual of `-7.13310266409195e-9` MJ, the
        // gap IS carbon moving while the surface temperature drifts inside the
        // hour, and the fix is to price each substep's carbon step against the
        // temperature the census will use rather than the substep's own.
        // `booked_over_c_org` reproduces
        // `litter_soil_organic_heat_rebase_megajoules / c_org` as a cross-check
        // that the probe saw every substep.
        if (driver_context.state.*.cell_count > 0) {
            const drift = driver_context.hourly_science_context.*.diagnostic_litter_soil_rebase_drift;
            const dry_organic = driver_context.runscript.*.surface_pond_dry_organic_heat_capacity_megajoules_per_g_c_k;
            // `census_temperature_gap_megajoules` is the decisive one:
            //   c_org * [ sum_i dC_i*T_i  -  (sum_i dC_i) * T_census_end ]
            // i.e. what this site booked, minus what it would have booked had
            // every substep's carbon step been priced at the temperature the
            // census actually uses at the hour end. The first probe design
            // measured `dT` against the PREVIOUS SUBSTEP instead and produced
            // `9.433723952230303e-9` against a `7.13310266409195e-9` residual --
            // 32% out, because the substep temperatures are not bracketed by the
            // census endpoints (`275.40985990937395` vs `275.04131626252627`).
            const census_temperature_k = driver_context.hourly_science_context.*.grid.surface_temperature_k[0];
            std.log.err(
                "hourly litter-soil rebase drift: substeps={e} cross_term_megajoules={e} booked_over_c_org={e} last_temperature_k={e} carbon_step_total_g_c={e} census_temperature_gap_megajoules={e}",
                .{
                    drift.*[0],
                    dry_organic * drift.*[1],
                    drift.*[2],
                    drift.*[3],
                    drift.*[4],
                    dry_organic * (drift.*[2] - drift.*[4] * census_temperature_k),
                },
            );
        }
        std.log.err(
            "hourly surface respiration rebase: carbon_g_c={e}->{e} temperature_used_k={e} booked_rebase_megajoules={e}",
            .{
                driver_context.hourly_science_context.*.diagnostic_surface_respiration_rebase.*[0],
                driver_context.hourly_science_context.*.diagnostic_surface_respiration_rebase.*[1],
                driver_context.hourly_science_context.*.diagnostic_surface_respiration_rebase.*[2],
                driver_context.hourly_science_context.*.diagnostic_surface_respiration_rebase.*[3],
            },
        );
        std.log.err(
            "hourly surface solver residual: signed_total_megajoules={e} absolute_total_megajoules={e}",
            .{
                driver_context.hourly_science_context.*.diagnostic_surface_energy_residual_signed_megajoules.*,
                driver_context.hourly_science_context.*.diagnostic_surface_energy_residual_absolute_megajoules.*,
            },
        );
        std.log.err(
            "hourly WATSUB heat trace: terms=pre_storage,pre_closed,post_solve_storage,post_solve_closed,post_atmosphere_closed,post_state_storage,post_state_closed,ground_air_storage_delta,ground_air_atmospheric,ground_air_prescribed,ground_air_implicit,surface_net_radiation,surface_sensible,surface_latent,surface_vapor_sensible,combined_surface,represented_snow,exposed_ground,topsoil_vapor,topsoil_sensible,surface_phase,surface_storage,surface_conduction,soil_boundary_input,soil_boundary_output,external_water_advective_outward,soil_cell_source,transaction_surface_conduction,snow_reference,surface_phase_sensible_path_sum,soil_richards_enthalpy_change,soil_vapor_enthalpy_change,soil_phase_enthalpy_change,soil_phase_absolute_enthalpy_change,soil_spatial_heat_enthalpy_change,soil_phase_latent_heat,soil_heat_solver_freeze_thaw_latent,surface_internal_vapor_latent_path_sum,surface_atmospheric_water_thermalization_path_sum values_megajoules={any}",
            .{driver_context.hourly_science_context.*.diagnostic_watsub_heat_trace_megajoules.*},
        );
        for (0..driver_context.state.*.cell_count) |cell| {
            const accepted_snow = driver_context.hourly_science_context.*.snow_surface_discharge[cell];
            const direct_atmosphere = driver_context.hourly_science_context.*.direct_surface_solute_input[cell];
            const gas_first = cell * ecosys.gas_transport.species_count;
            std.log.err(
                "hourly surface chemistry ownership: cell={d} accepted_snow_litter_g={any} accepted_snow_soil_nonband_g={any} accepted_snow_soil_band_g={any} direct_litter_g={any} direct_soil_nonband_g={any} direct_soil_band_g={any} litter_atmospheric_gas_flux_g={any}",
                .{
                    cell,
                    accepted_snow.litter_g,
                    accepted_snow.soil_nonband_g,
                    accepted_snow.soil_band_g,
                    direct_atmosphere.litter_g,
                    direct_atmosphere.soil_nonband_g,
                    direct_atmosphere.soil_band_g,
                    driver_context.surface_litter_gas_transport_state.*.atmospheric_flux_g_per_h[gas_first..][0..ecosys.gas_transport.species_count],
                },
            );
        }
    }
    // REAL-DECK-HOUR-11-FATAL-STAGNATION-001 / MASS-BALANCE-HEAT-FLOOR-DECK-EDIT-001
    // (2026-09-04): mirrors the proven-safe local floor already landed for
    // hourly_heat_water_solute.zig's surface-energy ledger (d29668c/b0df6cf)
    // -- a real production run showed this layer-level heat ledger
    // independently catches the exact same genuine-but-physically-minute
    // (~0.0015 J) same-signed accumulated defect, at the same real hour,
    // that check already absorbs. Only `heat_megajoules_m2` is adjusted, via
    // a local copy; every other field (water/oxygen/carbon/nitrogen/
    // phosphorus/ions/hydrogen) and the shared
    // `driver_context.config.*.mass_balance_absolute_tolerance` struct
    // itself are untouched, so this cannot cascade into any of the other
    // consuming call sites the way editing that shared struct directly did
    // (see MASS-BALANCE-HEAT-FLOOR-DECK-EDIT-001's reverted attempt).
    var layer_absolute_per_area = driver_context.config.*.mass_balance_absolute_tolerance;
    layer_absolute_per_area.heat_megajoules_m2 = @max(
        layer_absolute_per_area.heat_megajoules_m2,
        3.0e-9,
    );
    var hourly_layer_conservation_report = try ecosys.layer_local_conservation.evaluate(
        driver_context.allocator.*,
        driver_context.hourly_layer_storage_before.*,
        driver_context.hourly_layer_storage_after.*,
        driver_context.hourly_layer_boundary_ledger.*.activity,
        driver_context.layer_scope_area_m2.*,
        .{
            .absolute_per_area = layer_absolute_per_area,
            .relative = driver_context.config.*.mass_balance_relative_tolerance,
        },
    );
    defer hourly_layer_conservation_report.deinit(driver_context.allocator.*);
    // SURFACE-HEAT-PONDED-LITTER-BOOKING-001: the surface scope's six heat terms
    // EVERY hour, not only on the hour that fails.
    //
    // The failure branch below prints them, which is what localized the defect
    // to a surface-only unbooked input of about 4.3e-5 MJ -- but one sample
    // cannot say whether that input steps in at one hour or accumulates, and
    // that distinction decides where to look. Two captures eight hours apart
    // showed the residual near-constant (4.273623903272572e-5 then
    // 4.3868628948784405e-5) across a NET STORAGE STEP THAT CHANGED SIGN, so it
    // scales with nothing already printed. The history is the missing evidence.
    //
    // One line per cell per hour at `info`, beside the `daily conservation
    // accepted` line the harness already scrapes. It reads the report and the
    // ledger that were both built above and mutates nothing.
    //
    // PERFORMANCE-LOGGING-OVERHEAD-001 (2026-09-18): this block is debug
    // scaffolding left over from a closed investigation (see the
    // SURFACE-HEAT-PONDED-LITTER-BOOKING-001 / PHOSPHORUS-SURFACE-CLOSURE-
    // HOUR-2658-001 comments above and below). Measured on the Ottawa
    // benchmark deck it alone produced 10,312 of 19,248 total log lines
    // (~54%) over a 2,578-hour run -- one hour's worth of lines fired on
    // EVERY hour, not just the frontier hour it was written to diagnose.
    // Every value read here is local to this loop and never used again (the
    // real conservation gate is `hourly_layer_conservation_report`, evaluated
    // above unconditionally); gating only this printing block cannot change
    // any accepted/rejected decision or any written output. Gated behind
    // `run_support.verbose_diagnostics_enabled` (off by default; enable with
    // `--verbose-diagnostics`) rather than deleted, so the historical
    // frontier investigation remains reproducible on demand.
    if (run_support.verbose_diagnostics_enabled) for (0..driver_context.state.*.cell_count) |cell| {
        const surface_scope = driver_context.layer_conservation_layout.*.index(
            .{ .kind = .surface, .cell = cell },
        ) catch continue;
        const surface_before = driver_context.hourly_layer_storage_before.*[surface_scope];
        const surface_after = driver_context.hourly_layer_storage_after.*[surface_scope];
        const surface_activity = driver_context.hourly_layer_boundary_ledger.*.activity[surface_scope];
        const surface_closure = hourly_layer_conservation_report.cells[surface_scope]
            .closure[@intFromEnum(ecosys.hourly_cell_conservation.Quantity.heat)];
        // PHOSPHORUS-SURFACE-CLOSURE-HOUR-2658-001, following the heat
        // precedent. `hourly_cell_conservation.totalPhosphorus` (`:2490`) is a
        // compensated sum of exactly four lanes, so printing them separately
        // before and after names the one that moves unbooked -- which is how the
        // surface heat defect was localized, after chasing producers had failed.
        //
        // The accumulation hypothesis is already refuted (all 45 interface
        // additions were bit-exact) and the interface transfer accounts for
        // neither the residual nor all of the booked flux, so the remaining
        // question is which STORAGE lane moves.
        const phosphorus_before = driver_context.hourly_layer_storage_before.*[surface_scope];
        const phosphorus_after = driver_context.hourly_layer_storage_after.*[surface_scope];
        const phosphorus_closure = hourly_layer_conservation_report.cells[surface_scope]
            .closure[@intFromEnum(ecosys.hourly_cell_conservation.Quantity.phosphorus)];
        std.log.info(
            "hourly surface phosphorus lanes: cell={d} hour={d} residue_before_g={e} residue_after_g={e} organic_before_g={e} organic_after_g={e} phosphate_before_g={e} phosphate_after_g={e} plant_before_g={e} plant_after_g={e} residual_g={e} accepted={}",
            .{
                cell,
                driver_context.stage_census.*.observed_hours,
                phosphorus_before.residue_phosphorus_g,
                phosphorus_after.residue_phosphorus_g,
                phosphorus_before.organic_phosphorus_g,
                phosphorus_after.organic_phosphorus_g,
                phosphorus_before.phosphate_phosphorus_g,
                phosphorus_after.phosphate_phosphorus_g,
                phosphorus_before.plant_phosphorus_g,
                phosphorus_after.plant_phosphorus_g,
                phosphorus_closure.residual,
                phosphorus_closure.accepted,
            },
        );
        // PHOSPHORUS-SOIL-SURFACE-BIOGEOCHEMISTRY-HALVES-001. The per-hour residual
        // distribution over all 2,658 hours settles what this defect is: median
        // 1.09e-16, 90th percentile 4.54e-16, largest non-failing hour 1.798e-15,
        // and hour 2,658 at 1.1048e-10 -- 61,000x the next hour and ~1e6x the
        // median, with exactly one hour above 1e-12. So the arithmetic floor is
        // machine precision, the gate's tolerance is well calibrated, and hour
        // 2,658 is a real single-hour event.
        //
        // The storage lanes cannot explain it: hours 2,654, 2,656 and 2,658 are all
        // surface-phosphate drain hours with structurally identical lanes (residue
        // +1e-4, organic bit-identical, phosphate ~5-7e-2 down to ~1e-9, plant
        // zero) and residuals of 1.39e-17, -6.94e-18 and 1.1048e-10. The difference
        // must therefore be on the BOOKED side, which the gate prints only when it
        // fails. Print it every hour so a passing drain hour can be differenced
        // against the failing one.
        std.log.info(
            "hourly surface phosphorus booked: cell={d} hour={d} input_g={e} output_g={e} allowance_g={e}",
            .{
                cell,
                driver_context.stage_census.*.observed_hours,
                surface_activity.phosphorus_input_g,
                surface_activity.phosphorus_output_g,
                surface_activity.phosphorus_storage_update_roundoff_allowance_g,
            },
        );
        // SURFACE-HEAT-PONDED-LITTER-BOOKING-001, two-owner test. The stored
        // `surface_heat_capacity_megajoules_per_k` is written once per hour at
        // `stages/hourly_snow_energy.zig:432` from
        // `litter_gas_transport.water_vapor_mol`, while
        // `landscape_mass_inventory_surface.zig:502` recomputes the same
        // quantity at audit time from `surface_gas.water_vapor_mol`. The
        // snowpack-disappearance transfer derives its DRY capacity by
        // subtracting a recomputed wet capacity from the stored total
        // (`snowpack_litter_heat_water_transfer.zig:232-238`), so any
        // disagreement between the two owners becomes fictitious dry capacity
        // and lands in the temperature and the energy split.
        //
        // The failing hour is the first hour surface vapor and ice are nonzero,
        // which is exactly when the two owners can first diverge. Printing both
        // settles it; a `1.509e-7` MJ/K gap reproduces the residual at the
        // observed temperature.
        const stored_surface_heat_capacity = driver_context.surface_heat_capacity_megajoules_per_k.*[cell];
        // The stored capacity is written ONCE PER HOUR at
        // `stages/hourly_snow_energy.zig:432`. Recomputing it here from the
        // audit-time state, with the same three terms and the same parameters,
        // measures directly whether it has gone stale within the hour --
        // which is the last unmeasured link, and the one the
        // snowpack-disappearance transfer depends on, because it derives its
        // DRY capacity by subtracting a freshly-recomputed wet capacity from
        // this stored total.
        //
        // The hour-2,657 comparison could not separate this from the latent
        // offset, because surface ice was zero there; at hour 2,658 it is not.
        const capacity_organic_carbon_g_c = driver_context.surface_organic_state.*.totalCarbon_g_c(cell) catch 0;
        const capacity_vapor_water_equivalent_m3 =
            driver_context.litter_gas_transport_state.*.water_vapor_mol[cell] *
            driver_context.runscript.*.soil_gas_transport_parameters.water_molar_mass_g_per_mol /
            driver_context.runscript.*.soil_gas_transport_parameters.water_density_g_per_m3;
        const capacity_ice_per_water_equivalent = ecosys.ice_units.heatCapacityPerWaterEquivalentM3K(
            driver_context.runscript.*.soil_phase_heat_parameters.ice_heat_capacity_megajoules_per_m3_k,
            driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.ice_density_megagrams_per_m3,
        ) catch 0;
        // Through the one owner, not a fourth copy: a probe that recomputed the
        // formula independently could drift from the quantity it is measuring,
        // which would make its own gap uninterpretable.
        const recomputed_surface_heat_capacity = ecosys.surface_litter_geometry.heatCapacityMegajoulesPerK(
            driver_context.runscript.*.surface_pond_dry_organic_heat_capacity_megajoules_per_g_c_k,
            capacity_organic_carbon_g_c,
            driver_context.runscript.*.soil_phase_heat_parameters.liquid_water_heat_capacity_megajoules_per_m3_k,
            driver_context.surface_precipitation_state.*.litter_water_m3[cell],
            capacity_vapor_water_equivalent_m3,
            capacity_ice_per_water_equivalent,
            driver_context.surface_litter_ice_m3.*[cell],
        ) catch 0;
        std.log.info(
            "hourly surface heat capacity owners: cell={d} hour={d} stored_megajoules_per_k={e} recomputed_megajoules_per_k={e} capacity_gap_megajoules_per_k={e} surface_temperature_k={e} capacity_gap_times_temperature_megajoules={e} organic_carbon_g_c={e} litter_water_m3={e} vapor_water_equivalent_m3={e} ice_water_equivalent_m3={e}",
            .{
                cell,
                driver_context.stage_census.*.observed_hours,
                stored_surface_heat_capacity,
                recomputed_surface_heat_capacity,
                recomputed_surface_heat_capacity - stored_surface_heat_capacity,
                driver_context.state.*.surface_temperature_k[cell],
                (recomputed_surface_heat_capacity - stored_surface_heat_capacity) *
                    driver_context.state.*.surface_temperature_k[cell],
                capacity_organic_carbon_g_c,
                driver_context.surface_precipitation_state.*.litter_water_m3[cell],
                capacity_vapor_water_equivalent_m3,
                driver_context.surface_litter_ice_m3.*[cell],
            },
        );
        std.log.info(
            "hourly surface heat scope history: cell={d} hour={d} storage_before_megajoules={e} storage_after_megajoules={e} storage_step_megajoules={e} external_input_megajoules={e} external_output_megajoules={e} internal_production_megajoules={e} internal_consumption_megajoules={e} booked_step_megajoules={e} residual_megajoules={e} accepted={}",
            .{
                cell,
                driver_context.stage_census.*.observed_hours,
                surface_before.heat_megajoules,
                surface_after.heat_megajoules,
                surface_after.heat_megajoules - surface_before.heat_megajoules,
                surface_activity.heat_input_megajoules,
                surface_activity.heat_output_megajoules,
                surface_activity.heat_internal_production_megajoules,
                surface_activity.heat_internal_consumption_megajoules,
                (surface_activity.heat_input_megajoules - surface_activity.heat_output_megajoules) +
                    (surface_activity.heat_internal_production_megajoules -
                        surface_activity.heat_internal_consumption_megajoules),
                surface_closure.residual,
                surface_closure.accepted,
            },
        );
    };
    if (hourly_cell_conservation_report.failing_cell_count[@intFromEnum(ecosys.hourly_cell_conservation.Quantity.heat)] != 0) {
        for (hourly_layer_conservation_report.cells, 0..) |scope_report, index| {
            const address = try driver_context.layer_conservation_layout.*.address(index);
            const heat = scope_report.closure[@intFromEnum(ecosys.hourly_cell_conservation.Quantity.heat)];
            std.log.err("hourly heat failure scope: kind={s} cell={d} layer={d} residual={e} physical_limit={e} arithmetic_roundoff_allowance={e} accepted={}", .{
                @tagName(address.kind), address.cell,                       address.layer, heat.residual,
                heat.acceptance_limit,  heat.arithmetic_roundoff_allowance, heat.accepted,
            });
            // The six terms the residual above is the signed sum of. `Closure`
            // keeps only the residual and its derived limits, so a scope whose
            // residual exceeds its own arithmetic allowance cannot be read any
            // further from the report alone -- which is exactly the situation
            // at soil layers 9, 10 and 11 (see
            // `HOUR-346-LIVES-IN-THE-THREE-0.500-M-DEEP-LAYERS-TWO-OF-WHICH-ARE-EXTRAPOLATED-004`).
            // Every array here is already in scope, passed to `evaluate` just
            // above and indexed identically by scope, so this adds no work on
            // any accepted hour: the whole block is inside the heat-failure
            // branch.
            const scope_before = driver_context.hourly_layer_storage_before.*[index];
            const scope_after = driver_context.hourly_layer_storage_after.*[index];
            const scope_activity = driver_context.hourly_layer_boundary_ledger.*.activity[index];
            std.log.err("hourly heat failure scope terms: kind={s} cell={d} layer={d} storage_before_megajoules={e} storage_after_megajoules={e} storage_step_megajoules={e} external_input_megajoules={e} external_output_megajoules={e} internal_production_megajoules={e} internal_consumption_megajoules={e} booked_step_megajoules={e}", .{
                @tagName(address.kind),
                address.cell,
                address.layer,
                scope_before.heat_megajoules,
                scope_after.heat_megajoules,
                scope_after.heat_megajoules - scope_before.heat_megajoules,
                scope_activity.heat_input_megajoules,
                scope_activity.heat_output_megajoules,
                scope_activity.heat_internal_production_megajoules,
                scope_activity.heat_internal_consumption_megajoules,
                (scope_activity.heat_input_megajoules - scope_activity.heat_output_megajoules) +
                    (scope_activity.heat_internal_production_megajoules -
                        scope_activity.heat_internal_consumption_megajoules),
            });
        }
    }
    // Both read-only reports must be evaluated before either acceptance gate
    // returns. A failing cell total can otherwise hide the current attempt's
    // local soil/snow/surface/canopy residuals and leave only stale stage
    // traces from an earlier hour. This changes diagnostics on failure only;
    // neither report mutates scientific or accounting state.
    // Survey mode records every breach and continues, instead of aborting the
    // hour on the first one. No tolerance changes: the reports above were
    // evaluated at exactly their production limits and their verdicts are
    // taken verbatim here. The deck stops at day 14 of a 30-year horizon, so
    // aborting reveals at most one defect per run; surveying names them all in
    // one pass. A surveyed run is not production evidence -- see
    // `validation/conservation_survey.zig` and the startup banner.
    if (driver_context.conservation_survey.*) |survey| {
        recordConservationSurvey(
            survey,
            hourly_cell_conservation_report,
            hourly_layer_conservation_report,
            driver_context.stage_census.*.observed_hours,
        );
    } else {
        try ecosys.hourly_cell_conservation.requireAccepted(hourly_cell_conservation_report);
        try ecosys.layer_local_conservation.requireAccepted(hourly_layer_conservation_report);
    }
    // Survey mode skips this entire accepted-bookkeeping block and clears the
    // accumulated closures each hour, so no cross-hour chain is ever built.
    //
    // It must be the whole block. `AccumulatedCellConservationFailure` is
    // raised INSIDE `evaluateAndCommit`, and the hourly history, the
    // accumulated commit and the continuity check are interlocked invariants
    // over one unbroken chain, so bypassing any single one desynchronises the
    // next. Skipping piecemeal died at day 14 four times in sequence:
    // `CannotRecordFailedHourlyCellClosure`, then
    // `InvalidAccumulatedCellClosureHistory`, then
    // `AccumulatedCellStorageDiscontinuity`, then the history error again.
    //
    // Never starting the chain is more honest than mending it: an accumulated
    // balance spanning an hour the model judged non-conserving means nothing,
    // so the correct output is no accumulated number rather than a repaired
    // one. The hourly audits still run at full production strength every hour;
    // only accumulation ACROSS hours is withheld, and the streamed
    // `CONSERVATION_BREACH` lines are the product.
    if (driver_context.conservation_survey.* != null) {
        if (driver_context.landscape_mass_balance_state.*.accumulated_cell_closure) |*live| live.deinit();
        driver_context.landscape_mass_balance_state.*.accumulated_cell_closure = null;
        if (driver_context.landscape_mass_balance_state.*.accumulated_layer_closure) |*live| live.deinit();
        driver_context.landscape_mass_balance_state.*.accumulated_layer_closure = null;
    } else {
        var accumulated_cell_conservation_report =
            try ecosys.accumulated_cell_conservation.evaluateAndCommit(
                &driver_context.landscape_mass_balance_state.*.accumulated_cell_closure,
                driver_context.allocator.*,
                driver_context.allocator.*,
                driver_context.hourly_cell_storage_before.*,
                driver_context.hourly_cell_storage_after.*,
                driver_context.hourly_cell_boundary_ledger.*.cells,
                driver_context.canopy_cell_area_m2.*,
                .{
                    .absolute_per_area = driver_context.config.*.mass_balance_absolute_tolerance,
                    .relative = driver_context.config.*.mass_balance_relative_tolerance,
                },
                driver_context.landscape_mass_balance_state.*.hourly_cell_closure.accepted_hour_count,
            );
        defer accumulated_cell_conservation_report.deinit(driver_context.allocator.*);
        var accumulated_layer_conservation_report =
            try ecosys.layer_local_conservation.evaluateAndCommitAccumulated(
                &driver_context.landscape_mass_balance_state.*.accumulated_layer_closure,
                driver_context.allocator.*,
                driver_context.allocator.*,
                driver_context.layer_conservation_layout.*,
                driver_context.hourly_layer_storage_before.*,
                driver_context.hourly_layer_storage_after.*,
                driver_context.hourly_layer_boundary_ledger.*.activity,
                driver_context.layer_scope_area_m2.*,
                .{
                    .absolute_per_area = driver_context.config.*.mass_balance_absolute_tolerance,
                    .relative = driver_context.config.*.mass_balance_relative_tolerance,
                },
                driver_context.landscape_mass_balance_state.*.hourly_layer_closure.accepted_hour_count,
            );
        defer accumulated_layer_conservation_report.deinit(driver_context.allocator.*);
        try driver_context.landscape_mass_balance_state.*.hourly_cell_closure.recordAccepted(
            hourly_cell_conservation_report,
        );
        try driver_context.landscape_mass_balance_state.*.hourly_layer_closure.recordAccepted(
            hourly_layer_conservation_report,
        );
        inline for (@typeInfo(ecosys.hourly_cell_conservation.Quantity).@"enum".fields) |quantity| {
            const index: usize = @intCast(quantity.value);
            std.log.debug(
                "accepted hourly and accumulated cell/layer closure: hour={d} quantity={s} cell_hourly_maximum_absolute={e} cell_hourly_maximum_normalized_relative={e} cell_historical_hourly_maximum_absolute={e} cell_historical_hourly_maximum_normalized_relative={e} cell_accumulated_maximum_absolute={e} cell_accumulated_maximum_normalized_relative={e} layer_hourly_maximum_absolute={e} layer_hourly_maximum_normalized_relative={e} layer_historical_hourly_maximum_absolute={e} layer_historical_hourly_maximum_normalized_relative={e} layer_accumulated_maximum_absolute={e} layer_accumulated_maximum_normalized_relative={e}",
                .{
                    advance_context.scene_weather_hours.* + 1,
                    quantity.name,
                    driver_context.landscape_mass_balance_state.*.hourly_cell_closure.last_maximum_absolute[index],
                    driver_context.landscape_mass_balance_state.*.hourly_cell_closure.last_maximum_normalized_relative[index],
                    driver_context.landscape_mass_balance_state.*.hourly_cell_closure.accumulated_maximum_absolute[index],
                    driver_context.landscape_mass_balance_state.*.hourly_cell_closure.accumulated_maximum_normalized_relative[index],
                    accumulated_cell_conservation_report.maximum_absolute[index],
                    accumulated_cell_conservation_report.maximum_normalized_relative[index],
                    driver_context.landscape_mass_balance_state.*.hourly_layer_closure.last_maximum_absolute[index],
                    driver_context.landscape_mass_balance_state.*.hourly_layer_closure.last_maximum_normalized_relative[index],
                    driver_context.landscape_mass_balance_state.*.hourly_layer_closure.accumulated_maximum_absolute[index],
                    driver_context.landscape_mass_balance_state.*.hourly_layer_closure.accumulated_maximum_normalized_relative[index],
                    accumulated_layer_conservation_report.maximum_absolute[index],
                    accumulated_layer_conservation_report.maximum_normalized_relative[index],
                },
            );
        }
    }
    try driver_context.landscape_mass_balance_state.*.boundary_ledger
        .accumulateAcceptedHourlyCellElements(
        driver_context.hourly_cell_boundary_ledger.*.cells,
    );
    // Complete all fallible hourly closure diagnostics before the
    // nontransactional output boundary. No file append occurs
    // while the scientific transaction is still rollbackable.
    if (std.log.logEnabled(.debug, .default)) {
        const heat_closure_totals = try reconstructLandscapeMassBalance(driver_context.hourly_science_context.*);
        const heat_closure_boundary = driver_context.landscape_mass_balance_state.*.boundary_ledger.cumulative;
        const heat_closure_delta_storage_megajoules = heat_closure_totals.heat_storage_megajoules - advance_context.heat_closure_previous_storage_megajoules.*;
        const heat_closure_delta_input_megajoules = heat_closure_boundary.heat_input_megajoules - advance_context.heat_closure_previous_cumulative_input_megajoules.*;
        const heat_closure_delta_output_megajoules = heat_closure_boundary.heat_output_megajoules - advance_context.heat_closure_previous_cumulative_output_megajoules.*;
        const heat_closure_delta_internal_production_megajoules = heat_closure_totals.cumulative_internal_heat_production_megajoules - advance_context.heat_closure_previous_cumulative_internal_production_megajoules.*;
        const heat_closure_delta_internal_consumption_megajoules = heat_closure_totals.cumulative_internal_heat_consumption_megajoules - advance_context.heat_closure_previous_cumulative_internal_consumption_megajoules.*;
        std.log.debug("hourly heat closure (own bookings): hour={d} residual_megajoules={e} delta_storage_megajoules={e} delta_input_megajoules={e} delta_output_megajoules={e} delta_internal_production_megajoules={e} delta_internal_consumption_megajoules={e}", .{ advance_context.scene_weather_hours.* + 1, heat_closure_delta_storage_megajoules - heat_closure_delta_input_megajoules + heat_closure_delta_output_megajoules - heat_closure_delta_internal_production_megajoules + heat_closure_delta_internal_consumption_megajoules, heat_closure_delta_storage_megajoules, heat_closure_delta_input_megajoules, heat_closure_delta_output_megajoules, heat_closure_delta_internal_production_megajoules, heat_closure_delta_internal_consumption_megajoules });
        advance_context.heat_closure_previous_storage_megajoules.* = heat_closure_totals.heat_storage_megajoules;
        advance_context.heat_closure_previous_cumulative_input_megajoules.* = heat_closure_boundary.heat_input_megajoules;
        advance_context.heat_closure_previous_cumulative_output_megajoules.* = heat_closure_boundary.heat_output_megajoules;
        advance_context.heat_closure_previous_cumulative_internal_production_megajoules.* = heat_closure_totals.cumulative_internal_heat_production_megajoules;
        advance_context.heat_closure_previous_cumulative_internal_consumption_megajoules.* = heat_closure_totals.cumulative_internal_heat_consumption_megajoules;
        const ion_deviation = try driver_context.landscape_mass_balance_state.*.monitor.?.deviation(heat_closure_totals);
        std.log.debug("hourly ion inventory trace: hour={d} ion_inventory_mol={e} cumulative_ion_input_mol={e} cumulative_ion_output_mol={e} ions_mol_m2={e}", .{ advance_context.scene_weather_hours.* + 1, heat_closure_totals.ion_inventory_mol, heat_closure_totals.cumulative_ion_input_mol, heat_closure_totals.cumulative_ion_output_mol, ion_deviation.ions_mol_m2 });
        const ion_subcomponents = try ecosys.landscape_mass_inventory.debugIonSubcomponents(
            driver_context.hourly_science_context.*.grid,
            driver_context.hourly_science_context.*.micropore_solute_state,
            driver_context.hourly_science_context.*.macropore_solute_state,
            driver_context.hourly_science_context.*.soil_chemistry,
            driver_context.hourly_science_context.*.mineral_fertilizer_inventory,
            driver_context.hourly_science_context.*.grid.matrix_liquid_water_m3,
            driver_context.hourly_science_context.*.landscape_soil_mass_megagrams_scratch,
            driver_context.hourly_science_context.*.fertilizer_band,
        );
        std.log.debug("hourly ion subcomponent trace: hour={d} dissolved_aqueous_mol={e} immobile_phosphate_ion_mol={e} cation_exchange_mol={e} geochemistry_solids_mol={e} pending_fertilizer_ion_mol={e}", .{ advance_context.scene_weather_hours.* + 1, ion_subcomponents.dissolved_aqueous_mol, ion_subcomponents.immobile_phosphate_ion_mol, ion_subcomponents.cation_exchange_mol, ion_subcomponents.geochemistry_solids_mol, ion_subcomponents.pending_fertilizer_ion_mol });
        const per_species = try ecosys.landscape_mass_inventory.debugDissolvedAqueousPerSpecies(driver_context.hourly_science_context.*.grid, driver_context.hourly_science_context.*.micropore_solute_state, driver_context.hourly_science_context.*.macropore_solute_state);
        inline for (@typeInfo(ecosys.solute_transport_species.AqueousSpecies).@"enum".fields) |field| if (per_species[field.value] != 0)
            std.log.debug("hourly dissolved-aqueous per-species trace: hour={d} species={s} mol={e}", .{ advance_context.scene_weather_hours.* + 1, field.name, per_species[field.value] });
    }
    const completed_day_timestamp = advance_context.previous_weather_timestamp.*;
    advance_context.previous_weather_timestamp.* = accept_context.timestamp.*;
    advance_context.scene_weather_hours.* = try std.math.add(usize, advance_context.scene_weather_hours.*, 1);
    driver_context.executed_weather_hours.* = try std.math.add(usize, driver_context.executed_weather_hours.*, 1);
    // HOUR1 freezes the complete R*X competition history only after this
    // external hour is scientifically accepted. Failed attempts and recovery
    // substeps therefore cannot leak next-hour allocation history.
    if (driver_context.plant_root_state.*) |*roots|
        roots.publishAcceptedNutrientDemandHistory();
    try driver_context.soil_nutrient_competition_attempt.*.publishAccepted(
        driver_context.soil_nutrient_competition_history,
        driver_context.soil_reactive_nitrogen_state,
        driver_context.soil_microbial_phosphorus_state,
    );
    accept_context.outer_hour_soil_gas_transport_transaction.*.commit();
    accept_context.outer_hour_carbon_exchange_transaction.*.commit();
    accept_context.outer_hour_transaction.*.commit();
    if (timeline_state.execution_journal) |journal| try journal.commit();
    const accepted_output_context = .{
        .active_options = &advance_context.active_options.*,
        .completed_day_timestamp = &completed_day_timestamp,
        .current_day_of_year = &accept_context.current_day_of_year.*,
        .current_year = &accept_context.current_year.*,
        .management_date = &accept_context.management_date.*,
        .pass = &advance_context.pass.*,
        .scene = &advance_context.scene.*,
        .scene_expected_hours = &advance_context.scene_expected_hours.*,
        .scene_weather_hours = &advance_context.scene_weather_hours.*,
        .timestamp = &accept_context.timestamp.*,
    };
    try writeAcceptedHourOutputs(driver_context, timeline_state, &accepted_output_context);
    if (timeline_state.execution_journal) |journal| try journal.accept();
}

/// Prepares irrigation, calendars, material caches, hourly ledgers, and the
/// plant conservation snapshot immediately before hourly science.
noinline fn prepareHourlyScience(driver_context: anytype, timeline_state: *TimelineState, advance_context: anytype, prepare_context: anytype) !void {
    if (prepare_context.begins_day.* and driver_context.irrigation_schedule_maps.*[advance_context.pass.*.scene_index] != null) {
        @memset(driver_context.minimum_canopy_water_potential_mpa_by_cell.*, 0);
        try ecosys.plant_water_balance.publishFirstPlantDailyMinimumByCell(&driver_context.detailed_canopy_state.*.?, driver_context.minimum_canopy_water_potential_mpa_by_cell.*);
        _ = try ecosys.irrigation_management_dispatch.planAutomatedDay(
            driver_context.irrigation_schedule_maps.*[advance_context.pass.*.scene_index].?,
            driver_context.irrigation_catalog.*,
            .{
                .date = prepare_context.management_date.*,
                .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
                .active_layer_count = driver_context.state.*.active_soil_layer_count,
                .soil_layer_capacity = driver_context.state.*.soil_layer_capacity,
                .layer_thickness_m = driver_context.soil_solver_property_state.*.layer_thickness_m,
                .porosity_fraction = driver_context.soil_solver_property_state.*.porosity_fraction,
                .field_capacity_fraction = driver_context.soil_field_capacity_fraction.*,
                .wilting_point_fraction = driver_context.soil_wilting_point_fraction.*,
                .liquid_water_m3 = driver_context.state.*.liquid_water_m3,
                .ice_water_m3 = driver_context.state.*.ice_water_m3,
                .minimum_canopy_water_potential_megapascal = driver_context.minimum_canopy_water_potential_mpa_by_cell.*,
            },
            driver_context.automatic_irrigation_depth_m_by_cell_hour.*,
        );
    }
    if (prepare_context.begins_day.* and driver_context.detailed_canopy_state.* != null) ecosys.plant_water_balance.resetDailyMinimumCanopyWaterPotential(&driver_context.detailed_canopy_state.*.?);
    @memset(driver_context.irrigation_water_depth_m.*, 0);
    @memset(driver_context.irrigation_dissolved_mass_g_per_m2.*, 0);
    @memset(driver_context.irrigation_hydrogen_mol_per_m2.*, 0);
    driver_context.irrigation_loads.*.reset();
    // The hourly boundary has resolved READS endpoints to their owning day
    // and source hour 1..24. Scheduled and automatic irrigation use that same
    // domain (day.f:407); adding one would delay every event and reject 24.
    const irrigation_source_hour: u8 = try prepare_context.timestamp.*.modelHourIndex() + 1;
    if (driver_context.irrigation_schedule_maps.*[advance_context.pass.*.scene_index]) |irrigation_map| {
        _ = try ecosys.irrigation_management_dispatch.accumulateScheduledHourRouted(
            irrigation_map,
            driver_context.irrigation_catalog.*,
            prepare_context.management_date.*,
            irrigation_source_hour,
            .{
                .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
                .active_layer_count = driver_context.state.*.active_soil_layer_count,
                .layer_thickness_m = driver_context.soil_solver_property_state.*.layer_thickness_m,
                .loads = &driver_context.irrigation_loads.*,
            },
        );
        _ = try ecosys.irrigation_management_dispatch.accumulatePlannedAutomatedHourRouted(
            irrigation_map,
            driver_context.irrigation_catalog.*,
            irrigation_source_hour,
            driver_context.automatic_irrigation_depth_m_by_cell_hour.*,
            .{
                .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
                .active_layer_count = driver_context.state.*.active_soil_layer_count,
                .layer_thickness_m = driver_context.soil_solver_property_state.*.layer_thickness_m,
                .loads = &driver_context.irrigation_loads.*,
            },
        );
    }
    // WTHR TDIRI scales the entire accepted irrigation event,
    // including its dissolved carriers, exactly once.
    try driver_context.irrigation_loads.*.scale(try timeline_state.climate_state.irrigationMultiplier(
        advance_context.active_options.*,
        prepare_context.current_day_of_year.*,
    ));
    for (0..driver_context.state.*.cell_count) |cell| {
        const area_m2 = driver_context.canopy_cell_area_m2.*[cell];
        if (!std.math.isFinite(area_m2) or area_m2 <= 0)
            return error.InvalidIrrigationCellArea;
        driver_context.irrigation_water_depth_m.*[cell] =
            driver_context.irrigation_loads.*.surface_water_m3[cell] / area_m2;
        driver_context.irrigation_hydrogen_mol_per_m2.*[cell] =
            driver_context.irrigation_loads.*.surface_hydrogen_mol[cell] / area_m2;
        const first = cell *
            ecosys.irrigation_management_dispatch.dissolved_species_count;
        for (0..ecosys.irrigation_management_dispatch.dissolved_species_count) |species|
            driver_context.irrigation_dissolved_mass_g_per_m2.*[first + species] =
                driver_context.irrigation_loads.*.surface_dissolved_mass_g[first + species] /
                area_m2;
    }
    const previous_day_of_year: u16 = if (prepare_context.current_day_of_year.* > 1) prepare_context.current_day_of_year.* - 1 else ecosys.climate_change.daysInYear(prepare_context.current_year.* -| 1);
    for (driver_context.plant_calendar_by_cell.*, 0..) |*calendar, cell| {
        const current_daylength_h = ecosys.daily_weather_disaggregation.calculateDaylength(prepare_context.current_day_of_year.*, driver_context.latitude_degrees_north_by_cell.*[cell]);
        const previous_daylength_h = ecosys.daily_weather_disaggregation.calculateDaylength(previous_day_of_year, driver_context.latitude_degrees_north_by_cell.*[cell]);
        const solstice_day: u16 = if (driver_context.latitude_degrees_north_by_cell.*[cell] >= 0) 173 else 355;
        const maximum_daylength_h = ecosys.daily_weather_disaggregation.calculateDaylength(solstice_day, driver_context.latitude_degrees_north_by_cell.*[cell]);
        calendar.* = .{
            .day_of_year = prepare_context.current_day_of_year.*,
            .current_year = prepare_context.current_year.*,
            .current_daylength_h = current_daylength_h,
            .previous_daylength_h = previous_daylength_h,
            .maximum_seasonal_daylength_h = maximum_daylength_h,
            .latitude_degrees_north = driver_context.latitude_degrees_north_by_cell.*[cell],
        };
    }
    // HOUR1 2348--2356: refresh current external tables from
    // persistent references and the live REDIST surface datum
    // before WATSUB assembles this hour's boundary fluxes.
    try driver_context.soil_boundary_topology_state.*.refreshExternalWaterTables(&driver_context.soil_geometry_state.*);
    driver_context.organic_matter_fire_exchange_state.*.resetHourly();
    driver_context.surface_fire_exchange_state.*.resetHourly();
    @memset(driver_context.shoot_harvest_litter_carbon_g_c_by_plant.*, 0);
    @memset(driver_context.shoot_harvest_litter_nitrogen_g_n_by_plant.*, 0);
    @memset(driver_context.shoot_harvest_litter_phosphorus_g_p_by_plant.*, 0);
    @memset(driver_context.hourly_manure_products_by_plant.*, .{});
    @memcpy(
        driver_context.harvest_carbon_at_hour_start_g_c_by_plant.*,
        driver_context.plant_daily_flux_ledger.*.harvested_carbon_g,
    );
    @memcpy(
        driver_context.harvest_salt_at_hour_start_mol_by_plant_species.*,
        driver_context.cumulative_harvest_salt_mol_by_plant.*,
    );
    // The scheduled planting/reconstruction phase above is the
    // lifecycle boundary that establishes a plant's initial seed
    // and standing-dead condition. Snapshot every authoritative
    // C/N/P pool and annual boundary owner after that boundary,
    // but before any hourly plant science. Failed hours restore
    // those owners through the surrounding outer transaction.
    if (driver_context.detailed_canopy_state.* != null or driver_context.plant_root_state.* != null) {
        const canopy = if (driver_context.detailed_canopy_state.*) |*value| value else return error.PlantConservationRequiresCompleteState;
        const roots = if (driver_context.plant_root_state.*) |*value| value else return error.PlantConservationRequiresCompleteState;
        try assemblePlantBalanceInputs(
            canopy,
            roots,
            driver_context.root_metabolism_plant_parameters.*,
            &driver_context.plant_daily_flux_ledger.*,
            driver_context.plant_conservation_scope_enabled.*,
            driver_context.plant_balance_carbon_inputs_workspace.*,
            driver_context.plant_balance_nitrogen_inputs_workspace.*,
            driver_context.plant_balance_phosphorus_inputs_workspace.*,
            driver_context.plant_balance_carbon_root_by_layer.*,
            driver_context.plant_balance_carbon_root_length_density_by_layer.*,
            driver_context.plant_balance_nutrient_root_by_layer.*,
        );
        for (0..driver_context.runtime_plant_count.*) |plant| {
            const inventory = try ecosys.plant_daily_flux_ledger
                .ElementalInventory.fromBalanceInputs(
                driver_context.plant_balance_carbon_inputs_workspace.*[plant],
                driver_context.plant_balance_nitrogen_inputs_workspace.*[plant],
                driver_context.plant_balance_phosphorus_inputs_workspace.*[plant],
                .{
                    // GROSUB 12147: Zig keeps WTSTDG(5) separate
                    // from the four ordinary standing-dead kinetics.
                    .carbon_g = canopy.plant_charcoal_carbon_g[plant],
                    .nitrogen_g = canopy.plant_charcoal_nitrogen_g[plant],
                    .phosphorus_g = canopy.plant_charcoal_phosphorus_g[plant],
                },
            );
            driver_context.plant_conservation_hour_start.*[plant] =
                try ecosys.plant_daily_flux_ledger.AcceptedHourSnapshot
                    .capture(&driver_context.plant_daily_flux_ledger.*, plant, inventory);
        }
    }
}

noinline fn prepareAcceptedHourStorageAndLedgers(driver_context: anytype, advance_context: anytype) !void {
    @memset(driver_context.fire_active_this_hour.*, false);
    @memset(driver_context.deferred_tillage_soil_by_cell.*, .{});
    @memset(driver_context.symbiotic_inoculum_input_by_cell.*, .{
        .carbon_g_c = 0,
        .nitrogen_g_n = 0,
        .phosphorus_g_p = 0,
    });
    // WTHR 548--561 constructs ICHKF before HFUNC/GROSUB from the
    // prior accepted TKS/TKQ state, then ORs that temperature event
    // with the scheduled ITILL=22 fire at solar noon. Derive the
    // temperature half before pre-science management so both
    // producers suppress same-hour symbiont infection and reach
    // every later fire consumer through one rollbackable flag.
    try ecosys.disturbance_management_dispatch.mergeWthrTemperatureFireFlags(
        driver_context.fire_active_this_hour.*,
        .{
            .surface_temperature_k = driver_context.state.*.surface_temperature_k,
            .soil_temperature_k = driver_context.state.*.soil_temperature_k,
            .canopy_bulk_air_temperature_k = driver_context.atmospheric_canopy_gas_state.*.bulk_temperature_k,
            .first_active_soil_layer_by_cell = driver_context.soil_geometry_state.*.first_active_layer,
            .active_soil_layer_count_by_cell = driver_context.soil_geometry_state.*.active_layer_count,
            .soil_layer_capacity = driver_context.state.*.soil_layer_capacity,
        },
    );
    // HOUR1 3656--3715: accepted prior-hour tillage, erosion and
    // organic changes become constitutive soil material at the
    // next fixed one-hour boundary. The refresh stages every
    // owner first, so an invalid capacity or refit leaves zero
    // side effects.
    if (driver_context.executed_weather_hours.* != 0) {
        _ = try ecosys.soil_runtime_material_refresh.refreshAcceptedHour(&.{
            .allocator = driver_context.allocator.*,
            .grid = &driver_context.state.*,
            .geometry = &driver_context.soil_geometry_state.*,
            .soil_organic = &driver_context.soil_organic_state.*,
            .properties = &driver_context.soil_solver_property_state.*,
            .thermal = &driver_context.soil_thermal_state.*,
            .parameters = driver_context.runscript.*.soil_solver_parameters,
            .maximum_iterations = advance_context.active_iteration_limits.*.hard_max_iterations,
            .ice_density_megagrams_per_m3 = driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.ice_density_megagrams_per_m3,
            .cation_exchange_capacity_delta_mol_by_cell = driver_context.charcoal_cation_exchange_capacity_delta_mol_by_cell.*,
            .anion_exchange_capacity_delta_mol_by_cell = driver_context.charcoal_anion_exchange_capacity_delta_mol_by_cell.*,
            .cation_exchange_capacity_delta_mol_by_layer = driver_context.charcoal_cation_exchange_capacity_delta_mol_by_layer.*,
            .anion_exchange_capacity_delta_mol_by_layer = driver_context.charcoal_anion_exchange_capacity_delta_mol_by_layer.*,
        });
    }
    // Refresh changes only derived material/air-property caches;
    // capture the authoritative storage control volumes before
    // any current-hour reset, management or science mutation.
    try diagnostics.reconstructLayerMassBalanceScopes(
        driver_context.hourly_science_context.*,
        driver_context.layer_conservation_layout.*,
        driver_context.hourly_layer_storage_before.*,
        driver_context.hourly_cell_storage_before.*,
    );
    // The HOUR1 refresh has already committed signed DORGCC
    // exchange-site creation/loss. Reconstruct the pre-refresh
    // storage side here and book the same signed extensive delta
    // below as an internal process, never a fertilizer boundary.
    for (0..driver_context.state.*.cell_count) |cell| {
        driver_context.hourly_cell_storage_before.*[cell].cation_exchange_capacity_mol -=
            driver_context.charcoal_cation_exchange_capacity_delta_mol_by_cell.*[cell];
        driver_context.hourly_cell_storage_before.*[cell].anion_exchange_capacity_mol -=
            driver_context.charcoal_anion_exchange_capacity_delta_mol_by_cell.*[cell];
    }
    for (0..driver_context.state.*.layer_count) |flat_layer| {
        const cell = flat_layer / driver_context.state.*.soil_layer_capacity;
        const layer = flat_layer % driver_context.state.*.soil_layer_capacity;
        const scope = try driver_context.layer_conservation_layout.*.index(.{
            .kind = .soil_layer,
            .cell = cell,
            .layer = layer,
        });
        driver_context.hourly_layer_storage_before.*[scope].cation_exchange_capacity_mol -=
            driver_context.charcoal_cation_exchange_capacity_delta_mol_by_layer.*[flat_layer];
        driver_context.hourly_layer_storage_before.*[scope].anion_exchange_capacity_mol -=
            driver_context.charcoal_anion_exchange_capacity_delta_mol_by_layer.*[flat_layer];
    }
    try ecosys.layer_mass_inventory.requireExactCellPartition(
        driver_context.layer_conservation_layout.*,
        driver_context.hourly_layer_storage_before.*,
        driver_context.hourly_cell_storage_before.*,
    );
    // Zero-free-parameter diagnostic for the surface heat gap. The census
    // prices surface enthalpy from exactly five inputs
    // (`landscape_mass_inventory_surface.zig:499-533`), so snapshot them where
    // hour-start storage is established and print them beside their
    // end-of-hour values on a heat failure. Differencing the two sets names
    // whichever input moved without a matching booking.
    //
    // This exists because TWO diagnoses of that gap were retracted for
    // inverting the residual for a free parameter instead of measuring: see
    // the retractions of
    // `SURFACE-RESPIRATION-CHANGES-THE-HEAT-CAPACITY-AND-NOTHING-BOOKS-IT-012`.
    // The carbon carrier is eliminated; water, vapour, ice and temperature are
    // not, and this reads all five so no further guess is needed.
    if (driver_context.state.*.cell_count > 0) {
        const science = driver_context.hourly_science_context.*;
        const inputs = science.diagnostic_surface_census_inputs_at_hour_start;
        inputs.*[0] = try science.surface_organic.totalCarbon_g_c(0);
        inputs.*[1] = science.surface_precipitation.litter_water_m3[0];
        inputs.*[2] = science.litter_gas_transport.water_vapor_mol[0];
        inputs.*[3] = science.surface_litter_ice_m3[0];
        inputs.*[4] = science.grid.surface_temperature_k[0];
        // The interface-rebase drift probe accumulates across substeps, so it
        // must start each hour empty, with `previous_temperature` seeded to this
        // hour's opening surface temperature rather than 0 -- otherwise the
        // first substep's `dT` would be the whole absolute temperature.
        const drift = science.diagnostic_litter_soil_rebase_drift;
        drift.*[0] = 0;
        drift.*[1] = 0;
        drift.*[2] = 0;
        drift.*[3] = science.grid.surface_temperature_k[0];
        drift.*[4] = 0;
    }
    // HOUR1 clears hourly plant ledgers before GROSUB management.
    // Management dispatch below may publish disturbance, harvest,
    // or combustion fluxes that must survive into this hour's
    // HCNET and output aggregation.
    driver_context.soil_nutrient_competition_attempt.*.begin();
    if (driver_context.plant_root_state.*) |*roots| roots.resetHourlyFluxes();
    if (driver_context.canopy_carbon_exchange_state.*) |*ledger| ledger.reset();
    for (driver_context.hourly_accumulators.*) |*acc| ecosys.hourly_grid_cell_accumulator_reset.reset(acc);
    // Per-cell conservation activity is scoped to exactly one
    // fixed external hour. Reset before management so every
    // producer in this hour contributes once and no partial
    // diagnostic activity can leak into the next hour.
    driver_context.hourly_cell_boundary_ledger.*.reset();
    driver_context.hourly_layer_boundary_ledger.*.reset();
    for (0..driver_context.state.*.cell_count) |cell| {
        const cec_delta = driver_context.charcoal_cation_exchange_capacity_delta_mol_by_cell.*[cell];
        const aec_delta = driver_context.charcoal_anion_exchange_capacity_delta_mol_by_cell.*[cell];
        if (!std.math.isFinite(cec_delta) or !std.math.isFinite(aec_delta))
            return error.InvalidCharcoalExchangeCapacityChange;
        try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, .{
            .cation_exchange_capacity_internal_production_mol = @max(cec_delta, 0),
            .cation_exchange_capacity_internal_consumption_mol = @max(-cec_delta, 0),
            .anion_exchange_capacity_internal_production_mol = @max(aec_delta, 0),
            .anion_exchange_capacity_internal_consumption_mol = @max(-aec_delta, 0),
        });
    }
    for (0..driver_context.state.*.layer_count) |flat_layer| {
        const cec_delta = driver_context.charcoal_cation_exchange_capacity_delta_mol_by_layer.*[flat_layer];
        const aec_delta = driver_context.charcoal_anion_exchange_capacity_delta_mol_by_layer.*[flat_layer];
        if (!std.math.isFinite(cec_delta) or !std.math.isFinite(aec_delta))
            return error.InvalidCharcoalExchangeCapacityChange;
        try driver_context.hourly_layer_boundary_ledger.*.accumulate(.{
            .kind = .soil_layer,
            .cell = flat_layer / driver_context.state.*.soil_layer_capacity,
            .layer = flat_layer % driver_context.state.*.soil_layer_capacity,
        }, .{
            .cation_exchange_capacity_internal_production_mol = @max(cec_delta, 0),
            .cation_exchange_capacity_internal_consumption_mol = @max(-cec_delta, 0),
            .anion_exchange_capacity_internal_production_mol = @max(aec_delta, 0),
            .anion_exchange_capacity_internal_consumption_mol = @max(-aec_delta, 0),
        });
    }
    // HOUR1 3371 clears the accepted TBH2O water-equilibrium
    // ledgers once at the fixed external-hour boundary. Surface
    // chemistry may legitimately run again after same-hour fire;
    // that accepted projection must accumulate instead of erasing
    // the earlier litter projection. Both owners are inside the
    // outer-hour transaction, so failed attempts roll this reset
    // and every later publication back atomically.
    driver_context.initial_chemistry_state.*.resetWaterEquilibriumBalanceHourly();
    driver_context.surface_litter_chemistry_state.*.resetWaterEquilibriumBalanceHourly();
}

const HourIdentity = struct {
    timestamp: ecosys.weather.Timestamp,
    current_year: u16,
    current_day_of_year: u16,
    begins_day: bool,
};

noinline fn resolveHourIdentity(
    driver_context: anytype,
    advance_context: anytype,
    timestamp: ecosys.weather.Timestamp,
) !HourIdentity {
    const current_year = timestamp.year.?;
    const current_day_of_year = try dayOfYearFromTimestamp(timestamp);
    if (advance_context.resolved_development_year.* == null or advance_context.resolved_development_year.*.? != current_year) {
        for (driver_context.development_planting_dates.*, 0..) |date, plant| {
            const resolved = try date.resolve(current_year);
            driver_context.development_planting_day_of_year.*[plant] = try date.dayOfYear(current_year);
            driver_context.development_planting_year.*[plant] = resolved.year;
        }
        advance_context.resolved_development_year.* = current_year;
    }
    const begins_day = if (advance_context.previous_weather_timestamp.*) |previous| !sameCalendarDay(previous, timestamp) else true;
    return .{
        .timestamp = timestamp,
        .current_year = current_year,
        .current_day_of_year = current_day_of_year,
        .begins_day = begins_day,
    };
}

noinline fn advancePlantLifecycleManagement(
    driver_context: anytype,
    hour: *const HourIdentity,
) !void {
    const timestamp = hour.timestamp;
    if (driver_context.management_schedule_map.* != null) {
        const management_date = try ecosys.plant_management_dispatch.dateFromTimestamp(timestamp);
        if (driver_context.plant_phenology_state.* != null and driver_context.plant_growth_stage_state.* != null) {
            const lifecycle_canopy = if (driver_context.detailed_canopy_state.*) |*value| value else return error.PlantLifecycleConservationRequiresCompleteState;
            const lifecycle_roots = if (driver_context.plant_root_state.*) |*value| value else return error.PlantLifecycleConservationRequiresCompleteState;
            @memcpy(driver_context.plant_lifecycle_initialized_before.*, driver_context.plant_phenology_state.*.?.lifecycle_initialized);
            @memset(driver_context.plant_lifecycle_external_input.*, .{});
            try assemblePlantBalanceInputs(
                lifecycle_canopy,
                lifecycle_roots,
                driver_context.root_metabolism_plant_parameters.*,
                &driver_context.plant_daily_flux_ledger.*,
                driver_context.plant_conservation_scope_enabled.*,
                driver_context.plant_balance_carbon_inputs_workspace.*,
                driver_context.plant_balance_nitrogen_inputs_workspace.*,
                driver_context.plant_balance_phosphorus_inputs_workspace.*,
                driver_context.plant_balance_carbon_root_by_layer.*,
                driver_context.plant_balance_carbon_root_length_density_by_layer.*,
                driver_context.plant_balance_nutrient_root_by_layer.*,
            );
            for (0..driver_context.runtime_plant_count.*) |plant| {
                driver_context.plant_lifecycle_inventory_before.*[plant] =
                    try ecosys.plant_daily_flux_ledger.ElementalInventory.fromBalanceInputs(
                        driver_context.plant_balance_carbon_inputs_workspace.*[plant],
                        driver_context.plant_balance_nitrogen_inputs_workspace.*[plant],
                        driver_context.plant_balance_phosphorus_inputs_workspace.*[plant],
                        .{
                            .carbon_g = lifecycle_canopy.plant_charcoal_carbon_g[plant],
                            .nitrogen_g = lifecycle_canopy.plant_charcoal_nitrogen_g[plant],
                            .phosphorus_g = lifecycle_canopy.plant_charcoal_phosphorus_g[plant],
                        },
                    );
            }
            const activation_count = try ecosys.plant_management_dispatch.refreshPlantActivity(driver_context.management_schedule_map.*.?, driver_context.plant_management_catalog.*, management_date, &driver_context.plant_phenology_state.*.?, &driver_context.plant_growth_stage_state.*.?, driver_context.plant_phenology_state.*.?.emerged, driver_context.plant_phenology_state.*.?.lifecycle_initialized, driver_context.newly_activated_plants.*);
            if (activation_count > 0) {
                const assignments = driver_context.plant_assignments.* orelse return error.PlantActivationRequiresAssignments;
                var topology_changed = false;
                for (driver_context.newly_activated_plants.*, 0..) |activated, plant| {
                    if (!activated) continue;
                    const cell = plant / driver_context.config.*.plant_populations;
                    const species = plant % driver_context.config.*.plant_populations;
                    const unit_index = driver_context.plant_unit_by_cell.*.?[cell];
                    if (species >= assignments.units[unit_index].species.len) return error.PlantActivationSpeciesOutOfBounds;
                    const assignment = assignments.units[unit_index].species[species];
                    const traits = driver_context.plant_catalog.*.entries.items[driver_context.plant_catalog.*.find(assignment.species_file) orelse return error.MissingPlantTraitProfile].traits;
                    const planting = driver_context.plant_management_catalog.*.entries.items[driver_context.plant_management_catalog.*.find(assignment.management_file) orelse return error.MissingPlantManagementSchedule].schedule.planting;
                    var cumulative_depth_m: f64 = 0;
                    for (driver_context.replant_layer_bottom_depth_m.*, 0..) |*bottom, layer| {
                        cumulative_depth_m += driver_context.soil_solver_property_state.*.layer_thickness_m[cell * driver_context.config.*.soil_layers + layer];
                        bottom.* = cumulative_depth_m;
                    }
                    const planting_layer = try ecosys.plant_initialization.plantingLayer(planting.seed_depth_m, driver_context.replant_layer_bottom_depth_m.*);
                    const adjusted = try ecosys.plant_initialization.adjustedPhenology(traits, driver_context.runscript.*.phenology_initialization_parameters);
                    const concurrent = try ecosys.plant_initialization.concurrentNodeSettings(traits.functional_type.aboveground_turnover_type, adjusted.leaf_appearance_per_h, adjusted.floral_initiation_node_count_after_seed, driver_context.runscript.*.phenology_initialization_parameters);
                    const storage = try ecosys.plant_initialization.seedStorage(traits.morphology.seed_mass_at_planting_g, planting.population_per_m2, driver_context.canopy_cell_area_m2.*[cell], traits.organ_nitrogen_to_carbon_ratio.grain, traits.organ_phosphorus_to_carbon_ratio.grain);
                    const thermal = try ecosys.plant_initialization.thermalAcclimation(assignment.species_file, traits.functional_type.photosynthesis_pathway, traits.functional_type.thermal_adaptation_zone, driver_context.runscript.*.thermal_acclimation_parameters);
                    driver_context.plant_initial_thermal_adaptation_zone.*[plant] = traits.functional_type.thermal_adaptation_zone;
                    driver_context.plant_initial_photosynthesis_pathway.*[plant] = traits.functional_type.photosynthesis_pathway;
                    driver_context.plant_initial_floral_initiation_group.*[plant] = traits.phenology.floral_initiation_node_count;
                    driver_context.plant_seed_initial_node_number.*[plant] = adjusted.seed_initial_node_count;
                    const preserve_reseed_inventories = driver_context.plant_phenology_state.*.?.reseed_pending[plant];
                    // STARTQ creates WTSTDG and the static thermal
                    // defaults once. Every later planting retains
                    // live standing-dead/charcoal and the current
                    // WTHR mode-2 acclimation across topology reset.
                    const persistent_reseed_inventories =
                        try ecosys.canopy_photosynthesis.capturePersistentReseedInventories(&driver_context.detailed_canopy_state.*.?, plant);
                    const carried_standing_dead_surface_water_m3 = driver_context.canopy_precipitation_retention_state.*.?.standing_dead_surface_water_m3[plant];

                    const old_branch_range = try driver_context.detailed_canopy_state.*.?.branchRange(plant);
                    const old_node_range = try driver_context.detailed_canopy_state.*.?.nodeRange(old_branch_range.first);
                    topology_changed = topology_changed or old_branch_range.end - old_branch_range.first != 1 or old_node_range.end - old_node_range.first != 1;
                    try ecosys.plant_topology.compactPlantToInitialTopology(.{
                        .canopy = &driver_context.detailed_canopy_state.*.?,
                        .growth_stages = &driver_context.plant_growth_stage_state.*.?,
                        .dormancy = &driver_context.plant_dormancy_state.*.?,
                        .branch_development = &driver_context.branch_development_state.*.?,
                    }, plant);
                    try driver_context.detailed_canopy_state.*.?.clearPlantForReconstruction(plant);
                    try driver_context.plant_root_state.*.?.reconstructPlant(plant, traits, planting_layer, planting.seed_depth_m, driver_context.runscript.*.root_initialization_parameters);
                    const seed_geometry = try ecosys.plant_initialization.seedGeometry(traits.morphology.seed_mass_at_planting_g, driver_context.runscript.*.plant_geometry_parameters);
                    try driver_context.plant_root_state.*.?.setSeedGeometry(plant, seed_geometry.volume_m3, seed_geometry.length_m, seed_geometry.surface_area_m2);
                    try driver_context.plant_litter_partition_state.*.?.initializePlant(plant, traits, driver_context.runscript.*.standing_dead_partition_parameters);
                    const branch_range = try driver_context.plant_growth_stage_state.*.?.clearPlantForReconstruction(plant);
                    try driver_context.plant_dormancy_state.*.?.clearRangeForReconstruction(branch_range.first, branch_range.end);
                    try driver_context.branch_development_state.*.?.clearRangeForReconstruction(branch_range.first, branch_range.end);
                    const initial_branch_end = @min(branch_range.end, branch_range.first + 1);
                    try driver_context.branch_development_state.*.?.initializeRange(branch_range.first, initial_branch_end, driver_context.plant_topology_controls.*.initial_maturity_group[plant], adjusted.seed_initial_node_count, traits.functional_type.growth_habit == 0 and traits.functional_type.leaf_phenology_type == 1, concurrent.perennial_node_scaling, concurrent.maximum_concurrently_growing_nodes);
                    for (driver_context.plant_growth_stage_state.*.?.branches[initial_branch_end..branch_range.end]) |*branch| branch.dead = true;
                    driver_context.plant_phenology_state.*.?.floral_initiated[plant] = false;
                    driver_context.plant_phenology_state.*.?.node_initiation_rate_at_25c_per_h[plant] = adjusted.node_initiation_per_h;
                    driver_context.plant_phenology_state.*.?.leaf_appearance_rate_at_25c_per_h[plant] = adjusted.leaf_appearance_per_h;
                    driver_context.plant_phenology_state.*.?.initiated_node_count[plant] = adjusted.seed_initial_node_count;
                    driver_context.plant_phenology_state.*.?.appeared_leaf_count[plant] = adjusted.seed_initial_node_count;
                    driver_context.plant_phenology_state.*.?.node_initiation_per_timestep[plant] = 0;
                    driver_context.plant_phenology_state.*.?.leaf_appearance_per_timestep[plant] = 0;
                    if (branch_range.first < branch_range.end) {
                        driver_context.plant_growth_stage_state.*.?.branches[branch_range.first].initiated_node_count = adjusted.seed_initial_node_count;
                        driver_context.plant_growth_stage_state.*.?.branches[branch_range.first].appeared_leaf_count = adjusted.seed_initial_node_count;
                    }
                    try ecosys.plant_initialization.initializeShootControls(&driver_context.detailed_canopy_state.*.?, plant, planting.population_per_m2, driver_context.canopy_cell_area_m2.*[cell], traits.water_relations.cuticular_resistance_s_per_m, traits.functional_type.photosynthesis_pathway, driver_context.runscript.*.shoot_control_parameters);
                    try ecosys.plant_initialization.initializeThermalAcclimation(&driver_context.detailed_canopy_state.*.?, plant, thermal);
                    if (!preserve_reseed_inventories) {
                        try ecosys.plant_initialization.initializeSeedStorage(&driver_context.detailed_canopy_state.*.?, plant, storage);
                    }
                    const initialized_seed_storage = ecosys.canopy_photosynthesis.ElementalMass{
                        .carbon_g = driver_context.detailed_canopy_state.*.?.plant_seed_storage_carbon_g[plant],
                        .nitrogen_g = driver_context.detailed_canopy_state.*.?.plant_seed_storage_nitrogen_g[plant],
                        .phosphorus_g = driver_context.detailed_canopy_state.*.?.plant_seed_storage_phosphorus_g[plant],
                    };
                    // Seed is an external planting input only after
                    // the initial condition. Self-reseeded storage
                    // is internal carryover. WTSTDG is never a
                    // recurring input (STARTQ 679; GROSUB only
                    // transfers/adds/removes/decays it).
                    driver_context.plant_lifecycle_external_input.*[plant] = if (!driver_context.plant_lifecycle_initialized_before.*[plant] or preserve_reseed_inventories)
                        .{}
                    else
                        .{
                            .carbon_g = storage.carbon_g,
                            .nitrogen_g = storage.nitrogen_g,
                            .phosphorus_g = storage.phosphorus_g,
                        };
                    try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, .{
                        .carbon_input_g = driver_context.plant_lifecycle_external_input.*[plant].carbon_g,
                        .nitrogen_input_g = driver_context.plant_lifecycle_external_input.*[plant].nitrogen_g,
                        .phosphorus_input_g = driver_context.plant_lifecycle_external_input.*[plant].phosphorus_g,
                    });
                    try ecosys.plant_initialization.initializePlantHeatAndWater(&driver_context.plant_state.*, &driver_context.detailed_canopy_state.*.?, plant, driver_context.mean_annual_temperature_c_by_cell.*[cell], traits.water_relations.osmotic_potential_megapascal, driver_context.runscript.*.plant_heat_water_parameters);
                    try ecosys.canopy_photosynthesis.restorePersistentReseedInventories(&driver_context.detailed_canopy_state.*.?, plant, persistent_reseed_inventories);
                    if (!preserve_reseed_inventories) {
                        driver_context.detailed_canopy_state.*.?.plant_seed_storage_carbon_g[plant] = initialized_seed_storage.carbon_g;
                        driver_context.detailed_canopy_state.*.?.plant_seed_storage_nitrogen_g[plant] = initialized_seed_storage.nitrogen_g;
                        driver_context.detailed_canopy_state.*.?.plant_seed_storage_phosphorus_g[plant] = initialized_seed_storage.phosphorus_g;
                    }
                    driver_context.plant_phenology_state.*.?.reseed_pending[plant] = false;
                    driver_context.plant_phenology_state.*.?.death_replant_pending[plant] = false;
                    driver_context.plant_state.*.canopy_water_storage_m_per_m2[plant] = 0;
                    driver_context.plant_state.*.leaf_area_index_m2_m2[plant] = 0;
                    driver_context.plant_state.*.shoot_carbon_g_m2[plant] = 0;
                    @memset(driver_context.plant_state.*.root_carbon_g_m2[plant * driver_context.config.*.soil_layers .. (plant + 1) * driver_context.config.*.soil_layers], 0);
                    const retention_state = &driver_context.canopy_precipitation_retention_state.*.?;
                    inline for (@typeInfo(ecosys.canopy_precipitation_retention.State).@"struct".fields) |field| {
                        if (field.type == []f64 and !std.mem.startsWith(u8, field.name, "cell_")) @field(retention_state, field.name)[plant] = 0;
                    }
                    retention_state.standing_dead_surface_water_m3[plant] = carried_standing_dead_surface_water_m3;
                }
                if (topology_changed) {
                    var replacement_layers = try ecosys.canopy_layer_distribution.State.init(driver_context.allocator.*, driver_context.state.*.cell_count, driver_context.config.*.plant_populations, driver_context.runscript.*.canopy_layer_count, driver_context.canopy_geometry.*.leaf_inclination_sine.len, driver_context.canopy_geometry.*.leaf_azimuth_radians.len, &driver_context.detailed_canopy_state.*.?);
                    const replacement_carbon_exchange = ecosys.canopy_carbon_exchange.State.init(driver_context.allocator.*, driver_context.detailed_canopy_state.*.?.branch_node_offsets.len - 1) catch |err| {
                        replacement_layers.deinit();
                        return err;
                    };
                    var previous_carbon_exchange = driver_context.canopy_carbon_exchange_state.*.?;
                    driver_context.canopy_carbon_exchange_state.*.? = replacement_carbon_exchange;
                    previous_carbon_exchange.deinit();
                    var previous_layers = driver_context.canopy_layer_distribution_state.*.?;
                    driver_context.canopy_layer_distribution_state.*.? = replacement_layers;
                    previous_layers.deinit();
                }
                try assemblePlantBalanceInputs(
                    &driver_context.detailed_canopy_state.*.?,
                    &driver_context.plant_root_state.*.?,
                    driver_context.root_metabolism_plant_parameters.*,
                    &driver_context.plant_daily_flux_ledger.*,
                    driver_context.plant_conservation_scope_enabled.*,
                    driver_context.plant_balance_carbon_inputs_workspace.*,
                    driver_context.plant_balance_nitrogen_inputs_workspace.*,
                    driver_context.plant_balance_phosphorus_inputs_workspace.*,
                    driver_context.plant_balance_carbon_root_by_layer.*,
                    driver_context.plant_balance_carbon_root_length_density_by_layer.*,
                    driver_context.plant_balance_nutrient_root_by_layer.*,
                );
                for (driver_context.newly_activated_plants.*, 0..) |activated, plant| {
                    if (!activated) continue;
                    const inventory_after = try ecosys.plant_daily_flux_ledger.ElementalInventory.fromBalanceInputs(
                        driver_context.plant_balance_carbon_inputs_workspace.*[plant],
                        driver_context.plant_balance_nitrogen_inputs_workspace.*[plant],
                        driver_context.plant_balance_phosphorus_inputs_workspace.*[plant],
                        .{
                            .carbon_g = driver_context.detailed_canopy_state.*.?.plant_charcoal_carbon_g[plant],
                            .nitrogen_g = driver_context.detailed_canopy_state.*.?.plant_charcoal_nitrogen_g[plant],
                            .phosphorus_g = driver_context.detailed_canopy_state.*.?.plant_charcoal_phosphorus_g[plant],
                        },
                    );
                    const cell = plant / driver_context.config.*.plant_populations;
                    const report = try ecosys.plant_daily_flux_ledger.evaluateLifecycleBoundary(
                        driver_context.plant_lifecycle_inventory_before.*[plant],
                        inventory_after,
                        driver_context.plant_lifecycle_external_input.*[plant],
                        driver_context.canopy_cell_area_m2.*[cell],
                        .{
                            .absolute_per_area = driver_context.config.*.mass_balance_absolute_tolerance,
                            .relative = driver_context.config.*.mass_balance_relative_tolerance,
                        },
                    );
                    try ecosys.plant_daily_flux_ledger.requireLifecycleAccepted(report, plant);
                    try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, .{
                        .carbon_input_g = driver_context.plant_lifecycle_external_input.*[plant].carbon_g,
                        .nitrogen_input_g = driver_context.plant_lifecycle_external_input.*[plant].nitrogen_g,
                        .phosphorus_input_g = driver_context.plant_lifecycle_external_input.*[plant].phosphorus_g,
                    });
                }
                if (driver_context.harvest_context.* != null) for (0..driver_context.runtime_plant_count.*) |plant| {
                    const exported = try ecosys.plant_harvest_runtime.publishPlantProducts(&driver_context.harvest_context.*.?, plant);
                    const harvest_activity: ecosys.hourly_cell_conservation.BoundaryActivity = .{
                        .carbon_output_g = exported.carbon_g,
                        .nitrogen_output_g = exported.nitrogen_g,
                        .phosphorus_output_g = exported.phosphorus_g,
                    };
                    const cell = plant / driver_context.config.*.plant_populations;
                    try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, harvest_activity);
                    try ecosys.layer_local_conservation.accumulateCanopyHarvest(
                        &driver_context.hourly_layer_boundary_ledger.*,
                        cell,
                        exported.carbon_g,
                        exported.nitrogen_g,
                        exported.phosphorus_g,
                    );
                    try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, harvest_activity);
                    try driver_context.plant_daily_flux_ledger.*.accumulateHarvest(plant, exported.carbon_g, exported.nitrogen_g, exported.phosphorus_g);
                };
            }
        }
    }
}

test "lime-only production management closes the landscape carbon boundary" {
    try @import("driver/fertilizer_production_fixture.zig").verifyLimeOnly(advanceFertilizerManagement, HourIdentity);
}

test "gypsum-only production management records real mineral input without carbon" {
    try @import("driver/fertilizer_production_fixture.zig").verifyGypsumOnly(advanceFertilizerManagement, HourIdentity);
}

test "organic fertilizer production management credits physical carbon once" {
    try @import("driver/fertilizer_production_fixture.zig").verifyOrganic(advanceFertilizerManagement, HourIdentity);
}

noinline fn advanceFertilizerManagement(
    driver_context: anytype,
    advance_context: anytype,
    hour: *const HourIdentity,
) !void {
    const timestamp = hour.timestamp;
    if (driver_context.fertilizer_schedule_maps.*[advance_context.pass.*.scene_index] != null) {
        const fertilizer_source_hour =
            try ecosys.fertilizer_management_dispatch.sourceHourOneThroughTwentyFour(
                try timestamp.modelClockHour(),
            );
        const management_date = try ecosys.plant_management_dispatch.dateFromTimestamp(timestamp);
        // Resolve every accepted event to the actual litter or
        // depth-selected soil owner before any of the three
        // fertilizer mutations. This producer sidecar is only
        // published to the local ledger after all owners accept.
        try driver_context.fertilizer_local_activity.*.reconstructAcceptedHour(
            driver_context.fertilizer_schedule_maps.*[advance_context.pass.*.scene_index].?,
            driver_context.fertilizer_catalog.*,
            management_date,
            fertilizer_source_hour,
            advance_context.solar_noon_hour_by_cell.*,
            driver_context.canopy_cell_area_m2.*,
            12.0,
            driver_context.state.*.active_soil_layer_count,
            driver_context.soil_solver_property_state.*.layer_thickness_m,
            &driver_context.surface_organic_state.*,
        );
        // Preflight exact schedule-derived inputs before any of
        // the N, mineral, or organic owners mutate. This includes
        // carbonate C and every phosphate/gypsum/rock element.
        var landscape_candidate = driver_context.landscape_mass_balance_state.*.boundary_ledger;
        var any_application = false;
        for (0..driver_context.state.*.cell_count) |cell| {
            const applied = try ecosys.fertilizer_management_dispatch.applicationActivityForCell(
                driver_context.fertilizer_schedule_maps.*[advance_context.pass.*.scene_index].?,
                driver_context.fertilizer_catalog.*,
                management_date,
                fertilizer_source_hour,
                advance_context.solar_noon_hour_by_cell.*,
                driver_context.canopy_cell_area_m2.*,
                12.0,
                cell,
            );
            try landscape_candidate.accumulateAccepted(.{
                .mineral_fertilizer_carbon_g_c = applied.mineral_carbon_g_c,
            });
            any_application = any_application or applied.hasMaterialInput();
            try driver_context.hourly_cell_boundary_ledger.*.preflight(cell, .{
                .carbon_input_g = applied.carbon_g_c,
                .nitrogen_input_g = applied.nitrogen_g_n,
                .phosphorus_input_g = applied.phosphorus_g_p,
                .aluminum_input_mol = applied.aluminum_mol,
                .iron_input_mol = applied.iron_mol,
                .calcium_input_mol = applied.calcium_mol,
                .magnesium_input_mol = applied.magnesium_mol,
                .sodium_input_mol = applied.sodium_mol,
                .potassium_input_mol = applied.potassium_mol,
                .sulfur_input_mol = applied.sulfur_mol,
                .silicon_input_mol = applied.silicon_mol,
            });
        }
        var fertilizer_context: ecosys.fertilizer_management_dispatch.NitrogenApplyContext = .{
            .soil = &driver_context.soil_fertilizer_inventory.*,
            .surface = &driver_context.surface_litter_fertilizer_state.*,
            .reactive_nitrogen = &driver_context.soil_reactive_nitrogen_state.*,
            .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
            .active_soil_layer_count = driver_context.state.*.active_soil_layer_count,
            .soil_layer_thickness_m = driver_context.soil_solver_property_state.*.layer_thickness_m,
            .nitrogen_molar_mass_g_per_mol = driver_context.runscript.*.fertilizer_nitrogen_molar_mass_g_per_mol,
            .surface_organic = &driver_context.surface_organic_state.*,
            .source_hour_one_through_twenty_four = fertilizer_source_hour,
            .solar_noon_hour_by_cell = advance_context.solar_noon_hour_by_cell.*,
        };
        _ = try ecosys.fertilizer_management_dispatch.dispatchDate(driver_context.fertilizer_schedule_maps.*[advance_context.pass.*.scene_index].?, driver_context.fertilizer_catalog.*, management_date, &fertilizer_context, ecosys.fertilizer_management_dispatch.applyNitrogen);
        var mineral_fertilizer_context: ecosys.fertilizer_management_dispatch.MineralApplyContext = .{
            .inventory = &driver_context.mineral_fertilizer_inventory.*,
            .surface_organic = &driver_context.surface_organic_state.*,
            .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
            .active_soil_layer_count = driver_context.state.*.active_soil_layer_count,
            .soil_layer_thickness_m = driver_context.soil_solver_property_state.*.layer_thickness_m,
            .source_hour_one_through_twenty_four = fertilizer_source_hour,
            .solar_noon_hour_by_cell = advance_context.solar_noon_hour_by_cell.*,
        };
        _ = try ecosys.fertilizer_management_dispatch.dispatchDate(driver_context.fertilizer_schedule_maps.*[advance_context.pass.*.scene_index].?, driver_context.fertilizer_catalog.*, management_date, &mineral_fertilizer_context, ecosys.fertilizer_management_dispatch.applyMinerals);
        var organic_fertilizer_context: ecosys.fertilizer_management_dispatch.OrganicApplyContext = .{
            .soil = &driver_context.soil_organic_state.*,
            .surface = &driver_context.surface_organic_state.*,
            .parameters = &driver_context.organic_parameters.*,
            .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
            .active_soil_layer_count = driver_context.state.*.active_soil_layer_count,
            .soil_layer_capacity = driver_context.config.*.soil_layers,
            .soil_layer_thickness_m = driver_context.soil_solver_property_state.*.layer_thickness_m,
            .daily_organic_carbon_input_g_c = driver_context.daily_organic_fertilizer_carbon_input_g_c.*,
            .daily_biome_carbon_input_g_c = driver_context.daily_biome_organic_carbon_input_g_c.*,
            .daily_organic_phosphorus_input_g_p = driver_context.daily_organic_fertilizer_phosphorus_input_g_p.*,
            .daily_organic_nitrogen_input_g_n = driver_context.daily_organic_fertilizer_nitrogen_input_g_n.*,
            .source_hour_one_through_twenty_four = fertilizer_source_hour,
            .solar_noon_hour_by_cell = advance_context.solar_noon_hour_by_cell.*,
        };
        _ = try ecosys.fertilizer_management_dispatch.dispatchDate(driver_context.fertilizer_schedule_maps.*[advance_context.pass.*.scene_index].?, driver_context.fertilizer_catalog.*, management_date, &organic_fertilizer_context, ecosys.fertilizer_management_dispatch.applyOrganic);
        // All three scientific owners accepted. Publish exactly
        // the already-preflighted per-cell producer activity.
        for (0..driver_context.state.*.cell_count) |cell| {
            const applied = ecosys.fertilizer_management_dispatch.applicationActivityForCell(
                driver_context.fertilizer_schedule_maps.*[advance_context.pass.*.scene_index].?,
                driver_context.fertilizer_catalog.*,
                management_date,
                fertilizer_source_hour,
                advance_context.solar_noon_hour_by_cell.*,
                driver_context.canopy_cell_area_m2.*,
                12.0,
                cell,
            ) catch unreachable;
            try driver_context.hourly_cell_boundary_ledger.*.accumulate(cell, .{
                .carbon_input_g = applied.carbon_g_c,
                .nitrogen_input_g = applied.nitrogen_g_n,
                .phosphorus_input_g = applied.phosphorus_g_p,
                .aluminum_input_mol = applied.aluminum_mol,
                .iron_input_mol = applied.iron_mol,
                .calcium_input_mol = applied.calcium_mol,
                .magnesium_input_mol = applied.magnesium_mol,
                .sodium_input_mol = applied.sodium_mol,
                .potassium_input_mol = applied.potassium_mol,
                .sulfur_input_mol = applied.sulfur_mol,
                .silicon_input_mol = applied.silicon_mol,
            });
        }
        try ecosys.layer_local_conservation
            .accumulateFertilizerLocalActivity(
            &driver_context.hourly_layer_boundary_ledger.*,
            &driver_context.fertilizer_local_activity.*,
            driver_context.state.*.active_soil_layer_count,
        );
        // Organic C is consumed by the existing daily fertilizer ledger;
        // only the distinct carbonate subset is added here. Ca and other
        // elements already reach the landscape through the hourly cell ledger.
        // The outer-hour transaction checkpoints/restores this boundary state
        // with the scientific owners if any subsequent science stage fails.
        driver_context.landscape_mass_balance_state.*.boundary_ledger = landscape_candidate;
        // Count actual accepted owner input, including lime/gypsum/rock-only
        // amendments, not daily dispatches or zero-valued schedule records.
        if (any_application) driver_context.stage_census.*.recordCurrent(.fertilizer_application);
    }
}

noinline fn advancePreScienceDisturbance(
    driver_context: anytype,
    advance_context: anytype,
    hour: *const HourIdentity,
) !void {
    const timestamp = hour.timestamp;
    const current_year = hour.current_year;
    const current_day_of_year = hour.current_day_of_year;
    // GROSUB applies tillage at integer solar noon, not at the
    // daily management initialization boundary.
    if (driver_context.disturbance_schedule_maps.*[advance_context.pass.*.scene_index] != null) {
        const management_date = try ecosys.plant_management_dispatch.dateFromTimestamp(timestamp);
        const disturbance_source_hour =
            try ecosys.disturbance_management_dispatch.sourceHourOneThroughTwentyFour(
                try timestamp.modelClockHour(),
            );
        var disturbance_context: ecosys.disturbance_management_dispatch.ApplyContext = .{
            .roots = &driver_context.plant_root_state.*.?,
            .litter_partition = &driver_context.plant_litter_partition_state.*.?,
            .soil_organic = &driver_context.soil_organic_state.*,
            .grid = &driver_context.state.*,
            .species_count = driver_context.config.*.plant_populations,
            .plant_assignments = &driver_context.plant_assignments.*.?,
            .plant_unit_by_cell = driver_context.plant_unit_by_cell.*.?,
            .biological_domain_count_by_plant = driver_context.root_biological_domain_count_by_plant.*,
            .root_nonwoody_fraction_by_plant = driver_context.plant_water_workspace.*.?.woody_root_fraction,
            .biomass_turnover_type_by_plant = driver_context.canopy_layer_controls.*.biomass_turnover_type,
            .root_profile_type_by_plant = driver_context.canopy_layer_controls.*.root_profile_type,
            .growth_habit_by_plant = driver_context.plant_topology_controls.*.growth_habit_code,
            .leaf_phenology_type_by_plant = driver_context.plant_topology_controls.*.leaf_phenology_code,
            .planting_day_of_year_by_plant = driver_context.development_planting_day_of_year.*,
            .planting_year_by_plant = driver_context.development_planting_year.*,
            .current_day_of_year = current_day_of_year,
            .current_year = @intCast(current_year),
            .source_hour_one_through_twenty_four = disturbance_source_hour,
            .solar_noon_hour_by_cell = advance_context.solar_noon_hour_by_cell.*,
            .soil_boundary_topology = &driver_context.soil_boundary_topology_state.*,
            .terrain_hydrology = &driver_context.terrain_hydrology_state.*,
            .soil_geometry = &driver_context.soil_geometry_state.*,
            .plant_harvest = if (driver_context.harvest_context.*) |*value| value else null,
            .root_litter_carbon_ledger = &driver_context.root_litter_carbon_ledger.*,
            .surface_energy = &driver_context.surface_energy_state.*,
            .fire_active_this_hour = driver_context.fire_active_this_hour.*,
            .tillage_runtime = .{
                .allocator = driver_context.allocator.*,
                .local_activity = &driver_context.tillage_local_activity.*,
                .grid = &driver_context.state.*,
                .geometry = &driver_context.soil_geometry_state.*,
                .properties = &driver_context.soil_solver_property_state.*,
                .thermal = &driver_context.soil_thermal_state.*,
                .soil_organic = &driver_context.soil_organic_state.*,
                .soil_organic_transport = &driver_context.soil_organic_transport_state.*,
                .surface_organic = &driver_context.surface_organic_state.*,
                .soil_gas = &driver_context.gas_transport_state.*,
                .surface_gas = &driver_context.litter_gas_transport_state.*,
                .soil_chemistry = &driver_context.initial_chemistry_state.*,
                .surface_chemistry = &driver_context.surface_litter_chemistry_state.*,
                .surface_geometry = &driver_context.surface_litter_geometry_state.*,
                .fertilizer_band = &driver_context.fertilizer_band_state.*,
                .fertilizer_nitrogen = &driver_context.soil_fertilizer_inventory.*,
                .surface_fertilizer = &driver_context.surface_litter_fertilizer_state.*,
                .mineral_fertilizer = &driver_context.mineral_fertilizer_inventory.*,
                .reactive_nitrogen = &driver_context.soil_reactive_nitrogen_state.*,
                .micropore_solutes = &driver_context.micropore_solute_state.*,
                .macropore_solutes = &driver_context.macropore_solute_state.*,
                .mineral_nitrogen_transport = &driver_context.mineral_nitrogen_transport_state.*,
                .chemistry_layer_parameters = driver_context.soil_chemistry_layer_parameters.*,
                .surface_denitrification = &driver_context.surface_denitrification_state.*,
                .surface_solute_transport = &driver_context.surface_transport_state.*,
                .plant_litter_salt_ingress = &driver_context.plant_litter_salt_ingress_state.*,
                .surface_water_m3 = driver_context.surface_precipitation_state.*.litter_water_m3,
                .surface_ice_m3 = driver_context.surface_litter_ice_m3.*,
                .surface_heat_capacity_megajoules_per_k = driver_context.surface_heat_capacity_megajoules_per_k.*,
                .cell_area_m2 = driver_context.canopy_cell_area_m2.*,
                .salinity_enabled_by_cell = driver_context.salinity_enabled_by_cell.*,
                .minimum_layer_thickness_m = driver_context.runscript.*.soil_geometry_parameters.minimum_layer_thickness_m,
                .dry_organic_heat_capacity_megajoules_per_g_c_k = driver_context.runscript.*.surface_pond_dry_organic_heat_capacity_megajoules_per_g_c_k,
                .liquid_water_heat_capacity_megajoules_per_m3_k = driver_context.runscript.*.soil_phase_heat_parameters.liquid_water_heat_capacity_megajoules_per_m3_k,
                .physical_ice_heat_capacity_megajoules_per_m3_k = driver_context.runscript.*.soil_phase_heat_parameters.ice_heat_capacity_megajoules_per_m3_k,
                .ice_density_megagrams_per_m3 = driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.ice_density_megagrams_per_m3,
                .latent_heat_of_fusion_megajoules_per_m3 = driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.latent_heat_of_fusion_megajoules_per_m3,
                .pure_water_melting_temperature_k = driver_context.runscript.*.soil_phase_heat_parameters.freeze_thaw.pure_water_freezing_temperature_k,
                .carbon_g_per_mol = 12.0,
                .nitrogen_g_per_mol = driver_context.runscript.*.fertilizer_nitrogen_molar_mass_g_per_mol,
                .phosphorus_g_per_mol = driver_context.runscript.*.root_nutrient_parameters.phosphorus_molar_mass_g_per_mol,
            },
        };
        _ = try ecosys.disturbance_management_dispatch.dispatchDatePhase(
            driver_context.disturbance_schedule_maps.*[advance_context.pass.*.scene_index].?,
            driver_context.disturbance_catalog.*,
            management_date,
            &disturbance_context,
            .pre_science,
        );
    }
}

noinline fn advanceDailyClimateAcclimation(
    driver_context: anytype,
    timeline_state: *TimelineState,
    advance_context: anytype,
    hour: *const HourIdentity,
) !void {
    const timestamp = hour.timestamp;
    const current_day_of_year = hour.current_day_of_year;
    const begins_day = hour.begins_day;
    if (begins_day and advance_context.active_options.*.climate_change_mode == 2) {
        try timeline_state.climate_state.advanceDay(advance_context.active_options.*, ecosys.climate_change.daysInYear(timestamp.year.?));
        const daily_average_air_temperature_change_c = try timeline_state.climate_state.averageAirTemperatureChangeC(advance_context.active_options.*, current_day_of_year);
        try driver_context.microbial_thermal_adaptation_state.*.refreshClimateMode2(
            driver_context.mean_annual_temperature_c_by_cell.*,
            daily_average_air_temperature_change_c,
        );
        // PLANT_ACCLIM_MODE2_DAILY_BINDING: `wthr.f:412--431`'s per-plant
        // biological re-acclimation, run once per simulated day
        // like the legacy `J.EQ.1` guard. Bare-soil scenes with
        // no plant catalog have no canopy state to refresh.
        if (driver_context.detailed_canopy_state.*) |*canopy| {
            try ecosys.biological_climate_acclimation.applyDaily(driver_context.allocator.*, .{
                .cell_count = driver_context.state.*.cell_count,
                .plants_per_cell = driver_context.config.*.plant_populations,
                .source_hour = 1,
                .incremental_climate_change = true,
                .daily_average_air_temperature_change_c = daily_average_air_temperature_change_c,
                .initial_mean_annual_air_temperature_c_by_cell = driver_context.mean_annual_temperature_c_by_cell.*,
                .plant_initial_thermal_adaptation_zone = driver_context.plant_initial_thermal_adaptation_zone.*,
                .plant_photosynthesis_pathway = driver_context.plant_initial_photosynthesis_pathway.*,
                .plant_initial_floral_initiation_group = driver_context.plant_initial_floral_initiation_group.*,
                .plant_seed_initial_node_number = driver_context.plant_seed_initial_node_number.*,
                .plant_biomass_turnover_type = driver_context.plant_topology_controls.*.aboveground_turnover_type,
                .default_lower_temperature_threshold_c = driver_context.runscript.*.thermal_acclimation_parameters.base_leafout_threshold_c,
                .default_upper_temperature_threshold_c = driver_context.runscript.*.thermal_acclimation_parameters.base_leafoff_threshold_c,
            }, .{
                .thermal_adaptation_offset_c = canopy.plant_thermal_adaptation_offset_c,
                .leafout_threshold_c = canopy.plant_leafout_threshold_c,
                .leafoff_threshold_c = canopy.plant_leafoff_threshold_c,
                .seed_set_high_temperature_c = canopy.plant_seed_set_high_temperature_c,
                .floral_initiation_node_number = driver_context.plant_topology_controls.*.initial_maturity_group,
                .dormancy_parameters_by_plant = driver_context.development_dormancy_parameters.*,
            });
            // HFUNC normalizes both vegetative and reproductive
            // progress by the current per-plant GROUPI. Existing
            // branch-specific GROUP values remain unchanged, as
            // in the oracle; future branches read the topology
            // control updated above.
            for (driver_context.development_species_parameters.*, driver_context.plant_topology_controls.*.initial_maturity_group) |*parameters, group|
                parameters.maturity_group_node_count = group;
            if (driver_context.branch_development_state.*) |*development| {
                for (driver_context.newly_activated_plants.*, 0..) |activated, plant| {
                    if (!activated) continue;
                    const branches = try driver_context.detailed_canopy_state.*.?.branchRange(plant);
                    for (branches.first..branches.end) |branch|
                        development.maturity_group[branch] = driver_context.plant_topology_controls.*.initial_maturity_group[plant];
                }
            }
        }
    }
}

noinline fn prepareHourlyWeatherAndAtmosphere(
    driver_context: anytype,
    timeline_state: *TimelineState,
    advance_context: anytype,
    hour: *const HourIdentity,
) !ecosys.climate_change.PrecipitationChemistryMultipliers {
    const timestamp = hour.timestamp;
    const current_day_of_year = hour.current_day_of_year;
    for (0..driver_context.state.*.cell_count) |cell| {
        const stream_index = advance_context.weather_assignment.*.stream_index_by_cell[cell];
        if (stream_index >= advance_context.weather_hour_by_stream.*.len)
            return error.WeatherGridStreamIndexOutOfRange;
        const selected_site = driver_context.site_by_cell.*[cell];
        const cell_weather_stream = advance_context.weather_streams.*[stream_index];
        driver_context.hourly_weather_header_by_cell.*[cell] = cell_weather_stream.header;
        var cell_radiation = try ecosys.atmospheric_radiation.prepare(
            advance_context.weather_hour_by_stream.*[stream_index].forcing,
            timestamp,
            driver_context.grid_input_files.*.latitude_degrees_north_by_cell[cell],
            cell_weather_stream.header.solar_noon_hour,
            selected_site.ecosystem_type == -2,
        );
        driver_context.hourly_forcing_by_cell.*[cell] = try timeline_state.climate_state.apply(
            cell_radiation.forcing,
            advance_context.active_options.*,
            timestamp,
            cell_weather_stream.header.solar_noon_hour,
            selected_site.elevation_m,
        );
        cell_radiation.forcing = driver_context.hourly_forcing_by_cell.*[cell];
        driver_context.hourly_radiation_by_cell.*[cell] = cell_radiation;
    }
    const atmospheric_co2_multiplier = try timeline_state.climate_state.atmosphericCo2Multiplier(advance_context.active_options.*, current_day_of_year);
    const precipitation_chemistry_multipliers = try timeline_state.climate_state.precipitationChemistryMultipliers(advance_context.active_options.*, current_day_of_year);
    for (driver_context.site_by_cell.*, driver_context.atmospheric_background_mixing_ratios.*) |selected_site, *ratios| {
        ratios.carbon_dioxide_umol_mol = selected_site.atmospheric_co2_umol_mol * atmospheric_co2_multiplier;
        if (!std.math.isFinite(ratios.carbon_dioxide_umol_mol) or ratios.carbon_dioxide_umol_mol <= 0)
            return error.InvalidAtmosphericCarbonDioxide;
    }
    // HOUR1 2443-2449 consumes the prior accepted TKQ and
    // CO2Q/CH4Q/OXYQ before any current-hour gas process runs.
    try driver_context.atmospheric_canopy_gas_state.*.refreshMassConcentrations(
        driver_context.atmospheric_background_mixing_ratios.*,
    );
    return precipitation_chemistry_multipliers;
}

noinline fn advanceHour(driver_context: anytype, timeline_state: *TimelineState, advance_context: anytype) !void {
    for (advance_context.hourly_weather_streams.*, 0..) |*stream, stream_index| {
        advance_context.weather_hour_by_stream.*[stream_index] = try stream.next() orelse {
            std.log.err("weather stream ended before scene: scene={d} expected_hours={d} received_hours={d} file='{s}'", .{
                advance_context.pass.*.scene_index + 1,
                advance_context.scene_expected_hours.*,
                advance_context.scene_weather_hours.*,
                advance_context.weather_assignment.*.unique_file_names[stream_index],
            });
            return error.WeatherStreamEndedBeforeScene;
        };
        advance_context.weather_hour_by_stream.*[stream_index].timestamp = try advance_context.weather_hour_by_stream.*[stream_index].timestamp.modelHour(advance_context.active_options.*.start_date.year);
        if (stream_index > 0 and !sameWeatherTimestamp(
            advance_context.weather_hour_by_stream.*[0].timestamp,
            advance_context.weather_hour_by_stream.*[stream_index].timestamp,
        )) {
            std.log.err("weather-grid timestamp mismatch: scene={d} hour_index={d} first_file='{s}' mismatched_file='{s}'", .{
                advance_context.pass.*.scene_index + 1,
                advance_context.scene_weather_hours.*,
                advance_context.weather_assignment.*.unique_file_names[0],
                advance_context.weather_assignment.*.unique_file_names[stream_index],
            });
            return error.WeatherGridTimestampMismatch;
        }
    }
    const weather_hour = advance_context.weather_hour_by_stream.*[0];
    const timestamp = weather_hour.timestamp;
    const temporary_profile_active = !builtin.is_test and
        driver_context.executed_weather_hours.* >= 48 and
        driver_context.executed_weather_hours.* < 56;
    const temporary_profile_start = std.Io.Clock.now(.boot, driver_context.init.*.io);
    // The fixed external hour is one atomic scientific/accounting
    // transaction. Clone every reallocating persistent owner in
    // memory before material refresh, and byte-journal the stable
    // workspaces/ledgers. Any later error (including management,
    // canopy topology, soil solve, or conservation acceptance)
    // unwinds through this scope and restores the exact accepted
    // hour-start state. Weather `next()` intentionally precedes
    // the transaction: input cursors are external I/O and are not
    // rewindable. A process restart resumes from the completed-
    // hour cursor and rereads this failed hour; an in-memory retry
    // must reuse the already-materialized `weather_hour_by_stream`.
    const outer_hour_targets: ecosys.checkpoint_bundle_reader.LiveTargets = .{
        .grid = &driver_context.state.*,
        .plants = &driver_context.plant_state.*,
        .plant_development = .{ .phenology = &driver_context.plant_phenology_state.*.?, .growth = &driver_context.plant_growth_stage_state.*.?, .dormancy = &driver_context.plant_dormancy_state.*.?, .branch_development = &driver_context.branch_development_state.*.? },
        .plant_roots = &driver_context.plant_root_state.*.?,
        .plant_canopy = .{ .canopy = &driver_context.detailed_canopy_state.*.?, .retention = &driver_context.canopy_precipitation_retention_state.*.?, .layer_distribution = &driver_context.canopy_layer_distribution_state.*.? },
        .soil_biogeochemistry = .{ .microbial = &driver_context.soil_microbial_state.*, .microbial_thermal_adaptation = &driver_context.microbial_thermal_adaptation_state.*, .chemistry = &driver_context.initial_chemistry_state.*, .available_nutrients = &driver_context.plant_available_nutrient_state.*, .fertilizer = &driver_context.soil_fertilizer_inventory.*, .mineral_fertilizer = &driver_context.mineral_fertilizer_inventory.*, .fertilizer_band = &driver_context.fertilizer_band_state.*, .reactive_nitrogen = &driver_context.soil_reactive_nitrogen_state.*, .microbial_phosphorus = &driver_context.soil_microbial_phosphorus_state.*, .nutrient_competition = &driver_context.soil_nutrient_competition_history.* },
        .soil_organic_matter = .{ .profile = &driver_context.soil_organic_state.*, .surface = &driver_context.surface_organic_state.*, .litter_chemistry = &driver_context.surface_litter_chemistry_state.*, .litter_fertilizer = &driver_context.surface_litter_fertilizer_state.*, .surface_respiration = &driver_context.surface_microbial_respiration_state.*, .surface_autotrophic = &driver_context.surface_autotrophic_complex_state.*, .surface_denitrification = &driver_context.surface_denitrification_state.*, .surface_fire_exchange = &driver_context.surface_fire_exchange_state.*, .litter_salt_ingress = &driver_context.plant_litter_salt_ingress_state.* },
        .transport = .{ .micropore = &driver_context.micropore_solute_state.*, .macropore = &driver_context.macropore_solute_state.*, .mineral_nitrogen = &driver_context.mineral_nitrogen_transport_state.*, .organic = &driver_context.soil_organic_transport_state.*, .gas = &driver_context.gas_transport_state.*, .litter_gas = &driver_context.litter_gas_transport_state.*, .snow = &driver_context.snow_transport_state.*, .surface = &driver_context.surface_transport_state.* },
        .soil_geometry_and_hydrology = .{ .geometry = &driver_context.soil_geometry_state.*, .hydrology = &driver_context.transport_hydrology_state.*, .surface = &driver_context.surface_precipitation_state.*, .erosion = &driver_context.surface_erosion_state.*, .suspended = &driver_context.suspended_constituent_state.*, .climate = &timeline_state.climate_state, .eroded_minerals = &driver_context.eroded_mineral_state.*, .runtime = .{ .soil_properties = &driver_context.soil_solver_property_state.*, .soil_thermal = &driver_context.soil_thermal_state.*, .soil_chemistry_layer_parameters = driver_context.soil_chemistry_layer_parameters.* }, .surface_boundary = .{ .ground_air = &driver_context.ground_air_state.*, .surface_aerodynamics = &driver_context.surface_aerodynamic_state.*, .atmospheric_carrier = &driver_context.atmospheric_canopy_gas_state.* }, .water_table = .{ .topology = &driver_context.soil_boundary_topology_state.* }, .adaptive_hour_schedule = &driver_context.fixed_hour_recovery_workspace.*.adaptive_hour_schedule, .surface_litter_geometry = &driver_context.surface_litter_geometry_state.*, .surface_litter_ice_m3 = driver_context.surface_litter_ice_m3.*, .delayed_live_canopy_combustion_heat_megajoules = driver_context.delayed_live_canopy_combustion_heat_megajoules.*, .delayed_standing_dead_combustion_heat_megajoules = driver_context.delayed_standing_dead_combustion_heat_megajoules.*, .delayed_subsurface_combustion_heat_megajoules = driver_context.delayed_subsurface_combustion_heat_megajoules.*, .delayed_root_uptake_heat_megajoules = driver_context.delayed_root_uptake_heat_megajoules.*, .delayed_surface_combustion_heat_megajoules = driver_context.delayed_surface_combustion_heat_megajoules.* },
        .landscape_mass_balance = &driver_context.landscape_mass_balance_state.*,
        .plant_accounting = .{ .daily_flux = &driver_context.plant_daily_flux_ledger.*, .root_soil_exchange = &driver_context.plant_root_soil_exchange_state.*, .cumulative_harvest_salt_mol_by_plant = driver_context.cumulative_harvest_salt_mol_by_plant.*, .cumulative_water_source_m3_by_plant = driver_context.plant_water_state_update_state.*.cumulative_water_source_m3_by_plant },
    };
    driver_context.fixed_hour_recovery_workspace.*.configure(outer_hour_targets);
    var outer_hour_transaction = try driver_context.outer_hour_transaction_workspace.*.begin(
        driver_context.config.*,
        outer_hour_targets,
    );
    defer outer_hour_transaction.deinit();
    const temporary_profile_outer_bundle_done = std.Io.Clock.now(.boot, driver_context.init.*.io);
    const outer_hour_carbon_exchange = if (driver_context.canopy_carbon_exchange_state.*) |*value| value else return error.OuterHourTransactionRequiresCanopyCarbonExchange;
    var outer_hour_carbon_exchange_transaction = try driver_context.outer_hour_carbon_exchange_workspace.*.begin(
        outer_hour_carbon_exchange,
        ecosys.canopy_carbon_exchange.State.clone,
    );
    defer outer_hour_carbon_exchange_transaction.deinit();
    const temporary_profile_outer_carbon_done = std.Io.Clock.now(.boot, driver_context.init.*.io);
    var outer_hour_soil_gas_transport_transaction = try driver_context.outer_hour_soil_gas_transport_workspace.*.begin(
        &driver_context.soil_gas_transport_state.*,
        ecosys.soil_gas_transport_step.State.clone,
    );
    defer outer_hour_soil_gas_transport_transaction.deinit();
    const temporary_profile_outer_gas_done = std.Io.Clock.now(.boot, driver_context.init.*.io);
    try outer_hour_transaction.captureStable(&driver_context.hourly_science_context.*, .{
        driver_context.executor.*.pool,
        &driver_context.hourly_science_context.*.plant_reproduction_workspace.*,
        &driver_context.lateral_contribution_workspace.*,
        &driver_context.runscript.*,
        &driver_context.canopy_geometry.*,
        &driver_context.plant_root_state.*,
        &driver_context.detailed_canopy_state.*,
        &driver_context.canopy_precipitation_retention_state.*,
        &driver_context.canopy_layer_distribution_state.*,
        &driver_context.canopy_carbon_exchange_state.*,
        outer_hour_carbon_exchange,
        &driver_context.plant_phenology_state.*,
        &driver_context.plant_growth_stage_state.*,
        &driver_context.plant_dormancy_state.*,
        &driver_context.branch_development_state.*,
        &driver_context.soil_gas_transport_state.*,
    });
    const temporary_profile_outer_context_done = std.Io.Clock.now(.boot, driver_context.init.*.io);
    var dry_branch_executions_owner: *u64 = undefined;
    dry_branch_executions_owner =
        &ecosys.surface_litter_chemistry_carrier_rebase.dry_branch_executions;
    var outer_hour_transients = .{
        .hourly_accumulators = driver_context.hourly_accumulators.*,
        .newly_activated_plants = driver_context.newly_activated_plants.*,
        .replant_layer_bottom_depth_m = driver_context.replant_layer_bottom_depth_m.*,
        .plant_initial_thermal_adaptation_zone = driver_context.plant_initial_thermal_adaptation_zone.*,
        .plant_initial_photosynthesis_pathway = driver_context.plant_initial_photosynthesis_pathway.*,
        .daily_soil_gas_flux = &driver_context.daily_soil_gas_flux.*,
        .daily_canopy_gas_exchange = &driver_context.daily_canopy_gas_exchange.*,
        .daily_heterotrophic_respiration = &driver_context.daily_heterotrophic_respiration.*,
        .daily_carbon_export = &driver_context.daily_carbon_export.*,
        .daily_phosphorus_export = &driver_context.daily_phosphorus_export.*,
        .daily_nitrogen_export = &driver_context.daily_nitrogen_export.*,
        .daily_water_ledger = &driver_context.daily_water_ledger.*,
        .daily_heat_ledger = &driver_context.daily_heat_ledger.*,
        .daily_ecosystem_carbon = &driver_context.daily_ecosystem_carbon.*,
        .daily_soil_fire_charcoal_production_g_c = driver_context.daily_soil_fire_charcoal_production_g_c.*,
        .daily_soil_fire_carbon_dioxide_emission_g_c = driver_context.daily_soil_fire_carbon_dioxide_emission_g_c.*,
        .daily_soil_fire_methane_emission_g_c = driver_context.daily_soil_fire_methane_emission_g_c.*,
        .daily_soil_fire_phosphorus_flux_g_p = driver_context.daily_soil_fire_phosphorus_flux_g_p.*,
        .daily_soil_fire_nitrogen_flux_g_n = driver_context.daily_soil_fire_nitrogen_flux_g_n.*,
        .daily_root_fire_carbon_dioxide_emission_g_c = driver_context.daily_root_fire_carbon_dioxide_emission_g_c.*,
        .daily_root_fire_methane_emission_g_c = driver_context.daily_root_fire_methane_emission_g_c.*,
        .daily_root_fire_nitrogen_flux_g_n = driver_context.daily_root_fire_nitrogen_flux_g_n.*,
        .daily_root_fire_phosphorus_flux_g_p = driver_context.daily_root_fire_phosphorus_flux_g_p.*,
        .daily_root_fire_nitrogen_loss_g_n = driver_context.daily_root_fire_nitrogen_loss_g_n.*,
        .daily_root_fire_phosphorus_loss_g_p = driver_context.daily_root_fire_phosphorus_loss_g_p.*,
        .daily_soil_combusted_nitrogen_g_n = driver_context.daily_soil_combusted_nitrogen_g_n.*,
        .daily_soil_combusted_phosphorus_g_p = driver_context.daily_soil_combusted_phosphorus_g_p.*,
        .daily_microbial_phosphate_mineralization_g_p = driver_context.daily_microbial_phosphate_mineralization_g_p.*,
        .daily_microbial_nitrogen_mineralization_g_n = driver_context.daily_microbial_nitrogen_mineralization_g_n.*,
        .daily_organic_fertilizer_carbon_input_g_c = driver_context.daily_organic_fertilizer_carbon_input_g_c.*,
        .daily_biome_organic_carbon_input_g_c = driver_context.daily_biome_organic_carbon_input_g_c.*,
        .daily_organic_fertilizer_phosphorus_input_g_p = driver_context.daily_organic_fertilizer_phosphorus_input_g_p.*,
        .daily_organic_fertilizer_nitrogen_input_g_n = driver_context.daily_organic_fertilizer_nitrogen_input_g_n.*,
        .redistribution_ledger = &driver_context.redistribution_ledger.*,
        .ecosystem_energy_ledger = &driver_context.ecosystem_energy_ledger_state.*,
        .root_uptake_ledger = &driver_context.root_uptake_ledger_state.*,
        .resolved_development_year = &advance_context.resolved_development_year.*,
        .previous_weather_timestamp = &advance_context.previous_weather_timestamp.*,
        .scene_weather_hours = &advance_context.scene_weather_hours.*,
        .executed_weather_hours = &driver_context.executed_weather_hours.*,
        .heat_closure_previous_storage_megajoules = &advance_context.heat_closure_previous_storage_megajoules.*,
        .heat_closure_previous_cumulative_input_megajoules = &advance_context.heat_closure_previous_cumulative_input_megajoules.*,
        .heat_closure_previous_cumulative_output_megajoules = &advance_context.heat_closure_previous_cumulative_output_megajoules.*,
        .plant_water_state_update = &driver_context.plant_water_state_update_state.*,
        .pending_surface_gas_ledger = driver_context.pending_surface_gas_ledger.*,
        .tillage_local_activity = &driver_context.tillage_local_activity.*,
        .dry_branch_executions = dry_branch_executions_owner,
    };
    try outer_hour_transaction.captureStable(&outer_hour_transients, .{});
    const temporary_profile_outer_transients_done = std.Io.Clock.now(.boot, driver_context.init.*.io);
    if (temporary_profile_active) std.log.info(
        "TEMP_PROFILE outer capture elapsed_ms={d}",
        .{temporary_profile_start.durationTo(std.Io.Clock.now(.boot, driver_context.init.*.io)).toMilliseconds()},
    );
    if (temporary_profile_active) std.log.info(
        "TEMP_PROFILE outer_capture_detail bundle_ns={d} carbon_ns={d} gas_ns={d} context_stable_ns={d} transients_stable_ns={d}",
        .{
            temporary_profile_start.durationTo(temporary_profile_outer_bundle_done).nanoseconds,
            temporary_profile_outer_bundle_done.durationTo(temporary_profile_outer_carbon_done).nanoseconds,
            temporary_profile_outer_carbon_done.durationTo(temporary_profile_outer_gas_done).nanoseconds,
            temporary_profile_outer_gas_done.durationTo(temporary_profile_outer_context_done).nanoseconds,
            temporary_profile_outer_context_done.durationTo(temporary_profile_outer_transients_done).nanoseconds,
        },
    );
    const FixedHourAliasRebindContext = struct {
        hourly: *@TypeOf(driver_context.hourly_science_context.*),
        harvest: *@TypeOf(driver_context.harvest_context.*),
        metadata_cells: @TypeOf(driver_context.checkpoint_metadata_cells.*),
        phenology: *@TypeOf(driver_context.plant_phenology_state.*),
        plant_populations: usize,

        fn rebind(raw: *anyopaque) anyerror!void {
            const self: *@This() = @ptrCast(@alignCast(raw));
            var harvest_emerged: ?*?[]bool = null;
            if (self.harvest.*) |*value|
                harvest_emerged = &value.emerged_by_plant;
            try hourly_heat_water_solute.rebindPhenologyAliases(
                &self.phenology.*.?,
                &self.hourly.development_emerged,
                harvest_emerged,
                self.metadata_cells,
                self.plant_populations,
            );
        }
    };
    var fixed_hour_alias_rebind_context: FixedHourAliasRebindContext = .{
        .hourly = &driver_context.hourly_science_context.*,
        .harvest = &driver_context.harvest_context.*,
        .metadata_cells = driver_context.checkpoint_metadata_cells.*,
        .phenology = &driver_context.plant_phenology_state.*,
        .plant_populations = driver_context.config.*.plant_populations,
    };
    driver_context.fixed_hour_recovery_workspace.*.bindOuterTransaction(
        &outer_hour_transaction,
        .{
            .context = @ptrCast(&fixed_hour_alias_rebind_context),
            .rebind = FixedHourAliasRebindContext.rebind,
        },
    );
    defer driver_context.fixed_hour_recovery_workspace.*.unbindOuterTransaction(&outer_hour_transaction);
    try prepareAcceptedHourStorageAndLedgers(driver_context, advance_context);
    const hour_identity = try resolveHourIdentity(driver_context, advance_context, timestamp);
    if (timeline_state.execution_journal) |journal| try journal.attempt(.{
        .execution = advance_context.pass.*.execution_iteration + 1,
        .scenario = advance_context.pass.*.scenario_index + 1,
        .repeat = advance_context.pass.*.scenario_iteration + 1,
        .scene = advance_context.pass.*.scene_index + 1,
        .scene_hour = advance_context.scene_weather_hours.* + 1,
        .total_hour = driver_context.executed_weather_hours.* + 1,
        .year = hour_identity.current_year,
        .day = hour_identity.current_day_of_year,
        .hour = timestamp.hour,
    });
    const current_year = hour_identity.current_year;
    const current_day_of_year = hour_identity.current_day_of_year;
    const begins_day = hour_identity.begins_day;
    try advancePlantLifecycleManagement(driver_context, &hour_identity);
    try advanceFertilizerManagement(driver_context, advance_context, &hour_identity);
    try advancePreScienceDisturbance(driver_context, advance_context, &hour_identity);
    try advanceDailyClimateAcclimation(driver_context, timeline_state, advance_context, &hour_identity);
    const precipitation_chemistry_multipliers = try prepareHourlyWeatherAndAtmosphere(
        driver_context,
        timeline_state,
        advance_context,
        &hour_identity,
    );
    const management_date = try ecosys.plant_management_dispatch.dateFromTimestamp(timestamp);
    const prepare_science_context = .{
        .begins_day = &begins_day,
        .current_day_of_year = &current_day_of_year,
        .current_year = &current_year,
        .management_date = &management_date,
        .timestamp = &timestamp,
    };
    try prepareHourlyScience(driver_context, timeline_state, advance_context, &prepare_science_context);
    if (temporary_profile_active) std.log.info(
        "TEMP_PROFILE prepared elapsed_ms={d}",
        .{temporary_profile_start.durationTo(std.Io.Clock.now(.boot, driver_context.init.*.io)).toMilliseconds()},
    );
    const gas_failure_file_name = try std.fmt.allocPrint(
        driver_context.allocator.*,
        "ecosys-ng-gas-failure-ex{d}-scenario{d}-repeat{d}-scene{d}-year{d}-day{d}-hour{d}-cells0-{d}.bin",
        .{
            advance_context.pass.*.execution_iteration + 1,
            advance_context.pass.*.scenario_index + 1,
            advance_context.pass.*.scenario_iteration + 1,
            advance_context.pass.*.scene_index + 1,
            current_year,
            current_day_of_year,
            timestamp.hour,
            driver_context.state.*.cell_count - 1,
        },
    );
    defer driver_context.allocator.*.free(gas_failure_file_name);
    const solute_failure_file_name = try std.fmt.allocPrint(
        driver_context.allocator.*,
        "ecosys-ng-solute-failure-ex{d}-scenario{d}-repeat{d}-scene{d}-year{d}-day{d}-hour{d}.bin",
        .{
            advance_context.pass.*.execution_iteration + 1,
            advance_context.pass.*.scenario_index + 1,
            advance_context.pass.*.scenario_iteration + 1,
            advance_context.pass.*.scene_index + 1,
            current_year,
            current_day_of_year,
            timestamp.hour,
        },
    );
    defer driver_context.allocator.*.free(solute_failure_file_name);
    // Diagnostic logs are outside the output coordinator's transactional
    // scientific categories, so snapshots survive rejected-hour rollback.
    // Bind the run's log directory directly: its parent can be the input deck
    // and must not receive diagnostic files.
    try ecosys.outer_hour_transaction.Transaction.injectFailureForTest(.after_canopy_and_management);
    executeHourlyScience(
        driver_context.hourly_science_context.*,
        try timestamp.modelClockHour(),
        driver_context.hourly_radiation_by_cell.*,
        driver_context.hourly_forcing_by_cell.*,
        driver_context.hourly_weather_header_by_cell.*,
        driver_context.plant_calendar_by_cell.*,
        precipitation_chemistry_multipliers,
        .{ .value = driver_context.executed_weather_hours.* + 1 },
        .{
            .io = driver_context.init.*.io,
            .directory = driver_context.output_tree.*.logs,
            .file_path = gas_failure_file_name,
        },
        .{
            .io = driver_context.init.*.io,
            .directory = driver_context.output_tree.*.logs,
            .file_path = solute_failure_file_name,
            .context = .{
                .execution_id = @intCast(
                    advance_context.pass.*.execution_iteration + 1,
                ),
                .scenario_id = @intCast(
                    advance_context.pass.*.scenario_index + 1,
                ),
                .repeat_id = @intCast(
                    advance_context.pass.*.scenario_iteration + 1,
                ),
                .scene_id = @intCast(advance_context.pass.*.scene_index + 1),
                .scene_hour = @intCast(advance_context.scene_weather_hours.* + 1),
                .year = @intCast(current_year),
                .day_of_year = @intCast(current_day_of_year),
                .hour = @intCast(timestamp.hour),
            },
        },
    ) catch |err| {
        std.log.err("hourly science failed: execution={d} scenario={d} scenario_repeat={d} scene={d} scene_hour={d} total_hour={d} year={?} day_of_year={?} month={?} day={?} hour={d} error={s}", .{ advance_context.pass.*.execution_iteration + 1, advance_context.pass.*.scenario_index + 1, advance_context.pass.*.scenario_iteration + 1, advance_context.pass.*.scene_index + 1, advance_context.scene_weather_hours.* + 1, driver_context.executed_weather_hours.* + 1, timestamp.year, timestamp.day_of_year, timestamp.month, timestamp.day_of_month, timestamp.hour, @errorName(err) });
        return err;
    };
    if (temporary_profile_active) std.log.info(
        "TEMP_PROFILE science elapsed_ms={d}",
        .{temporary_profile_start.durationTo(std.Io.Clock.now(.boot, driver_context.init.*.io)).toMilliseconds()},
    );
    const post_science_context = .{
        .current_day_of_year = &current_day_of_year,
        .current_year = &current_year,
        .management_date = &management_date,
        .timestamp = &timestamp,
    };
    try postScienceAccounting(driver_context, advance_context, &post_science_context);
    if (temporary_profile_active) std.log.info(
        "TEMP_PROFILE post_science elapsed_ms={d}",
        .{temporary_profile_start.durationTo(std.Io.Clock.now(.boot, driver_context.init.*.io)).toMilliseconds()},
    );
    const accept_hour_context = .{
        .current_day_of_year = &current_day_of_year,
        .current_year = &current_year,
        .management_date = &management_date,
        .outer_hour_carbon_exchange_transaction = &outer_hour_carbon_exchange_transaction,
        .outer_hour_soil_gas_transport_transaction = &outer_hour_soil_gas_transport_transaction,
        .outer_hour_transaction = &outer_hour_transaction,
        .timestamp = &timestamp,
    };
    try acceptHourAndPublish(driver_context, timeline_state, advance_context, &accept_hour_context);
    if (temporary_profile_active) std.log.info(
        "TEMP_PROFILE accepted elapsed_ms={d}",
        .{temporary_profile_start.durationTo(std.Io.Clock.now(.boot, driver_context.init.*.io)).toMilliseconds()},
    );
}

noinline fn runTimeline(driver_context: anytype, evidence_writer: ?*std.Io.Writer, evidence_id: []const u8) !void {
    var timeline_state = try initializeTimeline(driver_context);
    var evidence_plan = if (evidence_writer != null)
        try ecosys.execution_evidence.Plan.init(driver_context.allocator.*, driver_context.scene_options.*, driver_context.runscript.*.scenarios, driver_context.runscript.*.execution_repeat_count)
    else
        null;
    defer if (evidence_plan) |*plan| plan.deinit(driver_context.allocator.*);
    var journal: ecosys.execution_evidence.Journal = undefined;
    if (evidence_writer) |writer| {
        journal = try ecosys.execution_evidence.Journal.start(&evidence_plan.?, writer, evidence_id, driver_context.executed_weather_hours.*, driver_context.conservation_survey.* == null);
        timeline_state.execution_journal = &journal;
    }
    // Publish on every exit, including the error path. A run that dies mid-deck
    // is precisely when "which science actually ran before it died" is the
    // question, and `finishTimeline` below is skipped on error.
    defer reportStageExecutionCensus(driver_context.stage_census);
    // Same reasoning as the census: published on every exit, because a
    // surveyed run that still dies of something else is exactly when the
    // accumulated breach list matters.
    defer if (driver_context.conservation_survey.*) |survey| reportConservationSurvey(survey);
    var pass_iterator = try ecosys.simulation_timeline.PassIterator.init(driver_context.runscript.*.scenarios, driver_context.runscript.*.execution_repeat_count);
    while (pass_iterator.next()) |pass| {
        {
            const scene = driver_context.runscript.*.scenes[pass.scene_index];
            const active_options = driver_context.scene_options.*[pass.scene_index];
            try driver_context.visualization_streams.*.configureScene(
                active_options.visualization_enabled,
                active_options.visualization_start_year,
                active_options.visualization_end_year,
            );
            if (timeline_state.resume_position) |position| {
                const before_target = pass.execution_iteration < position.execution_iteration or
                    (pass.execution_iteration == position.execution_iteration and pass.scenario_index < position.scenario_index) or
                    (pass.execution_iteration == position.execution_iteration and pass.scenario_index == position.scenario_index and pass.scenario_iteration < position.scenario_iteration) or
                    (pass.execution_iteration == position.execution_iteration and pass.scenario_index == position.scenario_index and pass.scenario_iteration == position.scenario_iteration and pass.scene_index < position.scene_index);
                if (before_target) continue;
                if (pass.execution_iteration != position.execution_iteration or pass.scenario_index != position.scenario_index or pass.scenario_iteration != position.scenario_iteration or pass.scene_index != position.scene_index) return error.CheckpointTimelinePositionNotInRunscript;
            }
            const active_iteration_limits = try ecosys.iteration_control.Limits.fromSceneOptions(active_options, driver_context.runscript.*.max_nonlinear_iterations);
            driver_context.hourly_science_context.*.iteration_limits = active_iteration_limits;
            driver_context.hourly_science_context.*.surface_energy_solver_options.max_iterations = active_iteration_limits.water_heat_solute_max_iterations;

            const weather_assignment = driver_context.scene_weather_assignments.*[pass.scene_index];
            const weather_streams = try driver_context.allocator.*.alloc(
                *ecosys.weather.WeatherStream,
                weather_assignment.unique_file_names.len,
            );
            defer driver_context.allocator.*.free(weather_streams);
            var opened_weather_stream_count: usize = 0;
            defer for (weather_streams[0..opened_weather_stream_count]) |stream| stream.deinit();
            const hourly_weather_streams = try driver_context.allocator.*.alloc(
                ecosys.hourly_weather_stream.Stream,
                weather_assignment.unique_file_names.len,
            );
            defer driver_context.allocator.*.free(hourly_weather_streams);
            for (
                weather_assignment.unique_file_names,
                weather_assignment.forcing_geometry_by_stream,
                0..,
            ) |weather_name, geometry, stream_index| {
                const weather_path = try resolveSiblingInputPath(
                    driver_context.allocator.*,
                    driver_context.init.*.io,
                    driver_context.runscript_directory.*,
                    driver_context.scene_weather_grid_paths.*[pass.scene_index],
                    weather_name,
                );
                defer driver_context.allocator.*.free(weather_path);
                weather_streams[stream_index] = ecosys.weather.WeatherStream.init(
                    driver_context.allocator.*,
                    driver_context.init.*.io,
                    weather_path,
                    64 * 1024,
                ) catch |err| {
                    std.log.err("weather stream open failed: execution={d} scenario={d} scenario_repeat={d} scene={d} file='{s}' error={s}", .{ pass.execution_iteration + 1, pass.scenario_index + 1, pass.scenario_iteration + 1, pass.scene_index + 1, weather_name, @errorName(err) });
                    return err;
                };
                driver_context.hourly_science_context.*.restoring_checkpoint = false;
                opened_weather_stream_count += 1;
                hourly_weather_streams[stream_index] = try ecosys.hourly_weather_stream.Stream.init(
                    weather_streams[stream_index],
                    geometry.altitude_m,
                    geometry.latitude_degrees_north,
                    geometry.phytotron,
                    .{
                        .snowfall_temperature_threshold_c = active_options.snowfall_temperature_threshold_c,
                        .minimum_snowfall_water_equivalent_m = active_options.minimum_snowfall_water_equivalent_m,
                    },
                );
            }
            if (!timeline_state.initial_snow_chemistry_initialized) {
                const concentration_by_cell = try driver_context.allocator.*.alloc(
                    ecosys.snow_solute_transport.InitialChemicalConcentrations,
                    driver_context.state.*.cell_count,
                );
                defer driver_context.allocator.*.free(concentration_by_cell);
                for (concentration_by_cell, 0..) |*concentration, cell| {
                    concentration.* = .{
                        .primary_g_per_m3 = [_]f64{0} ** ecosys.snow_solute_transport.primary_species_count,
                        .static_ion_g_per_m3 = [_]f64{0} ** ecosys.snow_solute_transport.static_ion_species_count,
                        .salt_mol_per_m3 = [_]f64{0} ** ecosys.snow_solute_transport.salt_species_count,
                    };
                    const first = cell * driver_context.snow_transport_state.*.layer_capacity;
                    var has_initial_snow = false;
                    for (
                        driver_context.snow_transport_state.*.heat_capacity_megajoules_per_k[first..][0..driver_context.snow_transport_state.*.layer_capacity],
                        driver_context.snow_transport_state.*.horizontal_area_m2[first..][0..driver_context.snow_transport_state.*.layer_capacity],
                    ) |heat_capacity, area_m2| {
                        if (heat_capacity > ecosys.snow_solute_transport.activation_heat_capacity_megajoules_per_m2_k * area_m2) {
                            has_initial_snow = true;
                            break;
                        }
                    }
                    // STARTE's VHCPW gate makes zero-depth cells exact no-ops;
                    // do not run a chemically irrelevant nonlinear solve.
                    if (!has_initial_snow) continue;
                    const stream_index = weather_assignment.stream_index_by_cell[cell];
                    if (stream_index >= weather_streams.len)
                        return error.WeatherGridStreamIndexOutOfRange;
                    const header = weather_streams[stream_index].header;
                    var atmospheric_gas_g_per_m3: [5]f64 = undefined;
                    for (&atmospheric_gas_g_per_m3, 0..) |*value, species|
                        value.* = driver_context.initial_atmospheric_gas_concentration_g_per_m3.*[cell * ecosys.gas_transport.species_count + species];
                    const dissolved_gas_g_per_m3 = try ecosys.snow_chemistry_initialization.initialPrecipitationDissolvedGasGPerM3(
                        atmospheric_gas_g_per_m3,
                        driver_context.mean_annual_temperature_k_by_cell.*[cell],
                        driver_context.surface_gas_parameters.*.solubility,
                        driver_context.surface_gas_parameters.*.precipitation_activity_log,
                    );
                    concentration.* = try ecosys.snow_chemistry_initialization.equilibrate(
                        driver_context.allocator.*,
                        .{
                            .precipitation_ph = header.precipitation_ph,
                            .dissolved_gas_g_per_m3 = dissolved_gas_g_per_m3,
                            .ammonium_g_n_per_m3 = header.precipitation_ammonium_g_per_m3,
                            .nitrate_g_n_per_m3 = header.precipitation_nitrate_g_per_m3,
                            .phosphate_g_p_per_m3 = header.precipitation_phosphate_g_per_m3,
                            .free_ion_g_per_m3 = .{
                                header.precipitation_aluminum_g_per_m3,
                                header.precipitation_iron_g_per_m3,
                                header.precipitation_calcium_g_per_m3,
                                header.precipitation_magnesium_g_per_m3,
                                header.precipitation_sodium_g_per_m3,
                                header.precipitation_potassium_g_per_m3,
                                header.precipitation_sulfate_sulfur_g_per_m3,
                                header.precipitation_chloride_g_per_m3,
                            },
                            .molar_mass_g_per_mol = driver_context.runscript.*.chemistry_primary_initialization.molar_mass_g_per_mol,
                        },
                        driver_context.chemistry_reaction_parameters.*,
                        .{
                            .absolute_tolerance_mol_per_m3 = driver_context.config.*.nonlinear_tolerance.reaction_mol_per_m3,
                            .absolute_tolerance_mol_per_megagram = driver_context.config.*.nonlinear_tolerance.reaction_mol_per_megagram,
                            .relative_tolerance = driver_context.config.*.nonlinear_tolerance.relative,
                            .picard_relaxation = driver_context.config.*.picard_relaxation,
                            .max_iterations = active_iteration_limits.initial_solute_reaction_max_iterations,
                        },
                    );
                }
                try ecosys.snow_solute_transport.initializeChemicalState(
                    &driver_context.snow_transport_state.*,
                    concentration_by_cell,
                    driver_context.salinity_enabled_by_cell.*,
                    driver_context.runscript.*.snow_ice_density_megagrams_per_m3,
                    ecosys.snow_solute_transport.activation_heat_capacity_megajoules_per_m2_k,
                );
                timeline_state.initial_snow_chemistry_initialized = true;
            }
            const solar_noon_hour_by_cell = try driver_context.allocator.*.alloc(u8, driver_context.state.*.cell_count);
            defer driver_context.allocator.*.free(solar_noon_hour_by_cell);
            for (solar_noon_hour_by_cell, 0..) |*solar_noon, cell| {
                const stream_index = weather_assignment.stream_index_by_cell[cell];
                if (stream_index >= weather_streams.len)
                    return error.WeatherGridStreamIndexOutOfRange;
                const value = weather_streams[stream_index].header.solar_noon_hour;
                if (!std.math.isFinite(value) or value < 0 or value >= 25)
                    return error.InvalidHourlyFertilizerSchedule;
                solar_noon.* = @intFromFloat(@trunc(value));
            }
            const weather_hour_by_stream = try driver_context.allocator.*.alloc(
                ecosys.hourly_weather_stream.Observation,
                hourly_weather_streams.len,
            );
            defer driver_context.allocator.*.free(weather_hour_by_stream);
            var previous_weather_timestamp: ?ecosys.weather.Timestamp = null;
            var resolved_development_year: ?u16 = null;
            var dormant_seed_branches: std.ArrayList(ecosys.plant_harvest_runtime.SourceOrderDormantSeedBranch) = .empty;
            defer dormant_seed_branches.deinit(driver_context.allocator.*);
            var scene_weather_hours: usize = 0;
            if (timeline_state.resume_position) |position| {
                // The manifest stores an accepted-hour count. Consume exactly
                // that many records so the next stream record is the first
                // hour not represented by the restored state.
                const completed_scene_hours = std.math.cast(usize, position.completed_scene_hours) orelse return error.CheckpointSceneHourExceedsRuntimeCounter;
                for (0..completed_scene_hours) |_| {
                    for (hourly_weather_streams, 0..) |*stream, stream_index| {
                        var skipped = try stream.next() orelse return error.CheckpointSceneHourExceedsWeatherStream;
                        skipped.timestamp = try skipped.timestamp.modelHour(active_options.start_date.year);
                        if (stream_index == 0) {
                            previous_weather_timestamp = skipped.timestamp;
                        } else if (!sameWeatherTimestamp(previous_weather_timestamp.?, skipped.timestamp)) {
                            return error.WeatherGridTimestampMismatch;
                        }
                    }
                }
                const checkpoint_timestamp = previous_weather_timestamp orelse return error.CheckpointHasNoCompletedWeatherHour;
                const checkpoint_year = checkpoint_timestamp.year orelse active_options.start_date.year;
                const checkpoint_day = checkpoint_timestamp.day_of_year orelse return error.CheckpointWeatherRequiresDayOfYear;
                const checkpoint_hour = try checkpoint_timestamp.modelHourIndex();
                if (checkpoint_year != position.year or checkpoint_day != position.day_of_year or checkpoint_hour != position.hour) return error.CheckpointWeatherTimestampMismatch;
                // The weather source can legitimately omit its year. Keep the
                // accepted-hour cursor self-contained after verification so a
                // midnight resume can label/close the previous day before the
                // next observation becomes the new cursor.
                previous_weather_timestamp = withWeatherYear(previous_weather_timestamp.?, checkpoint_year);
                scene_weather_hours = completed_scene_hours;
                timeline_state.resume_position = null;
            }
            // EXEC IBEGIN/ISTART reset: establish a new seven-domain
            // reference only at a fresh scene boundary. A resumed scene keeps
            // the checkpointed monitor and cumulative boundary history.
            if (scene_weather_hours == 0) {
                if (shouldSeedStarteChemistryAtSceneStart(timeline_state.executed_scene_passes)) {
                    // Sync gas_transport dissolved CO2 and micropore solutes
                    // from STARTE-equilibrated chemistry exactly once, before
                    // the first EXEC baseline. Later scenes inherit the live
                    // authoritative transport owners. Reapplying this seed at
                    // every scene boundary overwrites evolved dissolved CO2
                    // and creates an unbooked carbon source.
                    for (0..driver_context.state.*.cell_count) |_sync_cell| {
                        const _sync_first = _sync_cell * driver_context.state.*.soil_layer_capacity;
                        for (0..driver_context.state.*.active_soil_layer_count[_sync_cell]) |_sync_local| {
                            const _sync_layer = _sync_first + _sync_local;
                            const _sync_water = driver_context.state.*.matrix_liquid_water_m3[_sync_layer];
                            if (_sync_water <= driver_context.config.*.physical_tolerance.waterVolume(_sync_water)) continue;
                            const _sync_co2_idx = try ecosys.gas_transport.massIndex(_sync_layer, .carbon_dioxide, driver_context.gas_transport_state.*.cell_count);
                            driver_context.gas_transport_state.*.dissolved_mass_g[_sync_co2_idx] = driver_context.initial_chemistry_state.*.aqueous[_sync_layer].carbon_dioxide * 12.0 * _sync_water;
                        }
                    }
                    try ecosys.soil_aqueous_transport_bridge.exportChemistry(
                        &driver_context.initial_chemistry_state.*,
                        &driver_context.micropore_solute_state.*,
                        &driver_context.fertilizer_band_state.*,
                    );
                }
                const totals = try reconstructLandscapeMassBalance(
                    driver_context.hourly_science_context.*,
                );
                {
                    const area = totals.landscape_area_m2;
                    const b = try ecosys.mass_balance_audit.balance(totals);
                    std.log.debug("carbon baseline: residue={e} organic={e} co2={e} co2in={e} co2out={e} fert={e} sink={e} total_g_m2={e}", .{ totals.residue_carbon_g / area, totals.organic_carbon_g / area, totals.carbon_dioxide_carbon_g / area, totals.cumulative_carbon_dioxide_input_g / area, totals.cumulative_carbon_output_g / area, totals.cumulative_organic_fertilizer_carbon_g / area, totals.cumulative_carbon_sink_g / area, b.carbon_g / area });
                    std.log.debug("nitrogen baseline: residue={e} organic={e} n2={e} nh4={e} no3={e} n2in={e} nin={e} nout={e} fert={e} sink={e} root_uptake={e} root_exudate={e} total_g_m2={e}", .{ totals.residue_nitrogen_g / area, totals.organic_nitrogen_g / area, totals.dinitrogen_nitrogen_g / area, totals.ammonium_nitrogen_g / area, totals.nitrate_nitrogen_g / area, totals.cumulative_dinitrogen_input_g / area, totals.cumulative_nitrogen_input_g / area, totals.cumulative_nitrogen_output_g / area, totals.cumulative_organic_fertilizer_nitrogen_g / area, totals.cumulative_nitrogen_sink_g / area, totals.cumulative_plant_root_organic_nitrogen_uptake_g / area, totals.cumulative_plant_root_organic_nitrogen_exudate_g / area, b.nitrogen_g / area });
                    // EXEC-003: the oxygen baseline is captured after STARTE
                    // gas seeding, so a nonzero value here confirms seeding ran
                    // and any later climb is genuine accumulation, not fill-in.
                    std.log.debug("oxygen baseline: storage={e} storage_g_m2={e} area_m2={e}", .{ totals.oxygen_storage_g, totals.oxygen_storage_g / area, area });
                }
                if (driver_context.landscape_mass_balance_state.*.monitor) |*monitor|
                    try monitor.reset(totals)
                else
                    driver_context.landscape_mass_balance_state.*.monitor =
                        try ecosys.mass_balance_audit.Monitor.init(
                            totals,
                            driver_context.config.*.mass_balance_absolute_tolerance,
                            driver_context.config.*.mass_balance_relative_tolerance,
                        );
            } else if (driver_context.landscape_mass_balance_state.*.monitor == null) {
                return error.CheckpointResumeMissingMassBalanceMonitor;
            }
            const scene_expected_hours = try std.math.mul(usize, try ecosys.simulation_timeline.inclusiveDays(active_options.start_date, active_options.end_date), 24);
            // HEAT-001: per-hour closure against THIS hour's own boundary
            // bookings, not the day's. `hourly heat closure` (below, existing)
            // reads the boundary ledger before this hour's own
            // `accumulateAcceptedSurfaceAndCanopyHeat`/`accumulateAcceptedSignedHeat`
            // calls land, so it lags storage by one hour and cannot localise a
            // sub-daily defect (see docs/traceability/heat_001_scaled_closure_criterion.md).
            // These five track the previous hour's fully-booked snapshot so
            // the delta below is taken between two equally-complete points.
            const heat_closure_initial_totals = try reconstructLandscapeMassBalance(driver_context.hourly_science_context.*);
            const heat_closure_initial_boundary = driver_context.landscape_mass_balance_state.*.boundary_ledger.cumulative;
            var heat_closure_previous_storage_megajoules = heat_closure_initial_totals.heat_storage_megajoules;
            var heat_closure_previous_cumulative_input_megajoules = heat_closure_initial_boundary.heat_input_megajoules;
            var heat_closure_previous_cumulative_output_megajoules = heat_closure_initial_boundary.heat_output_megajoules;
            var heat_closure_previous_cumulative_internal_production_megajoules = heat_closure_initial_totals.cumulative_internal_heat_production_megajoules;
            var heat_closure_previous_cumulative_internal_consumption_megajoules = heat_closure_initial_totals.cumulative_internal_heat_consumption_megajoules;
            const advance_hour_context = .{
                .active_iteration_limits = &active_iteration_limits,
                .active_options = &active_options,
                .dormant_seed_branches = &dormant_seed_branches,
                .heat_closure_previous_cumulative_input_megajoules = &heat_closure_previous_cumulative_input_megajoules,
                .heat_closure_previous_cumulative_internal_consumption_megajoules = &heat_closure_previous_cumulative_internal_consumption_megajoules,
                .heat_closure_previous_cumulative_internal_production_megajoules = &heat_closure_previous_cumulative_internal_production_megajoules,
                .heat_closure_previous_cumulative_output_megajoules = &heat_closure_previous_cumulative_output_megajoules,
                .heat_closure_previous_storage_megajoules = &heat_closure_previous_storage_megajoules,
                .hourly_weather_streams = &hourly_weather_streams,
                .pass = &pass,
                .previous_weather_timestamp = &previous_weather_timestamp,
                .resolved_development_year = &resolved_development_year,
                .scene = &scene,
                .scene_expected_hours = &scene_expected_hours,
                .scene_weather_hours = &scene_weather_hours,
                .solar_noon_hour_by_cell = &solar_noon_hour_by_cell,
                .weather_assignment = &weather_assignment,
                .weather_hour_by_stream = &weather_hour_by_stream,
                .weather_streams = &weather_streams,
            };
            while (scene_weather_hours < scene_expected_hours) {
                const hour_start_timestamp = std.Io.Clock.now(.boot, driver_context.init.*.io);
                const day_of_year_before: ?u16 =
                    if (previous_weather_timestamp) |stamp| stamp.day_of_year else null;
                // Announce the hour BEFORE the hour runs, so stage-layer sites
                // can call `recordCurrent` and get this hour rather than the
                // previous one. `scene_weather_hours` counts completed hours,
                // so the hour about to run is one past it.
                driver_context.stage_census.*.observeHour(@intCast(scene_weather_hours + 1));
                try advanceHour(driver_context, &timeline_state, &advance_hour_context);
                recordHourStageExecution(
                    driver_context.stage_census,
                    scene_weather_hours,
                    day_of_year_before,
                    if (previous_weather_timestamp) |stamp| stamp.day_of_year else null,
                );
                const hour_elapsed_ms = hour_start_timestamp.durationTo(std.Io.Clock.now(.boot, driver_context.init.*.io)).toMilliseconds();
                // Keep default production progress visible at each accepted
                // day boundary. Per-hour timing remains available in debug
                // builds without forcing two synchronous writes and a run-log
                // flush for every simulated hour.
                //
                // PERF_HOUR_TRACE (run-006, temporary profiling instrumentation):
                // when `--verbose-diagnostics` is passed, also surface every
                // non-day-boundary hour's elapsed_ms at `info` level so a
                // profiling pass can reconstruct a full per-hour timing series
                // without a ReleaseSafe/Debug rebuild. Off by default (identical
                // to the pre-existing `debug`-only behavior); read-only
                // `run_support.verbose_diagnostics_enabled` gate, no state or
                // output change. Candidate for removal or promotion once the
                // retry-ladder profiling this supports is complete.
                if (scene_weather_hours % 24 == 0)
                    std.log.info("day advanced: scene_weather_hours={d} final_hour_elapsed_ms={d}", .{ scene_weather_hours, hour_elapsed_ms })
                else if (run_support.verbose_diagnostics_enabled)
                    std.log.info("PERF_HOUR_TRACE scene_weather_hours={d} elapsed_ms={d}", .{ scene_weather_hours, hour_elapsed_ms })
                else
                    std.log.debug("hour advanced: scene_weather_hours={d} elapsed_ms={d}", .{ scene_weather_hours, hour_elapsed_ms });
            }
            if (scene_weather_hours == 0) return error.EmptyWeatherStream;
            // A scene finished, so the boundary between it and the next one is
            // a scene transition; and completing a scene pass is a forcing
            // repeat transition. Recorded here rather than in the hourly loop
            // because this is where the transition actually occurs.
            driver_context.stage_census.*.record(.scene_transition, @intCast(scene_weather_hours));
            timeline_state.executed_scene_passes = try std.math.add(usize, timeline_state.executed_scene_passes, 1);
            if (timeline_state.executed_scene_passes > 1)
                driver_context.stage_census.*.record(.forcing_repeat_transition, @intCast(scene_weather_hours));
        }
    }
    try finishTimeline(driver_context, &timeline_state);
    if (timeline_state.execution_journal) |active_journal| try active_journal.finish();
}

noinline fn reportTimelineExecutor(
    executor: ecosys.compute.CpuExecutor,
    parallel_dispatches_before_timeline: u64,
) !void {
    const after = executor.statistics();
    if (after.parallel_dispatches < parallel_dispatches_before_timeline)
        return error.ExecutorParallelDispatchCounterRegressed;
    std.log.info(
        "executor summary: requested_threads={d} effective_threads={d} background_threads={d} maximum_owned_tile_cells={d} timeline_parallel_dispatches={d}",
        .{
            after.requested_threads,
            after.effective_threads,
            after.background_threads,
            after.maximum_tile_cells,
            after.parallel_dispatches - parallel_dispatches_before_timeline,
        },
    );
}

/// Stable main-frame owners produced by the input/domain planning phase.
/// Cleanup entries are registered against these fields only after the struct
/// itself has reached its final address in `main`; no entry points into the
/// initializer's stack frame.
const RunPlanOwners = struct {
    source: []u8,
    runscript: ecosys.runscript.RunScript,
    runscript_own_directory: []const u8,
    runscript_directory: []u8,
    organic_parameter_path: []u8,
    organic_parameter_source: []u8,
    organic_parameters: ecosys.soil_organic_parameters.OwnedParameters,
    surface_gas_parameter_path: []u8,
    surface_gas_parameter_source: []u8,
    surface_gas_parameters: ecosys.surface_gas_parameters.Parameters,
    soil_nitrogen_parameter_path: []u8,
    soil_nitrogen_parameter_source: []u8,
    soil_nitrogen_parameters: ecosys.soil_nitrogen_parameters.Parameters,
    chemistry_reaction_parameter_path: []u8,
    chemistry_reaction_parameter_source: []u8,
    chemistry_reaction_parameters: ecosys.soil_chemistry_parameters.Parameters,
    grid_input_path: []u8,
    grid_input_source: []u8,
    geospatial_grid: ecosys.spatial_grid.RegularGrid,
    grid_input_files: ecosys.grid_input_files.CellFiles,
    site_catalog: ecosys.site_catalog.Catalog,
    grid_environment: ecosys.grid_environment.Assignments,
    lateral_connection_mode_by_cell: []u8,
    tile_plan: ecosys.spatial_grid.TilePlan,
    topography: ecosys.topography.Topography,
    unit_by_cell: []usize,
    terrain_hydrology_state: ecosys.terrain_hydrology.State,
    surface_runoff_state: ecosys.surface_runoff.State,
    surface_pond_transition_state: ecosys.surface_pond_transition_step.State,
    surface_inorganic_nitrogen_export_g_n_per_h: []f64,
    surface_inorganic_phosphorus_export_g_p_per_h: []f64,
    surface_organic_carbon_export_g_c_per_h: []f64,
    surface_inorganic_carbon_export_g_c_per_h: []f64,
    surface_dissolved_oxygen_export_g_o_per_h: []f64,
    surface_organic_nitrogen_export_g_n_per_h: []f64,
    surface_organic_phosphorus_export_g_p_per_h: []f64,
    surface_erosion_state: ecosys.soil_erosion.RuntimeState,
    surface_soil_mass_at_erosion_start_megagrams: []f64,
    net_sediment_megagrams_per_h: []f64,
    eroded_mineral_state: ecosys.soil_erosion_mineral_bridge.State,
    soil_catalog: ecosys.soil_catalog.Catalog,
    catalog_index_by_cell: []usize,
    scene_options: []ecosys.options.SceneOptions,
    weather_forcing_geometry_by_cell: []ecosys.weather_grid.ForcingGeometry,
    scene_weather_assignments: []ecosys.weather_grid.Assignments,
    scene_weather_grid_paths: [][]u8,
    resolved_weather_grid_paths: usize,
    initialized_scene_weather_assignments: usize,
    total_weather_records: usize,
    iteration_limits: ecosys.iteration_control.Limits,
    timeline: ecosys.simulation_timeline.Summary,
};

noinline fn initializeRunPlan(
    owners: *RunPlanOwners,
    resources: *MainResources,
    allocator: std.mem.Allocator,
    io: std.Io,
    runscript_path: []const u8,
) !void {
    owners.source = try std.Io.Dir.cwd().readFileAlloc(io, runscript_path, allocator, .limited(16 * 1024 * 1024));
    resources.ownFree(&owners.source);
    owners.runscript = try ecosys.runscript.parse(allocator, owners.source);
    resources.ownDeinit(&owners.runscript);
    const runscript = &owners.runscript;
    try ecosys.soil_microbial_inventory_bridge.validateRepresentableDimensions(
        runscript.microbial_substrate_count,
        runscript.microbial_population_count,
    );
    if (runscript.geospatial_bounds == null) {
        std.log.err("missing compulsory geospatial_grid record: expected minimum/maximum latitude, minimum/maximum longitude, and latitude/longitude intervals", .{});
        return error.MissingGeospatialGridRecord;
    }
    std.log.info("runtime max_nonlinear_iterations={d} is the hard ceiling for all process solvers", .{runscript.max_nonlinear_iterations});
    owners.runscript_own_directory = std.fs.path.dirname(runscript_path) orelse ".";
    owners.runscript_directory = try std.fs.path.join(allocator, &.{ owners.runscript_own_directory, runscript.input_root });
    resources.ownFree(&owners.runscript_directory);
    owners.organic_parameter_path = try resolveInputPath(allocator, io, owners.runscript_directory, runscript.organic_initialization_file);
    resources.ownFree(&owners.organic_parameter_path);
    owners.organic_parameter_source = try std.Io.Dir.cwd().readFileAlloc(io, owners.organic_parameter_path, allocator, .limited(16 * 1024 * 1024));
    resources.ownFree(&owners.organic_parameter_source);
    owners.organic_parameters = try ecosys.soil_organic_parameters.parse(allocator, owners.organic_parameter_source);
    resources.ownDeinit(&owners.organic_parameters);
    owners.surface_gas_parameter_path = try resolveInputPath(allocator, io, owners.runscript_directory, runscript.surface_gas_parameter_file);
    resources.ownFree(&owners.surface_gas_parameter_path);
    owners.surface_gas_parameter_source = try std.Io.Dir.cwd().readFileAlloc(io, owners.surface_gas_parameter_path, allocator, .limited(1024 * 1024));
    resources.ownFree(&owners.surface_gas_parameter_source);
    owners.surface_gas_parameters = try ecosys.surface_gas_parameters.parse(owners.surface_gas_parameter_source);
    std.log.info("loaded runtime surface gas and microbial oxygen parameters", .{});
    owners.soil_nitrogen_parameter_path = try resolveInputPath(allocator, io, owners.runscript_directory, runscript.soil_nitrogen_parameter_file);
    resources.ownFree(&owners.soil_nitrogen_parameter_path);
    owners.soil_nitrogen_parameter_source = try std.Io.Dir.cwd().readFileAlloc(io, owners.soil_nitrogen_parameter_path, allocator, .limited(1024 * 1024));
    resources.ownFree(&owners.soil_nitrogen_parameter_source);
    owners.soil_nitrogen_parameters = try ecosys.soil_nitrogen_parameters.parse(owners.soil_nitrogen_parameter_source);
    std.log.info("loaded runtime layer-resolved soil nitrogen parameters", .{});
    owners.chemistry_reaction_parameter_path = try resolveInputPath(allocator, io, owners.runscript_directory, runscript.chemistry_reaction_file);
    resources.ownFree(&owners.chemistry_reaction_parameter_path);
    owners.chemistry_reaction_parameter_source = try std.Io.Dir.cwd().readFileAlloc(io, owners.chemistry_reaction_parameter_path, allocator, .limited(4 * 1024 * 1024));
    resources.ownFree(&owners.chemistry_reaction_parameter_source);
    owners.chemistry_reaction_parameters = try ecosys.soil_chemistry_parameters.parse(owners.chemistry_reaction_parameter_source);
    owners.grid_input_path = try resolveInputPath(
        allocator,
        io,
        owners.runscript_directory,
        runscript.grid_input_file,
    );
    resources.ownFree(&owners.grid_input_path);
    owners.grid_input_source = try std.Io.Dir.cwd().readFileAlloc(
        io,
        owners.grid_input_path,
        allocator,
        .limited(16 * 1024 * 1024),
    );
    resources.ownFree(&owners.grid_input_source);
    owners.geospatial_grid = try ecosys.spatial_grid.RegularGrid.init(
        allocator,
        runscript.geospatial_bounds orelse return error.MissingGeospatialGridRecord,
    );
    resources.ownDeinit(&owners.geospatial_grid);
    owners.grid_input_files = try ecosys.grid_input_files.CellFiles.parse(
        allocator,
        owners.grid_input_source,
        owners.geospatial_grid,
    );
    resources.ownDeinit(&owners.grid_input_files);

    try initializeDomainRunPlan(
        owners,
        resources,
        allocator,
        io,
        runscript,
    );
}

/// Stable owners for output transaction wiring and validated management/input
/// catalogs. The coordinator and grid state are initialized in place because
/// later output banks retain the coordinator address.
const OutputPlanOwners = struct {
    output_run_identity: u64,
    output_resume_manifest: ?ecosys.checkpoint_manifest.Manifest,
    output_tree: OutputTree,
    output_hour_coordinator: ecosys.output_hour_transaction.Coordinator,
    plant_assignments: ?ecosys.plant_assignment.Assignments,
    plant_unit_by_cell: ?[]usize,
    plant_catalog: ecosys.plant_catalog.Catalog,
    plant_management_catalog: ecosys.plant_management.Catalog,
    land_management_assignments: ?ecosys.land_management.Assignments,
    land_management_unit_by_cell: ?[]usize,
    disturbance_catalog: ecosys.disturbance_schedule.Catalog,
    disturbance_schedule_maps: []?ecosys.disturbance_management_dispatch.ScheduleMap,
    fertilizer_catalog: ecosys.fertilizer_schedule.Catalog,
    fertilizer_schedule_maps: []?ecosys.fertilizer_management_dispatch.ScheduleMap,
    irrigation_catalog: ecosys.irrigation_schedule.Catalog,
    irrigation_schedule_maps: []?ecosys.irrigation_management_dispatch.ScheduleMap,
    output_selection_catalog: ecosys.output_selection.Catalog,
    config: ecosys.config.SimulationConfig,
    resolved_output_editors: []?ecosys.output_editor_layout.Resolved,
    state: ecosys.grid.GridState,
    state_cleanup_index: usize,
};

noinline fn initializeOutputPlan(
    owners: *OutputPlanOwners,
    resources: *MainResources,
    allocator: std.mem.Allocator,
    io: std.Io,
    source: []const u8,
    runscript: *const ecosys.runscript.RunScript,
    runscript_own_directory: []const u8,
    runscript_directory: []const u8,
    geospatial_grid: ecosys.spatial_grid.RegularGrid,
    soil_catalog: *const ecosys.soil_catalog.Catalog,
    scene_options: []const ecosys.options.SceneOptions,
    thread_limit: ?usize,
) !void {
    var output_pass_preview = try ecosys.simulation_timeline.PassIterator.init(runscript.scenarios, runscript.execution_repeat_count);
    const output_first_pass = output_pass_preview.next() orelse return error.EmptySimulationTimeline;
    const output_resume_requested = scene_options[output_first_pass.scene_index].resume_from_checkpoint;
    owners.output_run_identity = ecosys.output_record.runIdentity(source);
    owners.output_resume_manifest = if (output_resume_requested)
        try ecosys.checkpoint_bundle_reader.readManifest(
            allocator,
            io,
            std.Io.Dir.cwd(),
            "restart.manifest",
            16 * 1024,
            .{
                .maximum_columns = try runscript.domain.columns(),
                .maximum_rows = try runscript.domain.rows(),
                .maximum_soil_layers = try soil_catalog.maximumLayerCount(),
                .maximum_snow_layers = runscript.snow_layer_bottom_depth_m.len,
                .maximum_plant_species_per_cell = runscript.plant_species_count,
                .maximum_root_axes_per_plant = runscript.root_axes_per_plant,
            },
        )
    else
        null;
    resources.ownOptionalDeinit(&owners.output_resume_manifest);
    if (owners.output_resume_manifest) |manifest| if (manifest.output.run_identity != owners.output_run_identity)
        return error.CheckpointOutputRunIdentityMismatch;
    owners.output_tree = if (output_resume_requested)
        try OutputTree.resumeCanonical(allocator, io, owners.output_resume_manifest.?.output.canonical_root)
    else
        try OutputTree.init(allocator, io, runscript_own_directory, runscript.output_root);
    resources.ownDeinit(&owners.output_tree);
    std.log.info("structured output tree ready: root='{s}' resume={}", .{ owners.output_tree.root_path, output_resume_requested });
    owners.output_hour_coordinator = try ecosys.output_hour_transaction.Coordinator.init(
        allocator,
        io,
        owners.output_tree.root,
        .{
            .carbon = owners.output_tree.carbon,
            .water = owners.output_tree.water,
            .nitrogen = owners.output_tree.nitrogen,
            .heat_energy = owners.output_tree.heat_energy,
            .phosphorus = owners.output_tree.phosphorus,
        },
        owners.output_run_identity,
        64 * 1024,
        .{},
    );
    resources.ownDeinit(&owners.output_hour_coordinator);
    owners.plant_assignments = null;
    resources.ownOptionalDeinit(&owners.plant_assignments);
    owners.plant_unit_by_cell = null;
    resources.ownOptionalFree(&owners.plant_unit_by_cell);
    owners.plant_catalog = ecosys.plant_catalog.Catalog.init(allocator);
    resources.ownDeinit(&owners.plant_catalog);
    owners.plant_management_catalog = ecosys.plant_management.Catalog.init(allocator);
    resources.ownDeinit(&owners.plant_management_catalog);
    owners.land_management_assignments = null;
    resources.ownOptionalDeinit(&owners.land_management_assignments);
    owners.land_management_unit_by_cell = null;
    resources.ownOptionalFree(&owners.land_management_unit_by_cell);
    owners.disturbance_catalog = ecosys.disturbance_schedule.Catalog.init(allocator);
    resources.ownDeinit(&owners.disturbance_catalog);
    owners.disturbance_schedule_maps = try allocator.alloc(?ecosys.disturbance_management_dispatch.ScheduleMap, runscript.scenes.len);
    @memset(owners.disturbance_schedule_maps, null);
    resources.ownOptionalDeinitSliceAndFree(&owners.disturbance_schedule_maps);
    owners.fertilizer_catalog = ecosys.fertilizer_schedule.Catalog.init(allocator);
    resources.ownDeinit(&owners.fertilizer_catalog);
    owners.fertilizer_schedule_maps = try allocator.alloc(?ecosys.fertilizer_management_dispatch.ScheduleMap, runscript.scenes.len);
    @memset(owners.fertilizer_schedule_maps, null);
    resources.ownOptionalDeinitSliceAndFree(&owners.fertilizer_schedule_maps);
    owners.irrigation_catalog = ecosys.irrigation_schedule.Catalog.init(allocator);
    resources.ownDeinit(&owners.irrigation_catalog);
    owners.irrigation_schedule_maps = try allocator.alloc(?ecosys.irrigation_management_dispatch.ScheduleMap, runscript.scenes.len);
    @memset(owners.irrigation_schedule_maps, null);
    resources.ownOptionalDeinitSliceAndFree(&owners.irrigation_schedule_maps);
    owners.output_selection_catalog = ecosys.output_selection.Catalog.init(allocator);
    resources.ownDeinit(&owners.output_selection_catalog);
    for (runscript.scenes, 0..) |scene, scene_index| for (scene.output_editors) |editor_name| {
        if (ecosys.delimited_input.isNo(editor_name) or owners.output_selection_catalog.find(editor_name) != null) continue;
        const path = try resolveInputPath(allocator, io, runscript_directory, editor_name);
        defer allocator.free(path);
        const editor_source = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .limited(16 * 1024 * 1024));
        defer allocator.free(editor_source);
        _ = owners.output_selection_catalog.appendFromSource(editor_name, editor_source) catch |err| {
            std.log.err("scene {d} output-selection validation failed for '{s}'", .{ scene_index + 1, editor_name });
            return err;
        };
    };
    if (!ecosys.delimited_input.isNo(runscript.scenes[0].land_management)) {
        const management_path = try resolveInputPath(allocator, io, runscript_directory, runscript.scenes[0].land_management);
        defer allocator.free(management_path);
        const management_source = try std.Io.Dir.cwd().readFileAlloc(io, management_path, allocator, .limited(16 * 1024 * 1024));
        defer allocator.free(management_source);
        owners.land_management_assignments = try ecosys.land_management.parse(
            allocator,
            management_source,
            geospatial_grid,
        );
        owners.land_management_unit_by_cell = try owners.land_management_assignments.?.buildCellUnitMap(allocator);
        for (owners.land_management_assignments.?.units) |unit| {
            if (!ecosys.delimited_input.isNo(unit.tillage_file) and owners.disturbance_catalog.find(unit.tillage_file) == null) {
                const path = try resolveSiblingInputPath(allocator, io, runscript_directory, management_path, unit.tillage_file);
                defer allocator.free(path);
                const schedule_source = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .limited(64 * 1024 * 1024));
                defer allocator.free(schedule_source);
                _ = try owners.disturbance_catalog.appendFromSource(unit.tillage_file, schedule_source);
            }
            if (!ecosys.delimited_input.isNo(unit.fertilizer_file) and owners.fertilizer_catalog.find(unit.fertilizer_file) == null) {
                const path = try resolveSiblingInputPath(allocator, io, runscript_directory, management_path, unit.fertilizer_file);
                defer allocator.free(path);
                const schedule_source = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .limited(64 * 1024 * 1024));
                defer allocator.free(schedule_source);
                _ = try owners.fertilizer_catalog.appendFromSource(unit.fertilizer_file, schedule_source);
            }
            if (!ecosys.delimited_input.isNo(unit.irrigation_file) and owners.irrigation_catalog.find(unit.irrigation_file) == null) {
                const path = try resolveSiblingInputPath(allocator, io, runscript_directory, management_path, unit.irrigation_file);
                defer allocator.free(path);
                const schedule_source = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .limited(64 * 1024 * 1024));
                defer allocator.free(schedule_source);
                _ = try owners.irrigation_catalog.appendFromSource(unit.irrigation_file, schedule_source);
            }
        }
        owners.fertilizer_schedule_maps[0] = try ecosys.fertilizer_management_dispatch.ScheduleMap.init(allocator, owners.land_management_assignments.?, owners.land_management_unit_by_cell.?, owners.fertilizer_catalog);
        owners.disturbance_schedule_maps[0] = try ecosys.disturbance_management_dispatch.ScheduleMap.init(allocator, owners.land_management_assignments.?, owners.land_management_unit_by_cell.?, owners.disturbance_catalog);
        owners.irrigation_schedule_maps[0] = try ecosys.irrigation_management_dispatch.ScheduleMap.init(allocator, owners.land_management_assignments.?, owners.land_management_unit_by_cell.?, owners.irrigation_catalog);
    }
    if (!ecosys.delimited_input.isNo(runscript.scenes[0].plant_management)) {
        const plant_assignment_path = try resolveInputPath(allocator, io, runscript_directory, runscript.scenes[0].plant_management);
        defer allocator.free(plant_assignment_path);
        const plant_assignment_source = try std.Io.Dir.cwd().readFileAlloc(io, plant_assignment_path, allocator, .limited(16 * 1024 * 1024));
        defer allocator.free(plant_assignment_source);
        owners.plant_assignments = try ecosys.plant_assignment.parse(
            allocator,
            plant_assignment_source,
            geospatial_grid,
        );
        owners.plant_unit_by_cell = try owners.plant_assignments.?.buildCellUnitMap(allocator, runscript.plant_species_count);
        for (owners.plant_assignments.?.units) |unit| for (unit.species) |species| {
            if (owners.plant_catalog.find(species.species_file) == null) {
                const traits_path = try resolveSiblingInputPath(allocator, io, runscript_directory, plant_assignment_path, species.species_file);
                defer allocator.free(traits_path);
                const traits_source = try std.Io.Dir.cwd().readFileAlloc(io, traits_path, allocator, .limited(16 * 1024 * 1024));
                defer allocator.free(traits_source);
                _ = try owners.plant_catalog.appendFromSource(species.species_file, traits_source);
            }
            if (owners.plant_management_catalog.find(species.management_file) == null and !ecosys.delimited_input.isNo(species.management_file)) {
                const management_path = try resolveSiblingInputPath(allocator, io, runscript_directory, plant_assignment_path, species.management_file);
                defer allocator.free(management_path);
                const management_source = try std.Io.Dir.cwd().readFileAlloc(io, management_path, allocator, .limited(16 * 1024 * 1024));
                defer allocator.free(management_source);
                _ = try owners.plant_management_catalog.appendFromSource(species.management_file, management_source);
            }
        };
    }

    // Validate later scene assignments and populate the shared input catalogs.
    // The first scene maps remain alive for state initialization; subsequent
    // maps are checked and released immediately.
    for (runscript.scenes[1..], 1..) |scene, scene_index| {
        if (!ecosys.delimited_input.isNo(scene.land_management)) {
            const path = try resolveInputPath(allocator, io, runscript_directory, scene.land_management);
            defer allocator.free(path);
            const assignment_source = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .limited(16 * 1024 * 1024));
            defer allocator.free(assignment_source);
            var assignments = ecosys.land_management.parse(allocator, assignment_source, geospatial_grid) catch |err| {
                std.log.err("scene {d} land-management validation failed for '{s}'", .{ scene_index + 1, scene.land_management });
                return err;
            };
            defer assignments.deinit();
            const map = try assignments.buildCellUnitMap(allocator);
            defer allocator.free(map);
            for (assignments.units) |unit| {
                if (!ecosys.delimited_input.isNo(unit.tillage_file) and owners.disturbance_catalog.find(unit.tillage_file) == null) {
                    const schedule_path = try resolveSiblingInputPath(allocator, io, runscript_directory, path, unit.tillage_file);
                    defer allocator.free(schedule_path);
                    const schedule_source = try std.Io.Dir.cwd().readFileAlloc(io, schedule_path, allocator, .limited(64 * 1024 * 1024));
                    defer allocator.free(schedule_source);
                    _ = try owners.disturbance_catalog.appendFromSource(unit.tillage_file, schedule_source);
                }
                if (!ecosys.delimited_input.isNo(unit.fertilizer_file) and owners.fertilizer_catalog.find(unit.fertilizer_file) == null) {
                    const schedule_path = try resolveSiblingInputPath(allocator, io, runscript_directory, path, unit.fertilizer_file);
                    defer allocator.free(schedule_path);
                    const schedule_source = try std.Io.Dir.cwd().readFileAlloc(io, schedule_path, allocator, .limited(64 * 1024 * 1024));
                    defer allocator.free(schedule_source);
                    _ = try owners.fertilizer_catalog.appendFromSource(unit.fertilizer_file, schedule_source);
                }
                if (!ecosys.delimited_input.isNo(unit.irrigation_file) and owners.irrigation_catalog.find(unit.irrigation_file) == null) {
                    const schedule_path = try resolveSiblingInputPath(allocator, io, runscript_directory, path, unit.irrigation_file);
                    defer allocator.free(schedule_path);
                    const schedule_source = try std.Io.Dir.cwd().readFileAlloc(io, schedule_path, allocator, .limited(64 * 1024 * 1024));
                    defer allocator.free(schedule_source);
                    _ = try owners.irrigation_catalog.appendFromSource(unit.irrigation_file, schedule_source);
                }
            }
            owners.fertilizer_schedule_maps[scene_index] = try ecosys.fertilizer_management_dispatch.ScheduleMap.init(allocator, assignments, map, owners.fertilizer_catalog);
            owners.disturbance_schedule_maps[scene_index] = try ecosys.disturbance_management_dispatch.ScheduleMap.init(allocator, assignments, map, owners.disturbance_catalog);
            owners.irrigation_schedule_maps[scene_index] = try ecosys.irrigation_management_dispatch.ScheduleMap.init(allocator, assignments, map, owners.irrigation_catalog);
        }
        if (!ecosys.delimited_input.isNo(scene.plant_management)) {
            const path = try resolveInputPath(allocator, io, runscript_directory, scene.plant_management);
            defer allocator.free(path);
            const assignment_source = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .limited(16 * 1024 * 1024));
            defer allocator.free(assignment_source);
            var assignments = ecosys.plant_assignment.parse(allocator, assignment_source, geospatial_grid) catch |err| {
                std.log.err("scene {d} plant-management validation failed for '{s}'", .{ scene_index + 1, scene.plant_management });
                return err;
            };
            defer assignments.deinit();
            const map = try assignments.buildCellUnitMap(allocator, runscript.plant_species_count);
            defer allocator.free(map);
            for (assignments.units) |unit| for (unit.species) |species| {
                if (owners.plant_catalog.find(species.species_file) == null) {
                    const traits_path = try resolveSiblingInputPath(allocator, io, runscript_directory, path, species.species_file);
                    defer allocator.free(traits_path);
                    const traits_source = try std.Io.Dir.cwd().readFileAlloc(io, traits_path, allocator, .limited(16 * 1024 * 1024));
                    defer allocator.free(traits_source);
                    _ = try owners.plant_catalog.appendFromSource(species.species_file, traits_source);
                }
                if (!ecosys.delimited_input.isNo(species.management_file) and owners.plant_management_catalog.find(species.management_file) == null) {
                    const management_path = try resolveSiblingInputPath(allocator, io, runscript_directory, path, species.management_file);
                    defer allocator.free(management_path);
                    const management_source = try std.Io.Dir.cwd().readFileAlloc(io, management_path, allocator, .limited(16 * 1024 * 1024));
                    defer allocator.free(management_source);
                    _ = try owners.plant_management_catalog.appendFromSource(species.management_file, management_source);
                }
            };
        }
    }

    owners.config = try ecosys.config.SimulationConfig.init(
        .{
            .lon_count = try runscript.domain.columns(),
            .lat_count = try runscript.domain.rows(),
            .soil_layers = try soil_catalog.maximumLayerCount(),
            .plant_populations = runscript.plant_species_count,
        },
        .{ .worker_threads = thread_limit orelse runscript.worker_count, .tile_cells = runscript.tile_cell_count },
        .{
            .relative_tolerance = runscript.relative_tolerance,
            .absolute_tolerance = runscript.compatibilityLegacyAbsoluteTolerance(),
            .nonlinear_tolerance = runscript.nonlinear_tolerance,
            .mass_balance_tolerance = runscript.mass_balance_tolerance,
            .mass_balance_absolute_tolerance = runscript.mass_balance_absolute_tolerance,
            .mass_balance_relative_tolerance = runscript.mass_balance_relative_tolerance,
            .negligible_quantity_threshold = runscript.compatibilityLegacyPresenceTolerance(),
            .physical_tolerance = runscript.physical_tolerance,
            .max_nonlinear_iterations = runscript.max_nonlinear_iterations,
            .picard_relaxation = runscript.picard_relaxation,
        },
    );
    owners.resolved_output_editors = try allocator.alloc(?ecosys.output_editor_layout.Resolved, try std.math.mul(usize, runscript.scenes.len, 10));
    @memset(owners.resolved_output_editors, null);
    resources.ownOptionalDeinitSliceAndFree(&owners.resolved_output_editors);
    for (runscript.scenes, 0..) |scene, scene_index| for (scene.output_editors, 0..) |editor_name, editor_index| {
        if (ecosys.delimited_input.isNo(editor_name)) continue;
        const selection_index = owners.output_selection_catalog.find(editor_name) orelse return error.MissingOutputSelection;
        var soil_catalog_for_editor = try soilOutputCatalog(allocator, editor_index, owners.config.soil_layers);
        defer soil_catalog_for_editor.deinit();
        var plant_catalog_for_editor = try plantOutputCatalog(allocator, editor_index, owners.config.soil_layers);
        defer plant_catalog_for_editor.deinit();
        // `editor_index` selects the source slot layout: FOUTS/FOUTP slot
        // identity is per editor family, so the same slot number means
        // different variables in different editors and the layer block widths
        // differ. Passing only the catalog lengths is what let a runtime layer
        // count other than the source's silently shift every slot after the
        // first layer block. See `src/io/output/editor_layout.zig`.
        owners.resolved_output_editors[scene_index * 10 + editor_index] = try ecosys.output_editor_layout.resolve(
            allocator,
            editor_index,
            owners.output_selection_catalog.entries.items[selection_index].selection.enabled_variables,
            soil_catalog_for_editor.variables.len,
            plant_catalog_for_editor.variables.len,
        );
    };
    owners.state = try ecosys.grid.GridState.init(allocator, owners.config);
    owners.state_cleanup_index = resources.ownDeinitTracked(&owners.state);
}

