const AccountingOutputInitializationContext = struct {
    owners: *AccountingOutputOwners,
    resources: *MainResources,
    allocator: std.mem.Allocator,
    io: std.Io,
    runscript: *const ecosys.runscript.RunScript,
    scene_options: []const ecosys.options.SceneOptions,
    output_tree: *OutputTree,
    output_hour_coordinator: *ecosys.output_hour_transaction.Coordinator,
    config: ecosys.config.SimulationConfig,
    resolved_output_editors: []const ?ecosys.output_editor_layout.Resolved,
    state: *ecosys.grid.GridState,
};

noinline fn initializeAccountingVisualizationAndBaseLedgers(
    context: *const AccountingOutputInitializationContext,
) !void {
    const owners = context.owners;
    const resources = context.resources;
    const allocator = context.allocator;
    const io = context.io;
    const scene_options = context.scene_options;
    const output_tree = context.output_tree;
    const output_hour_coordinator = context.output_hour_coordinator;
    const config = context.config;
    const state = context.state;
    var any_visualization_enabled = false;
    for (scene_options) |options|
        any_visualization_enabled =
            any_visualization_enabled or options.visualization_enabled;
    owners.visualization_streams = try ecosys.visualization_output.Streams.initTransactional(
        allocator,
        io,
        output_tree.dirFor(.carbon),
        any_visualization_enabled,
        state.cell_count,
        config.plant_populations,
        config.soil_layers,
        scene_options[0].visualization_start_year,
        scene_options[0].visualization_end_year,
        64 * 1024,
        output_hour_coordinator,
    );
    resources.ownDeinit(&owners.visualization_streams);
    owners.visualization_species_respired_carbon_g =
        try allocator.alloc(f64, config.plant_populations);
    resources.ownFree(&owners.visualization_species_respired_carbon_g);
    owners.visualization_leaf_carbon_g =
        try allocator.alloc(f64, config.plant_populations);
    resources.ownFree(&owners.visualization_leaf_carbon_g);
    owners.visualization_stalk_carbon_g =
        try allocator.alloc(f64, config.plant_populations);
    resources.ownFree(&owners.visualization_stalk_carbon_g);
    owners.visualization_root_carbon_g =
        try allocator.alloc(f64, config.plant_populations);
    resources.ownFree(&owners.visualization_root_carbon_g);
    owners.visualization_root_profile_carbon_g =
        try allocator.alloc(f64, config.soil_layers);
    resources.ownFree(&owners.visualization_root_profile_carbon_g);
    owners.visualization_organic_carbon_g =
        try allocator.alloc(f64, config.soil_layers + 1);
    resources.ownFree(&owners.visualization_organic_carbon_g);
    owners.daily_soil_gas_flux = try ecosys.soil_daily_gas_flux.State.init(allocator, state.cell_count);
    resources.ownDeinit(&owners.daily_soil_gas_flux);
    // HOUR1 lines 2408-2432: per-cell hourly accumulator array (XCNET, XHNET, XONET, etc.).
    owners.hourly_accumulators = try allocator.alloc(
        ecosys.hourly_grid_cell_accumulator_reset.GridCellAccumulators,
        state.cell_count,
    );
    resources.ownFree(&owners.hourly_accumulators);
    for (owners.hourly_accumulators) |*acc| ecosys.hourly_grid_cell_accumulator_reset.reset(acc);
    owners.daily_canopy_gas_exchange = try ecosys.daily_canopy_gas_exchange.State.init(allocator, state.cell_count);
    resources.ownDeinit(&owners.daily_canopy_gas_exchange);
    owners.daily_heterotrophic_respiration = try ecosys.soil_daily_heterotrophic_respiration.State.init(allocator, state.cell_count, state.layer_count);
    resources.ownDeinit(&owners.daily_heterotrophic_respiration);
    owners.daily_carbon_export = try ecosys.soil_daily_carbon_export.State.init(allocator, state.cell_count);
    resources.ownDeinit(&owners.daily_carbon_export);
    owners.daily_phosphorus_export = try ecosys.soil_daily_phosphorus_export.State.init(allocator, state.cell_count);
    resources.ownDeinit(&owners.daily_phosphorus_export);
    owners.daily_nitrogen_export = try ecosys.soil_daily_nitrogen_export.State.init(allocator, state.cell_count);
    resources.ownDeinit(&owners.daily_nitrogen_export);
    owners.daily_water_ledger = try ecosys.soil_daily_water_ledger.State.init(allocator, state.cell_count);
    resources.ownDeinit(&owners.daily_water_ledger);
    owners.daily_heat_ledger = try ecosys.soil_daily_heat_ledger.State.init(allocator, state.cell_count, config.soil_layers);
    resources.ownDeinit(&owners.daily_heat_ledger);
    owners.landscape_mass_balance_state = .{
        .boundary_ledger = .{},
        .monitor = null,
    };
    resources.ownDeinit(&owners.landscape_mass_balance_state);
    owners.hourly_cell_boundary_ledger = try ecosys.hourly_cell_conservation.BoundaryLedger.init(
        allocator,
        state.cell_count,
    );
    resources.ownDeinit(&owners.hourly_cell_boundary_ledger);
    owners.hourly_cell_storage_before = try allocator.alloc(
        ecosys.landscape_mass_inventory.Storage,
        state.cell_count,
    );
    resources.ownFree(&owners.hourly_cell_storage_before);
    owners.hourly_cell_storage_after = try allocator.alloc(
        ecosys.landscape_mass_inventory.Storage,
        state.cell_count,
    );
    resources.ownFree(&owners.hourly_cell_storage_after);
    @memset(owners.hourly_cell_storage_before, .{});
    @memset(owners.hourly_cell_storage_after, .{});
    owners.landscape_soil_mass_megagrams_scratch = try allocator.alloc(
        f64,
        state.layer_count,
    );
    resources.ownFree(&owners.landscape_soil_mass_megagrams_scratch);
    @memset(owners.landscape_soil_mass_megagrams_scratch, 0);
}

