    @memset(owners.daily_soil_fire_carbon_dioxide_emission_g_c, 0);
    owners.daily_soil_fire_methane_emission_g_c = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.daily_soil_fire_methane_emission_g_c);
    @memset(owners.daily_soil_fire_methane_emission_g_c, 0);
    owners.daily_soil_fire_phosphorus_flux_g_p = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.daily_soil_fire_phosphorus_flux_g_p);
    @memset(owners.daily_soil_fire_phosphorus_flux_g_p, 0);
    owners.daily_soil_fire_nitrogen_flux_g_n = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.daily_soil_fire_nitrogen_flux_g_n);
    @memset(owners.daily_soil_fire_nitrogen_flux_g_n, 0);
    owners.daily_root_fire_carbon_dioxide_emission_g_c = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.daily_root_fire_carbon_dioxide_emission_g_c);
    @memset(owners.daily_root_fire_carbon_dioxide_emission_g_c, 0);
    owners.daily_root_fire_methane_emission_g_c = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.daily_root_fire_methane_emission_g_c);
    @memset(owners.daily_root_fire_methane_emission_g_c, 0);
    owners.daily_root_fire_nitrogen_flux_g_n = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.daily_root_fire_nitrogen_flux_g_n);
    @memset(owners.daily_root_fire_nitrogen_flux_g_n, 0);
    owners.daily_root_fire_phosphorus_flux_g_p = try allocator.alloc(f64, state.cell_count);
