    for (runscript.scenes, 0..) |scene, scene_index| {
        if (ecosys.delimited_input.isNo(scene.output_editors[4])) continue;
        const resolved = resolved_output_editors[scene_index * 10 + 4] orelse continue;
        hourly_plant_heat_enabled = hourly_plant_heat_enabled or std.mem.indexOfScalar(bool, resolved.plant_enabled, true) != null;
    }
    owners.hourly_plant_heat_bank = try ecosys.output_stream_bank.Bank.initTransactional(allocator, io, output_tree.dirFor(.heat_energy), hourly_plant_heat_enabled, owners.output_plant_count, owners.hourly_plant_heat_catalog.variables.len, 64 * 1024, .tab, output_hour_coordinator, .heat_energy);
    resources.ownDeinit(&owners.hourly_plant_heat_bank);
}

noinline fn initializeAccountingOutputs(
    owners: *AccountingOutputOwners,
    resources: *MainResources,
    allocator: std.mem.Allocator,
    io: std.Io,
    runscript: *const ecosys.runscript.RunScript,
    scene_options: []const ecosys.options.SceneOptions,
    output_tree: *OutputTree,
    output_hour_coordinator: *ecosys.output_hour_transaction.Coordinator,
    config: ecosys.config.SimulationConfig,
    resolved_output_editors: []const ?ecosys.output_editor_layout.Resolved,
    state: *ecosys.grid.GridState,
) !void {
    const context: AccountingOutputInitializationContext = .{
        .owners = owners,
        .resources = resources,
        .allocator = allocator,
        .io = io,
        .runscript = runscript,
        .scene_options = scene_options,
        .output_tree = output_tree,
        .output_hour_coordinator = output_hour_coordinator,
        .config = config,
        .resolved_output_editors = resolved_output_editors,
        .state = state,
    };
    try initializeAccountingVisualizationAndBaseLedgers(&context);
    try initializeAccountingDailyBalancesAndPlantState(&context);
    try initializeAccountingCarbonAndWaterOutputs(&context);
    try initializeAccountingDailyElementHeatAndDevelopmentOutputs(&context);
    try initializeAccountingHourlyElementAndHeatOutputs(&context);
    try state.validateFinite();
    try owners.plant_state.validateFinite();
}

test "accounting output initialization dispatches ordered noinline phases" {
    const allocator = std.testing.allocator;
    const source = try std.Io.Dir.cwd().readFileAlloc(
        std.testing.io,
        "src/ecosys_ng.zig",
        allocator,
        .limited(4 * 1024 * 1024),
    );
    defer allocator.free(source);

    const wrapper_start = std.mem.indexOf(
        u8,
        source,
        "noinline fn initializeAccountingOutputs(",
    ) orelse return error.MissingAccountingOutputInitializationWrapper;
    const wrapper_end = std.mem.indexOfPos(
        u8,
        source,
        wrapper_start,
        "const DomainInitializationOwners = struct",
    ) orelse return error.MissingAccountingOutputInitializationWrapperEnd;
    const wrapper = source[wrapper_start..wrapper_end];
    var previous_call: usize = 0;
    inline for (.{
        "try initializeAccountingVisualizationAndBaseLedgers(&context);",
        "try initializeAccountingDailyBalancesAndPlantState(&context);",
        "try initializeAccountingCarbonAndWaterOutputs(&context);",
        "try initializeAccountingDailyElementHeatAndDevelopmentOutputs(&context);",
        "try initializeAccountingHourlyElementAndHeatOutputs(&context);",
        "try state.validateFinite();",
        "try owners.plant_state.validateFinite();",
    }) |call| {
        const position = std.mem.indexOfPos(u8, wrapper, previous_call, call) orelse
            return error.MissingOrderedAccountingOutputInitializationPhase;
        previous_call = position + call.len;
    }
    const production_end = std.mem.indexOf(
        u8,
        source,
        "test \"accounting output initialization dispatches ordered noinline phases\"",
    ) orelse return error.MissingAccountingOutputInitializationTestBoundary;
    const production_source = source[0..production_end];
    inline for (.{
        "noinline fn initializeAccountingVisualizationAndBaseLedgers(",
        "noinline fn initializeAccountingDailyBalancesAndPlantState(",
        "noinline fn initializeAccountingCarbonAndWaterOutputs(",
        "noinline fn initializeAccountingDailyElementHeatAndDevelopmentOutputs(",
        "noinline fn initializeAccountingHourlyElementAndHeatOutputs(",
    }) |declaration| try std.testing.expectEqual(
        @as(usize, 1),
        std.mem.count(u8, production_source, declaration),
    );
}

test "accounting output phase ownership follows allocation order exactly" {
    const allocator = std.testing.allocator;
    const source = try std.Io.Dir.cwd().readFileAlloc(
        std.testing.io,
        "src/ecosys_ng.zig",
        allocator,
        .limited(4 * 1024 * 1024),
    );
    defer allocator.free(source);

    const Audit = struct {
        fn phaseBody(text: []const u8, declaration: []const u8, next_declaration: []const u8) ![]const u8 {
            const start = std.mem.indexOf(u8, text, declaration) orelse
                return error.MissingAccountingOutputInitializationPhase;
            const end = std.mem.indexOfPos(u8, text, start + declaration.len, next_declaration) orelse
                return error.MissingAccountingOutputInitializationPhaseEnd;
            return text[start..end];
        }

        fn requireOwnershipOrder(body: []const u8, expected_count: usize) !void {
            var count: usize = 0;
            var cursor: usize = 0;
            var previous_registration_end: usize = 0;
            while (std.mem.indexOfPos(u8, body, cursor, "resources.own")) |registration| {
                const field_prefix = std.mem.indexOfPos(u8, body, registration, "&owners.") orelse
                    return error.MissingAccountingOutputOwnedField;
                const field_start = field_prefix + "&owners.".len;
                const field_end = std.mem.indexOfScalarPos(u8, body, field_start, ')') orelse
                    return error.MissingAccountingOutputOwnedFieldEnd;
                const field_name = body[field_start..field_end];
                try std.testing.expect(std.mem.indexOf(
                    u8,
                    body[previous_registration_end..registration],
                    field_name,
                ) != null);
                count += 1;
                cursor = field_end + 1;
                previous_registration_end = cursor;
            }
            try std.testing.expectEqual(expected_count, count);
        }
    };

    const declarations = .{
        "noinline fn initializeAccountingVisualizationAndBaseLedgers(",
        "noinline fn initializeAccountingDailyBalancesAndPlantState(",
        "noinline fn initializeAccountingCarbonAndWaterOutputs(",
        "noinline fn initializeAccountingDailyElementHeatAndDevelopmentOutputs(",
        "noinline fn initializeAccountingHourlyElementAndHeatOutputs(",
        "noinline fn initializeAccountingOutputs(",
    };
    const expected_ownership_counts = .{ 21, 25, 17, 20, 12 };
    inline for (expected_ownership_counts, 0..) |expected, phase| {
        const body = try Audit.phaseBody(source, declarations[phase], declarations[phase + 1]);
        try Audit.requireOwnershipOrder(body, expected);
    }
}

/// Final-address owners established by the mapped domain initialization phase.
/// `MainResources` cleanup entries point directly at these fields, so this
/// value must be declared in its final `main` stack location before the
/// initializer is called and must never be returned or moved by value.
const DomainInitializationOwners = struct {
    soil_thermal_state: ecosys.soil_thermal.State,
    site_by_cell: []ecosys.site.Site,
    salinity_enabled_by_cell: []bool,
    latitude_degrees_north_by_cell: []f64,
    longitude_degrees_east_by_cell: []f64,
    initial_surface_elevation_m: []f64,
    surface_runoff_boundary_storage: []f64,
    surface_runoff_boundary_fraction_by_direction: [4][]f64,
    mean_annual_temperature_c_by_cell: []f64,
    mean_annual_temperature_k_by_cell: []f64,
    geothermal_enabled_by_cell: []bool,
    initial_atmospheric_gas_concentration_g_per_m3: []f64,
    microbial_thermal_adaptation_state: ecosys.microbial_thermal_adaptation_initialization.State,
    soil_boundary_topology_state: ecosys.soil_boundary_topology.State,
    soil_solver_property_state: ecosys.soil_solver_properties.State,
    soil_geometry_state: ecosys.soil_layer_geometry.State,
    surface_pond_domain_workspace: ecosys.surface_pond_domain_transaction.Workspace,
    soil_profile_relayering_workspace: ecosys.soil_profile_relayering.Workspace,
    fertilizer_band_layer_upper_depth_m: []f64,
    fertilizer_band_layer_lower_depth_m: []f64,
    fertilizer_band_state: ecosys.fertilizer_band_state.State,
};

const DomainInitializationInputs = struct {
    allocator: std.mem.Allocator,
    executor: ecosys.compute.CpuExecutor,
    tile_plan: *const ecosys.spatial_grid.TilePlan,
    state: *ecosys.grid.GridState,
    soil_catalog: *const ecosys.soil_catalog.Catalog,
    catalog_index_by_cell: []const usize,
    grid_environment: *const ecosys.grid_environment.Assignments,
    grid_input_files: *const ecosys.grid_input_files.CellFiles,
    site_catalog: *const ecosys.site_catalog.Catalog,
    runscript: *const ecosys.runscript.RunScript,
    terrain_hydrology_state: *ecosys.terrain_hydrology.State,
    config: ecosys.config.SimulationConfig,
    atmospheric_hydrogen_mixing_ratio_umol_per_mol: f64,
};

noinline fn initializeDomainScience(
    owners: *DomainInitializationOwners,
    resources: *MainResources,
    inputs: DomainInitializationInputs,
) !void {
    owners.soil_thermal_state = try ecosys.soil_thermal.State.initMapped(
        inputs.allocator,
        inputs.state.*,
        inputs.soil_catalog.entries.items,
        inputs.catalog_index_by_cell,
        inputs.grid_environment.horizontal_cell_width_m,
        inputs.grid_environment.vertical_cell_width_m,
    );
    resources.ownDeinit(&owners.soil_thermal_state);
    var initialization_context = ecosys.model_initialization.MappedHydrologyContext{
        .grid = inputs.state,
        .catalog_entries = inputs.soil_catalog.entries.items,
        .catalog_index_by_cell = inputs.catalog_index_by_cell,
        .horizontal_cell_width_m = inputs.grid_environment.horizontal_cell_width_m,
        .vertical_cell_width_m = inputs.grid_environment.vertical_cell_width_m,
        .ice_density_megagrams_per_m3 = inputs.runscript.soil_phase_heat_parameters.freeze_thaw.ice_density_megagrams_per_m3,
    };
    try runKernelAcrossSerialTilePlan(
        inputs.executor,
        inputs.tile_plan,
        &initialization_context,
        ecosys.model_initialization.initializeMappedHydrologyTile,
    );
    owners.site_by_cell = try inputs.allocator.alloc(ecosys.site.Site, inputs.state.cell_count);
    resources.ownFree(&owners.site_by_cell);
    for (owners.site_by_cell, inputs.grid_environment.site_catalog_index_by_cell) |*selected_site, site_index|
        selected_site.* = inputs.site_catalog.entries.items[site_index].site;
    owners.salinity_enabled_by_cell = try inputs.allocator.alloc(bool, inputs.state.cell_count);
    resources.ownFree(&owners.salinity_enabled_by_cell);
    for (owners.site_by_cell, owners.salinity_enabled_by_cell) |selected_site, *enabled|
        enabled.* = selected_site.salinity_enabled;
    // A cell's coordinate is stated once, in the grid-cell mapping, and is
    // read from there by everything that needs it: solar geometry, daylength,
    // and the coordinate stamped into every output filename and record. The
    // site file no longer carries it, so a site can be reused verbatim at any
    // location without editing the file.
    owners.latitude_degrees_north_by_cell = inputs.grid_input_files.latitude_degrees_north_by_cell;
    owners.longitude_degrees_east_by_cell = inputs.grid_input_files.longitude_degrees_east_by_cell;
    if (owners.latitude_degrees_north_by_cell.len != inputs.state.cell_count or
        owners.longitude_degrees_east_by_cell.len != inputs.state.cell_count)
        return error.GeospatialGridEnvironmentDimensionMismatch;
    owners.initial_surface_elevation_m = try inputs.allocator.alloc(f64, inputs.state.cell_count);
    resources.ownFree(&owners.initial_surface_elevation_m);
    for (owners.site_by_cell, owners.initial_surface_elevation_m) |selected_site, *elevation_m|
        elevation_m.* = selected_site.elevation_m;
    try inputs.terrain_hydrology_state.bindInitialSurfaceElevations(owners.initial_surface_elevation_m);
    owners.surface_runoff_boundary_storage = try inputs.allocator.alloc(
        f64,
        try std.math.mul(usize, inputs.state.cell_count, 4),
    );
    resources.ownFree(&owners.surface_runoff_boundary_storage);
    owners.mean_annual_temperature_c_by_cell = try inputs.allocator.alloc(f64, inputs.state.cell_count);
    resources.ownFree(&owners.mean_annual_temperature_c_by_cell);
    owners.mean_annual_temperature_k_by_cell = try inputs.allocator.alloc(f64, inputs.state.cell_count);
    resources.ownFree(&owners.mean_annual_temperature_k_by_cell);
    owners.geothermal_enabled_by_cell = try inputs.allocator.alloc(bool, inputs.state.cell_count);
    resources.ownFree(&owners.geothermal_enabled_by_cell);
    owners.surface_runoff_boundary_fraction_by_direction = [4][]f64{
        owners.surface_runoff_boundary_storage[0 * inputs.state.cell_count ..][0..inputs.state.cell_count],
        owners.surface_runoff_boundary_storage[1 * inputs.state.cell_count ..][0..inputs.state.cell_count],
        owners.surface_runoff_boundary_storage[2 * inputs.state.cell_count ..][0..inputs.state.cell_count],
        owners.surface_runoff_boundary_storage[3 * inputs.state.cell_count ..][0..inputs.state.cell_count],
    };
    for (owners.site_by_cell, 0..) |selected_site, cell| {
        owners.mean_annual_temperature_c_by_cell[cell] =
            selected_site.mean_annual_air_temperature_c;
        owners.mean_annual_temperature_k_by_cell[cell] =
            selected_site.mean_annual_air_temperature_c + 273.15;
        owners.geothermal_enabled_by_cell[cell] =
            inputs.runscript.geothermal_controls.enabled and selected_site.ecosystem_type != -2;
        for (0..4) |direction| {
            owners.surface_runoff_boundary_fraction_by_direction[direction][cell] =
                selected_site.surface_runoff_boundary_fraction[direction];
        }
        // STARTS lines 397--400 and 1222: `TKS(L,NY,NX)=ATKS(NY,NX)` seeds the
        // profile isothermally at the mean annual soil temperature. See
        // `seed_soil_profile_from_mean_annual` at the top of this file for the
        // measured effect on the EXEC heat audit.
        if (seed_soil_profile_from_mean_annual) {
            const initial_soil_temperature_k = selected_site.mean_annual_air_temperature_c + 273.15;
            if (!std.math.isFinite(initial_soil_temperature_k) or initial_soil_temperature_k <= 0)
                return error.InvalidInitialSoilTemperature;
            const layer_base = cell * inputs.state.soil_layer_capacity;
            for (0..inputs.state.soil_layer_capacity) |layer|
                inputs.state.soil_temperature_k[layer_base + layer] = initial_soil_temperature_k;
            // BIND-STARTS-654, source `starts.f` 659: `TKS(0,NY,NX)=ATKS(NY,NX)`.
            // This is the LAYER-0 companion of the `starts.f` 1222 seed
            // immediately above, and it was left on the `273.15 K` placeholder
            // that `grid.zig:79` installs at allocation. `273.15 K` is the
            // pure-water melting point, so every example began with its surface
            // litter sitting exactly on the ice/liquid phase boundary
            // regardless of site climate, which is the worst possible start for
            // a phase-enthalpy solver for the same reason recorded at the
            // `seed_soil_profile_from_mean_annual` declaration.
            //
            // A8 measured the placeholder error across the whole migrated
            // corpus and it FLIPS SIGN, so it cannot be corrected by an offset
            // and Ottawa is not the worst case: Ottawa `-5.40 K`, Boreal Crop
            // AB `-2.00 K`, Arctic Fen CH `+6.90 K`, Arctic Tundra IQ
            // `+9.80 K`. On the warm sites the surface started too cold; on the
            // frozen sites it held a `-9.8 C` site at the melting point, the
            // wrong side of the phase boundary for a permafrost column.
            //
            // Bound here rather than in `grid.zig` deliberately. The value is
            // `lower_soil_heat_boundary_initialization.initialize`'s
            // `surface_litter_temperature_k`, which that module sets to exactly
            // `inputs.mean_annual_soil_temperature_k` (`:108--109`), the same
            // per-cell quantity already in hand here. Seeding it at the one
            // place that already owns the mean-annual seed keeps a single
            // writer, needs no claim on the shared `src/grid.zig`, and leaves
            // `grid.zig:79`'s `@memset` as the correct allocation-time default
            // for callers that never reach site selection. Per A8's
            // recommendation this binds ONLY the surface temperature and does
            // not wire `lower_heat_source_depth_m` or `deep_source_temperature_k`,
            // which `solver.zig:498--504` and `:698--699` already
            // recompute per step from the same runscript controls, so `INIT-003`
            // is deferred entirely rather than half-answered.
            //
            // No double mutation: `surface_temperature_k` is written here before
            // any solver runs, and the hourly surface-temperature solver is its
            // only other writer, which advances this value rather than
            // establishing it. This runs before the EXEC heat baseline is
            // captured, which is the whole point: the baseline must see the
            // physical initial condition, not the placeholder.
            inputs.state.surface_temperature_k[cell] = initial_soil_temperature_k;
        }
    }
    // Initial atmosphere-derived soil, litter, snow, and plant state is
    // cell-local. A heterogeneous grid may map adjacent cells to different
    // site records; collapsing these concentrations to cell zero silently
    // changed every other cell's initial chemistry and microbial boundary.
    owners.initial_atmospheric_gas_concentration_g_per_m3 = try inputs.allocator.alloc(
        f64,
        try std.math.mul(usize, inputs.state.cell_count, ecosys.gas_transport.species_count),
    );
    resources.ownFree(&owners.initial_atmospheric_gas_concentration_g_per_m3);
    for (owners.site_by_cell, 0..) |selected_site, cell| {
        try ecosys.surface_gas_parameters.writeAtmosphericConcentrationsForCell(
            owners.initial_atmospheric_gas_concentration_g_per_m3,
            cell,
            .{
                selected_site.atmospheric_co2_umol_mol,
                selected_site.atmospheric_methane_umol_mol,
                selected_site.atmospheric_oxygen_umol_mol,
                selected_site.atmospheric_nitrogen_umol_mol,
                selected_site.atmospheric_nitrous_oxide_umol_mol,
                selected_site.atmospheric_ammonia_umol_mol,
                inputs.atmospheric_hydrogen_mixing_ratio_umol_per_mol,
            },
            owners.mean_annual_temperature_k_by_cell[cell],
        );
    }
    owners.microbial_thermal_adaptation_state = try ecosys.microbial_thermal_adaptation_initialization.State.init(
        inputs.allocator,
        owners.mean_annual_temperature_c_by_cell,
    );
    resources.ownDeinit(&owners.microbial_thermal_adaptation_state);
    owners.soil_boundary_topology_state = try ecosys.soil_boundary_topology.State.initMapped(
        inputs.allocator,
        inputs.state,
        inputs.terrain_hydrology_state,
        inputs.config.lon_count,
        inputs.config.lat_count,
        inputs.grid_environment.horizontal_cell_width_m,
        inputs.grid_environment.vertical_cell_width_m,
        owners.site_by_cell,
    );
    resources.ownDeinit(&owners.soil_boundary_topology_state);
    owners.soil_solver_property_state = try ecosys.soil_solver_properties.State.initMapped(
        inputs.allocator,
        inputs.state,
        inputs.soil_catalog.entries.items,
        inputs.catalog_index_by_cell,
        inputs.grid_environment.horizontal_cell_width_m,
        inputs.grid_environment.vertical_cell_width_m,
        inputs.runscript.soil_solver_parameters,
    );
    resources.ownDeinit(&owners.soil_solver_property_state);
    owners.soil_geometry_state = try ecosys.soil_layer_geometry.State.init(inputs.allocator, inputs.state.cell_count, inputs.config.soil_layers);
    resources.ownDeinit(&owners.soil_geometry_state);
    owners.surface_pond_domain_workspace = try ecosys.surface_pond_domain_transaction.Workspace.init(inputs.allocator, inputs.state.cell_count, inputs.config.soil_layers);
    resources.ownDeinit(&owners.surface_pond_domain_workspace);
    owners.soil_profile_relayering_workspace = try ecosys.soil_profile_relayering.Workspace.init(inputs.allocator, inputs.state.cell_count, inputs.config.soil_layers);
    resources.ownDeinit(&owners.soil_profile_relayering_workspace);
    for (0..inputs.state.cell_count) |cell| {
        const first_layer: usize = 0;
        const active_count = inputs.state.active_soil_layer_count[cell];
        const layer_base = cell * inputs.config.soil_layers;
        try ecosys.soil_layer_geometry.initializeCell(&owners.soil_geometry_state, cell, first_layer, owners.soil_solver_property_state.layer_thickness_m[layer_base .. layer_base + active_count], 0, inputs.runscript.soil_geometry_parameters.minimum_layer_thickness_m);
    }
    try owners.soil_boundary_topology_state.bindInitialSurfaceBoundaryDepths(&owners.soil_geometry_state);
    // HOUR1 2131--2168: once mapped hydrology, adjusted per-cell DTBLZ and
    // surface-relative layer midpoints all exist, liquid-saturate every active
    // layer at or below its natural table before chemistry, gas and phase
    // owners copy these carriers into their own initial state.
    // hour1.f:2131-2168 lives in the ELSE arm of hour1.f:2055, so it saturates
    // only where the soil file left field capacity or wilting point unsupplied
    // (ISOIL(1)/ISOIL(2) = 1, readi.f:454-470). Resolve that predicate per
    // (cell, layer) through the same catalog mapping the hydrology tile uses.
    const retention_endpoints_supplied_by_layer =
        try inputs.allocator.alloc(bool, inputs.state.layer_count);
    // `defer`, NOT `resources.ownFree`. This buffer is a function-scope local
    // used only by the two calls below, so registering it with the run-long
    // registry stored a pointer INTO THIS STACK FRAME. `resources.deinit()`
    // runs from `main` long after this function returns, dereferences that
    // dangling pointer, reads whatever now occupies the dead frame, and frees a
    // garbage slice.
    //
    // ReleaseFast hid it completely: it does not poison freed memory, so the
    // stale bytes still looked like a valid slice and the process exited 1 as
    // though nothing were wrong. ReleaseSafe poisons on free, so
    // `@memset(bytes, undefined)` dereferenced the garbage and segfaulted at
    // shutdown -- found the first time the deck was ever run in ReleaseSafe.
    //
    // The correct pattern for a run-long buffer is twelve lines below: allocate
    // into a field of `owners` and register THAT, because `owners` outlives the
    // registry. Registering `&local` is only safe when the local is in `main`.
    defer inputs.allocator.free(retention_endpoints_supplied_by_layer);
    try ecosys.model_initialization.fillSuppliedRetentionEndpoints(
        inputs.state,
        inputs.soil_catalog.entries.items,
        inputs.catalog_index_by_cell,
        retention_endpoints_supplied_by_layer,
    );
    try ecosys.model_initialization.applyInitialNaturalWaterTableSaturation(
        inputs.state,
        retention_endpoints_supplied_by_layer,
        owners.soil_boundary_topology_state.natural_water_table_depth_m,
        owners.soil_geometry_state.layer_midpoint_depth_from_surface_m,
    );
    owners.fertilizer_band_layer_upper_depth_m =
        try inputs.allocator.alloc(f64, inputs.state.layer_count);
    resources.ownFree(&owners.fertilizer_band_layer_upper_depth_m);
    owners.fertilizer_band_layer_lower_depth_m =
        try inputs.allocator.alloc(f64, inputs.state.layer_count);
    resources.ownFree(&owners.fertilizer_band_layer_lower_depth_m);
    for (0..inputs.state.cell_count) |cell| {
        const boundary_base = cell * (inputs.config.soil_layers + 1);
        const layer_base = cell * inputs.config.soil_layers;
        const surface_depth_m =
            owners.soil_geometry_state.boundary_depth_m[boundary_base];
        for (0..inputs.config.soil_layers) |layer| {
            owners.fertilizer_band_layer_upper_depth_m[layer_base + layer] =
                owners.soil_geometry_state.boundary_depth_m[
                    boundary_base + layer
                ] - surface_depth_m;
            owners.fertilizer_band_layer_lower_depth_m[layer_base + layer] =
                owners.soil_geometry_state.boundary_depth_m[
                    boundary_base + layer + 1
                ] - surface_depth_m;
        }
    }
    owners.fertilizer_band_state =
        try ecosys.fertilizer_band_state.State.initFromPlantNutrientParameters(
            inputs.allocator,
            inputs.state.cell_count,
            inputs.config.soil_layers,
            owners.soil_geometry_state.active_layer_count,
            owners.fertilizer_band_layer_upper_depth_m,
            owners.fertilizer_band_layer_lower_depth_m,
            owners.soil_geometry_state.layer_thickness_m,
            inputs.runscript.plant_nutrient_initialization,
        );
    resources.ownDeinit(&owners.fertilizer_band_state);
}

/// Final-address owners for the soil process, transport, and organic-state
/// initialization phase. Cleanup registrations target these fields directly;
/// this owner therefore remains in `main` for the complete model lifetime.
const SoilProcessTransportOwners = struct {
    soil_microbial_state: ecosys.soil_microbial_state.State,
    soil_reactive_nitrogen_state: ecosys.soil_reactive_nitrogen_state.State,
    soil_microbial_phosphorus_state: ecosys.soil_microbial_phosphorus_state.State,
    soil_nutrient_competition_history: ecosys.soil_nutrient_competition_history.State,
    soil_nutrient_competition_attempt: ecosys.soil_nutrient_competition_history.Attempt,
    soil_microbial_turnover_state: ecosys.soil_microbial_turnover_step.State,
    soil_litter_colonization_state: ecosys.soil_litter_colonization_step.State,
    soil_organic_sorption_state: ecosys.soil_organic_sorption_step.State,
    soil_organic_decomposition_state: ecosys.soil_organic_decomposition_step.State,
    soil_organic_priming_state: ecosys.soil_organic_priming_step.State,
    soil_respiration_products_state: ecosys.soil_respiration_products_step.State,
    soil_autotrophic_carbon_state: ecosys.soil_autotrophic_carbon_step.State,
    soil_microbial_layer_mixing_state: ecosys.soil_microbial_layer_mixing.State,
    soil_methane_state: ecosys.soil_methane_step.State,
    organic_matter_fire_exchange_state: ecosys.organic_matter_fire_exchange.State,
    surface_fire_exchange_state: ecosys.organic_matter_fire_exchange.State,
    soil_microbial_oxygen_state: ecosys.soil_oxygen_allocation.State,
    soil_oxygen_staging_state: ecosys.soil_oxygen_step.State,
    soil_nitrogen_flux_workspace: ecosys.soil_nitrogen_flux_workspace.State,
    soil_nitrifier_environment_state: ecosys.soil_nitrifier_environment_step.State,
    soil_field_capacity_fraction: []f64,
    soil_redox_satisfaction_fraction: []f64,
    aqueous_species_count: usize,
    micropore_solute_state: ecosys.solute_transport.State,
    macropore_solute_state: ecosys.solute_transport.State,
    soil_recharge_concentration_mol_per_m3: []f64,
    soil_solute_boundary_net_flux_mol: []f64,
    gas_transport_state: ecosys.gas_transport.State,
    soil_gas_transport_state: ecosys.soil_gas_transport_step.State,
    surface_litter_gas_transport_state: ecosys.surface_litter_gas_transport_step.State,
    litter_gas_transport_state: ecosys.gas_transport.State,
    plant_available_nutrient_state: ecosys.soil_plant_available_nutrients.State,
    soil_organic_state: ecosys.soil_organic_initialization.State,
    soil_organic_carbon_at_hour_start_g_c: []f64,
    soil_organic_carbon_change_g_c_per_h: []f64,
    erosion_organic_carbon_net_change_g_c: []f64,
    surface_organic_state: ecosys.soil_organic_initialization.State,
};

const SoilProcessTransportInputs = struct {
    allocator: std.mem.Allocator,
    state: *ecosys.grid.GridState,
    config: ecosys.config.SimulationConfig,
    runscript: *const ecosys.runscript.RunScript,
    soil_solver_property_state: *ecosys.soil_solver_properties.State,
    soil_catalog: *const ecosys.soil_catalog.Catalog,
    catalog_index_by_cell: []const usize,
};

noinline fn initializeSoilProcessTransport(
    owners: *SoilProcessTransportOwners,
    resources: *MainResources,
    inputs: SoilProcessTransportInputs,
) !void {
    owners.soil_microbial_state = try ecosys.soil_microbial_state.State.init(inputs.allocator, inputs.state.cell_count, inputs.config.soil_layers, inputs.runscript.microbial_substrate_count, inputs.runscript.microbial_population_count);
    resources.ownDeinit(&owners.soil_microbial_state);
    const soil_nitrogen_process_units_per_layer = try std.math.mul(usize, inputs.runscript.microbial_substrate_count, inputs.runscript.microbial_population_count);
    owners.soil_reactive_nitrogen_state = try ecosys.soil_reactive_nitrogen_state.State.init(inputs.allocator, inputs.state.layer_count, soil_nitrogen_process_units_per_layer);
    resources.ownDeinit(&owners.soil_reactive_nitrogen_state);
    owners.soil_microbial_phosphorus_state = try ecosys.soil_microbial_phosphorus_state.State.init(inputs.allocator, inputs.state.layer_count, soil_nitrogen_process_units_per_layer);
    resources.ownDeinit(&owners.soil_microbial_phosphorus_state);
    owners.soil_nutrient_competition_history = try ecosys.soil_nutrient_competition_history.State.init(inputs.allocator, inputs.state.layer_count, inputs.state.cell_count);
    resources.ownDeinit(&owners.soil_nutrient_competition_history);
    owners.soil_nutrient_competition_attempt = try ecosys.soil_nutrient_competition_history.Attempt.init(inputs.allocator, inputs.state.layer_count, inputs.state.cell_count);
    resources.ownDeinit(&owners.soil_nutrient_competition_attempt);
    owners.soil_microbial_turnover_state = try ecosys.soil_microbial_turnover_step.State.init(inputs.allocator, inputs.state.layer_count, soil_nitrogen_process_units_per_layer);
    resources.ownDeinit(&owners.soil_microbial_turnover_state);
    owners.soil_litter_colonization_state = try ecosys.soil_litter_colonization_step.State.init(inputs.allocator, inputs.state.layer_count);
    resources.ownDeinit(&owners.soil_litter_colonization_state);
    owners.soil_organic_sorption_state = try ecosys.soil_organic_sorption_step.State.init(inputs.allocator, inputs.state.layer_count);
    resources.ownDeinit(&owners.soil_organic_sorption_state);
    owners.soil_organic_decomposition_state = try ecosys.soil_organic_decomposition_step.State.init(inputs.allocator, inputs.state.layer_count);
    resources.ownDeinit(&owners.soil_organic_decomposition_state);
    owners.soil_organic_priming_state = try ecosys.soil_organic_priming_step.State.init(inputs.allocator, inputs.state.layer_count, inputs.runscript.microbial_population_count);
    resources.ownDeinit(&owners.soil_organic_priming_state);
    owners.soil_respiration_products_state = try ecosys.soil_respiration_products_step.State.init(inputs.allocator, inputs.state.layer_count, soil_nitrogen_process_units_per_layer);
    resources.ownDeinit(&owners.soil_respiration_products_state);
    owners.soil_autotrophic_carbon_state = try ecosys.soil_autotrophic_carbon_step.State.init(inputs.allocator, inputs.state.layer_count, soil_nitrogen_process_units_per_layer);
    resources.ownDeinit(&owners.soil_autotrophic_carbon_state);
    owners.soil_microbial_layer_mixing_state = try ecosys.soil_microbial_layer_mixing.State.init(inputs.allocator, inputs.state.layer_count);
    resources.ownDeinit(&owners.soil_microbial_layer_mixing_state);
    owners.soil_methane_state = try ecosys.soil_methane_step.State.init(inputs.allocator, inputs.state.layer_count);
    resources.ownDeinit(&owners.soil_methane_state);
    owners.organic_matter_fire_exchange_state = try ecosys.organic_matter_fire_exchange.State.init(inputs.allocator, inputs.state.layer_count, ecosys.soil_organic_initialization.microbial_substrate_count);
    resources.ownDeinit(&owners.organic_matter_fire_exchange_state);
    owners.surface_fire_exchange_state = try ecosys.organic_matter_fire_exchange.State.init(inputs.allocator, inputs.state.cell_count, ecosys.soil_organic_initialization.microbial_substrate_count);
    resources.ownDeinit(&owners.surface_fire_exchange_state);
    owners.soil_microbial_oxygen_state = try ecosys.soil_oxygen_allocation.State.init(inputs.allocator, inputs.state.cell_count, inputs.config.soil_layers, soil_nitrogen_process_units_per_layer);
    resources.ownDeinit(&owners.soil_microbial_oxygen_state);
    owners.soil_oxygen_staging_state = try ecosys.soil_oxygen_step.State.init(inputs.allocator, inputs.state.cell_count, inputs.config.soil_layers, soil_nitrogen_process_units_per_layer);
    resources.ownDeinit(&owners.soil_oxygen_staging_state);
    owners.soil_nitrogen_flux_workspace = try ecosys.soil_nitrogen_flux_workspace.State.init(inputs.allocator, inputs.state.layer_count, soil_nitrogen_process_units_per_layer);
    resources.ownDeinit(&owners.soil_nitrogen_flux_workspace);
    owners.soil_nitrifier_environment_state = try ecosys.soil_nitrifier_environment_step.State.init(inputs.allocator, inputs.state.layer_count, soil_nitrogen_process_units_per_layer);
    resources.ownDeinit(&owners.soil_nitrifier_environment_state);
    owners.soil_field_capacity_fraction = inputs.soil_solver_property_state.field_capacity_fraction;
    owners.soil_redox_satisfaction_fraction = try inputs.allocator.alloc(f64, try std.math.mul(usize, inputs.state.layer_count, soil_nitrogen_process_units_per_layer));
    resources.ownFree(&owners.soil_redox_satisfaction_fraction);
    @memset(owners.soil_redox_satisfaction_fraction, 1);
    // Runtime transport domains. Capacities derive only from parsed grid and
    // profile inputs; there is no PARAMETERS.H-equivalent extent.
    owners.aqueous_species_count = ecosys.solute_transport_species.AqueousSpecies.count;
    owners.micropore_solute_state = try ecosys.solute_transport.State.init(inputs.allocator, inputs.state.layer_count, owners.aqueous_species_count);
    resources.ownDeinit(&owners.micropore_solute_state);
    owners.macropore_solute_state = try ecosys.solute_transport.State.init(inputs.allocator, inputs.state.layer_count, owners.aqueous_species_count);
    resources.ownDeinit(&owners.macropore_solute_state);
    owners.soil_recharge_concentration_mol_per_m3 = try inputs.allocator.alloc(f64, try std.math.mul(usize, inputs.state.layer_count, owners.aqueous_species_count));
    resources.ownFree(&owners.soil_recharge_concentration_mol_per_m3);
    owners.soil_solute_boundary_net_flux_mol = try inputs.allocator.alloc(f64, try std.math.mul(usize, inputs.state.layer_count, owners.aqueous_species_count));
    resources.ownFree(&owners.soil_solute_boundary_net_flux_mol);
    @memset(owners.soil_solute_boundary_net_flux_mol, 0);
    owners.gas_transport_state = try ecosys.gas_transport.State.init(inputs.allocator, inputs.state.layer_count);
    resources.ownDeinit(&owners.gas_transport_state);
    owners.soil_gas_transport_state = try ecosys.soil_gas_transport_step.State.init(inputs.allocator, inputs.state.layer_count);
    resources.ownDeinit(&owners.soil_gas_transport_state);
    owners.surface_litter_gas_transport_state = try ecosys.surface_litter_gas_transport_step.State.init(inputs.allocator, inputs.state.cell_count);
    resources.ownDeinit(&owners.surface_litter_gas_transport_state);
    owners.litter_gas_transport_state = try ecosys.gas_transport.State.init(inputs.allocator, inputs.state.cell_count);
    resources.ownDeinit(&owners.litter_gas_transport_state);
    owners.plant_available_nutrient_state = try ecosys.soil_plant_available_nutrients.State.init(inputs.allocator, inputs.state.layer_count);
    resources.ownDeinit(&owners.plant_available_nutrient_state);
    try owners.plant_available_nutrient_state.initializeMapped(inputs.state, inputs.soil_solver_property_state, inputs.soil_catalog.entries.items, inputs.catalog_index_by_cell, inputs.runscript.plant_nutrient_initialization);
    owners.soil_organic_state = try ecosys.soil_organic_initialization.State.init(inputs.allocator, inputs.state.layer_count);
    resources.ownDeinit(&owners.soil_organic_state);
    owners.soil_organic_carbon_at_hour_start_g_c = try inputs.allocator.alloc(f64, inputs.state.layer_count);
    resources.ownFree(&owners.soil_organic_carbon_at_hour_start_g_c);
    owners.soil_organic_carbon_change_g_c_per_h = try inputs.allocator.alloc(f64, inputs.state.layer_count);
    resources.ownFree(&owners.soil_organic_carbon_change_g_c_per_h);
    owners.erosion_organic_carbon_net_change_g_c = try inputs.allocator.alloc(f64, inputs.state.layer_count);
    resources.ownFree(&owners.erosion_organic_carbon_net_change_g_c);
    @memset(owners.soil_organic_carbon_at_hour_start_g_c, 0);
    @memset(owners.soil_organic_carbon_change_g_c_per_h, 0);
    @memset(owners.erosion_organic_carbon_net_change_g_c, 0);
    owners.surface_organic_state = try ecosys.soil_organic_initialization.State.init(inputs.allocator, inputs.state.cell_count);
    resources.ownDeinit(&owners.surface_organic_state);
}

/// Owns one reusable nonlinear-reaction workspace for every executor
/// participant. The owner is registered at its final address before the first
/// workspace is initialized, so partial initialization is cleaned up exactly
/// once on every error path.
const StartupSoilChemistryOwners = struct {
    allocator: std.mem.Allocator,
    solver_workspaces: []ecosys.solute_reaction_solver.Workspace,
    initialized_solver_workspace_count: usize,

    noinline fn deinit(self: *StartupSoilChemistryOwners) void {
        for (self.solver_workspaces[0..self.initialized_solver_workspace_count]) |*workspace|
            workspace.deinit();
        self.allocator.free(self.solver_workspaces);
        self.* = undefined;
    }
};

noinline fn initializeStartupSoilChemistryOwners(
    owners: *StartupSoilChemistryOwners,
    resources: *MainResources,
    allocator: std.mem.Allocator,
    participant_count: usize,
) !void {
    if (participant_count == 0) return error.InvalidSoilChemistryParticipantCount;
    owners.* = .{
        .allocator = allocator,
        .solver_workspaces = try allocator.alloc(
            ecosys.solute_reaction_solver.Workspace,
            participant_count,
        ),
        .initialized_solver_workspace_count = 0,
    };
    resources.ownDeinit(owners);
    while (owners.initialized_solver_workspace_count < owners.solver_workspaces.len) {
        const index = owners.initialized_solver_workspace_count;
        owners.solver_workspaces[index] = try ecosys.solute_reaction_solver.Workspace.init(allocator);
        owners.initialized_solver_workspace_count += 1;
    }
}

const StartupSoilChemistryContext = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    logs: std.Io.Dir,
    executor: ecosys.compute.CpuExecutor,
    tile_plan: *const ecosys.spatial_grid.TilePlan,
    state: *ecosys.grid.GridState,
    soil_catalog: *const ecosys.soil_catalog.Catalog,
    catalog_index_by_cell: []const usize,
    soil_solver_property_state: *const ecosys.soil_solver_properties.State,
    chemistry_state: *ecosys.solute_chemistry_state.State,
    chemistry_layer_parameters: []ecosys.solute_chemistry_state.ReactionParameters,
    solver_workspaces: []ecosys.solute_reaction_solver.Workspace,
    failure_by_layer: []?anyerror,
    plant_available_nutrient_state: *ecosys.soil_plant_available_nutrients.State,
    runscript: *const ecosys.runscript.RunScript,
    iteration_limits: ecosys.iteration_control.Limits,
    chemistry_reaction_parameters: *const ecosys.soil_chemistry_parameters.Parameters,
    surface_gas_parameters: *const ecosys.surface_gas_parameters.Parameters,
    mean_annual_temperature_k_by_cell: []const f64,
    initial_atmospheric_gas_concentration_g_per_m3: []const f64,
    ammonium_non_band_volume_m3: []f64,
    ammonium_band_volume_m3: []f64,
    nitrate_non_band_volume_m3: []f64,
    nitrate_band_volume_m3: []f64,
    phosphate_non_band_volume_m3: []f64,
    phosphate_band_volume_m3: []f64,
    fractions: ecosys.solute_charge_classification.ZoneFractions,
};

const StartupSoilChemistryInputs = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    logs: std.Io.Dir,
    executor: ecosys.compute.CpuExecutor,
    tile_plan: *const ecosys.spatial_grid.TilePlan,
    state: *ecosys.grid.GridState,
    soil_catalog: *const ecosys.soil_catalog.Catalog,
    catalog_index_by_cell: []const usize,
    soil_solver_property_state: *const ecosys.soil_solver_properties.State,
    chemistry_state: *ecosys.solute_chemistry_state.State,
    chemistry_layer_parameters: []ecosys.solute_chemistry_state.ReactionParameters,
    solver_workspaces: []ecosys.solute_reaction_solver.Workspace,
    plant_available_nutrient_state: *ecosys.soil_plant_available_nutrients.State,
    runscript: *const ecosys.runscript.RunScript,
    iteration_limits: ecosys.iteration_control.Limits,
    chemistry_reaction_parameters: *const ecosys.soil_chemistry_parameters.Parameters,
    surface_gas_parameters: *const ecosys.surface_gas_parameters.Parameters,
    mean_annual_temperature_k_by_cell: []const f64,
    initial_atmospheric_gas_concentration_g_per_m3: []const f64,
};

noinline fn prepareStartupSoilChemistry(
    context: *StartupSoilChemistryContext,
) !void {
    // Preparation remains row-major and single-threaded. Besides preserving
    // source order, this keeps all validation diagnostics deterministic; only
    // the allocation-free nonlinear solve below is dispatched across cells.
    for (0..context.state.cell_count) |cell| {
        const soil_entry = context.soil_catalog.entries.items[context.catalog_index_by_cell[cell]];
        const profile = soil_entry.profile;
        for (0..profile.total_layer_count) |layer| {
            const layer_cell = try context.state.layerIndex(cell, layer);
            const primary_parameters = context.runscript.chemistry_primary_initialization;
            const profile_chemistry_inputs = try ecosys.soil_chemistry_initialization.resolveProfileEquilibriumSentinels(.{
                .soil_ph = profile.ph[layer],
                .ammonium_g_n_per_megagram = soil_entry.material.initial_ammonium_g_per_megagram[layer],
                .nitrate_g_n_per_megagram = profile.property(.nitrate_g_per_megagram)[layer],
                .phosphate_g_p_per_megagram = profile.property(.phosphate_g_per_megagram)[layer],
                .aluminum_g_per_megagram = profile.property(.aluminum_g_per_megagram)[layer],
                .iron_g_per_megagram = profile.property(.iron_g_per_megagram)[layer],
                .calcium_g_per_megagram = soil_entry.material.initial_calcium_g_per_megagram[layer],
                .magnesium_g_per_megagram = profile.property(.magnesium_g_per_megagram)[layer],
                .sodium_g_per_megagram = profile.property(.sodium_g_per_megagram)[layer],
                .potassium_g_per_megagram = profile.property(.potassium_g_per_megagram)[layer],
                .sulfate_sulfur_g_s_per_megagram = profile.property(.sulfate_sulfur_g_per_megagram)[layer],
                .chloride_g_per_megagram = profile.property(.chloride_g_per_megagram)[layer],
                .aluminum_phosphate_g_p_per_megagram = profile.property(.aluminum_phosphate_p_g_per_megagram)[layer],
                .iron_phosphate_g_p_per_megagram = profile.property(.iron_phosphate_p_g_per_megagram)[layer],
                .dicalcium_phosphate_g_p_per_megagram = profile.property(.calcium_hydrogen_phosphate_p_g_per_megagram)[layer],
                .apatite_g_p_per_megagram = profile.property(.apatite_phosphorus_g_per_megagram)[layer],
                .aluminum_hydroxide_g_al_per_megagram = profile.property(.aluminum_hydroxide_al_g_per_megagram)[layer],
                .iron_hydroxide_g_fe_per_megagram = profile.property(.iron_hydroxide_fe_g_per_megagram)[layer],
                .calcium_carbonate_g_ca_per_megagram = profile.property(.calcium_carbonate_ca_g_per_megagram)[layer],
                .calcium_sulfate_g_ca_per_megagram = profile.property(.calcium_sulfate_ca_g_per_megagram)[layer],
            }, primary_parameters);
            try ecosys.soil_chemistry_initialization.seedProfilePrimaryState(context.chemistry_state, layer_cell, profile_chemistry_inputs, context.soil_solver_property_state.matrix_bulk_volume_m3[layer_cell] * context.soil_solver_property_state.bulk_density_megagrams_per_m3[layer_cell], context.state.matrix_liquid_water_m3[layer_cell], primary_parameters);
            // STARTE 1642--1662: seed the six natural silicate
            // inventories before the initial chemistry solve. The
            // source owns extensive Q*SI mol; runtime geochemistry
            // owns mol per matrix-water m3, so the conversion is
            // explicit and exactly reversible.
            const silicates = (try ecosys.soil_silicate_inventory_initialization.initializePerWaterVolume(
                .{ .profile_source = .atmospheric_equilibrium, .gas_initialization_index = 0 },
                .{
                    .sand_mass_fraction = soil_entry.material.sand_mass_fraction[layer],
                    .silt_mass_fraction = soil_entry.material.silt_mass_fraction[layer],
                    .clay_mass_fraction = soil_entry.material.clay_mass_fraction[layer],
                },
                context.soil_solver_property_state.matrix_bulk_volume_m3[layer_cell] * context.soil_solver_property_state.bulk_density_megagrams_per_m3[layer_cell],
                context.state.matrix_liquid_water_m3[layer_cell],
                profile.ph[layer],
            )).?;
            const natural = silicates.soil_silicates_mol_per_m3;
            const ground = silicates.ground_rock_silicates_mol_per_m3;
            context.chemistry_state.geochemistry_solids[layer_cell].aluminum_natural_silicate_mol_per_m3 = natural.aluminum_mol;
            context.chemistry_state.geochemistry_solids[layer_cell].iron_natural_silicate_mol_per_m3 = natural.iron_mol;
            context.chemistry_state.geochemistry_solids[layer_cell].calcium_natural_silicate_mol_per_m3 = natural.calcium_mol;
            context.chemistry_state.geochemistry_solids[layer_cell].magnesium_natural_silicate_mol_per_m3 = natural.magnesium_mol;
            context.chemistry_state.geochemistry_solids[layer_cell].sodium_natural_silicate_mol_per_m3 = natural.sodium_mol;
            context.chemistry_state.geochemistry_solids[layer_cell].potassium_natural_silicate_mol_per_m3 = natural.potassium_mol;
            context.chemistry_state.geochemistry_solids[layer_cell].aluminum_ground_silicate_mol_per_m3 = ground.aluminum_mol;
            context.chemistry_state.geochemistry_solids[layer_cell].iron_ground_silicate_mol_per_m3 = ground.iron_mol;
            context.chemistry_state.geochemistry_solids[layer_cell].calcium_ground_silicate_mol_per_m3 = ground.calcium_mol;
            context.chemistry_state.geochemistry_solids[layer_cell].magnesium_ground_silicate_mol_per_m3 = ground.magnesium_mol;
            context.chemistry_state.geochemistry_solids[layer_cell].sodium_ground_silicate_mol_per_m3 = ground.sodium_mol;
            context.chemistry_state.geochemistry_solids[layer_cell].potassium_ground_silicate_mol_per_m3 = ground.potassium_mol;
        }
    }
    const reaction_parameters = context.chemistry_reaction_parameters.*;
    for (0..context.state.cell_count) |cell| {
        const profile = context.soil_catalog.entries.items[context.catalog_index_by_cell[cell]].profile;
        for (0..profile.total_layer_count) |layer| {
            const layer_cell = try context.state.layerIndex(cell, layer);
            const water_volume_m3 = context.state.matrix_liquid_water_m3[layer_cell];
            // REDIST-POND-ORGANIC-MASS, source `starts.f` 1297--1304.
            // The carrier that intensive concentrations are made extensive
            // against is selected per layer: mineral mass where a matrix
            // exists, total layer volume where it does not.
            const soil_mass_megagrams = blk: {
                const carrier = ecosys.soil_organic_initialization.selectOrganicCarrier(
                    context.soil_solver_property_state.matrix_bulk_volume_m3[layer_cell] * context.soil_solver_property_state.bulk_density_megagrams_per_m3[layer_cell],
                    context.soil_solver_property_state.layer_volume_m3[layer_cell],
                    0,
                ) catch |err| {
                    std.log.err("STARTE requires a positive organic carrier (mineral mass or total layer volume): cell={d} layer={d} mineral_mass_megagrams={e} layer_volume_m3={e} water_volume_m3={e}", .{ cell, layer, context.soil_solver_property_state.matrix_bulk_volume_m3[layer_cell] * context.soil_solver_property_state.bulk_density_megagrams_per_m3[layer_cell], context.soil_solver_property_state.layer_volume_m3[layer_cell], water_volume_m3 });
                    return err;
                };
                break :blk carrier.amount;
            };
            if (!std.math.isFinite(water_volume_m3) or water_volume_m3 <= 0 or !std.math.isFinite(soil_mass_megagrams)) {
                std.log.err("STARTE requires positive runtime soil and matrix-water volumes: cell={d} layer={d} soil_mass_megagrams={e} water_volume_m3={e}", .{ cell, layer, soil_mass_megagrams, water_volume_m3 });
                return error.InvalidStarteLayerGeometry;
            }
            const prepared_zones = try ecosys.soil_fertilizer_dissolution.prepareLayerZones(.{
                .water_volume_m3 = water_volume_m3,
                .soil_mass_megagrams = soil_mass_megagrams,
                .soil_volume_m3 = context.soil_solver_property_state.matrix_bulk_volume_m3[layer_cell],
                .fractions = .{
                    .ammonium_non_band = context.fractions.ammonium_non_band,
                    .ammonium_band = context.fractions.ammonium_band,
                    .nitrate_non_band = context.fractions.nitrate_non_band,
                    .nitrate_band = context.fractions.nitrate_band,
                    .phosphate_non_band = context.fractions.phosphate_non_band,
                    .phosphate_band = context.fractions.phosphate_band,
                },
                .positive_soil_mass_threshold_megagrams = context.runscript.physical_tolerance.soilMass(soil_mass_megagrams),
            });
            context.ammonium_non_band_volume_m3[layer_cell] = prepared_zones.ammonium_non_band_water_m3;
            context.ammonium_band_volume_m3[layer_cell] = prepared_zones.ammonium_band_water_m3;
            context.nitrate_non_band_volume_m3[layer_cell] = prepared_zones.nitrate_non_band_water_m3;
            context.nitrate_band_volume_m3[layer_cell] = prepared_zones.nitrate_band_water_m3;
            context.phosphate_non_band_volume_m3[layer_cell] = prepared_zones.phosphate_non_band_water_m3;
            context.phosphate_band_volume_m3[layer_cell] = prepared_zones.phosphate_band_water_m3;
            const shared_soil_mass_per_water_volume_megagrams_per_m3 = try ecosys.soil_fertilizer_dissolution.normalizationBasisPerWaterVolume(prepared_zones.whole_layer_normalization_basis, water_volume_m3);
            const phosphate_non_band_ratio = try ecosys.soil_fertilizer_dissolution.normalizationBasisPerWaterVolume(prepared_zones.phosphate_non_band_normalization_basis, prepared_zones.phosphate_non_band_water_m3);
            const phosphate_band_ratio = try ecosys.soil_fertilizer_dissolution.normalizationBasisPerWaterVolume(prepared_zones.phosphate_band_normalization_basis, prepared_zones.phosphate_band_water_m3);
            const ammonium_non_band_ratio = try ecosys.soil_fertilizer_dissolution.normalizationBasisPerWaterVolume(prepared_zones.ammonium_non_band_normalization_basis, prepared_zones.ammonium_non_band_water_m3);
            const ammonium_band_ratio = try ecosys.soil_fertilizer_dissolution.normalizationBasisPerWaterVolume(prepared_zones.ammonium_band_normalization_basis, prepared_zones.ammonium_band_water_m3);
            const selectivity = ecosys.solute_cation_exchange.Selectivity{
                .calcium_ammonium = profile.property(.gapon_calcium_ammonium)[layer],
                .calcium_hydrogen = profile.property(.gapon_calcium_hydrogen)[layer],
                .calcium_aluminum_and_iron = profile.property(.gapon_calcium_aluminum)[layer],
                .calcium_magnesium = profile.property(.gapon_calcium_magnesium)[layer],
                .calcium_sodium = profile.property(.gapon_calcium_sodium)[layer],
                .calcium_potassium = profile.property(.gapon_calcium_potassium)[layer],
            };
            const cation_exchange_capacity_mol_charge_per_megagram = context.soil_solver_property_state.cation_exchange_capacity_mol_per_megagram[layer_cell];
            const anion_exchange_capacity_mol_charge_per_megagram = 10 * profile.anion_exchange_capacity_cmol_kg[layer];
            const total_carboxyl_sites_mol_per_megagram = reaction_parameters.surface_litter.carboxyl_sites_mol_per_megagram_c *
                1.0e-6 * context.soil_solver_property_state.total_organic_carbon_g_per_megagram[layer_cell];
            try ecosys.soil_chemistry_initialization.seedProfilePhosphateSurfaceSites(context.chemistry_state, layer_cell, profile.property(.phosphate_g_per_megagram)[layer] / 31.0, anion_exchange_capacity_mol_charge_per_megagram, reaction_parameters.phosphate_surface, reaction_parameters.phosphate_constants.h2po4);
            try ecosys.soil_chemistry_initialization.seedProfileCationExchange(context.chemistry_state, layer_cell, cation_exchange_capacity_mol_charge_per_megagram, selectivity, context.fractions);
            // SOLUTE-CARBOXYL-INIT-SEED, source `starte.f` 403. This must
            // follow primary-state seeding because it consumes aqueous H+.
            try ecosys.soil_chemistry_initialization.seedProfileCarboxylOccupancy(
                context.chemistry_state,
                layer_cell,
                total_carboxyl_sites_mol_per_megagram,
                reaction_parameters.surface_litter.carboxyl_dissociation_constant,
            );
            context.chemistry_state.water_mol_per_m3[layer_cell] = reaction_parameters.water_concentration_mol_per_m3;
            context.chemistry_layer_parameters[layer_cell] = reaction_parameters.forLayer(context.fractions, phosphate_non_band_ratio, phosphate_band_ratio, cation_exchange_capacity_mol_charge_per_megagram, total_carboxyl_sites_mol_per_megagram, .{ .shared_megagrams_per_m3 = shared_soil_mass_per_water_volume_megagrams_per_m3, .ammonium_non_band_megagrams_per_m3 = ammonium_non_band_ratio, .ammonium_band_megagrams_per_m3 = ammonium_band_ratio }, selectivity);
            // STARTE lines 234--248: seed dissolved CO2 before equilibrium.
            const co2 = @intFromEnum(ecosys.gas_transport.Species.carbon_dioxide);
            const sol = try ecosys.gas_transport.surfaceSolubilityWaterToAir(context.mean_annual_temperature_k_by_cell[cell], context.surface_gas_parameters.solubility);
            const dissolved_co2_mol_per_m3 = context.initial_atmospheric_gas_concentration_g_per_m3[cell * ecosys.gas_transport.species_count + co2] * sol[co2] / ecosys.gas_transport.g_per_mol_tracked[co2];
            if (!std.math.isFinite(dissolved_co2_mol_per_m3) or dissolved_co2_mol_per_m3 < 0)
                return error.InvalidStarteDissolvedCarbonDioxide;
            context.chemistry_state.aqueous[layer_cell].carbon_dioxide = dissolved_co2_mol_per_m3;
        }
    }
}

fn startupSoilChemistrySolverOptions(
    context: *const StartupSoilChemistryContext,
) ecosys.solute_reaction_solver.Options {
    return .{
        .absolute_tolerance_mol_per_m3 = context.runscript.nonlinear_tolerance.reaction_mol_per_m3,
        .absolute_tolerance_mol_per_megagram = context.runscript.nonlinear_tolerance.reaction_mol_per_megagram,
        .relative_tolerance = context.runscript.nonlinear_tolerance.relative,
        .picard_relaxation = context.runscript.picard_relaxation,
        .max_iterations = context.iteration_limits.initial_solute_reaction_max_iterations,
        // Ottawa's clean STARTE trace separated the preliminary rate-head
        // calls by more than three orders of magnitude: every call at or
        // above 8.16e8 exhausted all 25--38 rate axes and then repeated them
        // in the complete coordinate search, while every successful call was
        // at or below 6.84e5 and accepted its first axis. Keep the useful
        // near-root shortcut and route only the demonstrably hard entry
        // states directly to the unchanged complete Newton search.
        .rate_ranked_coordinate_head_maximum_norm = 1.0e8,
    };
}

fn startupSoilChemistryLayerParameters(
    context: *const StartupSoilChemistryContext,
    layer_cell: usize,
) ecosys.solute_chemistry_state.ReactionParameters {
    var result = context.chemistry_layer_parameters[layer_cell];
    // SOLUTE-042: STARTE's carboxyl hydrogen substrate cap is active only
    // during initialization and remains inside every solver iteration.
    result.carboxyl_exchange_parameters.use_starte_hydrogen_substrate_cap = true;
    return result;
}

noinline fn solveStartupSoilChemistryLayers(
    context: *StartupSoilChemistryContext,
    worker_layers: ecosys.compute.StridedIndexRange,
    worker_index: usize,
) !void {
    if (worker_index >= context.solver_workspaces.len)
        return error.SoilChemistryWorkerIndexOutOfBounds;
    var suppression = ecosys.solute_reaction_solver.suppressDiagnostics();
    defer suppression.restore();
    const options = startupSoilChemistrySolverOptions(context);
    const workspace = &context.solver_workspaces[worker_index];
    var layers = worker_layers;
    while (layers.next()) |layer_cell| {
        const cell = layer_cell / context.state.soil_layer_capacity;
        const layer = layer_cell % context.state.soil_layer_capacity;
        const profile = context.soil_catalog.entries.items[context.catalog_index_by_cell[cell]].profile;
        if (layer < profile.total_layer_count) {
            const parameters = startupSoilChemistryLayerParameters(context, layer_cell);
            // Diagnostic only, per the physical-acceptance runtime
            // investigation: STARTE's `max_iterations` defaults to 1000 (10x
            // the general nonlinear ceiling), so a per-layer iteration/timing
            // trace is the cheapest way to confirm or refute "this layer is
            // burning the full budget" before touching any solver tolerance.
            const layer_start_timestamp = std.Io.Clock.now(.boot, context.io);
            // Cheap call-count proxy for wall-clock cost, since threading a
            // clock through the whole reaction-network call graph (Newton,
            // Anderson, full-network, boundary-recovery, phosphate-extent
            // candidate strategies) would be far more invasive than a single
            // counter reset/read pair around the one call already timed.
            const detailed_profile = ecosys.solute_reaction_solver.diagnosticRuntimeProfilingEnabled;
            if (detailed_profile) {
                ecosys.solute_reaction_solver.resetDiagnosticEvaluationCounts();
                ecosys.solute_reaction_solver.resetDiagnosticReactionSpanBoundsSiteStats();
                ecosys.solute_reaction_solver.resetDiagnosticStrategyCallCounts();
                ecosys.solute_reaction_solver.resetDiagnosticAdmissibilityBacktrackStats();
            }
            const result = ecosys.solute_reaction_solver.solveCellWithWorkspace(
                workspace,
                context.chemistry_state,
                layer_cell,
                parameters,
                options,
            ) catch |err| {
                // Each packed layer has one writer. Record every failed layer;
                // the caller selects the canonical first failure after join.
                std.log.info("STARTE chemistry layer failed: cell={d} layer={d} elapsed_ms={d} error={s}", .{ cell, layer, layer_start_timestamp.durationTo(std.Io.Clock.now(.boot, context.io)).toMilliseconds(), @errorName(err) });
                if (detailed_profile) {
                    const counts = ecosys.solute_reaction_solver.diagnosticEvaluationCounts();
                    std.log.info("STARTE chemistry failed evaluations: cell={d} layer={d} full_network_evaluations={d} reaction_span_evaluations={d}", .{ cell, layer, counts.full_network, counts.reaction_span });
                    std.log.info("STARTE chemistry failed strategy calls: cell={d} layer={d} full_network_newton={d} retained_complementarity={d} analytic_coordinate_newton={d} phosphate_extent={d} global_inventory_boundary_recovery={d} active_boundary_surface_recovery={d} active_row_newton={d} ternary_correction_face={d} current_sign_coordinate_anderson={d}", .{
                        cell,
                        layer,
                        ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.full_network_newton),
                        ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.retained_complementarity),
                        ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.analytic_coordinate_newton),
                        ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.phosphate_extent),
                        ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.global_inventory_boundary_recovery),
                        ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.active_boundary_surface_recovery),
                        ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.active_row_newton),
                        ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.ternary_correction_face),
                        ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.current_sign_coordinate_anderson),
                    });
                    inline for (@typeInfo(ecosys.solute_reaction_solver.DiagnosticStrategy).@"enum".fields) |field| {
                        const strategy: ecosys.solute_reaction_solver.DiagnosticStrategy = @enumFromInt(field.value);
                        const evaluations = ecosys.solute_reaction_solver.diagnosticStrategyEvaluationCounts(strategy);
                        std.log.info("STARTE chemistry failed strategy evaluations: cell={d} layer={d} strategy={s} full_network_evaluations={d} reaction_span_evaluations={d}", .{ cell, layer, field.name, evaluations.full_network, evaluations.reaction_span });
                    }
                }
                context.failure_by_layer[layer_cell] = err;
                continue;
            };
            std.log.info("STARTE chemistry layer solved: cell={d} layer={d} elapsed_ms={d} iterations={d} newton_steps={d} anderson_steps={d} converged={} max_scaled_residual={e}", .{
                cell,
                layer,
                layer_start_timestamp.durationTo(std.Io.Clock.now(.boot, context.io)).toMilliseconds(),
                result.iterations,
                result.newton_raphson_steps,
                result.anderson_steps,
                result.converged,
                result.maximum_scaled_residual,
            });
            if (detailed_profile) {
                const counts = ecosys.solute_reaction_solver.diagnosticEvaluationCounts();
                std.log.info("STARTE chemistry layer evaluations: cell={d} layer={d} full_network_evaluations={d} reaction_span_evaluations={d}", .{ cell, layer, counts.full_network, counts.reaction_span });
                std.log.info("STARTE chemistry layer strategy calls: cell={d} layer={d} full_network_newton={d} retained_complementarity={d} analytic_coordinate_newton={d} phosphate_extent={d} global_inventory_boundary_recovery={d} active_boundary_surface_recovery={d} active_row_newton={d} ternary_correction_face={d} current_sign_coordinate_anderson={d}", .{
                    cell,
                    layer,
                    ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.full_network_newton),
                    ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.retained_complementarity),
                    ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.analytic_coordinate_newton),
                    ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.phosphate_extent),
                    ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.global_inventory_boundary_recovery),
                    ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.active_boundary_surface_recovery),
                    ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.active_row_newton),
                    ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.ternary_correction_face),
                    ecosys.solute_reaction_solver.diagnosticStrategyCallCount(.current_sign_coordinate_anderson),
                });
                inline for (@typeInfo(ecosys.solute_reaction_solver.DiagnosticStrategy).@"enum".fields) |field| {
                    const strategy: ecosys.solute_reaction_solver.DiagnosticStrategy = @enumFromInt(field.value);
                    const strategy_evaluations = ecosys.solute_reaction_solver.diagnosticStrategyEvaluationCounts(strategy);
                    std.log.info("STARTE chemistry strategy evaluations: cell={d} layer={d} strategy={s} full_network_evaluations={d} reaction_span_evaluations={d}", .{
                        cell,
                        layer,
                        field.name,
                        strategy_evaluations.full_network,
                        strategy_evaluations.reaction_span,
                    });
                }
                const backtrack_stats = ecosys.solute_reaction_solver.diagnosticAdmissibilityBacktrackStats();
                std.log.info("STARTE chemistry layer admissibility backtracks: cell={d} layer={d} calls={d} total_attempts={d} max_attempts={d}", .{
                    cell,
                    layer,
                    backtrack_stats.calls,
                    backtrack_stats.total_attempts,
                    backtrack_stats.max_attempts,
                });
                inline for (@typeInfo(ecosys.solute_reaction_solver.DiagnosticReactionSpanBoundsSite).@"enum".fields) |field| {
                    const site: ecosys.solute_reaction_solver.DiagnosticReactionSpanBoundsSite = @enumFromInt(field.value);
                    const site_stats = ecosys.solute_reaction_solver.diagnosticReactionSpanBoundsSiteStats(site);
                    std.log.info("STARTE reaction-span bounds site: cell={d} layer={d} site={s} calls={d} full_network_evaluations={d} reaction_span_evaluations={d}", .{
                        cell,
                        layer,
                        field.name,
                        site_stats.calls,
                        site_stats.full_network_evaluations,
                        site_stats.reaction_span_evaluations,
                    });
                }
            }
        }
    }
}

noinline fn initializeStartupSoilChemistry(inputs: StartupSoilChemistryInputs) !void {
    if (inputs.solver_workspaces.len < inputs.executor.statistics().effective_threads)
        return error.InsufficientSoilChemistryWorkerWorkspaces;
    std.log.info("STARTE chemistry beginning: cell_count={d} layer_count={d} max_iterations={d}", .{
        inputs.state.cell_count,
        inputs.state.layer_count,
        inputs.iteration_limits.initial_solute_reaction_max_iterations,
    });
    const zone_volume_storage = try inputs.allocator.alloc(f64, 6 * inputs.state.layer_count);
    defer inputs.allocator.free(zone_volume_storage);
    @memset(zone_volume_storage, 0);
    const failures = try inputs.allocator.alloc(?anyerror, inputs.state.layer_count);
    defer inputs.allocator.free(failures);
    @memset(failures, null);
    const nutrient_zones = inputs.runscript.plant_nutrient_initialization;
    var context = StartupSoilChemistryContext{
        .allocator = inputs.allocator,
        .io = inputs.io,
        .logs = inputs.logs,
        .executor = inputs.executor,
        .tile_plan = inputs.tile_plan,
        .state = inputs.state,
        .soil_catalog = inputs.soil_catalog,
        .catalog_index_by_cell = inputs.catalog_index_by_cell,
        .soil_solver_property_state = inputs.soil_solver_property_state,
        .chemistry_state = inputs.chemistry_state,
        .chemistry_layer_parameters = inputs.chemistry_layer_parameters,
        .solver_workspaces = inputs.solver_workspaces,
        .failure_by_layer = failures,
        .plant_available_nutrient_state = inputs.plant_available_nutrient_state,
        .runscript = inputs.runscript,
        .iteration_limits = inputs.iteration_limits,
        .chemistry_reaction_parameters = inputs.chemistry_reaction_parameters,
        .surface_gas_parameters = inputs.surface_gas_parameters,
        .mean_annual_temperature_k_by_cell = inputs.mean_annual_temperature_k_by_cell,
        .initial_atmospheric_gas_concentration_g_per_m3 = inputs.initial_atmospheric_gas_concentration_g_per_m3,
        .ammonium_non_band_volume_m3 = zone_volume_storage[0 * inputs.state.layer_count ..][0..inputs.state.layer_count],
        .ammonium_band_volume_m3 = zone_volume_storage[1 * inputs.state.layer_count ..][0..inputs.state.layer_count],
        .nitrate_non_band_volume_m3 = zone_volume_storage[2 * inputs.state.layer_count ..][0..inputs.state.layer_count],
        .nitrate_band_volume_m3 = zone_volume_storage[3 * inputs.state.layer_count ..][0..inputs.state.layer_count],
        .phosphate_non_band_volume_m3 = zone_volume_storage[4 * inputs.state.layer_count ..][0..inputs.state.layer_count],
        .phosphate_band_volume_m3 = zone_volume_storage[5 * inputs.state.layer_count ..][0..inputs.state.layer_count],
        .fractions = .{
            .ammonium_non_band = 1 - nutrient_zones.initial_ammonium_band_fraction,
            .ammonium_band = nutrient_zones.initial_ammonium_band_fraction,
            .nitrate_non_band = 1 - nutrient_zones.initial_nitrate_band_fraction,
            .nitrate_band = nutrient_zones.initial_nitrate_band_fraction,
            .phosphate_non_band = 1 - nutrient_zones.initial_phosphate_band_fraction,
            .phosphate_band = nutrient_zones.initial_phosphate_band_fraction,
        },
    };
    try prepareStartupSoilChemistry(&context);
    // STARTE cells are independent nonlinear systems. Dispatch packed layers
    // directly so a one-column production case can use its configured thread
    // budget instead of serializing the complete vertical profile.
    try inputs.executor.runIndependentStridedIndexed(
        .{ .first = 0, .end = inputs.state.layer_count },
        &context,
        solveStartupSoilChemistryLayers,
    );
    // Select the same first failure as the former row-major serial loop. The
    // selected layer is rerun serially with diagnostics enabled, producing one
    // stable log/snapshot and preserving the original error identity.
    for (0..inputs.state.cell_count) |cell| {
        const profile = inputs.soil_catalog.entries.items[inputs.catalog_index_by_cell[cell]].profile;
        for (0..profile.total_layer_count) |layer| {
            const layer_cell = try inputs.state.layerIndex(cell, layer);
            const worker_error = failures[layer_cell] orelse continue;
            const parameters = startupSoilChemistryLayerParameters(&context, layer_cell);
            const options = startupSoilChemistrySolverOptions(&context);
            _ = ecosys.solute_reaction_solver.solveCellWithWorkspace(
                &inputs.solver_workspaces[0],
                inputs.chemistry_state,
                layer_cell,
                parameters,
                options,
            ) catch |rerun_error| {
                if (rerun_error != worker_error) {
                    std.log.err(
                        "parallel SOLUTE initialization failure changed on serial rerun: cell={d} layer={d} worker_error={s} rerun_error={s}",
                        .{ cell, layer, @errorName(worker_error), @errorName(rerun_error) },
                    );
                    return error.NonDeterministicSoilChemistryInitialization;
                }
                var failure_name_buffer: [128]u8 = undefined;
                const failure_name = try std.fmt.bufPrint(
                    &failure_name_buffer,
                    "solute-initialization-failure-scene0-cell{d}-layer{d}.bin",
                    .{ cell, layer },
                );
                return ecosys.solute_failure_reporter.reportPreservingSolverError(
                    inputs.allocator,
                    .{
                        .io = inputs.io,
                        .directory = inputs.logs,
                        .file_path = failure_name,
                        .context = .{
                            .global_cell_id = @intCast(cell),
                            .soil_layer_id = @intCast(layer),
                            .packed_cell_index = @intCast(layer_cell),
                        },
                    },
                    inputs.chemistry_state,
                    layer_cell,
                    parameters,
                    options,
                    rerun_error,
                );
            };
            std.log.err(
                "parallel SOLUTE initialization failure was not reproduced serially: cell={d} layer={d} worker_error={s}",
                .{ cell, layer, @errorName(worker_error) },
            );
            return error.NonDeterministicSoilChemistryInitialization;
        }
    }
    try inputs.plant_available_nutrient_state.bindEquilibratedMineralPools(inputs.chemistry_state, .{
        .ammonium_non_band_m3 = context.ammonium_non_band_volume_m3,
        .ammonium_band_m3 = context.ammonium_band_volume_m3,
        .nitrate_non_band_m3 = context.nitrate_non_band_volume_m3,
        .nitrate_band_m3 = context.nitrate_band_volume_m3,
        .phosphate_non_band_m3 = context.phosphate_non_band_volume_m3,
        .phosphate_band_m3 = context.phosphate_band_volume_m3,
    });
}

const PlantTransferOwners = struct {
    shoot_senescence_products_by_plant: []ecosys.canopy_photosynthesis.SenescenceProducts,
    seasonal_turnover_event_by_plant: []bool,
    automatic_harvest_date_by_plant: []ecosys.plant_management.PackedDate,
    root_litter_products_by_plant: []ecosys.plant_root_metabolism.RootLitter,
    root_litter_carbon_ledger: ecosys.plant_root_litter_ledger.State,
    plant_salt_harvest_workspace: ecosys.plant_salt_harvest_adapter.Workspace,
    cumulative_harvest_salt_mol_by_plant: []f64,
    litter_salt_mol_by_plant_exchange_layer: []f64,
    plant_litter_salt_ingress_state: ecosys.plant_litter_salt_ingress.State,
    deferred_tillage_soil_by_cell: []ecosys.disturbance_management_dispatch.DeferredTillage,
    litter_salt_state_update_state: ecosys.litter_salt_state_update.State,
    root_litter_carbon_g_c_by_layer: []f64,
    shoot_harvest_litter_carbon_g_c_by_plant: []f64,
    hourly_manure_products_by_plant: []ecosys.grazing_manure.Products,
    shoot_harvest_litter_nitrogen_g_n_by_plant: []f64,
    shoot_harvest_litter_phosphorus_g_p_by_plant: []f64,
    harvest_carbon_at_hour_start_g_c_by_plant: []f64,
    harvest_salt_at_hour_start_mol_by_plant_species: []f64,
};

const PlantTransferInitializationInputs = struct {
    allocator: std.mem.Allocator,
    output_plant_count: usize,
    cell_count: usize,
    plant_populations: usize,
    soil_layers: usize,
};

/// Allocate the plant turnover, harvest, salt, and deferred-tillage transfer
/// owners in their original registration order. `MainResources` retains
/// pointers to these stable owner fields, so partial initialization unwinds in
/// precisely the same reverse order as the former declarations in `main`.
noinline fn initializePlantTransferOwners(
    owners: *PlantTransferOwners,
    resources: *MainResources,
    inputs: PlantTransferInitializationInputs,
) !void {
    owners.shoot_senescence_products_by_plant = try inputs.allocator.alloc(
        ecosys.canopy_photosynthesis.SenescenceProducts,
        inputs.output_plant_count,
    );
    resources.ownFree(&owners.shoot_senescence_products_by_plant);
    @memset(owners.shoot_senescence_products_by_plant, .{});
    owners.seasonal_turnover_event_by_plant = try inputs.allocator.alloc(bool, inputs.output_plant_count);
    resources.ownFree(&owners.seasonal_turnover_event_by_plant);
    @memset(owners.seasonal_turnover_event_by_plant, false);
    owners.automatic_harvest_date_by_plant = try inputs.allocator.alloc(
        ecosys.plant_management.PackedDate,
        inputs.output_plant_count,
    );
    resources.ownFree(&owners.automatic_harvest_date_by_plant);
    @memset(owners.automatic_harvest_date_by_plant, .{ .day = 1, .month = 1, .year = 0 });
    owners.root_litter_products_by_plant = try inputs.allocator.alloc(
        ecosys.plant_root_metabolism.RootLitter,
        inputs.output_plant_count,
    );
    resources.ownFree(&owners.root_litter_products_by_plant);
    @memset(
        owners.root_litter_products_by_plant,
        std.mem.zeroes(ecosys.plant_root_metabolism.RootLitter),
    );
    owners.root_litter_carbon_ledger = try ecosys.plant_root_litter_ledger.State.init(
        inputs.allocator,
        inputs.output_plant_count,
        ecosys.plant_root_system.biological_domain_count,
        inputs.soil_layers,
    );
    resources.ownDeinit(&owners.root_litter_carbon_ledger);
    owners.plant_salt_harvest_workspace = try ecosys.plant_salt_harvest_adapter.Workspace.init(
        inputs.allocator,
        inputs.soil_layers,
    );
    resources.ownDeinit(&owners.plant_salt_harvest_workspace);
    owners.cumulative_harvest_salt_mol_by_plant = try inputs.allocator.alloc(
        f64,
        inputs.output_plant_count * ecosys.plant_salt_harvest.salt_count,
    );
    resources.ownFree(&owners.cumulative_harvest_salt_mol_by_plant);
    @memset(owners.cumulative_harvest_salt_mol_by_plant, 0);
    owners.litter_salt_mol_by_plant_exchange_layer = try inputs.allocator.alloc(
        f64,
        inputs.output_plant_count * (inputs.soil_layers + 1) * ecosys.plant_salt_harvest.salt_count,
    );
    resources.ownFree(&owners.litter_salt_mol_by_plant_exchange_layer);
    @memset(owners.litter_salt_mol_by_plant_exchange_layer, 0);
    owners.plant_litter_salt_ingress_state = try ecosys.plant_litter_salt_ingress.State.init(
        inputs.allocator,
        inputs.cell_count,
        inputs.soil_layers,
    );
    resources.ownDeinit(&owners.plant_litter_salt_ingress_state);
    owners.deferred_tillage_soil_by_cell = try inputs.allocator.alloc(
        ecosys.disturbance_management_dispatch.DeferredTillage,
        inputs.cell_count,
    );
    resources.ownFree(&owners.deferred_tillage_soil_by_cell);
    @memset(owners.deferred_tillage_soil_by_cell, .{});
    owners.litter_salt_state_update_state = try ecosys.litter_salt_state_update.State.init(
        inputs.allocator,
        inputs.cell_count,
        inputs.plant_populations,
        inputs.soil_layers,
    );
    resources.ownDeinit(&owners.litter_salt_state_update_state);
    owners.root_litter_carbon_g_c_by_layer = try inputs.allocator.alloc(f64, inputs.soil_layers);
    resources.ownFree(&owners.root_litter_carbon_g_c_by_layer);
    @memset(owners.root_litter_carbon_g_c_by_layer, 0);
    owners.shoot_harvest_litter_carbon_g_c_by_plant = try inputs.allocator.alloc(f64, inputs.output_plant_count);
    resources.ownFree(&owners.shoot_harvest_litter_carbon_g_c_by_plant);
    @memset(owners.shoot_harvest_litter_carbon_g_c_by_plant, 0);
    owners.hourly_manure_products_by_plant = try inputs.allocator.alloc(
        ecosys.grazing_manure.Products,
        inputs.output_plant_count,
    );
    resources.ownFree(&owners.hourly_manure_products_by_plant);
    @memset(owners.hourly_manure_products_by_plant, .{});
    owners.shoot_harvest_litter_nitrogen_g_n_by_plant = try inputs.allocator.alloc(f64, inputs.output_plant_count);
    resources.ownFree(&owners.shoot_harvest_litter_nitrogen_g_n_by_plant);
    @memset(owners.shoot_harvest_litter_nitrogen_g_n_by_plant, 0);
    owners.shoot_harvest_litter_phosphorus_g_p_by_plant = try inputs.allocator.alloc(f64, inputs.output_plant_count);
    resources.ownFree(&owners.shoot_harvest_litter_phosphorus_g_p_by_plant);
    @memset(owners.shoot_harvest_litter_phosphorus_g_p_by_plant, 0);
    owners.harvest_carbon_at_hour_start_g_c_by_plant = try inputs.allocator.alloc(f64, inputs.output_plant_count);
    resources.ownFree(&owners.harvest_carbon_at_hour_start_g_c_by_plant);
    @memset(owners.harvest_carbon_at_hour_start_g_c_by_plant, 0);
    owners.harvest_salt_at_hour_start_mol_by_plant_species = try inputs.allocator.alloc(
        f64,
        owners.cumulative_harvest_salt_mol_by_plant.len,
    );
    resources.ownFree(&owners.harvest_salt_at_hour_start_mol_by_plant_species);
    @memset(owners.harvest_salt_at_hour_start_mol_by_plant_species, 0);
}

/// Stable surface-process and erosion owners. Keeping these allocations in a
/// separate phase bounds `main`'s error graph while preserving the original
/// allocation and reverse-cleanup order through `MainResources`.
const SurfaceProcessOwners = struct {
    eroded_organic_workspace: ecosys.eroded_constituents.PackedWorkspace,
    surface_litter_geometry_state: ecosys.surface_litter_geometry_step.State,
    surface_litter_water_environment_state: ecosys.surface_litter_water_environment.State,
    surface_microbial_environment_state: ecosys.surface_microbial_environment_step.State,
    surface_field_capacity_potential_megapascal: []f64,
    surface_wilting_point_potential_megapascal: []f64,
    surface_litter_ice_m3: []f64,
    surface_charcoal_carbon_g_c: []f64,
    surface_litter_chemistry_state: ecosys.surface_litter_chemistry.State,
    surface_litter_fertilizer_state: ecosys.surface_litter_fertilizer.State,
    surface_microbial_respiration_state: ecosys.surface_microbial_respiration_step.State,
    surface_autotrophic_complex_state: ecosys.surface_autotrophic_complex_step.State,
    surface_microbial_oxygen_state: ecosys.surface_microbial_oxygen_driver.State,
    surface_microbial_maintenance_state: ecosys.surface_microbial_maintenance_step.State,
    surface_nonsymbiotic_nitrogen_fixation_state: ecosys.surface_nonsymbiotic_nitrogen_fixation_step.State,
    surface_microbial_substrate_uptake_state: ecosys.surface_microbial_substrate_uptake_step.State,
    surface_denitrification_state: ecosys.surface_denitrification_step.State,
    surface_microbial_assimilation_state: ecosys.surface_microbial_assimilation_step.State,
    surface_microbial_mineral_exchange_state: ecosys.surface_microbial_mineral_exchange_step.State,
    surface_topsoil_mineral_exchange_state: ecosys.surface_topsoil_mineral_exchange_step.State,
    surface_microbial_turnover_state: ecosys.surface_microbial_turnover_step.State,
    surface_organic_priming_state: ecosys.surface_organic_priming_step.State,
    surface_organic_decomposition_state: ecosys.surface_organic_decomposition_step.State,
    surface_organic_sorption_state: ecosys.surface_organic_sorption_step.State,
    surface_litter_colonization_state: ecosys.surface_litter_colonization_step.State,
    surface_humification_fraction: []f64,
    topsoil_humus_partition: [][2]f64,
    humus_partition_by_layer: [][2]f64,
    surface_litter_fertilizer_diagnostics: ecosys.surface_litter_fertilizer_step.Diagnostics,
    soil_fertilizer_inventory: ecosys.fertilizer_nitrogen_inventory.State,
    mineral_fertilizer_inventory: ecosys.mineral_fertilizer_inventory.State,
    eroded_fertilizer_workspace: ecosys.eroded_constituents.PackedWorkspace,
    eroded_mineral_fertilizer_workspace: ecosys.eroded_constituents.PackedWorkspace,
    surface_litter_chemistry_diagnostics: ecosys.surface_litter_chemistry_step.Diagnostics,
    surface_litter_cation_selectivity: []ecosys.solute_cation_exchange.Selectivity,
};

const SurfaceProcessInitializationInputs = struct {
    allocator: std.mem.Allocator,
    cell_count: usize,
    layer_count: usize,
    soil_layers: usize,
    eroded_organic_component_count: usize,
    soil_catalog: *const ecosys.soil_catalog.Catalog,
    catalog_index_by_cell: []const usize,
};

noinline fn initializeSurfaceProcessOwners(
    owners: *SurfaceProcessOwners,
    resources: *MainResources,
    inputs: SurfaceProcessInitializationInputs,
) !void {
    const allocator = inputs.allocator;
    const cell_count = inputs.cell_count;
    owners.eroded_organic_workspace = try ecosys.eroded_constituents.PackedWorkspace.init(allocator, cell_count, inputs.eroded_organic_component_count);
    resources.ownDeinit(&owners.eroded_organic_workspace);
    owners.surface_litter_geometry_state = try ecosys.surface_litter_geometry_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_litter_geometry_state);
    owners.surface_litter_water_environment_state = try ecosys.surface_litter_water_environment.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_litter_water_environment_state);
    owners.surface_microbial_environment_state = try ecosys.surface_microbial_environment_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_microbial_environment_state);
    owners.surface_field_capacity_potential_megapascal = try allocator.alloc(f64, cell_count);
    resources.ownFree(&owners.surface_field_capacity_potential_megapascal);
    owners.surface_wilting_point_potential_megapascal = try allocator.alloc(f64, cell_count);
    resources.ownFree(&owners.surface_wilting_point_potential_megapascal);
    for (0..cell_count) |cell| {
        const profile = inputs.soil_catalog.entries.items[inputs.catalog_index_by_cell[cell]].profile;
        owners.surface_field_capacity_potential_megapascal[cell] = profile.field_capacity_potential_megapascal;
        owners.surface_wilting_point_potential_megapascal[cell] = profile.wilting_point_potential_megapascal;
    }
    owners.surface_litter_ice_m3 = try allocator.alloc(f64, cell_count);
    resources.ownFree(&owners.surface_litter_ice_m3);
    @memset(owners.surface_litter_ice_m3, 0);
    owners.surface_charcoal_carbon_g_c = try allocator.alloc(f64, cell_count);
    resources.ownFree(&owners.surface_charcoal_carbon_g_c);
    @memset(owners.surface_charcoal_carbon_g_c, 0);
    owners.surface_litter_chemistry_state = try ecosys.surface_litter_chemistry.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_litter_chemistry_state);
    owners.surface_litter_fertilizer_state = try ecosys.surface_litter_fertilizer.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_litter_fertilizer_state);
    owners.surface_microbial_respiration_state = try ecosys.surface_microbial_respiration_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_microbial_respiration_state);
    owners.surface_autotrophic_complex_state = try ecosys.surface_autotrophic_complex_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_autotrophic_complex_state);
    owners.surface_microbial_oxygen_state = try ecosys.surface_microbial_oxygen_driver.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_microbial_oxygen_state);
    owners.surface_microbial_maintenance_state = try ecosys.surface_microbial_maintenance_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_microbial_maintenance_state);
    owners.surface_nonsymbiotic_nitrogen_fixation_state = try ecosys.surface_nonsymbiotic_nitrogen_fixation_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_nonsymbiotic_nitrogen_fixation_state);
    owners.surface_microbial_substrate_uptake_state = try ecosys.surface_microbial_substrate_uptake_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_microbial_substrate_uptake_state);
    owners.surface_denitrification_state = try ecosys.surface_denitrification_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_denitrification_state);
    owners.surface_microbial_assimilation_state = try ecosys.surface_microbial_assimilation_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_microbial_assimilation_state);
    owners.surface_microbial_mineral_exchange_state = try ecosys.surface_microbial_mineral_exchange_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_microbial_mineral_exchange_state);
    owners.surface_topsoil_mineral_exchange_state = try ecosys.surface_topsoil_mineral_exchange_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_topsoil_mineral_exchange_state);
    owners.surface_microbial_turnover_state = try ecosys.surface_microbial_turnover_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_microbial_turnover_state);
    owners.surface_organic_priming_state = try ecosys.surface_organic_priming_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_organic_priming_state);
    owners.surface_organic_decomposition_state = try ecosys.surface_organic_decomposition_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_organic_decomposition_state);
    owners.surface_organic_sorption_state = try ecosys.surface_organic_sorption_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_organic_sorption_state);
    owners.surface_litter_colonization_state = try ecosys.surface_litter_colonization_step.State.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_litter_colonization_state);
    owners.surface_humification_fraction = try allocator.alloc(f64, cell_count);
    resources.ownFree(&owners.surface_humification_fraction);
    owners.topsoil_humus_partition = try allocator.alloc([2]f64, cell_count);
    resources.ownFree(&owners.topsoil_humus_partition);
    owners.humus_partition_by_layer = try allocator.alloc([2]f64, inputs.layer_count);
    resources.ownFree(&owners.humus_partition_by_layer);
    for (0..cell_count) |cell| {
        const topsoil_material = inputs.soil_catalog.entries.items[inputs.catalog_index_by_cell[cell]].material;
        owners.surface_humification_fraction[cell] = 0.150 + 0.300 * @min(0.333, topsoil_material.clay_mass_fraction[0]) + 0.182e-6 * topsoil_material.total_organic_carbon_g_per_megagram[0];
        const source_less_resistant_humus_fraction: f64 = 0.20;
        const source_microbial_litter_partition =
            5 * source_less_resistant_humus_fraction /
            (4 * source_less_resistant_humus_fraction + 1);
        owners.topsoil_humus_partition[cell] = .{
            source_microbial_litter_partition,
            1 - source_microbial_litter_partition,
        };
        for (0..inputs.soil_layers) |local_layer| {
            owners.humus_partition_by_layer[cell * inputs.soil_layers + local_layer] = .{
                source_microbial_litter_partition,
                1 - source_microbial_litter_partition,
            };
        }
    }
    owners.surface_litter_fertilizer_diagnostics = try ecosys.surface_litter_fertilizer_step.Diagnostics.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_litter_fertilizer_diagnostics);
    owners.soil_fertilizer_inventory = try ecosys.fertilizer_nitrogen_inventory.State.init(allocator, cell_count, inputs.soil_layers);
    resources.ownDeinit(&owners.soil_fertilizer_inventory);
    owners.mineral_fertilizer_inventory = try ecosys.mineral_fertilizer_inventory.State.init(allocator, cell_count, inputs.soil_layers);
    resources.ownDeinit(&owners.mineral_fertilizer_inventory);
    owners.eroded_fertilizer_workspace = try ecosys.eroded_constituents.PackedWorkspace.init(allocator, cell_count, ecosys.soil_erosion_fertilizer_bridge.component_count);
    resources.ownDeinit(&owners.eroded_fertilizer_workspace);
    owners.eroded_mineral_fertilizer_workspace = try ecosys.eroded_constituents.PackedWorkspace.init(allocator, cell_count, ecosys.soil_erosion_mineral_fertilizer_bridge.component_count);
    resources.ownDeinit(&owners.eroded_mineral_fertilizer_workspace);
    owners.surface_litter_chemistry_diagnostics = try ecosys.surface_litter_chemistry_step.Diagnostics.init(allocator, cell_count);
    resources.ownDeinit(&owners.surface_litter_chemistry_diagnostics);
    owners.surface_litter_cation_selectivity = try allocator.alloc(ecosys.solute_cation_exchange.Selectivity, cell_count);
    resources.ownFree(&owners.surface_litter_cation_selectivity);
    for (owners.surface_litter_cation_selectivity, 0..) |*selectivity, cell| {
        const profile = inputs.soil_catalog.entries.items[inputs.catalog_index_by_cell[cell]].profile;
        selectivity.* = .{
            .calcium_ammonium = profile.property(.gapon_calcium_ammonium)[0],
            .calcium_hydrogen = profile.property(.gapon_calcium_hydrogen)[0],
            .calcium_aluminum_and_iron = profile.property(.gapon_calcium_aluminum)[0],
            .calcium_magnesium = profile.property(.gapon_calcium_magnesium)[0],
            .calcium_sodium = profile.property(.gapon_calcium_sodium)[0],
            .calcium_potassium = profile.property(.gapon_calcium_potassium)[0],
        };
    }
}

/// Final-address owners for the snow, conservation-sidecar, and transport
/// initialization phase. Every `MainResources` entry targets one of these
/// stable fields in the same order as the former declarations in `main`.
const TransportConservationOwners = struct {
    snow_transport_state: ecosys.snow_solute_transport.State,
    layer_conservation_layout: ecosys.layer_local_conservation.Layout,
    hourly_layer_boundary_ledger: ecosys.layer_local_conservation.Ledger,
    tillage_local_activity: ecosys.redist_tillage_activity.Sidecar,
    plant_atmosphere_local_activity: []ecosys.hourly_cell_conservation.BoundaryActivity,
    fertilizer_local_activity: ecosys.fertilizer_management_dispatch.LocalActivityState,
    layer_scope_count: usize,
    hourly_layer_storage_before: []ecosys.landscape_mass_inventory.Storage,
    hourly_layer_storage_after: []ecosys.landscape_mass_inventory.Storage,
    layer_scope_area_m2: []f64,
    snow_atmospheric_input_g: []f64,
    snow_atmospheric_input_salt_mol: []f64,
    snow_accepted_downward_g: []f64,
    snow_accepted_downward_salt_mol: []f64,
    atmospheric_solute_input_ledger_state: ecosys.atmospheric_solute_input_ledger.State,
    snow_surface_partitions: []ecosys.snow_solute_transport.SurfacePartition,
    snow_surface_discharge: []ecosys.snow_solute_transport.SurfaceDischarge,
    direct_surface_solute_input: []ecosys.snow_solute_transport.SurfaceDischarge,
    snowpack_internal_solute_flux_by_layer: []ecosys.snowpack_internal_solute_aggregation.SoluteFlux,
    snowpack_internal_solute_flux_workspace: []ecosys.snowpack_internal_solute_aggregation.SoluteFlux,
    snowpack_internal_salt_flux_mol_by_layer_species: []f64,
    snowpack_internal_salt_flux_workspace_by_layer_species: []f64,
    transport_hydrology_state: ecosys.transport_hydrology.State,
    soil_transport_faces: ecosys.transport_hydrology.SoilFaces,
    soil_face_geometry_state: ecosys.soil_face_geometry.State,
    soil_solute_face_parameter_state: ecosys.soil_solute_face_parameters.State,
    micropore_solute_face_flux_mol: []f64,
    macropore_solute_face_flux_mol: []f64,
    soil_organic_face_parameter_state: ecosys.soil_organic_face_parameters.State,
    soil_dissolved_gas_face_parameter_state: ecosys.soil_dissolved_gas_face_parameters.State,
    soil_dissolved_gas_transport_state: ecosys.soil_dissolved_gas_transport.State,
    soil_dissolved_gas_recharge_concentration_g_per_m3: []f64,
    soil_organic_transport_state: ecosys.soil_organic_transport.State,
    soil_organic_recharge_concentration_g_per_m3: []f64,
    mineral_nitrogen_transport_state: ecosys.mineral_nitrogen_transport.State,
    mineral_nitrogen_face_parameters: ecosys.mineral_nitrogen_transport.FaceParameters,
    mineral_nitrogen_zone_fractions: ecosys.mineral_nitrogen_transport.ZoneFractions,
    surface_transport_state: ecosys.surface_solute_routing.State,
    redistribution_ledger: ecosys.transport_redistribution.Ledger,
};

const TransportConservationInitializationInputs = struct {
    allocator: std.mem.Allocator,
    state: *ecosys.grid.GridState,
    config: ecosys.config.SimulationConfig,
    runscript: *const ecosys.runscript.RunScript,
    lateral_connection_mode_by_cell: []const u8,
    soil_geometry_state: *const ecosys.soil_layer_geometry.State,
    soil_solver_property_state: *const ecosys.soil_solver_properties.State,
    grid_environment: *const ecosys.grid_environment.Assignments,
    soil_face_geometry_floor_m: f64,
    aqueous_species_count: usize,
    soil_organic_state: *ecosys.soil_organic_initialization.State,
    initial_chemistry_state: *const ecosys.solute_chemistry_state.State,
    soil_reactive_nitrogen_state: *const ecosys.soil_reactive_nitrogen_state.State,
    fertilizer_band_state: *const ecosys.fertilizer_band_state.State,
    micropore_solute_state: *const ecosys.solute_transport.State,
    gas_transport_state: *const ecosys.gas_transport.State,
};

noinline fn initializeTransportConservationOwners(
    owners: *TransportConservationOwners,
    resources: *MainResources,
    inputs: TransportConservationInitializationInputs,
) !void {
    const allocator = inputs.allocator;
    const state = inputs.state;
    const config = inputs.config;
    const runscript = inputs.runscript;
    owners.snow_transport_state = try ecosys.snow_solute_transport.State.init(
        allocator,
        state.cell_count,
        runscript.snow_layer_bottom_depth_m.len,
    );
    resources.ownDeinit(&owners.snow_transport_state);
    owners.layer_conservation_layout = try ecosys.layer_local_conservation.Layout.init(
        state.cell_count,
        state.soil_layer_capacity,
        owners.snow_transport_state.layer_capacity,
    );
    owners.hourly_layer_boundary_ledger = try ecosys.layer_local_conservation.Ledger.init(
        allocator,
        owners.layer_conservation_layout,
    );
    resources.ownDeinit(&owners.hourly_layer_boundary_ledger);
    // Activity reconstruction compares the exact REDIST producer matrix with
    // its committed post-state. Absolute floors are one-unit floating-point
    // representation scales in each native unit; relative/ULP terms scale
    // larger inventories without reusing conservation acceptance tolerances.
    const tillage_activity_roundoff = 512 * std.math.floatEps(f64);
    owners.tillage_local_activity = try ecosys.redist_tillage_activity.Sidecar.init(
        allocator,
        state.cell_count,
        state.soil_layer_capacity,
        .{
            .absolute = .{
                .water_m3 = tillage_activity_roundoff,
                .heat_megajoules = tillage_activity_roundoff,
                .oxygen_g = tillage_activity_roundoff,
                .hydrogen_g = tillage_activity_roundoff,
                .residue_carbon_g = tillage_activity_roundoff,
                .organic_carbon_g = tillage_activity_roundoff,
                .carbon_dioxide_carbon_g = tillage_activity_roundoff,
                .residue_nitrogen_g = tillage_activity_roundoff,
                .organic_nitrogen_g = tillage_activity_roundoff,
                .dinitrogen_nitrogen_g = tillage_activity_roundoff,
                .ammonium_nitrogen_g = tillage_activity_roundoff,
                .nitrate_nitrogen_g = tillage_activity_roundoff,
                .residue_phosphorus_g = tillage_activity_roundoff,
                .organic_phosphorus_g = tillage_activity_roundoff,
                .phosphate_phosphorus_g = tillage_activity_roundoff,
                .aluminum_mol = tillage_activity_roundoff,
                .iron_mol = tillage_activity_roundoff,
                .calcium_mol = tillage_activity_roundoff,
                .magnesium_mol = tillage_activity_roundoff,
                .sodium_mol = tillage_activity_roundoff,
                .potassium_mol = tillage_activity_roundoff,
                .sulfur_mol = tillage_activity_roundoff,
                .chloride_mol = tillage_activity_roundoff,
                .silicon_mol = tillage_activity_roundoff,
                .sand_megagrams = tillage_activity_roundoff,
                .silt_megagrams = tillage_activity_roundoff,
                .clay_megagrams = tillage_activity_roundoff,
                .rock_additive = tillage_activity_roundoff,
                .cation_exchange_capacity_mol = tillage_activity_roundoff,
                .anion_exchange_capacity_mol = tillage_activity_roundoff,
            },
            .relative = tillage_activity_roundoff,
            .representation_ulps = 512,
        },
    );
    resources.ownDeinit(&owners.tillage_local_activity);
    owners.plant_atmosphere_local_activity = try allocator.alloc(
        ecosys.hourly_cell_conservation.BoundaryActivity,
        state.cell_count,
    );
    resources.ownFree(&owners.plant_atmosphere_local_activity);
    @memset(owners.plant_atmosphere_local_activity, .{});
    owners.fertilizer_local_activity = try ecosys.fertilizer_management_dispatch
        .LocalActivityState.init(
        allocator,
        state.cell_count,
        state.soil_layer_capacity,
    );
    resources.ownDeinit(&owners.fertilizer_local_activity);
    owners.layer_scope_count = try owners.layer_conservation_layout.scopeCount();
    owners.hourly_layer_storage_before = try allocator.alloc(
        ecosys.landscape_mass_inventory.Storage,
        owners.layer_scope_count,
    );
    resources.ownFree(&owners.hourly_layer_storage_before);
    owners.hourly_layer_storage_after = try allocator.alloc(
        ecosys.landscape_mass_inventory.Storage,
        owners.layer_scope_count,
    );
    resources.ownFree(&owners.hourly_layer_storage_after);
    owners.layer_scope_area_m2 = try allocator.alloc(f64, owners.layer_scope_count);
    resources.ownFree(&owners.layer_scope_area_m2);
    @memset(owners.hourly_layer_storage_before, .{});
    @memset(owners.hourly_layer_storage_after, .{});
    @memset(owners.layer_scope_area_m2, 0);
    owners.snow_atmospheric_input_g = try allocator.alloc(
        f64,
        state.cell_count * ecosys.snow_solute_transport.species_count,
    );
    resources.ownFree(&owners.snow_atmospheric_input_g);
    @memset(owners.snow_atmospheric_input_g, 0);
    owners.snow_atmospheric_input_salt_mol = try allocator.alloc(
        f64,
        state.cell_count * ecosys.snow_solute_transport.salt_species_count,
    );
    resources.ownFree(&owners.snow_atmospheric_input_salt_mol);
    @memset(owners.snow_atmospheric_input_salt_mol, 0);
    owners.snow_accepted_downward_g = try allocator.alloc(
        f64,
        owners.snow_transport_state.amount_g.len,
    );
    resources.ownFree(&owners.snow_accepted_downward_g);
    @memset(owners.snow_accepted_downward_g, 0);
    owners.snow_accepted_downward_salt_mol = try allocator.alloc(
        f64,
        owners.snow_transport_state.salt_amount_mol.len,
    );
    resources.ownFree(&owners.snow_accepted_downward_salt_mol);
    @memset(owners.snow_accepted_downward_salt_mol, 0);
    owners.atmospheric_solute_input_ledger_state =
        try ecosys.atmospheric_solute_input_ledger.State.init(
            allocator,
            state.cell_count,
        );
    resources.ownDeinit(&owners.atmospheric_solute_input_ledger_state);
    owners.snow_surface_partitions = try allocator.alloc(
        ecosys.snow_solute_transport.SurfacePartition,
        state.cell_count,
    );
    resources.ownFree(&owners.snow_surface_partitions);
    owners.snow_surface_discharge = try allocator.alloc(
        ecosys.snow_solute_transport.SurfaceDischarge,
        state.cell_count,
    );
    resources.ownFree(&owners.snow_surface_discharge);
    owners.direct_surface_solute_input = try allocator.alloc(
        ecosys.snow_solute_transport.SurfaceDischarge,
        state.cell_count,
    );
    resources.ownFree(&owners.direct_surface_solute_input);
    @memset(owners.direct_surface_solute_input, .{});
    owners.snowpack_internal_solute_flux_by_layer = try allocator.alloc(
        ecosys.snowpack_internal_solute_aggregation.SoluteFlux,
        try std.math.mul(
            usize,
            state.cell_count,
            owners.snow_transport_state.layer_capacity,
        ),
    );
    resources.ownFree(&owners.snowpack_internal_solute_flux_by_layer);
    @memset(owners.snowpack_internal_solute_flux_by_layer, .{});
    owners.snowpack_internal_solute_flux_workspace = try allocator.alloc(
        ecosys.snowpack_internal_solute_aggregation.SoluteFlux,
        try std.math.mul(
            usize,
            state.cell_count,
            owners.snow_transport_state.layer_capacity,
        ),
    );
    resources.ownFree(&owners.snowpack_internal_solute_flux_workspace);
    @memset(owners.snowpack_internal_solute_flux_workspace, .{});
    owners.snowpack_internal_salt_flux_mol_by_layer_species = try allocator.alloc(
        f64,
        try std.math.mul(
            usize,
            try std.math.mul(
                usize,
                state.cell_count,
                owners.snow_transport_state.layer_capacity,
            ),
            ecosys.snowpack_internal_salt_aggregation.salt_species_count,
        ),
    );
    resources.ownFree(&owners.snowpack_internal_salt_flux_mol_by_layer_species);
    @memset(owners.snowpack_internal_salt_flux_mol_by_layer_species, 0);
    owners.snowpack_internal_salt_flux_workspace_by_layer_species = try allocator.alloc(
        f64,
        try std.math.mul(
            usize,
            try std.math.mul(
                usize,
                state.cell_count,
                owners.snow_transport_state.layer_capacity,
            ),
            ecosys.snowpack_internal_salt_aggregation.salt_species_count,
        ),
    );
    resources.ownFree(&owners.snowpack_internal_salt_flux_workspace_by_layer_species);
    @memset(owners.snowpack_internal_salt_flux_workspace_by_layer_species, 0);
    owners.transport_hydrology_state = try ecosys.transport_hydrology.State.init(
        allocator,
        config.lon_count,
        config.lat_count,
        config.soil_layers,
        owners.snow_transport_state.layer_capacity,
    );
    resources.ownDeinit(&owners.transport_hydrology_state);
    try owners.transport_hydrology_state.syncStorage(state, &owners.snow_transport_state);
    owners.soil_transport_faces = try ecosys.transport_hydrology.buildSoilFacesMapped(
        allocator,
        &owners.transport_hydrology_state,
        state,
        inputs.lateral_connection_mode_by_cell,
    );
    resources.ownDeinit(&owners.soil_transport_faces);
    try owners.soil_transport_faces.refreshMapped(
        &owners.transport_hydrology_state,
        state,
        inputs.soil_geometry_state,
        inputs.soil_face_geometry_floor_m,
    );
    owners.soil_face_geometry_state = try ecosys.soil_face_geometry.State.initMapped(
        allocator,
        state,
        &owners.soil_transport_faces,
        inputs.soil_solver_property_state.layer_thickness_m,
        inputs.grid_environment.horizontal_cell_width_m,
        inputs.grid_environment.vertical_cell_width_m,
    );
    resources.ownDeinit(&owners.soil_face_geometry_state);
    owners.soil_solute_face_parameter_state = try ecosys.soil_solute_face_parameters.State.init(
        allocator,
        owners.soil_transport_faces.micropore_faces.len,
    );
    resources.ownDeinit(&owners.soil_solute_face_parameter_state);
    const soil_solute_face_component_count = try std.math.mul(
        usize,
        owners.soil_transport_faces.micropore_faces.len,
        inputs.aqueous_species_count,
    );
    owners.micropore_solute_face_flux_mol = try allocator.alloc(
        f64,
        soil_solute_face_component_count,
    );
    resources.ownFree(&owners.micropore_solute_face_flux_mol);
    owners.macropore_solute_face_flux_mol = try allocator.alloc(
        f64,
        soil_solute_face_component_count,
    );
    resources.ownFree(&owners.macropore_solute_face_flux_mol);
    @memset(owners.micropore_solute_face_flux_mol, 0);
    @memset(owners.macropore_solute_face_flux_mol, 0);
    owners.soil_organic_face_parameter_state = try ecosys.soil_organic_face_parameters.State.init(
        allocator,
        owners.soil_transport_faces.micropore_faces.len,
    );
    resources.ownDeinit(&owners.soil_organic_face_parameter_state);
    owners.soil_dissolved_gas_face_parameter_state = try ecosys.soil_dissolved_gas_face_parameters.State.init(
        allocator,
        owners.soil_transport_faces.micropore_faces.len,
    );
    resources.ownDeinit(&owners.soil_dissolved_gas_face_parameter_state);
    owners.soil_dissolved_gas_transport_state = try ecosys.soil_dissolved_gas_transport.State.init(
        allocator,
        state.layer_count,
    );
    resources.ownDeinit(&owners.soil_dissolved_gas_transport_state);
    owners.soil_dissolved_gas_recharge_concentration_g_per_m3 = try allocator.alloc(
        f64,
        state.layer_count * ecosys.gas_transport.species_count,
    );
    resources.ownFree(&owners.soil_dissolved_gas_recharge_concentration_g_per_m3);
    @memset(owners.soil_dissolved_gas_recharge_concentration_g_per_m3, 0);
    owners.soil_organic_transport_state = try ecosys.soil_organic_transport.State.init(
        allocator,
        state.layer_count,
    );
    resources.ownDeinit(&owners.soil_organic_transport_state);
    try owners.soil_organic_transport_state.initializeFromProfile(inputs.soil_organic_state);
    owners.soil_organic_recharge_concentration_g_per_m3 = try allocator.alloc(
        f64,
        state.layer_count * ecosys.soil_organic_transport.component_count,
    );
    resources.ownFree(&owners.soil_organic_recharge_concentration_g_per_m3);
    @memset(owners.soil_organic_recharge_concentration_g_per_m3, 0);
    owners.mineral_nitrogen_transport_state = try ecosys.mineral_nitrogen_transport.State.init(
        allocator,
        state.layer_count,
    );
    resources.ownDeinit(&owners.mineral_nitrogen_transport_state);
    owners.mineral_nitrogen_face_parameters = try ecosys.mineral_nitrogen_transport.FaceParameters.init(
        allocator,
        owners.soil_transport_faces.micropore_faces.len,
    );
    resources.ownDeinit(&owners.mineral_nitrogen_face_parameters);
    owners.mineral_nitrogen_zone_fractions = .{
        .ammonium_non_band = 1 - runscript.plant_nutrient_initialization.initial_ammonium_band_fraction,
        .ammonium_band = runscript.plant_nutrient_initialization.initial_ammonium_band_fraction,
        .nitrate_non_band = 1 - runscript.plant_nutrient_initialization.initial_nitrate_band_fraction,
        .nitrate_band = runscript.plant_nutrient_initialization.initial_nitrate_band_fraction,
    };
    try owners.mineral_nitrogen_transport_state.initializeMatrix(
        inputs.initial_chemistry_state,
        inputs.soil_reactive_nitrogen_state,
        state.matrix_liquid_water_m3,
        // Establish the transport-owned hour-one inventory with the same
        // authoritative layer-aware fractions used by every later hourly
        // capture. This must precede the first cell/layer storage census.
        inputs.fertilizer_band_state,
        runscript.fertilizer_nitrogen_molar_mass_g_per_mol,
    );
    owners.surface_transport_state = try ecosys.surface_solute_routing.State.init(
        allocator,
        config.lon_count,
        config.lat_count,
        inputs.aqueous_species_count,
    );
    resources.ownDeinit(&owners.surface_transport_state);
    owners.redistribution_ledger = try ecosys.transport_redistribution.Ledger.init(
        allocator,
        inputs.micropore_solute_state.amount_mol.len,
        inputs.gas_transport_state.gaseous_mass_g.len,
        owners.snow_transport_state.amount_g.len,
        owners.surface_transport_state.amount_mol.len,
        inputs.micropore_solute_state.species_count,
        ecosys.gas_transport.species_count,
        ecosys.snow_solute_transport.species_count,
        inputs.aqueous_species_count,
    );
    resources.ownDeinit(&owners.redistribution_ledger);
}

/// Final-address owners for hourly forcing, atmosphere, irrigation, canopy
/// radiation, and surface-exchange workspaces. `MainResources` retains direct
/// pointers to these fields, so the owner must be initialized in its permanent
/// `main` stack location and must never be returned or moved by value.
const RuntimeEnvironmentWorkspaceOwners = struct {
    soil_hourly_workspace: ecosys.soil_hourly_workspace.State,
    soil_heat_solver_workspace: ecosys.soil_heat_solver.Workspace,
    atmospheric_state: ecosys.atmospheric_forcing.State,
    hourly_forcing_by_cell: []ecosys.weather.HourlyForcing,
    hourly_radiation_by_cell: []ecosys.atmospheric_radiation.Result,
    hourly_weather_header_by_cell: []ecosys.weather.Header,
    plant_calendar_by_cell: []ecosys.plant_development.Calendar,
    hourly_weather_reference_height_m: []f64,
    hourly_adjusted_shortwave_megajoules_per_m2: []f64,
    hourly_extraterrestrial_shortwave_megajoules_per_m2: []f64,
    hourly_solar_angle_sine: []f64,
    hourly_solar_azimuth_radians: []f64,
    irrigation_water_depth_m: []f64,
    irrigation_dissolved_mass_g_per_m2: []f64,
    irrigation_hydrogen_mol_per_m2: []f64,
    irrigation_loads: ecosys.irrigation_layer_routing.Loads,
    automatic_irrigation_depth_m_by_cell_hour: []f64,
    minimum_canopy_water_potential_mpa_by_cell: []f64,
    soil_wilting_point_fraction: []f64,
    canopy_radiation_state: ecosys.canopy_radiation.State,
    canopy_optics_state: ?ecosys.canopy_optics.State,
    canopy_cell_area_m2: []f64,
    surface_pond_minimum_heat_capacity_megajoules_per_k: []f64,
    total_grid_area_m2: f64,
    initial_ground_air_temperature_k: []f64,
    initial_ground_air_vapor_fraction: []f64,
    atmospheric_background_mixing_ratios: []ecosys.atmospheric_gas_mass_concentration.MixingRatios,
    surface_aerodynamic_state: ecosys.surface_aerodynamics.State,
    ground_air_state: ecosys.ground_air_exchange.State,
    atmospheric_canopy_gas_state: ecosys.atmospheric_canopy_gas_state.State,
    atmospheric_ground_radiation_fraction: []f64,
    atmospheric_boundary_resistance_h_per_m: []f64,
    atmospheric_co2_net_input_g_c: []f64,
    atmospheric_ch4_net_input_g_c: []f64,
    atmospheric_o2_net_input_g_o: []f64,
    surface_total_canopy_area_m2: []f64,
    surface_stalk_area_m2: []f64,
    surface_canopy_height_m: []f64,
    ground_air_vapor_pressure_kpa: []f64,
    atmospheric_vapor_fraction: []f64,
    ground_air_canopy_resistance_h_per_m: []f64,
    ground_air_sensible_source_megajoules_per_h: []f64,
    runtime_plant_count: usize,
    grazing_average_shoot_carbon_g_c: []f64,
    grazing_active_cell_count: []usize,
    grazing_total_shoot_carbon_g_c_by_cell: []f64,
    grazing_total_grazer_biomass_by_cell: []f64,
    plant_daily_flux_ledger: ecosys.plant_daily_flux_ledger.State,
    plant_root_soil_exchange_state: ecosys.plant_root_soil_exchange_accumulation.State,
    delayed_live_canopy_combustion_heat_megajoules: []f64,
    delayed_standing_dead_combustion_heat_megajoules: []f64,
    delayed_subsurface_combustion_heat_megajoules: []f64,
    delayed_root_uptake_heat_megajoules: []f64,
    delayed_surface_combustion_heat_megajoules: []f64,
    surface_combustion_heat_megajoules_per_m2: []f64,
    ground_air_vapor_source_m3_per_h: []f64,
    ground_air_surface_sensible_conductance_megajoules_per_h_k: []f64,
    ground_air_surface_vapor_conductance_m3_per_h: []f64,
    ground_air_surface_vapor_fraction: []f64,
    ground_surface_evaporation_m3_per_h: []f64,
    ground_surface_condensation_m3_per_h: []f64,
    ground_surface_litter_water_change_m3: []f64,
    ground_surface_topsoil_water_change_m3: []f64,
};

const RuntimeEnvironmentWorkspaceInputs = struct {
    allocator: std.mem.Allocator,
    state: *ecosys.grid.GridState,
    config: ecosys.config.SimulationConfig,
    runscript: *const ecosys.runscript.RunScript,
    soil_solver_property_state: *const ecosys.soil_solver_properties.State,
    soil_thermal_state: *const ecosys.soil_thermal.State,
    terrain_hydrology_state: *const ecosys.terrain_hydrology.State,
    initial_chemistry_state: *const ecosys.solute_chemistry_state.State,
    soil_micropore_face_count: usize,
    plant_assignments: ?ecosys.plant_assignment.Assignments,
    plant_unit_by_cell: ?[]usize,
    plant_catalog: ecosys.plant_catalog.Catalog,
    grid_environment: *const ecosys.grid_environment.Assignments,
    layer_conservation_layout: ecosys.layer_local_conservation.Layout,
    layer_scope_area_m2: []f64,
    site_by_cell: []const ecosys.site.Site,
    atmospheric_hydrogen_mixing_ratio_umol_per_mol: f64,
};

noinline fn initializeRuntimeEnvironmentWorkspaceOwners(
    owners: *RuntimeEnvironmentWorkspaceOwners,
    resources: *MainResources,
    inputs: RuntimeEnvironmentWorkspaceInputs,
) !void {
    const allocator = inputs.allocator;
    const state = inputs.state;
    const config = inputs.config;
    const runscript = inputs.runscript;
    owners.soil_hourly_workspace = try ecosys.soil_hourly_workspace.State.init(allocator, state.layer_count);
    resources.ownDeinit(&owners.soil_hourly_workspace);
    const initialization_soil_osmotic_zone_fractions = ecosys.solute_charge_classification.ZoneFractions{
        .ammonium_non_band = 1 - runscript.plant_nutrient_initialization.initial_ammonium_band_fraction,
        .ammonium_band = runscript.plant_nutrient_initialization.initial_ammonium_band_fraction,
        .nitrate_non_band = 1 - runscript.plant_nutrient_initialization.initial_nitrate_band_fraction,
        .nitrate_band = runscript.plant_nutrient_initialization.initial_nitrate_band_fraction,
        .phosphate_non_band = 1 - runscript.plant_nutrient_initialization.initial_phosphate_band_fraction,
        .phosphate_band = runscript.plant_nutrient_initialization.initial_phosphate_band_fraction,
    };
    try owners.soil_hourly_workspace.refresh(state, inputs.soil_solver_property_state, inputs.soil_thermal_state, inputs.terrain_hydrology_state, runscript.soil_process_parameters, runscript.soil_phase_heat_parameters.freeze_thaw.ice_density_megagrams_per_m3, inputs.initial_chemistry_state, initialization_soil_osmotic_zone_fractions);
    owners.soil_heat_solver_workspace = try ecosys.soil_heat_solver.Workspace.init(
        allocator,
        state.layer_count,
        inputs.soil_micropore_face_count,
        hourly_heat_water_solute.production_dense_newton_max_components,
    );
    resources.ownDeinit(&owners.soil_heat_solver_workspace);
    owners.atmospheric_state = try ecosys.atmospheric_forcing.State.init(allocator, state.cell_count);
    resources.ownDeinit(&owners.atmospheric_state);
    owners.hourly_forcing_by_cell = try allocator.alloc(ecosys.weather.HourlyForcing, state.cell_count);
    resources.ownFree(&owners.hourly_forcing_by_cell);
    owners.hourly_radiation_by_cell = try allocator.alloc(ecosys.atmospheric_radiation.Result, state.cell_count);
    resources.ownFree(&owners.hourly_radiation_by_cell);
    owners.hourly_weather_header_by_cell = try allocator.alloc(ecosys.weather.Header, state.cell_count);
    resources.ownFree(&owners.hourly_weather_header_by_cell);
    owners.plant_calendar_by_cell = try allocator.alloc(
        ecosys.plant_development.Calendar,
        state.cell_count,
    );
    resources.ownFree(&owners.plant_calendar_by_cell);
    owners.hourly_weather_reference_height_m = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.hourly_weather_reference_height_m);
    owners.hourly_adjusted_shortwave_megajoules_per_m2 = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.hourly_adjusted_shortwave_megajoules_per_m2);
    owners.hourly_extraterrestrial_shortwave_megajoules_per_m2 = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.hourly_extraterrestrial_shortwave_megajoules_per_m2);
    owners.hourly_solar_angle_sine = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.hourly_solar_angle_sine);
    owners.hourly_solar_azimuth_radians = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.hourly_solar_azimuth_radians);
    owners.irrigation_water_depth_m = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.irrigation_water_depth_m);
    @memset(owners.irrigation_water_depth_m, 0);
    owners.irrigation_dissolved_mass_g_per_m2 = try allocator.alloc(f64, state.cell_count * ecosys.irrigation_management_dispatch.dissolved_species_count);
    resources.ownFree(&owners.irrigation_dissolved_mass_g_per_m2);
    @memset(owners.irrigation_dissolved_mass_g_per_m2, 0);
    owners.irrigation_hydrogen_mol_per_m2 = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.irrigation_hydrogen_mol_per_m2);
    @memset(owners.irrigation_hydrogen_mol_per_m2, 0);
    owners.irrigation_loads = try ecosys.irrigation_layer_routing.Loads.init(
        allocator,
        state.cell_count,
        state.soil_layer_capacity,
    );
    resources.ownDeinit(&owners.irrigation_loads);
    owners.automatic_irrigation_depth_m_by_cell_hour = try allocator.alloc(f64, state.cell_count * 24);
    resources.ownFree(&owners.automatic_irrigation_depth_m_by_cell_hour);
    @memset(owners.automatic_irrigation_depth_m_by_cell_hour, 0);
    owners.minimum_canopy_water_potential_mpa_by_cell = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.minimum_canopy_water_potential_mpa_by_cell);
    @memset(owners.minimum_canopy_water_potential_mpa_by_cell, 0);
    owners.soil_wilting_point_fraction = inputs.soil_solver_property_state.wilting_point_fraction;
    owners.canopy_radiation_state = try ecosys.canopy_radiation.State.init(allocator, state.cell_count);
    resources.ownDeinit(&owners.canopy_radiation_state);
    owners.canopy_optics_state = null;
    resources.ownOptionalDeinit(&owners.canopy_optics_state);
    if (inputs.plant_assignments) |assignments| owners.canopy_optics_state = try ecosys.canopy_optics.State.initMapped(
        allocator,
        state.cell_count,
        config.plant_populations,
        assignments,
        inputs.plant_unit_by_cell.?,
        inputs.plant_catalog,
    );
    owners.canopy_cell_area_m2 = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.canopy_cell_area_m2);
    owners.surface_pond_minimum_heat_capacity_megajoules_per_k = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.surface_pond_minimum_heat_capacity_megajoules_per_k);
    owners.total_grid_area_m2 = 0;
    for (owners.canopy_cell_area_m2, 0..) |*area_m2, cell| {
        area_m2.* = inputs.grid_environment.horizontal_cell_width_m[cell] *
            inputs.grid_environment.vertical_cell_width_m[cell];
        if (!std.math.isFinite(area_m2.*) or area_m2.* <= 0) return error.InvalidCanopyCellArea;
        owners.surface_pond_minimum_heat_capacity_megajoules_per_k[cell] = runscript.surface_pond_activation_heat_capacity_megajoules_per_m2_k * area_m2.*;
        owners.total_grid_area_m2 += area_m2.*;
    }
    if (!std.math.isFinite(owners.total_grid_area_m2) or owners.total_grid_area_m2 <= 0) return error.InvalidOutputGridArea;
    try ecosys.layer_mass_inventory.fillScopeAreas(
        inputs.layer_conservation_layout,
        owners.canopy_cell_area_m2,
        inputs.layer_scope_area_m2,
    );
    owners.initial_ground_air_temperature_k = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.initial_ground_air_temperature_k);
    owners.initial_ground_air_vapor_fraction = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.initial_ground_air_vapor_fraction);
    owners.atmospheric_background_mixing_ratios = try allocator.alloc(
        ecosys.atmospheric_gas_mass_concentration.MixingRatios,
        state.cell_count,
    );
    resources.ownFree(&owners.atmospheric_background_mixing_ratios);
    for (inputs.site_by_cell, 0..) |selected_site, cell| {
        const initial_ground_air_temperature = selected_site.mean_annual_air_temperature_c + 273.15;
        owners.initial_ground_air_temperature_k[cell] = initial_ground_air_temperature;
        // STARTS TKQGX/VPQGX initializes boundary-air temperature from ATKA
        // and its water-vapor storage to zero. WATSUB subsequently advances
        // that storage from the accepted atmospheric/surface exchanges.
        owners.initial_ground_air_vapor_fraction[cell] = 0;
        owners.atmospheric_background_mixing_ratios[cell] = .{
            .carbon_dioxide_umol_mol = selected_site.atmospheric_co2_umol_mol,
            .methane_umol_mol = selected_site.atmospheric_methane_umol_mol,
            .oxygen_umol_mol = selected_site.atmospheric_oxygen_umol_mol,
            .nitrogen_umol_mol = selected_site.atmospheric_nitrogen_umol_mol,
            .nitrous_oxide_umol_mol = selected_site.atmospheric_nitrous_oxide_umol_mol,
            .ammonia_umol_mol = selected_site.atmospheric_ammonia_umol_mol,
            .hydrogen_umol_mol = inputs.atmospheric_hydrogen_mixing_ratio_umol_per_mol,
        };
    }
    owners.surface_aerodynamic_state = try ecosys.surface_aerodynamics.State.init(
        allocator,
        state.cell_count,
        runscript.surface_aerodynamic_parameters.soil_roughness_height_m,
        runscript.surface_aerodynamic_parameters.soil_roughness_height_m +
            runscript.surface_aerodynamic_parameters.minimum_reference_height_above_displacement_m,
    );
    resources.ownDeinit(&owners.surface_aerodynamic_state);
    owners.ground_air_state = try ecosys.ground_air_exchange.State.init(allocator, owners.initial_ground_air_temperature_k, owners.initial_ground_air_vapor_fraction, owners.canopy_cell_area_m2, runscript.ground_air_parameters.minimum_air_column_height_m, runscript.ground_air_parameters);
    resources.ownDeinit(&owners.ground_air_state);
    owners.atmospheric_canopy_gas_state = try ecosys.atmospheric_canopy_gas_state.State.init(
        allocator,
        owners.initial_ground_air_temperature_k,
        owners.initial_ground_air_vapor_fraction,
        owners.atmospheric_background_mixing_ratios,
    );
    resources.ownDeinit(&owners.atmospheric_canopy_gas_state);
    owners.atmospheric_ground_radiation_fraction = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.atmospheric_ground_radiation_fraction);
    @memset(owners.atmospheric_ground_radiation_fraction, 1);
    owners.atmospheric_boundary_resistance_h_per_m = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.atmospheric_boundary_resistance_h_per_m);
    owners.atmospheric_co2_net_input_g_c = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.atmospheric_co2_net_input_g_c);
    owners.atmospheric_ch4_net_input_g_c = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.atmospheric_ch4_net_input_g_c);
    owners.atmospheric_o2_net_input_g_o = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.atmospheric_o2_net_input_g_o);
    owners.surface_total_canopy_area_m2 = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.surface_total_canopy_area_m2);
    @memset(owners.surface_total_canopy_area_m2, 0);
    owners.surface_stalk_area_m2 = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.surface_stalk_area_m2);
    @memset(owners.surface_stalk_area_m2, 0);
    owners.surface_canopy_height_m = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.surface_canopy_height_m);
    @memset(owners.surface_canopy_height_m, 0);
    owners.ground_air_vapor_pressure_kpa = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.ground_air_vapor_pressure_kpa);
    @memset(owners.ground_air_vapor_pressure_kpa, 0);
    owners.atmospheric_vapor_fraction = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.atmospheric_vapor_fraction);
    @memset(owners.atmospheric_vapor_fraction, 0);
    owners.ground_air_canopy_resistance_h_per_m = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.ground_air_canopy_resistance_h_per_m);
    @memset(owners.ground_air_canopy_resistance_h_per_m, 0);
    owners.ground_air_sensible_source_megajoules_per_h = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.ground_air_sensible_source_megajoules_per_h);
    @memset(owners.ground_air_sensible_source_megajoules_per_h, 0);
    owners.runtime_plant_count = try std.math.mul(usize, state.cell_count, config.plant_populations);
    owners.grazing_average_shoot_carbon_g_c = try allocator.alloc(f64, config.plant_populations);
    resources.ownFree(&owners.grazing_average_shoot_carbon_g_c);
    @memset(owners.grazing_average_shoot_carbon_g_c, 0);
    owners.grazing_active_cell_count = try allocator.alloc(usize, config.plant_populations);
    resources.ownFree(&owners.grazing_active_cell_count);
    @memset(owners.grazing_active_cell_count, 0);
    owners.grazing_total_shoot_carbon_g_c_by_cell = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.grazing_total_shoot_carbon_g_c_by_cell);
    owners.grazing_total_grazer_biomass_by_cell = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.grazing_total_grazer_biomass_by_cell);
    owners.plant_daily_flux_ledger = try ecosys.plant_daily_flux_ledger.State.init(allocator, owners.runtime_plant_count);
    resources.ownDeinit(&owners.plant_daily_flux_ledger);
    owners.plant_root_soil_exchange_state = try ecosys.plant_root_soil_exchange_accumulation.State.init(allocator, owners.runtime_plant_count);
    resources.ownDeinit(&owners.plant_root_soil_exchange_state);
    owners.delayed_live_canopy_combustion_heat_megajoules = try allocator.alloc(f64, owners.runtime_plant_count);
    resources.ownFree(&owners.delayed_live_canopy_combustion_heat_megajoules);
    @memset(owners.delayed_live_canopy_combustion_heat_megajoules, 0);
    owners.delayed_standing_dead_combustion_heat_megajoules = try allocator.alloc(f64, owners.runtime_plant_count);
    resources.ownFree(&owners.delayed_standing_dead_combustion_heat_megajoules);
    @memset(owners.delayed_standing_dead_combustion_heat_megajoules, 0);
    owners.delayed_subsurface_combustion_heat_megajoules = try allocator.alloc(f64, state.layer_count);
    resources.ownFree(&owners.delayed_subsurface_combustion_heat_megajoules);
    @memset(owners.delayed_subsurface_combustion_heat_megajoules, 0);
    // Backward-compatible checkpoint slot for releases which carried TUPHT
    // across the hour boundary. Production consumes any restored legacy value
    // once; current root-water science applies and books TUPWTR/TUPHT together
    // in the same hour and never writes a new delayed value.
    owners.delayed_root_uptake_heat_megajoules = try allocator.alloc(f64, state.layer_count);
    resources.ownFree(&owners.delayed_root_uptake_heat_megajoules);
    @memset(owners.delayed_root_uptake_heat_megajoules, 0);
    owners.delayed_surface_combustion_heat_megajoules = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.delayed_surface_combustion_heat_megajoules);
    @memset(owners.delayed_surface_combustion_heat_megajoules, 0);
    owners.surface_combustion_heat_megajoules_per_m2 = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.surface_combustion_heat_megajoules_per_m2);
    @memset(owners.surface_combustion_heat_megajoules_per_m2, 0);
    owners.ground_air_vapor_source_m3_per_h = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.ground_air_vapor_source_m3_per_h);
    @memset(owners.ground_air_vapor_source_m3_per_h, 0);
    owners.ground_air_surface_sensible_conductance_megajoules_per_h_k = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.ground_air_surface_sensible_conductance_megajoules_per_h_k);
    @memset(owners.ground_air_surface_sensible_conductance_megajoules_per_h_k, 0);
    owners.ground_air_surface_vapor_conductance_m3_per_h = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.ground_air_surface_vapor_conductance_m3_per_h);
    @memset(owners.ground_air_surface_vapor_conductance_m3_per_h, 0);
    owners.ground_air_surface_vapor_fraction = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.ground_air_surface_vapor_fraction);
    @memset(owners.ground_air_surface_vapor_fraction, 0);
    owners.ground_surface_evaporation_m3_per_h = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.ground_surface_evaporation_m3_per_h);
    @memset(owners.ground_surface_evaporation_m3_per_h, 0);
    owners.ground_surface_condensation_m3_per_h = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.ground_surface_condensation_m3_per_h);
    @memset(owners.ground_surface_condensation_m3_per_h, 0);
    owners.ground_surface_litter_water_change_m3 = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.ground_surface_litter_water_change_m3);
    @memset(owners.ground_surface_litter_water_change_m3, 0);
    owners.ground_surface_topsoil_water_change_m3 = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.ground_surface_topsoil_water_change_m3);
    @memset(owners.ground_surface_topsoil_water_change_m3, 0);
}

test "runtime environment workspace ownership follows source order and final address" {
    const allocator = std.testing.allocator;
    const source = try std.Io.Dir.cwd().readFileAlloc(
        std.testing.io,
        "src/ecosys_ng.zig",
        allocator,
        .limited(4 * 1024 * 1024),
    );
    defer allocator.free(source);

    const initializer_start = std.mem.indexOf(
        u8,
        source,
        "noinline fn initializeRuntimeEnvironmentWorkspaceOwners(",
    ) orelse return error.MissingRuntimeEnvironmentWorkspaceInitializer;
    const initializer_end = std.mem.indexOfPos(
        u8,
        source,
        initializer_start,
        "test \"runtime environment workspace ownership follows source order and final address\"",
    ) orelse return error.MissingRuntimeEnvironmentWorkspaceInitializerEnd;
    const body = source[initializer_start..initializer_end];
    const expected = [_][]const u8{
        "resources.ownDeinit(&owners.soil_hourly_workspace);",
        "resources.ownDeinit(&owners.soil_heat_solver_workspace);",
        "resources.ownDeinit(&owners.atmospheric_state);",
        "resources.ownFree(&owners.hourly_forcing_by_cell);",
        "resources.ownFree(&owners.hourly_radiation_by_cell);",
        "resources.ownFree(&owners.hourly_weather_header_by_cell);",
        "resources.ownFree(&owners.plant_calendar_by_cell);",
        "resources.ownFree(&owners.hourly_weather_reference_height_m);",
        "resources.ownFree(&owners.hourly_adjusted_shortwave_megajoules_per_m2);",
        "resources.ownFree(&owners.hourly_extraterrestrial_shortwave_megajoules_per_m2);",
        "resources.ownFree(&owners.hourly_solar_angle_sine);",
        "resources.ownFree(&owners.hourly_solar_azimuth_radians);",
        "resources.ownFree(&owners.irrigation_water_depth_m);",
        "resources.ownFree(&owners.irrigation_dissolved_mass_g_per_m2);",
        "resources.ownFree(&owners.irrigation_hydrogen_mol_per_m2);",
        "resources.ownDeinit(&owners.irrigation_loads);",
        "resources.ownFree(&owners.automatic_irrigation_depth_m_by_cell_hour);",
        "resources.ownFree(&owners.minimum_canopy_water_potential_mpa_by_cell);",
        "resources.ownDeinit(&owners.canopy_radiation_state);",
        "resources.ownOptionalDeinit(&owners.canopy_optics_state);",
        "resources.ownFree(&owners.canopy_cell_area_m2);",
        "resources.ownFree(&owners.surface_pond_minimum_heat_capacity_megajoules_per_k);",
        "resources.ownFree(&owners.initial_ground_air_temperature_k);",
        "resources.ownFree(&owners.initial_ground_air_vapor_fraction);",
        "resources.ownFree(&owners.atmospheric_background_mixing_ratios);",
        "resources.ownDeinit(&owners.surface_aerodynamic_state);",
        "resources.ownDeinit(&owners.ground_air_state);",
        "resources.ownDeinit(&owners.atmospheric_canopy_gas_state);",
        "resources.ownFree(&owners.atmospheric_ground_radiation_fraction);",
        "resources.ownFree(&owners.atmospheric_boundary_resistance_h_per_m);",
        "resources.ownFree(&owners.atmospheric_co2_net_input_g_c);",
        "resources.ownFree(&owners.atmospheric_ch4_net_input_g_c);",
        "resources.ownFree(&owners.atmospheric_o2_net_input_g_o);",
        "resources.ownFree(&owners.surface_total_canopy_area_m2);",
        "resources.ownFree(&owners.surface_stalk_area_m2);",
        "resources.ownFree(&owners.surface_canopy_height_m);",
        "resources.ownFree(&owners.ground_air_vapor_pressure_kpa);",
        "resources.ownFree(&owners.atmospheric_vapor_fraction);",
        "resources.ownFree(&owners.ground_air_canopy_resistance_h_per_m);",
        "resources.ownFree(&owners.ground_air_sensible_source_megajoules_per_h);",
        "resources.ownFree(&owners.grazing_average_shoot_carbon_g_c);",
        "resources.ownFree(&owners.grazing_active_cell_count);",
        "resources.ownFree(&owners.grazing_total_shoot_carbon_g_c_by_cell);",
        "resources.ownFree(&owners.grazing_total_grazer_biomass_by_cell);",
        "resources.ownDeinit(&owners.plant_daily_flux_ledger);",
        "resources.ownDeinit(&owners.plant_root_soil_exchange_state);",
        "resources.ownFree(&owners.delayed_live_canopy_combustion_heat_megajoules);",
        "resources.ownFree(&owners.delayed_standing_dead_combustion_heat_megajoules);",
        "resources.ownFree(&owners.delayed_subsurface_combustion_heat_megajoules);",
        "resources.ownFree(&owners.delayed_root_uptake_heat_megajoules);",
        "resources.ownFree(&owners.delayed_surface_combustion_heat_megajoules);",
        "resources.ownFree(&owners.surface_combustion_heat_megajoules_per_m2);",
        "resources.ownFree(&owners.ground_air_vapor_source_m3_per_h);",
        "resources.ownFree(&owners.ground_air_surface_sensible_conductance_megajoules_per_h_k);",
        "resources.ownFree(&owners.ground_air_surface_vapor_conductance_m3_per_h);",
        "resources.ownFree(&owners.ground_air_surface_vapor_fraction);",
        "resources.ownFree(&owners.ground_surface_evaporation_m3_per_h);",
        "resources.ownFree(&owners.ground_surface_condensation_m3_per_h);",
        "resources.ownFree(&owners.ground_surface_litter_water_change_m3);",
        "resources.ownFree(&owners.ground_surface_topsoil_water_change_m3);",
    };
    var cursor: usize = 0;
    for (expected) |registration| {
        const position = std.mem.indexOfPos(u8, body, cursor, registration) orelse
            return error.MissingOrderedRuntimeEnvironmentWorkspaceOwnership;
        cursor = position + registration.len;
    }
    try std.testing.expectEqual(expected.len, std.mem.count(u8, body, "resources.own"));

    const main_marker = "\npub fn main(init: std.process.Init) !void {";
    const main_marker_start = std.mem.indexOf(u8, source, main_marker) orelse
        return error.MissingRuntimeEnvironmentWorkspaceMain;
    const main_source = source[main_marker_start + 1 ..];
    const declaration = std.mem.indexOf(
        u8,
        main_source,
        "var runtime_environment_workspace_owners: RuntimeEnvironmentWorkspaceOwners = undefined;",
    ) orelse return error.MissingFinalAddressRuntimeEnvironmentWorkspaceOwner;
    const call = std.mem.indexOfPos(
        u8,
        main_source,
        declaration,
        "try initializeRuntimeEnvironmentWorkspaceOwners(",
    ) orelse return error.MissingRuntimeEnvironmentWorkspaceInitializationCall;
    try std.testing.expect(declaration < call);

    const plant_phase_markers = [_][]const u8{
        "noinline fn initializePlantAccountingRuntimeOwners(",
        "noinline fn initializePlantProcessRuntimeOwners(",
        "noinline fn initializePlantEnergyWaterRuntimeOwners(",
        "noinline fn initializePlantCanopyRuntimeOwners(",
    };
    const expected_plant_ownership_counts = [_]usize{ 17, 14, 6 };
    for (expected_plant_ownership_counts, 0..) |expected_count, phase| {
        const start = std.mem.lastIndexOf(u8, source, plant_phase_markers[phase]) orelse
            return error.MissingPlantCanopyRuntimeOwnershipPhase;
        const end = std.mem.lastIndexOf(u8, source, plant_phase_markers[phase + 1]) orelse
            return error.MissingPlantCanopyRuntimeOwnershipPhaseEnd;
        try std.testing.expect(start < end);
        const phase_body = source[start..end];
        try std.testing.expectEqual(expected_count, std.mem.count(u8, phase_body, "resources.own"));
        try std.testing.expectEqual(expected_count, std.mem.count(u8, phase_body, "try "));
    }
    const plant_declaration = std.mem.indexOf(
        u8,
        main_source,
        "var plant_canopy_runtime_owners: PlantCanopyRuntimeOwners = undefined;",
    ) orelse return error.MissingFinalAddressPlantCanopyRuntimeOwner;
    const plant_call = std.mem.indexOfPos(
        u8,
        main_source,
        plant_declaration,
        "try initializePlantCanopyRuntimeOwners(",
    ) orelse return error.MissingPlantCanopyRuntimeInitializationCall;
    try std.testing.expect(plant_declaration < plant_call);
}

/// Runtime plant/canopy owners allocated after the static plant topology is
/// known. Cleanup registrations point at these fields, so the value must be
/// initialized in its final `main` stack location and never moved by value.
const PlantCanopyRuntimeOwners = struct {
    const PendingSurfaceGasLedgerEntry = struct {
        co2_surface_input_g: f64 = 0,
        ch4_surface_input_g: f64 = 0,
        total_subsurface_carbon_flux_g: f64 = 0,
        oxygen_hydrogen_inputs: ecosys.redist_surface_gas_flux_accounting.OxygenHydrogenInputs = std.mem.zeroes(
            ecosys.redist_surface_gas_flux_accounting.OxygenHydrogenInputs,
        ),
    };

    canopy_carbon_state_update_state: ecosys.canopy_carbon_state_update.State,
    canopy_net_fixation_g_c_per_h_by_plant: []f64,
    root_soil_element_exchange_state_update_state: ecosys.root_soil_element_exchange_state_update.State,
    plant_balance_state_update_state: ecosys.plant_balance_state_update.State,
    plant_balance_carbon_inputs_workspace: []ecosys.plant_daily_output.CarbonBalanceInputs,
    plant_balance_nitrogen_inputs_workspace: []ecosys.plant_daily_output.NutrientBalanceInputs,
    plant_balance_phosphorus_inputs_workspace: []ecosys.plant_daily_output.NutrientBalanceInputs,
    plant_balance_carbon_root_by_layer: []f64,
    plant_balance_carbon_root_length_density_by_layer: []f64,
    plant_balance_nutrient_root_by_layer: []f64,
    plant_conservation_scope_enabled: []bool,
    plant_conservation_hour_start: []ecosys.plant_daily_flux_ledger.AcceptedHourSnapshot,
    plant_conservation_reports: []ecosys.plant_daily_flux_ledger.AcceptedHourReport,
    plant_lifecycle_inventory_before: []ecosys.plant_daily_flux_ledger.ElementalInventory,
    plant_lifecycle_external_input: []ecosys.plant_daily_flux_ledger.ElementalInventory,
    plant_lifecycle_initialized_before: []bool,
    root_soil_element_exchange_workspace: []f64,
    root_soil_carbon_exchange_g_c_per_h_by_plant: []f64,
    root_soil_nitrogen_exchange_g_n_per_h_by_plant: []f64,
    root_soil_phosphorus_exchange_g_p_per_h_by_plant: []f64,
    rse_organic_carbon_by_plant: []f64,
    rse_organic_nitrogen_by_plant: []f64,
    rse_organic_phosphorus_by_plant: []f64,
    rse_phosphate_h2_by_plant: []f64,
    rse_phosphate_h_by_plant: []f64,
    rse_canopy_fixation_g_n_per_h_by_plant: []f64,
    root_gas_withdrawal_state_update_state: ecosys.root_gas_withdrawal_state_update.State,
    uptake_coupled_transaction_workspace: ecosys.uptake_coupled_transaction.Workspace,
    canopy_ammonia_state_update_state: ecosys.canopy_ammonia_state_update.State,
    cell_litter_standing_dead_state_update_state: ecosys.grid_cell_litter_standing_dead_state_update.State,
    manure_deposition_state_update_state: ecosys.manure_deposition_state_update.State,
    canopy_fire_state_update_state: ecosys.canopy_fire_state_update.State,
    plant_combustion_state_update_state: ecosys.plant_combustion_state_update.State,
    root_combustion_salt_state_update_state: ecosys.root_combustion_salt_state_update.State,
    aboveground_litter_state_update_workspace: []f64,
    aboveground_litter_carbon_g_c_per_h_by_plant: []f64,
    aboveground_litter_nitrogen_g_n_per_h_by_plant: []f64,
    aboveground_litter_phosphorus_g_p_per_h_by_plant: []f64,
    canopy_net_radiation_megajoules: []f64,
    canopy_storage_heat_megajoules: []f64,
    zero_plant_energy_megajoules: []f64,
    fire_active_this_hour: []bool,
    symbiotic_inoculum_input_by_cell: []ecosys.plant_symbiotic_fixation.Pool,
    pending_surface_gas_ledger: []PendingSurfaceGasLedgerEntry,
    surface_temperature_solver_state: ecosys.surface_temperature_solver.State,
    surface_heat_capacity_megajoules_per_k: []f64,
    canopy_energy_state: ?ecosys.canopy_energy.State,
    plant_water_balance_state: ?ecosys.plant_water_balance.State,
    plant_water_workspace: ?ecosys.plant_water_balance.Workspace,
    surface_energy_settings: ecosys.surface_energy.Settings,
    surface_energy_solver_options: ecosys.numerics.SolverOptions,
    canopy_temperature_solver_options: ecosys.numerics.SolverOptions,
    canopy_water_depth_solver_options: ecosys.numerics.SolverOptions,
    canopy_water_potential_solver_options: ecosys.numerics.SolverOptions,
};

const PlantCanopyRuntimeInputs = struct {
    allocator: std.mem.Allocator,
    state: *const ecosys.grid.GridState,
    config: ecosys.config.SimulationConfig,
    runscript: *const ecosys.runscript.RunScript,
    runtime_plant_count: usize,
    canopy_exposure_state: *const ?ecosys.canopy_exposure.State,
    plant_root_state: *const ?ecosys.plant_root_system.State,
    detailed_canopy_state: *const ?ecosys.canopy_photosynthesis.State,
    grid_environment: *const ecosys.grid_environment.Assignments,
    plant_assignments: *const ?ecosys.plant_assignment.Assignments,
    plant_unit_by_cell: *const ?[]usize,
    plant_catalog: *const ecosys.plant_catalog.Catalog,
    plant_management_catalog: *const ecosys.plant_management.Catalog,
};

noinline fn initializePlantAccountingRuntimeOwners(
    owners: *PlantCanopyRuntimeOwners,
    resources: *MainResources,
    inputs: PlantCanopyRuntimeInputs,
) !void {
    const allocator = inputs.allocator;
    const state = inputs.state;
    const config = inputs.config;
    const runtime_plant_count = inputs.runtime_plant_count;

    owners.canopy_carbon_state_update_state = try ecosys.canopy_carbon_state_update.State.init(
        allocator,
        state.cell_count,
        config.plant_populations,
    );
    resources.ownDeinit(&owners.canopy_carbon_state_update_state);
    owners.canopy_net_fixation_g_c_per_h_by_plant = try allocator.alloc(f64, runtime_plant_count);
    resources.ownFree(&owners.canopy_net_fixation_g_c_per_h_by_plant);
    @memset(owners.canopy_net_fixation_g_c_per_h_by_plant, 0);
    owners.root_soil_element_exchange_state_update_state = try ecosys.root_soil_element_exchange_state_update.State.init(
        allocator,
        state.cell_count,
        config.plant_populations,
    );
    resources.ownDeinit(&owners.root_soil_element_exchange_state_update_state);
    owners.plant_balance_state_update_state = try ecosys.plant_balance_state_update.State.init(
        allocator,
        state.cell_count,
        config.plant_populations,
    );
    resources.ownDeinit(&owners.plant_balance_state_update_state);
    owners.plant_balance_carbon_inputs_workspace = try allocator.alloc(ecosys.plant_daily_output.CarbonBalanceInputs, runtime_plant_count);
    resources.ownFree(&owners.plant_balance_carbon_inputs_workspace);
    @memset(std.mem.sliceAsBytes(owners.plant_balance_carbon_inputs_workspace), 0);
    owners.plant_balance_nitrogen_inputs_workspace = try allocator.alloc(ecosys.plant_daily_output.NutrientBalanceInputs, runtime_plant_count);
    resources.ownFree(&owners.plant_balance_nitrogen_inputs_workspace);
    @memset(std.mem.sliceAsBytes(owners.plant_balance_nitrogen_inputs_workspace), 0);
    owners.plant_balance_phosphorus_inputs_workspace = try allocator.alloc(ecosys.plant_daily_output.NutrientBalanceInputs, runtime_plant_count);
    resources.ownFree(&owners.plant_balance_phosphorus_inputs_workspace);
    @memset(std.mem.sliceAsBytes(owners.plant_balance_phosphorus_inputs_workspace), 0);
    owners.plant_balance_carbon_root_by_layer = try allocator.alloc(f64, state.soil_layer_capacity);
    resources.ownFree(&owners.plant_balance_carbon_root_by_layer);
    @memset(owners.plant_balance_carbon_root_by_layer, 0);
    owners.plant_balance_carbon_root_length_density_by_layer = try allocator.alloc(f64, state.soil_layer_capacity);
    resources.ownFree(&owners.plant_balance_carbon_root_length_density_by_layer);
    @memset(owners.plant_balance_carbon_root_length_density_by_layer, 0);
    owners.plant_balance_nutrient_root_by_layer = try allocator.alloc(f64, state.soil_layer_capacity);
    resources.ownFree(&owners.plant_balance_nutrient_root_by_layer);
    @memset(owners.plant_balance_nutrient_root_by_layer, 0);
    owners.plant_conservation_scope_enabled = try allocator.alloc(bool, runtime_plant_count);
    resources.ownFree(&owners.plant_conservation_scope_enabled);
    @memset(owners.plant_conservation_scope_enabled, true);
    owners.plant_conservation_hour_start = try allocator.alloc(
        ecosys.plant_daily_flux_ledger.AcceptedHourSnapshot,
        runtime_plant_count,
    );
    resources.ownFree(&owners.plant_conservation_hour_start);
    owners.plant_conservation_reports = try allocator.alloc(
        ecosys.plant_daily_flux_ledger.AcceptedHourReport,
        runtime_plant_count,
    );
    resources.ownFree(&owners.plant_conservation_reports);
    owners.plant_lifecycle_inventory_before = try allocator.alloc(
        ecosys.plant_daily_flux_ledger.ElementalInventory,
        runtime_plant_count,
    );
    resources.ownFree(&owners.plant_lifecycle_inventory_before);
    owners.plant_lifecycle_external_input = try allocator.alloc(
        ecosys.plant_daily_flux_ledger.ElementalInventory,
        runtime_plant_count,
    );
    resources.ownFree(&owners.plant_lifecycle_external_input);
    @memset(owners.plant_lifecycle_external_input, .{});
    owners.plant_lifecycle_initialized_before = try allocator.alloc(bool, runtime_plant_count);
    resources.ownFree(&owners.plant_lifecycle_initialized_before);
    owners.root_soil_element_exchange_workspace = try allocator.alloc(f64, 9 * runtime_plant_count);
    resources.ownFree(&owners.root_soil_element_exchange_workspace);
    @memset(owners.root_soil_element_exchange_workspace, 0);
    owners.root_soil_carbon_exchange_g_c_per_h_by_plant = owners.root_soil_element_exchange_workspace[0..runtime_plant_count];
    owners.root_soil_nitrogen_exchange_g_n_per_h_by_plant = owners.root_soil_element_exchange_workspace[runtime_plant_count .. 2 * runtime_plant_count];
    owners.root_soil_phosphorus_exchange_g_p_per_h_by_plant = owners.root_soil_element_exchange_workspace[2 * runtime_plant_count .. 3 * runtime_plant_count];
    owners.rse_organic_carbon_by_plant = owners.root_soil_element_exchange_workspace[3 * runtime_plant_count .. 4 * runtime_plant_count];
    owners.rse_organic_nitrogen_by_plant = owners.root_soil_element_exchange_workspace[4 * runtime_plant_count .. 5 * runtime_plant_count];
    owners.rse_organic_phosphorus_by_plant = owners.root_soil_element_exchange_workspace[5 * runtime_plant_count .. 6 * runtime_plant_count];
    owners.rse_phosphate_h2_by_plant = owners.root_soil_element_exchange_workspace[6 * runtime_plant_count .. 7 * runtime_plant_count];
    owners.rse_phosphate_h_by_plant = owners.root_soil_element_exchange_workspace[7 * runtime_plant_count .. 8 * runtime_plant_count];
    owners.rse_canopy_fixation_g_n_per_h_by_plant = owners.root_soil_element_exchange_workspace[8 * runtime_plant_count .. 9 * runtime_plant_count];
}

noinline fn initializePlantProcessRuntimeOwners(
    owners: *PlantCanopyRuntimeOwners,
    resources: *MainResources,
    inputs: PlantCanopyRuntimeInputs,
) !void {
    const allocator = inputs.allocator;
    const state = inputs.state;
    const config = inputs.config;
    const runtime_plant_count = inputs.runtime_plant_count;

    owners.root_gas_withdrawal_state_update_state = try ecosys.root_gas_withdrawal_state_update.State.init(
        allocator,
        state.cell_count,
        config.plant_populations,
        state.soil_layer_capacity,
        ecosys.plant_root_system.biological_domain_count,
    );
    resources.ownDeinit(&owners.root_gas_withdrawal_state_update_state);
    owners.uptake_coupled_transaction_workspace = try ecosys.uptake_coupled_transaction.Workspace.init(allocator, .{
        .cell_count = state.cell_count,
        .species_count = config.plant_populations,
        .soil_layer_capacity = state.soil_layer_capacity,
        .root_domain_capacity = ecosys.plant_root_system.biological_domain_count,
    });
    resources.ownDeinit(&owners.uptake_coupled_transaction_workspace);
    owners.canopy_ammonia_state_update_state = try ecosys.canopy_ammonia_state_update.State.init(
        allocator,
        runtime_plant_count,
    );
    resources.ownDeinit(&owners.canopy_ammonia_state_update_state);
    owners.cell_litter_standing_dead_state_update_state = try ecosys.grid_cell_litter_standing_dead_state_update.State.init(
        allocator,
        state.cell_count,
        config.plant_populations,
    );
    resources.ownDeinit(&owners.cell_litter_standing_dead_state_update_state);
    owners.manure_deposition_state_update_state = try ecosys.manure_deposition_state_update.State.init(
        allocator,
        state.cell_count,
        config.plant_populations,
    );
    resources.ownDeinit(&owners.manure_deposition_state_update_state);
    owners.canopy_fire_state_update_state = try ecosys.canopy_fire_state_update.State.init(
        allocator,
        state.cell_count,
        config.plant_populations,
    );
    resources.ownDeinit(&owners.canopy_fire_state_update_state);
    owners.plant_combustion_state_update_state = try ecosys.plant_combustion_state_update.State.init(
        allocator,
        runtime_plant_count,
    );
    resources.ownDeinit(&owners.plant_combustion_state_update_state);
    owners.root_combustion_salt_state_update_state = try ecosys.root_combustion_salt_state_update.State.init(
        allocator,
        state.cell_count,
        config.plant_populations,
        config.soil_layers,
        ecosys.plant_root_system.biological_domain_count,
    );
    resources.ownDeinit(&owners.root_combustion_salt_state_update_state);
    owners.aboveground_litter_state_update_workspace = try allocator.alloc(f64, 3 * runtime_plant_count);
    resources.ownFree(&owners.aboveground_litter_state_update_workspace);
    @memset(owners.aboveground_litter_state_update_workspace, 0);
    owners.aboveground_litter_carbon_g_c_per_h_by_plant = owners.aboveground_litter_state_update_workspace[0..runtime_plant_count];
    owners.aboveground_litter_nitrogen_g_n_per_h_by_plant = owners.aboveground_litter_state_update_workspace[runtime_plant_count .. 2 * runtime_plant_count];
    owners.aboveground_litter_phosphorus_g_p_per_h_by_plant = owners.aboveground_litter_state_update_workspace[2 * runtime_plant_count .. 3 * runtime_plant_count];
    owners.canopy_net_radiation_megajoules = try allocator.alloc(f64, runtime_plant_count);
    resources.ownFree(&owners.canopy_net_radiation_megajoules);
    owners.canopy_storage_heat_megajoules = try allocator.alloc(f64, runtime_plant_count);
    resources.ownFree(&owners.canopy_storage_heat_megajoules);
    owners.zero_plant_energy_megajoules = try allocator.alloc(f64, runtime_plant_count);
    resources.ownFree(&owners.zero_plant_energy_megajoules);
    @memset(owners.canopy_net_radiation_megajoules, 0);
    @memset(owners.canopy_storage_heat_megajoules, 0);
    @memset(owners.zero_plant_energy_megajoules, 0);
    owners.fire_active_this_hour = try allocator.alloc(bool, state.cell_count);
    resources.ownFree(&owners.fire_active_this_hour);
    @memset(owners.fire_active_this_hour, false);
    owners.symbiotic_inoculum_input_by_cell = try allocator.alloc(
        ecosys.plant_symbiotic_fixation.Pool,
        state.cell_count,
    );
    resources.ownFree(&owners.symbiotic_inoculum_input_by_cell);
    @memset(owners.symbiotic_inoculum_input_by_cell, .{
        .carbon_g_c = 0,
        .nitrogen_g_n = 0,
        .phosphorus_g_p = 0,
    });
}

noinline fn initializePlantEnergyWaterRuntimeOwners(
    owners: *PlantCanopyRuntimeOwners,
    resources: *MainResources,
    inputs: PlantCanopyRuntimeInputs,
) !void {
    const allocator = inputs.allocator;
    const state = inputs.state;
    const config = inputs.config;
    const runscript = inputs.runscript;

    owners.pending_surface_gas_ledger = try allocator.alloc(PlantCanopyRuntimeOwners.PendingSurfaceGasLedgerEntry, state.cell_count);
    resources.ownFree(&owners.pending_surface_gas_ledger);
    owners.surface_temperature_solver_state = try ecosys.surface_temperature_solver.State.init(allocator, state.cell_count);
    resources.ownDeinit(&owners.surface_temperature_solver_state);
    owners.surface_heat_capacity_megajoules_per_k = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&owners.surface_heat_capacity_megajoules_per_k);
    @memset(owners.surface_heat_capacity_megajoules_per_k, 0);
    owners.canopy_energy_state = null;
    resources.ownOptionalDeinit(&owners.canopy_energy_state);
    if (inputs.canopy_exposure_state.* != null)
        owners.canopy_energy_state = try ecosys.canopy_energy.State.init(allocator, state.cell_count, config.plant_populations);
    owners.plant_water_balance_state = null;
    resources.ownOptionalDeinit(&owners.plant_water_balance_state);
    owners.plant_water_workspace = null;
    resources.ownOptionalDeinit(&owners.plant_water_workspace);
    if (inputs.plant_root_state.* != null and inputs.detailed_canopy_state.* != null) {
        owners.plant_water_balance_state = try ecosys.plant_water_balance.State.init(allocator, state.cell_count, config.plant_populations, config.soil_layers);
        owners.plant_water_workspace = try ecosys.plant_water_balance.Workspace.init(allocator, state.cell_count, config.plant_populations, config.soil_layers);
        for (0..state.cell_count) |cell|
            owners.plant_water_workspace.?.cell_area_m2[cell] =
                inputs.grid_environment.horizontal_cell_width_m[cell] *
                inputs.grid_environment.vertical_cell_width_m[cell];
        if (inputs.plant_assignments.*) |assignments| for (inputs.plant_unit_by_cell.*.?, 0..) |unit_index, cell| for (assignments.units[unit_index].species, 0..) |assignment, species| {
            const trait_index = inputs.plant_catalog.find(assignment.species_file) orelse return error.MissingPlantTraitProfile;
            const management_index = inputs.plant_management_catalog.find(assignment.management_file) orelse continue;
            const plant = cell * config.plant_populations + species;
            const traits = inputs.plant_catalog.entries.items[trait_index].traits;
            const planting = inputs.plant_management_catalog.entries.items[management_index].schedule.planting;
            owners.plant_water_workspace.?.leaf_osmotic_potential_at_zero_total_megapascal[plant] = traits.water_relations.osmotic_potential_megapascal;
            owners.plant_water_workspace.?.plant_population_count[plant] = planting.population_per_m2 * owners.plant_water_workspace.?.cell_area_m2[cell];
            owners.plant_water_workspace.?.root_porosity_fraction[plant] = traits.roots.root_porosity_fraction;
            owners.plant_water_workspace.?.root_radial_resistivity_mpa_h_per_m3[plant] = traits.roots.radial_resistivity_mpa_h_per_m3;
            owners.plant_water_workspace.?.root_axial_resistivity_mpa_h_per_m2[plant] = traits.roots.axial_resistivity_mpa_h_per_m2;
            owners.plant_water_workspace.?.primary_root_radius_m[plant] = traits.roots.primary_root_radius_m;
            owners.plant_water_workspace.?.secondary_root_radius_m[plant] = traits.roots.secondary_root_radius_m;
            owners.plant_water_workspace.?.seeding_depth_m[plant] = planting.seed_depth_m;
            owners.plant_water_workspace.?.woody_root_fraction[plant] = 1;
            owners.plant_water_workspace.?.dynamically_woody[plant] = traits.functional_type.root_profile_type != 0 and traits.functional_type.growth_habit > 1;
            owners.plant_water_workspace.?.vascular_growth_habit[plant] = traits.functional_type.growth_habit != 0;
        };
    }
    owners.surface_energy_settings = .{
        .soil_longwave_emissivity = runscript.soil_longwave_emissivity,
        .snow_longwave_emissivity = runscript.snow_longwave_emissivity,
        .snow_full_cover_depth_m = runscript.snow_full_cover_depth_m,
    };
    owners.surface_energy_solver_options = .{
        .absolute_tolerance = config.nonlinear_tolerance.heat_megajoules_per_m2,
        .relative_tolerance = config.nonlinear_tolerance.relative,
        .picard_relaxation = config.picard_relaxation,
        .residual_scale = 1.0,
        .max_iterations = config.max_nonlinear_iterations,
    };
    owners.canopy_temperature_solver_options = .{
        .absolute_tolerance = config.nonlinear_tolerance.temperature_k,
        .relative_tolerance = config.nonlinear_tolerance.relative,
        .picard_relaxation = config.picard_relaxation,
        .residual_scale = 1.0,
        .max_iterations = config.max_nonlinear_iterations,
    };
    owners.canopy_water_depth_solver_options = .{
        .absolute_tolerance = config.nonlinear_tolerance.water_depth_m,
        .relative_tolerance = config.nonlinear_tolerance.relative,
        .picard_relaxation = config.picard_relaxation,
        .residual_scale = 1.0,
        .max_iterations = config.max_nonlinear_iterations,
    };
    owners.canopy_water_potential_solver_options = .{
        .absolute_tolerance = config.nonlinear_tolerance.water_potential_megapascal,
        .relative_tolerance = config.nonlinear_tolerance.relative,
        .picard_relaxation = config.picard_relaxation,
        .residual_scale = 1.0,
        .max_iterations = config.max_nonlinear_iterations,
    };
}

noinline fn initializePlantCanopyRuntimeOwners(
    owners: *PlantCanopyRuntimeOwners,
    resources: *MainResources,
    inputs: PlantCanopyRuntimeInputs,
) !void {
    try initializePlantAccountingRuntimeOwners(owners, resources, inputs);
    try initializePlantProcessRuntimeOwners(owners, resources, inputs);
    try initializePlantEnergyWaterRuntimeOwners(owners, resources, inputs);
}

/// Final-address owners for the plant, canopy, and root state-update ledgers
/// consumed by the hourly driver. Keeping these related allocations behind a
/// named owner removes twenty live locals and their error/cleanup edges from
/// `main` without moving any allocation after its cleanup has been registered.
const PlantStateUpdateOwners = struct {
    surface_energy_state: ecosys.surface_energy.State,
    ecosystem_energy_ledger_state: ecosys.ecosystem_energy_ledger.State,
    plant_energy_state_update_state: ecosys.plant_energy_state_update.State,
    plant_water_state_update_state: ecosys.plant_water_state_update.State,
    canopy_water_energy_state_update_state: ecosys.canopy_water_energy_state_update.State,
    canopy_conservation_sidecar_state: ecosys.canopy_conservation_sidecar.State,
    living_canopy_layer_state_update_state: ecosys.living_canopy_layer_state_update.State,
    standing_dead_area_state_update_state: ecosys.standing_dead_area_state_update.State,
    root_uptake_ledger_state: ecosys.root_uptake_ledger.State,
    root_water_uptake_state_update_state: ecosys.root_water_uptake_state_update.State,
    root_gas_content_state_update_state: ecosys.root_gas_content_state_update.State,
    root_atmosphere_gas_state_update_state: ecosys.root_atmosphere_gas_state_update.State,
    root_internal_gas_state_update_state: ecosys.root_internal_gas_state_update.State,
    root_soil_gas_state_update_state: ecosys.root_soil_gas_state_update.State,
    root_nutrient_uptake_state_update_state: ecosys.root_nutrient_uptake_state_update.State,
    root_salt_uptake_state_update_state: ecosys.root_salt_uptake_state_update.State,
    root_soil_ammonia_exchange_state_update_state: ecosys.root_soil_ammonia_exchange_state_update.State,
    root_exudate_state_update_state: ecosys.root_exudate_state_update.State,
    root_competition_demand_state_update_state: ecosys.root_competition_demand_state_update.State,
    root_nitrogen_fixation_state_update_state: ecosys.root_nitrogen_fixation_state_update.State,
};

const PlantStateUpdateInputs = struct {
    allocator: std.mem.Allocator,
    cell_count: usize,
    soil_layer_count: usize,
    soil_layer_capacity: usize,
    plant_populations: usize,
    runtime_plant_count: usize,
    canopy_layer_count: usize,
};

noinline fn initializePlantCanopyStateUpdateOwners(
    owners: *PlantStateUpdateOwners,
    resources: *MainResources,
    inputs: PlantStateUpdateInputs,
) !void {
    const allocator = inputs.allocator;
    owners.surface_energy_state = try ecosys.surface_energy.State.init(allocator, inputs.cell_count);
    resources.ownDeinit(&owners.surface_energy_state);
    owners.ecosystem_energy_ledger_state = try ecosys.ecosystem_energy_ledger.State.init(allocator, inputs.cell_count);
    resources.ownDeinit(&owners.ecosystem_energy_ledger_state);
    owners.plant_energy_state_update_state = try ecosys.plant_energy_state_update.State.init(
        allocator,
        inputs.runtime_plant_count,
    );
    resources.ownDeinit(&owners.plant_energy_state_update_state);
    owners.plant_water_state_update_state = try ecosys.plant_water_state_update.State.init(
        allocator,
        inputs.cell_count,
        inputs.plant_populations,
    );
    resources.ownDeinit(&owners.plant_water_state_update_state);
    owners.canopy_water_energy_state_update_state =
        try ecosys.canopy_water_energy_state_update.State.init(
            allocator,
            inputs.cell_count,
            inputs.plant_populations,
        );
    resources.ownDeinit(&owners.canopy_water_energy_state_update_state);
    owners.canopy_conservation_sidecar_state =
        try ecosys.canopy_conservation_sidecar.State.init(
            allocator,
            inputs.cell_count,
            inputs.plant_populations,
        );
    resources.ownDeinit(&owners.canopy_conservation_sidecar_state);
    owners.living_canopy_layer_state_update_state =
        try ecosys.living_canopy_layer_state_update.State.init(
            allocator,
            inputs.cell_count,
            inputs.plant_populations,
            inputs.canopy_layer_count,
        );
    resources.ownDeinit(&owners.living_canopy_layer_state_update_state);
    owners.standing_dead_area_state_update_state =
        try ecosys.standing_dead_area_state_update.State.init(
            allocator,
            inputs.cell_count,
            inputs.plant_populations,
            inputs.canopy_layer_count,
        );
    resources.ownDeinit(&owners.standing_dead_area_state_update_state);
}

noinline fn initializeRootStateUpdateOwners(
    owners: *PlantStateUpdateOwners,
    resources: *MainResources,
    inputs: PlantStateUpdateInputs,
) !void {
    const allocator = inputs.allocator;
    owners.root_uptake_ledger_state = try ecosys.root_uptake_ledger.State.init(
        allocator,
        inputs.soil_layer_count,
    );
    resources.ownDeinit(&owners.root_uptake_ledger_state);
    owners.root_water_uptake_state_update_state =
        try ecosys.root_water_uptake_state_update.State.init(
            allocator,
            inputs.cell_count,
            inputs.plant_populations,
            inputs.soil_layer_capacity,
            ecosys.plant_root_system.biological_domain_count,
        );
    resources.ownDeinit(&owners.root_water_uptake_state_update_state);
    owners.root_gas_content_state_update_state =
        try ecosys.root_gas_content_state_update.State.init(
            allocator,
            inputs.cell_count,
            inputs.plant_populations,
            inputs.soil_layer_capacity,
            ecosys.plant_root_system.biological_domain_count,
        );
    resources.ownDeinit(&owners.root_gas_content_state_update_state);
    owners.root_atmosphere_gas_state_update_state =
        try ecosys.root_atmosphere_gas_state_update.State.init(
            allocator,
            inputs.cell_count,
            inputs.plant_populations,
            inputs.soil_layer_capacity,
            ecosys.plant_root_system.biological_domain_count,
        );
    resources.ownDeinit(&owners.root_atmosphere_gas_state_update_state);
    owners.root_internal_gas_state_update_state =
        try ecosys.root_internal_gas_state_update.State.init(
            allocator,
            inputs.cell_count,
            inputs.plant_populations,
            inputs.soil_layer_capacity,
            ecosys.plant_root_system.biological_domain_count,
        );
    resources.ownDeinit(&owners.root_internal_gas_state_update_state);
    owners.root_soil_gas_state_update_state =
        try ecosys.root_soil_gas_state_update.State.init(
            allocator,
            inputs.cell_count,
            inputs.plant_populations,
            inputs.soil_layer_capacity,
            ecosys.plant_root_system.biological_domain_count,
        );
    resources.ownDeinit(&owners.root_soil_gas_state_update_state);
    owners.root_nutrient_uptake_state_update_state =
