noinline fn initializePlantStateUpdateOwners(
    owners: *PlantStateUpdateOwners,
    resources: *MainResources,
    inputs: PlantStateUpdateInputs,
) !void {
    try initializePlantCanopyStateUpdateOwners(owners, resources, inputs);
    try initializeRootStateUpdateOwners(owners, resources, inputs);
}

pub fn main(init: std.process.Init) !void {
    var debug_allocator: std.heap.DebugAllocator(.{}) = .init;
    defer {
        if (comptime builtin.mode == .Debug) _ = debug_allocator.deinit();
    }
    const allocator = if (comptime builtin.mode == .Debug)
        debug_allocator.allocator()
    else
        std.heap.smp_allocator;
    var resources = MainResources.init(allocator, init.io);
    defer resources.deinit();
    // Coarse startup-phase timing, `.info` (not `.debug`, which default
    // ReleaseFast logging filters out): the only way today to tell a slow
    // but healthy startup from one genuinely stuck in a specific phase, since
    // nothing between process launch and the hourly loop previously logged
    // at a visible level.
    const startup_timestamp = std.Io.Clock.now(.boot, init.io);
    // Declared before every model owner so these retained arenas outlive any
    // rollback-promoted owner buffers during reverse-order scope teardown.
    var outer_hour_transaction_workspace = ecosys.outer_hour_transaction.Workspace.init(allocator);
    resources.ownDeinit(&outer_hour_transaction_workspace);
    var outer_hour_carbon_exchange_workspace = ecosys.outer_hour_transaction.OwnerWorkspace(ecosys.canopy_carbon_exchange.State).init(allocator);
    resources.ownDeinit(&outer_hour_carbon_exchange_workspace);
    var outer_hour_soil_gas_transport_workspace = ecosys.outer_hour_transaction.OwnerWorkspace(ecosys.soil_gas_transport_step.State).init(allocator);
    resources.ownDeinit(&outer_hour_soil_gas_transport_workspace);
    var fixed_hour_recovery_workspace = hourly_heat_water_solute.FixedHourRecoveryWorkspace.init(allocator);
    resources.ownDeinit(&fixed_hour_recovery_workspace);

    const args = try init.minimal.args.toSlice(init.arena.allocator());
    const cli_options = ecosys.cli.parse(args) catch |err| {
        std.log.err("usage: ecosys_ng [--threads <positive integer>] [--describe-timeline] [--execution-evidence <new-file>] [--verbose-diagnostics] <runscript>", .{});
        return err;
    };
    // Set once, single-threaded, before any hourly work or worker threads
    // start; every later read is read-only. See `run_support.verbose_diagnostics_enabled`.
    run_support.verbose_diagnostics_enabled = cli_options.verbose_diagnostics;
    var run_plan: RunPlanOwners = undefined;
    try initializeRunPlan(&run_plan, &resources, allocator, init.io, cli_options.runscript_path);
    if (cli_options.describe_timeline) {
        var plan = try ecosys.execution_evidence.Plan.init(allocator, run_plan.scene_options, run_plan.runscript.scenarios, run_plan.runscript.execution_repeat_count);
        defer plan.deinit(allocator);
        var stdout_buffer: [16 * 1024]u8 = undefined;
        var stdout = std.Io.File.stdout().writerStreaming(init.io, &stdout_buffer);
        try plan.writeJson(&stdout.interface);
        try stdout.interface.flush();
        return;
    }
    std.log.info("startup phase complete: phase=run_plan elapsed_ms={d}", .{startup_timestamp.durationTo(std.Io.Clock.now(.boot, init.io)).toMilliseconds()});
    const source = run_plan.source;
    var runscript = run_plan.runscript;
    const runscript_own_directory = run_plan.runscript_own_directory;
    const runscript_directory = run_plan.runscript_directory;
    var organic_parameters = run_plan.organic_parameters;
    var surface_gas_parameters = run_plan.surface_gas_parameters;
    const soil_nitrogen_parameters = run_plan.soil_nitrogen_parameters;
    const chemistry_reaction_parameters = run_plan.chemistry_reaction_parameters;
    const geospatial_grid = run_plan.geospatial_grid;
    var grid_input_files = run_plan.grid_input_files;
    const site_catalog = run_plan.site_catalog;
    var grid_environment = run_plan.grid_environment;
    const lateral_connection_mode_by_cell = run_plan.lateral_connection_mode_by_cell;
    var tile_plan: ?ecosys.spatial_grid.TilePlan = run_plan.tile_plan;
    const atmospheric_hydrogen_mixing_ratio_umol_per_mol: f64 = 1.0e-3;
    var topography = run_plan.topography;
    const unit_by_cell = run_plan.unit_by_cell;
    const terrain_hydrology_state = &run_plan.terrain_hydrology_state;
    const surface_runoff_state = &run_plan.surface_runoff_state;
    const surface_pond_transition_state = &run_plan.surface_pond_transition_state;
    const surface_inorganic_nitrogen_export_g_n_per_h = run_plan.surface_inorganic_nitrogen_export_g_n_per_h;
    const surface_inorganic_phosphorus_export_g_p_per_h = run_plan.surface_inorganic_phosphorus_export_g_p_per_h;
    const surface_organic_carbon_export_g_c_per_h = run_plan.surface_organic_carbon_export_g_c_per_h;
    const surface_inorganic_carbon_export_g_c_per_h = run_plan.surface_inorganic_carbon_export_g_c_per_h;
