    const organic_matter_fire_exchange_state = &soil_process_transport_owners.organic_matter_fire_exchange_state;
    const surface_fire_exchange_state = &soil_process_transport_owners.surface_fire_exchange_state;
    const soil_microbial_oxygen_state = &soil_process_transport_owners.soil_microbial_oxygen_state;
    const soil_oxygen_staging_state = &soil_process_transport_owners.soil_oxygen_staging_state;
