    const soil_nitrifier_environment_state = &soil_process_transport_owners.soil_nitrifier_environment_state;
    const soil_field_capacity_fraction = soil_process_transport_owners.soil_field_capacity_fraction;
    const soil_redox_satisfaction_fraction = soil_process_transport_owners.soil_redox_satisfaction_fraction;
