    const surface_litter_gas_transport_state = &soil_process_transport_owners.surface_litter_gas_transport_state;
    const litter_gas_transport_state = &soil_process_transport_owners.litter_gas_transport_state;
    const plant_available_nutrient_state = &soil_process_transport_owners.plant_available_nutrient_state;
