    const surface_wilting_point_potential_megapascal = surface_process_owners.surface_wilting_point_potential_megapascal;
    const surface_litter_ice_m3 = surface_process_owners.surface_litter_ice_m3;
    const surface_charcoal_carbon_g_c = surface_process_owners.surface_charcoal_carbon_g_c;
    const surface_litter_chemistry_state = &surface_process_owners.surface_litter_chemistry_state;
    const surface_litter_fertilizer_state = &surface_process_owners.surface_litter_fertilizer_state;
    const surface_microbial_respiration_state = &surface_process_owners.surface_microbial_respiration_state;
    const surface_autotrophic_complex_state = &surface_process_owners.surface_autotrophic_complex_state;
    const surface_microbial_oxygen_state = &surface_process_owners.surface_microbial_oxygen_state;
    const surface_microbial_maintenance_state = &surface_process_owners.surface_microbial_maintenance_state;
    const surface_nonsymbiotic_nitrogen_fixation_state = &surface_process_owners.surface_nonsymbiotic_nitrogen_fixation_state;
    const surface_microbial_substrate_uptake_state = &surface_process_owners.surface_microbial_substrate_uptake_state;
    const surface_denitrification_state = &surface_process_owners.surface_denitrification_state;
    const surface_microbial_assimilation_state = &surface_process_owners.surface_microbial_assimilation_state;
    const surface_microbial_mineral_exchange_state = &surface_process_owners.surface_microbial_mineral_exchange_state;
    const surface_topsoil_mineral_exchange_state = &surface_process_owners.surface_topsoil_mineral_exchange_state;
    const surface_microbial_turnover_state = &surface_process_owners.surface_microbial_turnover_state;
    const surface_organic_priming_state = &surface_process_owners.surface_organic_priming_state;
    const surface_organic_decomposition_state = &surface_process_owners.surface_organic_decomposition_state;
    const surface_organic_sorption_state = &surface_process_owners.surface_organic_sorption_state;
    const surface_litter_colonization_state = &surface_process_owners.surface_litter_colonization_state;
    const surface_humification_fraction = surface_process_owners.surface_humification_fraction;
    const topsoil_humus_partition = surface_process_owners.topsoil_humus_partition;
    const humus_partition_by_layer = surface_process_owners.humus_partition_by_layer;
    const surface_litter_fertilizer_diagnostics = &surface_process_owners.surface_litter_fertilizer_diagnostics;
    const soil_fertilizer_inventory = &surface_process_owners.soil_fertilizer_inventory;
    const mineral_fertilizer_inventory = &surface_process_owners.mineral_fertilizer_inventory;
    const eroded_fertilizer_workspace = &surface_process_owners.eroded_fertilizer_workspace;
    const eroded_mineral_fertilizer_workspace = &surface_process_owners.eroded_mineral_fertilizer_workspace;
    const surface_litter_chemistry_diagnostics = &surface_process_owners.surface_litter_chemistry_diagnostics;
    const surface_litter_cation_selectivity = surface_process_owners.surface_litter_cation_selectivity;
    {
        const parameters = &organic_parameters;
        const depth_partition_factor = try allocator.alloc(f64, state.layer_count);
        defer allocator.free(depth_partition_factor);
        const wetland_layer = try allocator.alloc(bool, state.layer_count);
        defer allocator.free(wetland_layer);
        try ecosys.soil_organic_initialization.deriveMappedDepthPartition(
            allocator,
            &state,
            soil_solver_property_state,
            soil_catalog.entries.items,
            catalog_index_by_cell,
            grid_environment.horizontal_cell_width_m,
            grid_environment.vertical_cell_width_m,
            terrain_hydrology_state.relative_surface_elevation_m,
            terrain_hydrology_state.minimum_surface_elevation_m,
            grid_environment.initial_water_table_depth_m,
            grid_environment.natural_water_table_surface_slope,
            parameters.humusDepthParameters(),
            depth_partition_factor,
            wetland_layer,
        );
        try soil_organic_state.initializeMapped(&state, soil_solver_property_state, soil_catalog.entries.items, catalog_index_by_cell, grid_environment.horizontal_cell_width_m, grid_environment.vertical_cell_width_m, parameters.mapped(depth_partition_factor, wetland_layer));
        // REDIST ORGCCX starts from the initialized authoritative charcoal
        // owner, so the first HOUR1 sees no artificial charcoal creation.
        for (0..state.layer_count) |layer|
            soil_solver_property_state.previous_charcoal_carbon_g_c[layer] =
                try soil_organic_state.charcoalCarbon_g_c(layer);
        try plant_available_nutrient_state.bindInitializedDissolvedOrganic(soil_organic_state);
        try surface_organic_state.initializeMappedSurface(
            soil_catalog.entries.items,
            catalog_index_by_cell,
            grid_environment.horizontal_cell_width_m,
            grid_environment.vertical_cell_width_m,
            parameters.surface(),
        );
        for (0..state.cell_count) |cell| {
            // HUMUS-DEPTH-PARTITION-001: starts.f publishes CFOMC(1,L,..)/
            // CFOMC(2,L,..) per layer L (FCX shrinks the less-resistant share
            // with accumulated humus depth TORGL(L)), and nitro.f routes each
            // layer's own hourly humification product through its own L.
            // Re-derive that same per-layer split from the just-initialized
            // humus pools for every active layer, not only the top layer.
            for (0..state.active_soil_layer_count[cell]) |local_layer| {
                const layer_cell = try state.layerIndex(cell, local_layer);
                const humus_base = (layer_cell * ecosys.soil_organic_initialization.substrate_count + 4) * ecosys.soil_organic_initialization.structural_fraction_count;
                const less_resistant_carbon_g_c = soil_organic_state.structural[humus_base].carbon_g_c;
                const more_resistant_carbon_g_c = soil_organic_state.structural[humus_base + 1].carbon_g_c;
                const total_humus_carbon_g_c = less_resistant_carbon_g_c + more_resistant_carbon_g_c;
                const less_resistant_fraction = if (total_humus_carbon_g_c > 0) less_resistant_carbon_g_c / total_humus_carbon_g_c else parameters.less_resistant_humus_fraction_at_surface;
                const microbial_litter_to_less_resistant = 5 * less_resistant_fraction / (4 * less_resistant_fraction + 1);
                humus_partition_by_layer[layer_cell] = .{ microbial_litter_to_less_resistant, 1 - microbial_litter_to_less_resistant };
                if (local_layer == 0) topsoil_humus_partition[cell] = humus_partition_by_layer[layer_cell];
            }
        }
    }
    for (0..state.layer_count) |layer| for (0..@min(runscript.microbial_substrate_count, ecosys.soil_organic_initialization.microbial_substrate_count)) |substrate| for (0..@min(runscript.microbial_population_count, ecosys.soil_organic_initialization.microbial_population_count)) |population| {
        const runtime_index = try soil_microbial_state.populationIndex(layer / config.soil_layers, layer % config.soil_layers, substrate, population);
        const organic_index = ((layer * ecosys.soil_organic_initialization.microbial_substrate_count + substrate) * ecosys.soil_organic_initialization.microbial_population_count + population) * ecosys.soil_organic_initialization.kinetic_fraction_count;
        const initialized_labile = soil_organic_state.microbial[organic_index];
        const initialized_resistant = soil_organic_state.microbial[organic_index + 1];
        const initialized_nonstructural = soil_organic_state.microbial[organic_index + 2];
        soil_microbial_state.structural[runtime_index * 2] = .{ .carbon_g_c = initialized_labile.carbon_g_c, .nitrogen_g_n = initialized_labile.nitrogen_g_n, .phosphorus_g_p = initialized_labile.phosphorus_g_p };
        soil_microbial_state.structural[runtime_index * 2 + 1] = .{ .carbon_g_c = initialized_resistant.carbon_g_c, .nitrogen_g_n = initialized_resistant.nitrogen_g_n, .phosphorus_g_p = initialized_resistant.phosphorus_g_p };
        soil_microbial_state.nonstructural[runtime_index] = .{ .carbon_g_c = initialized_nonstructural.carbon_g_c, .nitrogen_g_n = initialized_nonstructural.nitrogen_g_n, .phosphorus_g_p = initialized_nonstructural.phosphorus_g_p };
    };
    var initial_chemistry_state = try ecosys.solute_chemistry_state.State.init(allocator, state.layer_count);
    resources.ownDeinit(&initial_chemistry_state);
    const soil_chemistry_layer_parameters = try allocator.alloc(ecosys.solute_chemistry_state.ReactionParameters, state.layer_count);
    resources.ownFree(&soil_chemistry_layer_parameters);
    var startup_soil_chemistry_owners: StartupSoilChemistryOwners = undefined;
    try initializeStartupSoilChemistryOwners(
        &startup_soil_chemistry_owners,
        &resources,
        allocator,
        executor.statistics().effective_threads,
    );
    // Serial atmospheric chemistry continues to use participant zero; hourly
    // soil chemistry uses the complete stable workspace set by layer.
    const soil_chemistry_solver_workspace = &startup_soil_chemistry_owners.solver_workspaces[0];
    var eroded_chemistry_workspace = try ecosys.eroded_constituents.PackedWorkspace.init(allocator, state.cell_count, ecosys.soil_erosion_chemistry_bridge.component_count);
    resources.ownDeinit(&eroded_chemistry_workspace);
    const erosion_canonical_topsoil_mass_megagrams = try allocator.alloc(f64, state.cell_count);
    resources.ownFree(&erosion_canonical_topsoil_mass_megagrams);
    @memset(erosion_canonical_topsoil_mass_megagrams, 0);
    const erosion_topsoil_zone_fractions = try allocator.alloc(ecosys.solute_charge_classification.ZoneFractions, state.cell_count);
    resources.ownFree(&erosion_topsoil_zone_fractions);
    const erosion_topsoil_layer_by_cell = try allocator.alloc(usize, state.cell_count);
    resources.ownFree(&erosion_topsoil_layer_by_cell);
    const suspended_layout: ecosys.suspended_constituents.Layout = .{
        .organic_cnp_count = eroded_organic_component_count,
        .nitrogen_fertilizer_count = ecosys.soil_erosion_fertilizer_bridge.component_count,
        .dry_mineral_fertilizer_count = ecosys.soil_erosion_mineral_fertilizer_bridge.component_count,
        .chemistry_live_and_pending_count = ecosys.soil_erosion_chemistry_bridge.component_count,
    };
    var suspended_constituent_state = try ecosys.suspended_constituents.State.initBorrowingSediment(
        allocator,
        surface_erosion_state.surface_sediment_megagrams,
        suspended_layout,
    );
    resources.ownDeinit(&suspended_constituent_state);
    const erosion_topsoil_constituent_pools = try allocator.alloc(f64, suspended_constituent_state.pools.len);
    resources.ownFree(&erosion_topsoil_constituent_pools);
    @memset(erosion_topsoil_constituent_pools, 0);
    const soil_numerical_scales_state = try ecosys.soil_initial_numerical_scales.initialize(.{
        .calculation_floor = 1.0e-15,
        .geometry_floor_m = 1.0e-6,
        .initial_water_content_m3_per_m3 = 1.0e-3,
        .initial_ice_porosity_m3_per_m3 = 0.0,
        .pure_ice_density_megagrams_per_m3 = 0.92,
    });
    const chemistry_parameters = runscript.chemistry_initialization;
    {
        try initializeStartupSoilChemistry(.{
            .allocator = allocator,
            .io = init.io,
            .logs = output_tree.logs,
            .executor = executor,
            .tile_plan = &tile_plan.?,
            .state = &state,
            .soil_catalog = &soil_catalog,
            .catalog_index_by_cell = catalog_index_by_cell,
            .soil_solver_property_state = soil_solver_property_state,
            .chemistry_state = &initial_chemistry_state,
            .chemistry_layer_parameters = soil_chemistry_layer_parameters,
            .solver_workspaces = startup_soil_chemistry_owners.solver_workspaces,
            .plant_available_nutrient_state = plant_available_nutrient_state,
            .runscript = &runscript,
            .iteration_limits = iteration_limits,
            .chemistry_reaction_parameters = &chemistry_reaction_parameters,
            .surface_gas_parameters = &surface_gas_parameters,
            .mean_annual_temperature_k_by_cell = mean_annual_temperature_k_by_cell,
            .initial_atmospheric_gas_concentration_g_per_m3 = initial_atmospheric_gas_concentration_g_per_m3,
        });
        std.log.info("startup phase complete: phase=startup_soil_chemistry_starte elapsed_ms={d}", .{startup_timestamp.durationTo(std.Io.Clock.now(.boot, init.io)).toMilliseconds()});
        for (0..state.cell_count) |cell| {
            const profile = soil_catalog.entries.items[catalog_index_by_cell[cell]].profile;
            try ecosys.soil_chemistry_initialization.seedSurfaceLitterFromTopsoil(
                surface_litter_chemistry_state,
                cell,
                &initial_chemistry_state,
                try state.layerIndex(cell, 0),
                profile.surface_litter_ph,
                chemistry_parameters.water_activity_product_mol2_per_m6,
                salinity_enabled_by_cell[cell],
            );
            const surface_carbon_g_c = try surface_organic_state.totalCarbon_g_c(cell);
            const surface_dry_mass_megagrams = surface_carbon_g_c *
                organic_parameters.surface_litter_dry_mass_megagrams_per_g_c;
            try ecosys.soil_chemistry_initialization.initializeSurfaceLitterCarboxylHydrogen(
                surface_litter_chemistry_state,
                cell,
                surface_carbon_g_c,
                surface_dry_mass_megagrams,
                chemistry_reaction_parameters.surface_litter.carboxyl_sites_mol_per_megagram_c,
                chemistry_reaction_parameters.surface_litter.carboxyl_dissociation_constant,
                salinity_enabled_by_cell[cell],
                iteration_limits.initial_solute_reaction_max_iterations,
            );
        }
    }
    for (0..state.layer_count) |layer_cell| {
        // STARTE lines 1418-1422 gate dissolved oxygen on depth: only layers
        // whose upper face lies above the water table (`CDPTH(L-1) < DTBLZ`)
        // receive `OXYS`; saturated soil below it starts anoxic. The oracle's
        // `CDPTH(L-1)` is this layer's top face, which the solver geometry
        // already stores as bottom depth minus thickness.
        const depth_cell = layer_cell / state.soil_layer_capacity;
        const layer_top_depth_m = soil_solver_property_state.layer_bottom_depth_m[layer_cell] -
            soil_solver_property_state.layer_thickness_m[layer_cell];
        micropore_solute_state.water_volume_m3[layer_cell] = state.matrix_liquid_water_m3[layer_cell];
        macropore_solute_state.water_volume_m3[layer_cell] = state.macropore_liquid_water_m3[layer_cell];
        gas_transport_state.temperature_k[layer_cell] = state.soil_temperature_k[layer_cell];
        gas_transport_state.air_volume_m3[layer_cell] = state.matrix_air_volume_m3[layer_cell];
        {
            // STARTE lines 1418-1433: seed dissolved gas from atmospheric
            // concentrations at mean annual air temperature (ATCA), not current
            // soil temperature. Soil temperature is 273.15 K before the thermal
            // solver first runs; ATCA is a site-level constant already available.
            const cell = layer_cell / state.soil_layer_capacity;
            // STARTE 1419--1433 divide each dissolved concentration by
            // `exp(A*CSTR1)`. `CSTR1` is the layer's salt-derived ionic
            // strength, so this is exactly 1 for non-saline soil.
            const seed_zone_fractions: ecosys.solute_charge_classification.ZoneFractions = .{
                .ammonium_non_band = 1 - runscript.plant_nutrient_initialization.initial_ammonium_band_fraction,
                .ammonium_band = runscript.plant_nutrient_initialization.initial_ammonium_band_fraction,
                .nitrate_non_band = 1 - runscript.plant_nutrient_initialization.initial_nitrate_band_fraction,
                .nitrate_band = runscript.plant_nutrient_initialization.initial_nitrate_band_fraction,
                .phosphate_non_band = 1 - runscript.plant_nutrient_initialization.initial_phosphate_band_fraction,
                .phosphate_band = runscript.plant_nutrient_initialization.initial_phosphate_band_fraction,
            };
            const layer_ionic_strength =
                (try initial_chemistry_state.activityCoefficients(layer_cell, seed_zone_fractions)).ionic_strength_mol_per_l;
            const atmospheric_start = cell * ecosys.gas_transport.species_count;
            var atmospheric_concentration_g_per_m3: [ecosys.gas_transport.species_count]f64 = undefined;
            @memcpy(
                &atmospheric_concentration_g_per_m3,
                initial_atmospheric_gas_concentration_g_per_m3[atmospheric_start..][0..ecosys.gas_transport.species_count],
            );
            try ecosys.gas_transport.initializeSoilLayerCell(
                gas_transport_state,
                layer_cell,
                state.matrix_air_volume_m3[layer_cell],
                state.matrix_liquid_water_m3[layer_cell],
                layer_top_depth_m,
                soil_boundary_topology_state.natural_water_table_depth_m[depth_cell],
                mean_annual_temperature_k_by_cell[cell],
                atmospheric_concentration_g_per_m3,
                surface_gas_parameters.solubility,
                layer_ionic_strength,
                ecosys.gas_transport.starte_activity_coefficient,
            );
        }
    }
    try ecosys.soil_aqueous_transport_bridge.exportConcentrations(
        &initial_chemistry_state,
        soil_recharge_concentration_mol_per_m3,
    );
    var transport_conservation_owners: TransportConservationOwners = undefined;
    try initializeTransportConservationOwners(
        &transport_conservation_owners,
        &resources,
        .{
            .allocator = allocator,
            .state = &state,
            .config = config,
            .runscript = &runscript,
            .lateral_connection_mode_by_cell = lateral_connection_mode_by_cell,
            .soil_geometry_state = soil_geometry_state,
            .soil_solver_property_state = soil_solver_property_state,
            .grid_environment = &grid_environment,
            .soil_face_geometry_floor_m = soil_numerical_scales_state.geometry_floor_m,
            .aqueous_species_count = aqueous_species_count,
            .soil_organic_state = soil_organic_state,
            .initial_chemistry_state = &initial_chemistry_state,
            .soil_reactive_nitrogen_state = soil_reactive_nitrogen_state,
            .fertilizer_band_state = fertilizer_band_state,
            .micropore_solute_state = micropore_solute_state,
            .gas_transport_state = gas_transport_state,
        },
    );
    const snow_transport_state = &transport_conservation_owners.snow_transport_state;
    const layer_conservation_layout = transport_conservation_owners.layer_conservation_layout;
    const hourly_layer_boundary_ledger = &transport_conservation_owners.hourly_layer_boundary_ledger;
    const tillage_local_activity = &transport_conservation_owners.tillage_local_activity;
    const plant_atmosphere_local_activity = transport_conservation_owners.plant_atmosphere_local_activity;
    const fertilizer_local_activity = &transport_conservation_owners.fertilizer_local_activity;
    const hourly_layer_storage_before = transport_conservation_owners.hourly_layer_storage_before;
    const hourly_layer_storage_after = transport_conservation_owners.hourly_layer_storage_after;
