        .terrain_radiation_state = &terrain_radiation_state,
        .tillage_local_activity = tillage_local_activity,
        .timeline = &timeline,
        .topography = &topography,
        .total_grid_area_m2 = &runtime_environment_workspace_owners.total_grid_area_m2,
        .total_weather_records = &total_weather_records,
        .transport_hydrology_state = transport_hydrology_state,
        .uptake_coupled_transaction_workspace = &plant_canopy_runtime_owners.uptake_coupled_transaction_workspace,
        .visualization_leaf_carbon_g = &visualization_leaf_carbon_g,
        .visualization_organic_carbon_g = &visualization_organic_carbon_g,
        .visualization_root_carbon_g = &visualization_root_carbon_g,
        .visualization_root_profile_carbon_g = &visualization_root_profile_carbon_g,
        .visualization_species_respired_carbon_g = &visualization_species_respired_carbon_g,
        .visualization_stalk_carbon_g = &visualization_stalk_carbon_g,
        .visualization_streams = visualization_streams,
        .zero_plant_energy_megajoules = &plant_canopy_runtime_owners.zero_plant_energy_megajoules,
        .zero_root_layer_flux_g_per_h = &zero_root_layer_flux_g_per_h,
    };
    const parallel_dispatches_before_timeline = executor.statistics().parallel_dispatches;
    std.log.info("startup phase complete: phase=pre_timeline elapsed_ms={d}", .{startup_timestamp.durationTo(std.Io.Clock.now(.boot, init.io)).toMilliseconds()});
    if (cli_options.execution_evidence_path) |path| {
        const file = try std.Io.Dir.cwd().createFile(init.io, path, .{ .exclusive = true });
        defer file.close(init.io);
        var evidence_buffer: [64 * 1024]u8 = undefined;
        var evidence_writer = file.writerStreaming(init.io, &evidence_buffer);
        errdefer evidence_writer.interface.flush() catch {};
        try runTimeline(&timeline_context, &evidence_writer.interface, path);
        try evidence_writer.interface.flush();
    } else {
        try runTimeline(&timeline_context, null, "");
    }
    try reportTimelineExecutor(executor, parallel_dispatches_before_timeline);
}

// The executable is its own module, so nothing in `src/module_index.zig` can
// reach the `src/stages/*.zig` files imported directly above -- adding one
// there makes it a member of two modules and the compiler rejects it. An
// `@import` alone does not pull a file's tests into analysis either, so
// without an explicit reference here those tests never compile and bit-rot
// unobserved (TEST-DISCOVERY-GAP-STAGES-001: `run_support` was the only one
// referenced here, so every other stage file's tests -- and everything they
// transitively `@import`, e.g. `hourly_science`'s whole hourly-process chain
// -- silently never ran under `zig build test` despite it reporting full
// success). Referencing every top-level stage import here forces the whole
// tree into test analysis; `zig build check` staying clean does not
// guarantee this, since non-test builds never analyze `test` blocks at all.
test {
    _ = tile_kernels;
    _ = plant_daily;
    _ = root_processes;
    _ = soil_chemistry_convergence;
    _ = biogeochemistry_batches;
    _ = surface_litter_convergence;
    _ = hourly_process_pipeline;
    _ = hourly_geometry_disturbance;
    _ = hourly_heat_water_solute;
    _ = hourly_phenology_preparation;
    _ = hourly_process_driver;
    _ = hourly_sediment;
    _ = hourly_snow_energy;
    _ = hourly_vegetation;
    _ = diagnostics;
    _ = run_support;
}

noinline fn initializeSceneWeatherAssignment(
    owners: *RunPlanOwners,
    allocator: std.mem.Allocator,
    io: std.Io,
    runscript: *const ecosys.runscript.RunScript,
    scene: ecosys.runscript.SceneFiles,
    scene_index: usize,
) !usize {
    const climate_grid_path = try resolveInputPath(allocator, io, owners.runscript_directory, scene.options);
    defer allocator.free(climate_grid_path);
    const climate_grid_source = try std.Io.Dir.cwd().readFileAlloc(
        io,
        climate_grid_path,
        allocator,
        .limited(16 * 1024 * 1024),
    );
    defer allocator.free(climate_grid_source);
    const options_name = ecosys.cell_grid_file.readSharedName(
        allocator,
        climate_grid_source,
        owners.geospatial_grid,
        "climate_cell",
    ) catch |err| {
        std.log.err("scene {d} climate grid validation failed for '{s}': {s}", .{
            scene_index + 1,
            scene.options,
            @errorName(err),
        });
        return err;
    };
    defer allocator.free(options_name);
    const options_path = try resolveSiblingInputPath(
        allocator,
        io,
        owners.runscript_directory,
        climate_grid_path,
        options_name,
    );
    defer allocator.free(options_path);
    const options_source = try std.Io.Dir.cwd().readFileAlloc(io, options_path, allocator, .limited(16 * 1024 * 1024));
    defer allocator.free(options_source);
    owners.scene_options[scene_index] = ecosys.options.parse(options_source) catch |err| {
        std.log.err("scene {d} options validation failed for '{s}'", .{ scene_index + 1, options_name });
        return err;
    };
    _ = try ecosys.iteration_control.Limits.fromSceneOptions(owners.scene_options[scene_index], runscript.max_nonlinear_iterations);
    const weather_grid_path = try resolveInputPath(
        allocator,
        io,
        owners.runscript_directory,
        scene.weather_grid_file,
    );
    owners.scene_weather_grid_paths[scene_index] = weather_grid_path;
    owners.resolved_weather_grid_paths += 1;
    const weather_grid_source = try std.Io.Dir.cwd().readFileAlloc(
        io,
        weather_grid_path,
        allocator,
        .limited(16 * 1024 * 1024),
    );
    defer allocator.free(weather_grid_source);
    var weather_files = ecosys.grid_input_files.WeatherFiles.parse(
        allocator,
        weather_grid_source,
        owners.geospatial_grid,
    ) catch |err| {
        std.log.err("scene {d} weather-grid validation failed for '{s}': {s}", .{
            scene_index + 1,
            scene.weather_grid_file,
            @errorName(err),
        });
        return err;
    };
    defer weather_files.deinit();
    owners.scene_weather_assignments[scene_index] = try ecosys.weather_grid.Assignments.init(
        allocator,
        weather_files,
        owners.weather_forcing_geometry_by_cell,
    );
    owners.initialized_scene_weather_assignments += 1;
    var weather_record_count: usize = 0;
    for (owners.scene_weather_assignments[scene_index].unique_file_names) |weather_name| {
        const weather_path = try resolveSiblingInputPath(allocator, io, owners.runscript_directory, weather_grid_path, weather_name);
        defer allocator.free(weather_path);
        var weather_summary = ecosys.weather.scanFile(allocator, io, weather_path, 64 * 1024) catch |err| {
            std.log.err("scene {d} weather validation failed for '{s}'", .{ scene_index + 1, weather_name });
            return err;
        };
        defer weather_summary.deinit();
        weather_record_count = try std.math.add(
            usize,
            weather_record_count,
            weather_summary.observation_count,
        );
    }
    return weather_record_count;
}

noinline fn initializeSceneWeatherPlan(
    owners: *RunPlanOwners,
    resources: *MainResources,
    allocator: std.mem.Allocator,
    io: std.Io,
    runscript: *const ecosys.runscript.RunScript,
) !void {
    owners.scene_options = try allocator.alloc(ecosys.options.SceneOptions, runscript.scenes.len);
    resources.ownFree(&owners.scene_options);
    owners.weather_forcing_geometry_by_cell = try allocator.alloc(
        ecosys.weather_grid.ForcingGeometry,
        owners.grid_environment.site_catalog_index_by_cell.len,
    );
    resources.ownFree(&owners.weather_forcing_geometry_by_cell);
    for (owners.weather_forcing_geometry_by_cell, 0..) |*geometry, cell| {
        const selected_site = owners.site_catalog.entries.items[
            owners.grid_environment.site_catalog_index_by_cell[cell]
        ].site;
        geometry.* = .{
            .altitude_m = selected_site.elevation_m,
            .latitude_degrees_north = owners.grid_input_files.latitude_degrees_north_by_cell[cell],
            .longitude_degrees_east = owners.grid_input_files.longitude_degrees_east_by_cell[cell],
            .phytotron = selected_site.ecosystem_type == -2,
        };
    }
    owners.scene_weather_assignments = try allocator.alloc(
        ecosys.weather_grid.Assignments,
        runscript.scenes.len,
    );
    resources.ownFree(&owners.scene_weather_assignments);
    owners.scene_weather_grid_paths = try allocator.alloc([]u8, runscript.scenes.len);
    resources.ownFree(&owners.scene_weather_grid_paths);
    owners.resolved_weather_grid_paths = 0;
    resources.ownPrefixFree(&owners.scene_weather_grid_paths, &owners.resolved_weather_grid_paths);
    owners.initialized_scene_weather_assignments = 0;
    resources.ownPrefixDeinit(&owners.scene_weather_assignments, &owners.initialized_scene_weather_assignments);

    owners.total_weather_records = 0;
    for (runscript.scenes, 0..) |scene, scene_index|
        owners.total_weather_records = try std.math.add(
            usize,
            owners.total_weather_records,
            try initializeSceneWeatherAssignment(
                owners,
                allocator,
                io,
                runscript,
                scene,
                scene_index,
            ),
        );
    owners.iteration_limits = try ecosys.iteration_control.Limits.fromSceneOptions(owners.scene_options[0], runscript.max_nonlinear_iterations);
    owners.timeline = try ecosys.simulation_timeline.summarize(owners.scene_options, runscript.scenarios, runscript.execution_repeat_count);
}

noinline fn initializeSiteEnvironmentPlan(
    owners: *RunPlanOwners,
    resources: *MainResources,
    allocator: std.mem.Allocator,
    io: std.Io,
    runscript: *const ecosys.runscript.RunScript,
) !void {
    owners.site_catalog = ecosys.site_catalog.Catalog.init(allocator);
    resources.ownDeinit(&owners.site_catalog);
    for (owners.grid_input_files.site_file_by_cell) |site_name| {
        if (owners.site_catalog.find(site_name) != null) continue;
        const site_path = try resolveSiblingInputPath(allocator, io, owners.runscript_directory, owners.grid_input_path, site_name);
        defer allocator.free(site_path);
        const site_source = try std.Io.Dir.cwd().readFileAlloc(
            io,
            site_path,
            allocator,
            .limited(16 * 1024 * 1024),
        );
        defer allocator.free(site_source);
        _ = owners.site_catalog.appendFromSource(
            site_name,
            site_source,
            1,
            1,
        ) catch |err| {
            std.log.err("site input validation failed: file='{s}' error={s}", .{ site_name, @errorName(err) });
            return err;
        };
    }
    owners.grid_environment = try ecosys.grid_environment.Assignments.init(
        allocator,
        owners.grid_input_files,
        owners.site_catalog,
        owners.geospatial_grid,
    );
    resources.ownDeinit(&owners.grid_environment);
    owners.lateral_connection_mode_by_cell = try allocator.alloc(
        u8,
        owners.grid_environment.site_catalog_index_by_cell.len,
    );
    resources.ownFree(&owners.lateral_connection_mode_by_cell);
    for (owners.lateral_connection_mode_by_cell, 0..) |*mode, cell| {
        mode.* = @intFromEnum(owners.site_catalog.entries.items[
            owners.grid_environment.site_catalog_index_by_cell[cell]
        ].site.lateral_connection_mode);
    }
    if (try owners.geospatial_grid.cellCount() != owners.grid_environment.horizontal_cell_width_m.len)
        return error.GeospatialGridEnvironmentDimensionMismatch;
    try ecosys.spatial_grid.validateNeighborExchangeControls(
        owners.geospatial_grid.row_count,
        owners.geospatial_grid.column_count,
        owners.lateral_connection_mode_by_cell,
    );
    owners.tile_plan = try ecosys.spatial_grid.TilePlan.init(
        allocator,
        owners.geospatial_grid.row_count,
        owners.geospatial_grid.column_count,
        runscript.tile_row_count,
        runscript.tile_column_count,
        runscript.lateral_flow_halo_cell_count,
    );
    resources.ownDeinit(&owners.tile_plan);
}

noinline fn initializeSurfaceTerrainPlan(
    owners: *RunPlanOwners,
    resources: *MainResources,
    allocator: std.mem.Allocator,
    runscript: *const ecosys.runscript.RunScript,
) !void {
    owners.topography = try owners.grid_environment.buildDomainTopography(
        runscript.domain,
        owners.grid_input_files,
        owners.site_catalog,
    );
    resources.ownDeinit(&owners.topography);
    owners.unit_by_cell = try owners.topography.buildCellUnitMap(runscript.domain, allocator);
    resources.ownFree(&owners.unit_by_cell);
    owners.terrain_hydrology_state = try ecosys.terrain_hydrology.State.initMapped(
        allocator,
        owners.topography,
        owners.unit_by_cell,
        owners.grid_environment.horizontal_cell_width_m,
        owners.grid_environment.vertical_cell_width_m,
        try runscript.domain.columns(),
        try runscript.domain.rows(),
    );
    resources.ownDeinit(&owners.terrain_hydrology_state);
    owners.surface_runoff_state = try ecosys.surface_runoff.State.init(
        allocator,
        owners.unit_by_cell.len,
        runscript.surface_runoff_parameters.runoff_roughness_h_per_m_one_third,
    );
    resources.ownDeinit(&owners.surface_runoff_state);
    owners.surface_pond_transition_state = try ecosys.surface_pond_transition_step.State.init(allocator, owners.unit_by_cell.len);
    resources.ownDeinit(&owners.surface_pond_transition_state);
    owners.surface_inorganic_nitrogen_export_g_n_per_h = try allocator.alloc(f64, owners.unit_by_cell.len);
    resources.ownFree(&owners.surface_inorganic_nitrogen_export_g_n_per_h);
    @memset(owners.surface_inorganic_nitrogen_export_g_n_per_h, 0);
    owners.surface_inorganic_phosphorus_export_g_p_per_h = try allocator.alloc(f64, owners.unit_by_cell.len);
    resources.ownFree(&owners.surface_inorganic_phosphorus_export_g_p_per_h);
    @memset(owners.surface_inorganic_phosphorus_export_g_p_per_h, 0);
    owners.surface_organic_carbon_export_g_c_per_h = try allocator.alloc(f64, owners.unit_by_cell.len);
    resources.ownFree(&owners.surface_organic_carbon_export_g_c_per_h);
    @memset(owners.surface_organic_carbon_export_g_c_per_h, 0);
    owners.surface_inorganic_carbon_export_g_c_per_h = try allocator.alloc(f64, owners.unit_by_cell.len);
    resources.ownFree(&owners.surface_inorganic_carbon_export_g_c_per_h);
    @memset(owners.surface_inorganic_carbon_export_g_c_per_h, 0);
    owners.surface_dissolved_oxygen_export_g_o_per_h = try allocator.alloc(f64, owners.unit_by_cell.len);
    resources.ownFree(&owners.surface_dissolved_oxygen_export_g_o_per_h);
    @memset(owners.surface_dissolved_oxygen_export_g_o_per_h, 0);
    owners.surface_organic_nitrogen_export_g_n_per_h = try allocator.alloc(f64, owners.unit_by_cell.len);
    resources.ownFree(&owners.surface_organic_nitrogen_export_g_n_per_h);
    @memset(owners.surface_organic_nitrogen_export_g_n_per_h, 0);
    owners.surface_organic_phosphorus_export_g_p_per_h = try allocator.alloc(f64, owners.unit_by_cell.len);
    resources.ownFree(&owners.surface_organic_phosphorus_export_g_p_per_h);
    @memset(owners.surface_organic_phosphorus_export_g_p_per_h, 0);
    owners.surface_erosion_state = try ecosys.soil_erosion.RuntimeState.init(allocator, try runscript.domain.columns(), try runscript.domain.rows());
    resources.ownDeinit(&owners.surface_erosion_state);
    owners.surface_soil_mass_at_erosion_start_megagrams = try allocator.alloc(f64, owners.unit_by_cell.len);
    resources.ownFree(&owners.surface_soil_mass_at_erosion_start_megagrams);
    owners.net_sediment_megagrams_per_h = try allocator.alloc(f64, owners.unit_by_cell.len);
    resources.ownFree(&owners.net_sediment_megagrams_per_h);
    @memset(owners.surface_soil_mass_at_erosion_start_megagrams, 0);
    @memset(owners.net_sediment_megagrams_per_h, 0);
    owners.eroded_mineral_state = try ecosys.soil_erosion_mineral_bridge.State.init(allocator, owners.unit_by_cell.len);
    resources.ownDeinit(&owners.eroded_mineral_state);
}

noinline fn initializeSoilCatalogPlan(
    owners: *RunPlanOwners,
    resources: *MainResources,
    allocator: std.mem.Allocator,
    io: std.Io,
    runscript: *const ecosys.runscript.RunScript,
) !void {
    owners.soil_catalog = ecosys.soil_catalog.Catalog.init(allocator);
    resources.ownDeinit(&owners.soil_catalog);
    owners.catalog_index_by_cell = try allocator.alloc(usize, owners.unit_by_cell.len);
    resources.ownFree(&owners.catalog_index_by_cell);
    for (owners.unit_by_cell, 0..) |unit_index, cell_index| {
        const profile_name = owners.topography.units[unit_index].soil_profile_file;
        const catalog_index = owners.soil_catalog.find(profile_name) orelse load: {
            const profile_path = try resolveSiblingInputPath(allocator, io, owners.runscript_directory, owners.grid_input_path, profile_name);
            defer allocator.free(profile_path);
            const profile_source = try std.Io.Dir.cwd().readFileAlloc(io, profile_path, allocator, .limited(64 * 1024 * 1024));
            defer allocator.free(profile_source);
            break :load try owners.soil_catalog.appendFromSource(profile_name, profile_source, runscript.soil_solver_parameters.retention, runscript.soil_solver_parameters.profile_derivation);
        };
        owners.catalog_index_by_cell[cell_index] = catalog_index;
    }
}

noinline fn initializeDomainRunPlan(
    owners: *RunPlanOwners,
    resources: *MainResources,
    allocator: std.mem.Allocator,
    io: std.Io,
    runscript: *const ecosys.runscript.RunScript,
) !void {
    try initializeSiteEnvironmentPlan(
        owners,
        resources,
        allocator,
        io,
        runscript,
    );
    try initializeSurfaceTerrainPlan(
        owners,
        resources,
        allocator,
        runscript,
    );
    try initializeSoilCatalogPlan(
        owners,
        resources,
        allocator,
        io,
        runscript,
    );

    try initializeSceneWeatherPlan(
        owners,
        resources,
        allocator,
        io,
        runscript,
    );
}
